import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Participant {
  id: string;
  name: string;
  avatar: string;
}

export interface Expense {
  id: string;
  description: string;
  amount: number;
  payerId: string;
  participantIds: string[];
  date: number;
  category: 'Food' | 'Transport' | 'Lodging' | 'Entertainment' | 'Other';
}

export interface Settlement {
  from: string;
  to: string;
  amount: number;
}

export interface Balance {
  participantId: string;
  amount: number;
}

import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export interface ParsedReceipt {
  description: string;
  amount: number;
  category: 'Food' | 'Transport' | 'Lodging' | 'Entertainment' | 'Other';
}

export const parseReceipt = async (base64Image: string): Promise<ParsedReceipt | null> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        {
          parts: [
            { text: "Extract the following details from this receipt image: description (brief, e.g., 'Lunch at Mario's'), total amount (numeric), and the most suitable category from: Food, Transport, Lodging, Entertainment, Other." },
            {
              inlineData: {
                mimeType: "image/jpeg",
                data: base64Image.split(',')[1] // remove data:image/jpeg;base64,
              }
            }
          ]
        }
      ],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            description: { type: Type.STRING },
            amount: { type: Type.NUMBER },
            category: { 
              type: Type.STRING,
              description: "Must be one of: Food, Transport, Lodging, Entertainment, Other"
            }
          },
          required: ["description", "amount", "category"]
        }
      }
    });

    const json = JSON.parse(response.text || '{}');
    return json as ParsedReceipt;
  } catch (error) {
    console.error("Error parsing receipt:", error);
    return null;
  }
};

import { Expense, Participant, Settlement, Balance } from '../types';

export const calculateBalances = (participants: Participant[], expenses: Expense[]): Balance[] => {
  const balances: Record<string, number> = {};
  participants.forEach(p => balances[p.id] = 0);

  expenses.forEach(expense => {
    const splitAmount = expense.amount / expense.participantIds.length;

    // Payer gets back their total minus their share
    balances[expense.payerId] += expense.amount;

    // Each participant (including payer if they are in participantIds) owes their share
    expense.participantIds.forEach(pId => {
      balances[pId] -= splitAmount;
    });
  });

  return Object.entries(balances).map(([id, amount]) => ({
    participantId: id,
    amount: parseFloat(amount.toFixed(2))
  }));
};

export const calculateSettlements = (balances: Balance[]): Settlement[] => {
  const settlements: Settlement[] = [];
  const pos = balances.filter(b => b.amount > 0).sort((a, b) => b.amount - a.amount);
  const neg = balances.filter(b => b.amount < 0).sort((a, b) => a.amount - b.amount);

  let i = 0; // pos index
  let j = 0; // neg index

  while (i < pos.length && j < neg.length) {
    const amount = Math.min(pos[i].amount, Math.abs(neg[j].amount));
    settlements.push({
      from: neg[j].participantId,
      to: pos[i].participantId,
      amount: parseFloat(amount.toFixed(2))
    });

    pos[i].amount -= amount;
    neg[j].amount += amount;

    if (pos[i].amount < 0.01) i++;
    if (Math.abs(neg[j].amount) < 0.01) j++;
  }

  return settlements;
};

import React, { useState } from 'react';
import { Participant } from '../types';

interface Props {
  participants: Participant[];
  onAdd: (name: string) => void;
  onRemove: (id: string) => void;
}

const ParticipantManager: React.FC<Props> = ({ participants, onAdd, onRemove }) => {
  const [name, setName] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (name.trim()) {
      onAdd(name.trim());
      setName('');
    }
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6">
      <h2 className="text-xl font-bold mb-4 flex items-center gap-2">
        <i className="fa-solid fa-users text-indigo-600"></i>
        Travelers
      </h2>

      <form onSubmit={handleSubmit} className="flex gap-2 mb-6">
        <input
          type="text"
          value={name}
          onChange={(e) => setName(e.target.value)}
          placeholder="Enter name..."
          className="flex-1 px-4 py-2 rounded-lg border border-slate-300 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all"
        />
        <button
          type="submit"
          className="bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2 rounded-lg font-medium transition-colors"
        >
          Add
        </button>
      </form>

      <div className="space-y-3">
        {participants.length === 0 ? (
          <p className="text-slate-400 text-center py-4">No participants yet.</p>
        ) : (
          participants.map(p => (
            <div key={p.id} className="flex items-center justify-between group bg-slate-50 p-3 rounded-lg hover:bg-slate-100 transition-colors">
              <div className="flex items-center gap-3">
                <img src={p.avatar} alt={p.name} className="w-8 h-8 rounded-full bg-indigo-100 border border-indigo-200" />
                <span className="font-medium text-slate-700">{p.name}</span>
              </div>
              <button
                onClick={() => onRemove(p.id)}
                className="text-slate-400 hover:text-rose-500 opacity-0 group-hover:opacity-100 transition-all"
              >
                <i className="fa-solid fa-trash-can"></i>
              </button>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default ParticipantManager;

import React, { useState, useRef } from 'react';
import { Participant, Expense } from '../types';
import { parseReceipt } from '../services/geminiService';

interface Props {
  participants: Participant[];
  onAdd: (expense: Omit<Expense, 'id' | 'date'>) => void;
}

const ExpenseForm: React.FC<Props> = ({ participants, onAdd }) => {
  const [description, setDescription] = useState('');
  const [amount, setAmount] = useState('');
  const [payerId, setPayerId] = useState('');
  const [category, setCategory] = useState<Expense['category']>('Other');
  const [selectedParticipants, setSelectedParticipants] = useState<string[]>([]);
  const [isScanning, setIsScanning] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const toggleParticipant = (id: string) => {
    setSelectedParticipants(prev => 
      prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id]
    );
  };

  const handleAll = () => {
    if (selectedParticipants.length === participants.length) {
      setSelectedParticipants([]);
    } else {
      setSelectedParticipants(participants.map(p => p.id));
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (description && amount && payerId && selectedParticipants.length > 0) {
      onAdd({
        description,
        amount: parseFloat(amount),
        payerId,
        participantIds: selectedParticipants,
        category
      });
      // Reset form
      setDescription('');
      setAmount('');
      setSelectedParticipants([]);
    }
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsScanning(true);
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      const data = await parseReceipt(base64);
      if (data) {
        setDescription(data.description);
        setAmount(data.amount.toString());
        setCategory(data.category);
      }
      setIsScanning(false);
    };
    reader.readAsDataURL(file);
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 sticky top-6">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-xl font-bold flex items-center gap-2">
          <i className="fa-solid fa-receipt text-indigo-600"></i>
          Add Expense
        </h2>
        <button
          onClick={() => fileInputRef.current?.click()}
          disabled={isScanning}
          className={`flex items-center gap-2 px-3 py-1.5 rounded-lg text-sm font-semibold transition-all ${
            isScanning 
            ? 'bg-slate-100 text-slate-400 cursor-not-allowed'
            : 'bg-indigo-50 text-indigo-700 hover:bg-indigo-100'
          }`}
        >
          {isScanning ? (
            <><i className="fa-solid fa-spinner animate-spin"></i> Analyzing...</>
          ) : (
            <><i className="fa-solid fa-camera"></i> Scan Receipt</>
          )}
        </button>
        <input
          type="file"
          accept="image/*"
          ref={fileInputRef}
          onChange={handleFileChange}
          className="hidden"
        />
      </div>

      <form onSubmit={handleSubmit} className="space-y-4">
        <div>
          <label className="block text-sm font-semibold text-slate-700 mb-1">Description</label>
          <input
            type="text"
            required
            value={description}
            onChange={e => setDescription(e.target.value)}
            className="w-full px-4 py-2 rounded-lg border border-slate-300 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none"
            placeholder="What was it for?"
          />
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-semibold text-slate-700 mb-1">Amount</label>
            <div className="relative">
              <span className="absolute left-3 top-2 text-slate-400">$</span>
              <input
                type="number"
                step="0.01"
                required
                value={amount}
                onChange={e => setAmount(e.target.value)}
                className="w-full pl-8 pr-4 py-2 rounded-lg border border-slate-300 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none"
                placeholder="0.00"
              />
            </div>
          </div>
          <div>
            <label className="block text-sm font-semibold text-slate-700 mb-1">Category</label>
            <select
              value={category}
              onChange={e => setCategory(e.target.value as any)}
              className="w-full px-4 py-2 rounded-lg border border-slate-300 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none"
            >
              <option value="Food">Food</option>
              <option value="Transport">Transport</option>
              <option value="Lodging">Lodging</option>
              <option value="Entertainment">Entertainment</option>
              <option value="Other">Other</option>
            </select>
          </div>
        </div>

        <div>
          <label className="block text-sm font-semibold text-slate-700 mb-1">Who paid?</label>
          <select
            required
            value={payerId}
            onChange={e => setPayerId(e.target.value)}
            className="w-full px-4 py-2 rounded-lg border border-slate-300 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none"
          >
            <option value="" disabled>Select payer</option>
            {participants.map(p => (
              <option key={p.id} value={p.id}>{p.name}</option>
            ))}
          </select>
        </div>

        <div>
          <div className="flex justify-between items-center mb-1">
            <label className="text-sm font-semibold text-slate-700">Split among</label>
            <button
              type="button"
              onClick={handleAll}
              className="text-xs text-indigo-600 font-bold hover:underline"
            >
              Select All
            </button>
          </div>
          <div className="flex flex-wrap gap-2 p-3 bg-slate-50 rounded-lg border border-slate-200">
            {participants.length === 0 && <span className="text-xs text-slate-400">Add participants first</span>}
            {participants.map(p => (
              <button
                key={p.id}
                type="button"
                onClick={() => toggleParticipant(p.id)}
                className={`px-3 py-1 rounded-full text-xs font-semibold transition-all border ${
                  selectedParticipants.includes(p.id)
                    ? 'bg-indigo-600 text-white border-indigo-600'
                    : 'bg-white text-slate-600 border-slate-300 hover:border-indigo-400'
                }`}
              >
                {p.name}
              </button>
            ))}
          </div>
        </div>

        <button
          type="submit"
          className="w-full bg-indigo-600 hover:bg-indigo-700 text-white py-3 rounded-lg font-bold shadow-md shadow-indigo-100 transition-all flex items-center justify-center gap-2"
        >
          <i className="fa-solid fa-plus"></i>
          Add Expense
        </button>
      </form>
    </div>
  );
};

export default ExpenseForm;

import React from 'react';
import { Participant, Settlement, Balance } from '../types';
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip, BarChart, Bar, XAxis, YAxis, CartesianGrid } from 'recharts';

interface Props {
  participants: Participant[];
  balances: Balance[];
  settlements: Settlement[];
  totalSpent: number;
}

const SettlementView: React.FC<Props> = ({ participants, balances, settlements, totalSpent }) => {
  const getParticipantName = (id: string) => participants.find(p => p.id === id)?.name || 'Unknown';

  const COLORS = ['#6366f1', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6'];

  const chartData = balances.map(b => ({
    name: getParticipantName(b.participantId),
    value: b.amount
  }));

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Settlement Summary */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <h2 className="text-xl font-bold mb-4 flex items-center gap-2">
            <i className="fa-solid fa-handshake text-indigo-600"></i>
            Settlement Guide
          </h2>
          <div className="space-y-3">
            {settlements.length === 0 ? (
              <p className="text-slate-400 text-center py-4">Everything settled up!</p>
            ) : (
              settlements.map((s, idx) => (
                <div key={idx} className="flex items-center justify-between bg-slate-50 p-4 rounded-xl border border-slate-100">
                  <div className="flex flex-col">
                    <span className="text-xs font-bold text-slate-400 uppercase">From</span>
                    <span className="font-bold text-slate-700">{getParticipantName(s.from)}</span>
                  </div>
                  <div className="flex flex-col items-center">
                    <i className="fa-solid fa-arrow-right text-indigo-400"></i>
                    <span className="text-sm font-black text-indigo-600">${s.amount.toFixed(2)}</span>
                  </div>
                  <div className="flex flex-col text-right">
                    <span className="text-xs font-bold text-slate-400 uppercase">To</span>
                    <span className="font-bold text-slate-700">{getParticipantName(s.to)}</span>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>

        {/* Balance Status */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <h2 className="text-xl font-bold mb-4 flex items-center gap-2">
            <i className="fa-solid fa-scale-balanced text-indigo-600"></i>
            Net Balances
          </h2>
          <div className="h-[250px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData} layout="vertical">
                <CartesianGrid strokeDasharray="3 3" horizontal={false} stroke="#f1f5f9" />
                <XAxis type="number" hide />
                <YAxis dataKey="name" type="category" width={80} axisLine={false} tickLine={false} tick={{ fontSize: 12, fontWeight: 600 }} />
                <Tooltip 
                  cursor={{ fill: '#f8fafc' }}
                  contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                  formatter={(value: number) => [`$${value}`, 'Balance']}
                />
                <Bar dataKey="value" radius={[0, 4, 4, 0]}>
                  {chartData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.value >= 0 ? '#10b981' : '#f43f5e'} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* Stats Summary */}
      <div className="bg-indigo-600 p-8 rounded-2xl shadow-lg shadow-indigo-100 text-white flex flex-col md:flex-row items-center justify-between gap-6">
        <div>
          <h3 className="text-indigo-200 font-semibold mb-1">Total Trip Spending</h3>
          <p className="text-4xl font-black">${totalSpent.toFixed(2)}</p>
        </div>
        <div className="flex gap-4">
          <div className="bg-white/10 px-4 py-2 rounded-xl backdrop-blur-sm">
            <span className="block text-xs font-bold text-indigo-200">Per Person Avg</span>
            <span className="text-xl font-bold">${(totalSpent / (participants.length || 1)).toFixed(2)}</span>
          </div>
          <div className="bg-white/10 px-4 py-2 rounded-xl backdrop-blur-sm">
            <span className="block text-xs font-bold text-indigo-200">Transactions</span>
            <span className="text-xl font-bold">{settlements.length}</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default SettlementView;

import React, { useState, useMemo, useEffect } from 'react';
import { Participant, Expense, Settlement, Balance } from './types';
import ParticipantManager from './components/ParticipantManager';
import ExpenseForm from './components/ExpenseForm';
import SettlementView from './components/SettlementView';
import { calculateBalances, calculateSettlements } from './utils/calculation';

const App: React.FC = () => {
  const [participants, setParticipants] = useState<Participant[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [activeTab, setActiveTab] = useState<'expenses' | 'settlement'>('expenses');

  // Persistence
  useEffect(() => {
    const savedParticipants = localStorage.getItem('splitit_participants');
    const savedExpenses = localStorage.getItem('splitit_expenses');
    if (savedParticipants) setParticipants(JSON.parse(savedParticipants));
    if (savedExpenses) setExpenses(JSON.parse(savedExpenses));
  }, []);

  useEffect(() => {
    localStorage.setItem('splitit_participants', JSON.stringify(participants));
    localStorage.setItem('splitit_expenses', JSON.stringify(expenses));
  }, [participants, expenses]);

  const addParticipant = (name: string) => {
    const newP: Participant = {
      id: crypto.randomUUID(),
      name,
      avatar: `https://picsum.photos/seed/${name}/100/100`
    };
    setParticipants([...participants, newP]);
  };

  const removeParticipant = (id: string) => {
    setParticipants(participants.filter(p => p.id !== id));
    setExpenses(expenses.filter(e => e.payerId !== id && !e.participantIds.includes(id)));
  };

  const addExpense = (newExp: Omit<Expense, 'id' | 'date'>) => {
    const exp: Expense = {
      ...newExp,
      id: crypto.randomUUID(),
      date: Date.now()
    };
    setExpenses([exp, ...expenses]);
  };

  const removeExpense = (id: string) => {
    setExpenses(expenses.filter(e => e.id !== id));
  };

  const { balances, settlements, totalSpent } = useMemo(() => {
    const bals = calculateBalances(participants, expenses);
    return {
      balances: bals,
      settlements: calculateSettlements([...bals]),
      totalSpent: expenses.reduce((acc, curr) => acc + curr.amount, 0)
    };
  }, [participants, expenses]);

  const getCategoryIcon = (cat: string) => {
    switch (cat) {
      case 'Food': return 'fa-utensils';
      case 'Transport': return 'fa-car';
      case 'Lodging': return 'fa-hotel';
      case 'Entertainment': return 'fa-ticket';
      default: return 'fa-ellipsis';
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-10">
        <div className="max-w-6xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-indigo-100">
              <i className="fa-solid fa-divide text-lg"></i>
            </div>
            <h1 className="text-xl font-black text-slate-800 tracking-tight">SplitIt <span className="text-indigo-600">AI</span></h1>
          </div>
          <nav className="flex gap-1 bg-slate-100 p-1 rounded-lg">
            <button
              onClick={() => setActiveTab('expenses')}
              className={`px-4 py-1.5 rounded-md text-sm font-bold transition-all ${
                activeTab === 'expenses' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'
              }`}
            >
              Overview
            </button>
            <button
              onClick={() => setActiveTab('settlement')}
              className={`px-4 py-1.5 rounded-md text-sm font-bold transition-all ${
                activeTab === 'settlement' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'
              }`}
            >
              Settlement
            </button>
          </nav>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 max-w-6xl mx-auto w-full px-4 py-8">
        {activeTab === 'expenses' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
            {/* Sidebar: People */}
            <div className="lg:col-span-3">
              <ParticipantManager
                participants={participants}
                onAdd={addParticipant}
                onRemove={removeParticipant}
              />
            </div>

            {/* Middle: Expenses Feed */}
            <div className="lg:col-span-5 space-y-6">
              <div className="flex justify-between items-center mb-2">
                <h2 className="text-xl font-bold flex items-center gap-2">
                  <i className="fa-solid fa-list-ul text-indigo-600"></i>
                  Expenses
                </h2>
                <span className="text-sm font-bold text-slate-400 bg-slate-200/50 px-2 py-0.5 rounded-full">
                  {expenses.length} Total
                </span>
              </div>

              {expenses.length === 0 ? (
                <div className="bg-white border-2 border-dashed border-slate-200 rounded-2xl p-12 text-center">
                  <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mx-auto mb-4 text-slate-400">
                    <i className="fa-solid fa-receipt text-2xl"></i>
                  </div>
                  <h3 className="text-lg font-bold text-slate-700 mb-1">No expenses yet</h3>
                  <p className="text-slate-500 mb-6">Start by adding your first expense or scan a receipt.</p>
                </div>
              ) : (
                <div className="space-y-3">
                  {expenses.map(e => (
                    <div key={e.id} className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 group relative">
                      <div className="flex items-start justify-between">
                        <div className="flex gap-4">
                          <div className="w-12 h-12 bg-indigo-50 rounded-xl flex items-center justify-center text-indigo-600 border border-indigo-100 shrink-0">
                            <i className={`fa-solid ${getCategoryIcon(e.category)} text-xl`}></i>
                          </div>
                          <div>
                            <h4 className="font-bold text-slate-800 leading-tight">{e.description}</h4>
                            <p className="text-xs font-semibold text-slate-400 mb-2">
                              {new Date(e.date).toLocaleDateString()} • Paid by {participants.find(p => p.id === e.payerId)?.name}
                            </p>
                            <div className="flex flex-wrap gap-1">
                              {e.participantIds.map(pId => (
                                <span key={pId} className="px-1.5 py-0.5 bg-slate-100 rounded text-[10px] font-black text-slate-500 uppercase tracking-tighter border border-slate-200">
                                  {participants.find(p => p.id === pId)?.name.substring(0, 3)}
                                </span>
                              ))}
                            </div>
                          </div>
                        </div>
                        <div className="text-right">
                          <div className="text-lg font-black text-slate-900">${e.amount.toFixed(2)}</div>
                          <div className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{e.category}</div>
                        </div>
                      </div>
                      <button
                        onClick={() => removeExpense(e.id)}
                        className="absolute top-2 right-2 text-slate-300 hover:text-rose-500 opacity-0 group-hover:opacity-100 transition-all p-2"
                      >
                        <i className="fa-solid fa-xmark"></i>
                      </button>
                    </div>
                  ))}
                </div>
              )}
            </div>

            {/* Right: Add Form */}
            <div className="lg:col-span-4">
              <ExpenseForm
                participants={participants}
                onAdd={addExpense}
              />
            </div>
          </div>
        ) : (
          <SettlementView
            participants={participants}
            balances={balances}
            settlements={settlements}
            totalSpent={totalSpent}
          />
        )}
      </main>

      {/* Footer */}
      <footer className="bg-white border-t border-slate-200 py-6 mt-12">
        <div className="max-w-6xl mx-auto px-4 text-center">
          <p className="text-sm font-semibold text-slate-400 uppercase tracking-[0.2em] mb-2">Powered by Gemini AI</p>
          <p className="text-slate-300 text-xs">A smarter way to split. Fast, accurate, and effortless.</p>
        </div>
      </footer>
    </div>
  );
};

export default App;

{
  "name": "HisaabAI",
  "description": "A smart expense splitting application for trips and parties, featuring AI-powered receipt scanning and automated debt settlement in INR.",
  "requestFramePermissions": [
