import React, { useState, useMemo, useEffect } from 'react';
import { Participant, Expense, Settlement, Balance } from './types.ts';
import ParticipantManager from './components/ParticipantManager.tsx';
import ExpenseForm from './components/ExpenseForm.tsx';
import SettlementView from './components/SettlementView.tsx';
import { calculateBalances, calculateSettlements } from './utils/calculation.ts';

const App: React.FC = () => {
  const [participants, setParticipants] = useState<Participant[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [activeTab, setActiveTab] = useState<'expenses' | 'settlement'>('expenses');

  // Persistence
  useEffect(() => {
    const savedParticipants = localStorage.getItem('splitit_participants');
    const savedExpenses = localStorage.getItem('splitit_expenses');
    if (savedParticipants) setParticipants(JSON.parse(savedParticipants));
    if (savedExpenses) setExpenses(JSON.parse(savedExpenses));
  }, []);

  useEffect(() => {
    localStorage.setItem('splitit_participants', JSON.stringify(participants));
    localStorage.setItem('splitit_expenses', JSON.stringify(expenses));
  }, [participants, expenses]);

  const addParticipant = (name: string, upiId?: string) => {
    const newP: Participant = {
      id: crypto.randomUUID(),
      name,
      upiId,
      avatar: `https://picsum.photos/seed/${name}/100/100`
    };
    setParticipants([...participants, newP]);
  };

  const removeParticipant = (id: string) => {
    setParticipants(participants.filter(p => p.id !== id));
    setExpenses(expenses.filter(e => e.payerId !== id && !e.participantIds.includes(id)));
  };

  const addExpense = (newExp: Omit<Expense, 'id'>) => {
    const exp: Expense = {
      ...newExp,
      id: crypto.randomUUID()
    };
    setExpenses([exp, ...expenses]);
  };

  const removeExpense = (id: string) => {
    setExpenses(expenses.filter(e => e.id !== id));
  };

  const handleSettle = (fromId: string, toId: string, amount: number) => {
    const fromName = participants.find(p => p.id === fromId)?.name || 'Someone';
    const toName = participants.find(p => p.id === toId)?.name || 'Someone';

    addExpense({
      description: `Settlement: ${fromName} paid ${toName}`,
      amount: amount,
      payerId: fromId,
      participantIds: [toId],
      category: 'Payment',
      date: Date.now()
    });
  };

  const { balances, settlements, totalSpent } = useMemo(() => {
    const bals = calculateBalances(participants, expenses);
    return {
      balances: bals,
      settlements: calculateSettlements([...bals]),
      totalSpent: expenses.reduce((acc, curr) => acc + curr.amount, 0)
    };
  }, [participants, expenses]);

  const getCategoryIcon = (cat: string) => {
    switch (cat) {
      case 'Food': return 'fa-utensils';
      case 'Transport': return 'fa-car';
      case 'Lodging': return 'fa-hotel';
      case 'Entertainment': return 'fa-ticket';
      case 'Payment': return 'fa-handshake';
      default: return 'fa-ellipsis';
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-10 shadow-sm">
        <div className="max-w-6xl mx-auto px-4 h-20 flex items-center justify-between">
          <div className="flex flex-col">
            <div className="flex items-center gap-2">
              <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white shadow-lg shadow-indigo-100">
                <i className="fa-solid fa-divide text-sm"></i>
              </div>
              <h1 className="text-xl font-black text-slate-800 tracking-tight">SplitIt<span className="text-indigo-600">AI</span></h1>
            </div>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">Good times in, awkward math out.</p>
          </div>
          <nav className="flex gap-1 bg-slate-100 p-1 rounded-xl">
            <button
              onClick={() => setActiveTab('expenses')}
              className={`px-5 py-1.5 rounded-lg text-sm font-bold transition-all ${
                activeTab === 'expenses' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'
              }`}
            >
              Overview
            </button>
            <button
              onClick={() => setActiveTab('settlement')}
              className={`px-5 py-1.5 rounded-lg text-sm font-bold transition-all ${
                activeTab === 'settlement' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'
              }`}
            >
              Settlement
            </button>
          </nav>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 max-w-6xl mx-auto w-full px-4 py-8">
        {activeTab === 'expenses' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
            {/* Sidebar: People */}
            <div className="lg:col-span-3">
              <ParticipantManager
                participants={participants}
                onAdd={addParticipant}
                onRemove={removeParticipant}
              />
            </div>

            {/* Middle: Expenses Feed */}
            <div className="lg:col-span-5 space-y-6">
              <div className="flex justify-between items-center mb-2">
                <h2 className="text-xl font-bold flex items-center gap-2 text-slate-800">
                  <i className="fa-solid fa-list-ul text-indigo-600"></i>
                  Recent Activity
                </h2>
                <span className="text-xs font-bold text-slate-400 bg-slate-200/50 px-3 py-1 rounded-full">
                  {expenses.length} Records
                </span>
              </div>

              {expenses.length === 0 ? (
                <div className="bg-white border-2 border-dashed border-slate-200 rounded-2xl p-12 text-center">
                  <div className="w-16 h-16 bg-slate-50 rounded-full flex items-center justify-center mx-auto mb-4 text-slate-300">
                    <i className="fa-solid fa-receipt text-2xl"></i>
                  </div>
                  <h3 className="text-lg font-bold text-slate-700 mb-1">Clean slate!</h3>
                  <p className="text-slate-400 text-sm max-w-[200px] mx-auto">Add an expense or scan a receipt to start splitting.</p>
                </div>
              ) : (
                <div className="space-y-3">
                  {expenses.sort((a, b) => b.date - a.date).map(e => (
                    <div key={e.id} className={`bg-white p-4 rounded-xl shadow-sm border border-slate-200 group relative transition-all hover:border-indigo-200 ${e.category === 'Payment' ? 'bg-indigo-50/30' : ''}`}>
                      <div className="flex items-start justify-between">
                        <div className="flex gap-4">
                          <div className={`w-12 h-12 ${e.category === 'Payment' ? 'bg-indigo-600 text-white' : 'bg-indigo-50 text-indigo-600'} rounded-xl flex items-center justify-center border border-indigo-100 shrink-0`}>
                            <i className={`fa-solid ${getCategoryIcon(e.category)} text-xl`}></i>
                          </div>
                          <div>
                            <h4 className="font-bold text-slate-800 leading-tight">{e.description}</h4>
                            <p className="text-xs font-semibold text-slate-400 mb-2">
                              {new Date(e.date).toLocaleDateString(undefined, { day: 'numeric', month: 'short', year: 'numeric' })} • Paid by {participants.find(p => p.id === e.payerId)?.name}
                            </p>
                            <div className="flex flex-wrap gap-1">
                              {e.participantIds.map(pId => (
                                <span key={pId} className="px-1.5 py-0.5 bg-slate-100 rounded text-[9px] font-black text-slate-500 uppercase tracking-tighter border border-slate-200">
                                  {participants.find(p => p.id === pId)?.name.substring(0, 3)}
                                </span>
                              ))}
                            </div>
                          </div>
                        </div>
                        <div className="text-right">
                          <div className={`text-lg font-black ${e.category === 'Payment' ? 'text-indigo-600' : 'text-slate-900'}`}>₹{e.amount.toFixed(2)}</div>
                          <div className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{e.category}</div>
                        </div>
                      </div>
                      <button
                        onClick={() => removeExpense(e.id)}
                        className="absolute top-2 right-2 text-slate-300 hover:text-rose-500 opacity-0 group-hover:opacity-100 transition-all p-2"
                      >
                        <i className="fa-solid fa-xmark"></i>
                      </button>
                    </div>
                  ))}
                </div>
              )}
            </div>

            {/* Right: Add Form */}
            <div className="lg:col-span-4">
              <ExpenseForm
                participants={participants}
                onAdd={addExpense}
              />
            </div>
          </div>
        ) : (
          <SettlementView
            participants={participants}
            balances={balances}
            settlements={settlements}
            totalSpent={totalSpent}
            onSettle={handleSettle}
          />
        )}
      </main>

      {/* Footer */}
      <footer className="bg-white border-t border-slate-200 py-8 mt-12">
        <div className="max-w-6xl mx-auto px-4 text-center">
          <p className="text-xs font-bold text-slate-400 uppercase tracking-[0.3em] mb-3">Good times in, awkward math out.</p>
          <div className="flex items-center justify-center gap-4 text-slate-300 text-[10px] font-bold uppercase tracking-widest">
            <span>SplitIt AI</span>
            <span className="w-1 h-1 bg-slate-200 rounded-full"></span>
            <span>Powered by Gemini</span>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React from 'react';
import { Participant, Settlement, Balance } from '../types.ts';
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip, BarChart, Bar, XAxis, YAxis, CartesianGrid } from 'recharts';

interface Props {
  participants: Participant[];
  balances: Balance[];
  settlements: Settlement[];
  totalSpent: number;
  onSettle: (fromId: string, toId: string, amount: number) => void;
}

const SettlementView: React.FC<Props> = ({ participants, balances, settlements, totalSpent, onSettle }) => {
  const getParticipant = (id: string) => participants.find(p => p.id === id);
  const getParticipantName = (id: string) => getParticipant(id)?.name || 'Unknown';

  const handleWhatsAppRequest = (s: Settlement) => {
    const payer = getParticipant(s.from);
    const payee = getParticipant(s.to);

    if (!payer || !payee) return;

    let message = `Hi ${payer.name}, just a friendly reminder from SplitIt AI! 👋\n\nYou owe me *₹${s.amount.toFixed(2)}* for our recent expenses.`;

    if (payee.upiId) {
      // Create a standard UPI payment link
      const upiLink = `upi://pay?pa=${payee.upiId}&pn=${encodeURIComponent(payee.name)}&am=${s.amount.toFixed(2)}&cu=INR`;
      message += `\n\nYou can pay me here: ${upiLink}\n\nOr use my UPI ID: *${payee.upiId}*`;
    } else {
      message += `\n\nPlease settle up when you can! Thanks!`;
    }

    const whatsappUrl = `https://api.whatsapp.com/send?text=${encodeURIComponent(message)}`;
    window.open(whatsappUrl, '_blank');
  };

  const chartData = balances.map(b => ({
    name: getParticipantName(b.participantId),
    value: b.amount
  }));

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Settlement Summary */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <h2 className="text-xl font-bold mb-4 flex items-center gap-2">
            <i className="fa-solid fa-handshake text-indigo-600"></i>
            Settlement Guide
          </h2>
          <div className="space-y-3">
            {settlements.length === 0 ? (
              <div className="text-center py-12">
                <div className="w-16 h-16 bg-emerald-50 text-emerald-500 rounded-full flex items-center justify-center mx-auto mb-3">
                  <i className="fa-solid fa-check-double text-2xl"></i>
                </div>
                <p className="text-slate-400 font-medium">Everything settled up!</p>
              </div>
            ) : (
              settlements.map((s, idx) => (
                <div key={idx} className="flex flex-col gap-3 bg-slate-50 p-4 rounded-xl border border-slate-100 group">
                  <div className="flex items-center justify-between">
                    <div className="flex flex-col">
                      <span className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">From (Payer)</span>
                      <span className="font-bold text-slate-700">{getParticipantName(s.from)}</span>
                    </div>
                    <div className="flex flex-col items-center">
                      <i className="fa-solid fa-arrow-right text-indigo-300"></i>
                      <span className="text-sm font-black text-indigo-600">₹{s.amount.toFixed(2)}</span>
                    </div>
                    <div className="flex flex-col text-right">
                      <span className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">To (Payee)</span>
                      <span className="font-bold text-slate-700">{getParticipantName(s.to)}</span>
                    </div>
                  </div>

                  <div className="grid grid-cols-2 gap-2">
                    <button
                      onClick={() => handleWhatsAppRequest(s)}
                      className="bg-emerald-500 hover:bg-emerald-600 text-white text-[10px] font-black uppercase tracking-wider py-2 px-3 rounded-lg transition-all flex items-center justify-center gap-2 shadow-sm"
                    >
                      <i className="fa-brands fa-whatsapp text-sm"></i>
                      Request
                    </button>
                    <button
                      onClick={() => onSettle(s.from, s.to, s.amount)}
                      className="bg-white hover:bg-indigo-600 hover:text-white text-indigo-600 text-[10px] font-black uppercase tracking-wider py-2 px-3 rounded-lg border border-indigo-100 transition-all flex items-center justify-center gap-2"
                    >
                      <i className="fa-solid fa-circle-check"></i>
                      Mark Paid
                    </button>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>

        {/* Balance Status */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <h2 className="text-xl font-bold mb-4 flex items-center gap-2">
            <i className="fa-solid fa-scale-balanced text-indigo-600"></i>
            Net Balances
          </h2>
          <div className="h-[250px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData} layout="vertical" margin={{ left: 20 }}>
                <CartesianGrid strokeDasharray="3 3" horizontal={false} stroke="#f1f5f9" />
                <XAxis type="number" hide />
                <YAxis dataKey="name" type="category" width={80} axisLine={false} tickLine={false} tick={{ fontSize: 12, fontWeight: 600, fill: '#64748b' }} />
                <Tooltip 
                  cursor={{ fill: '#f8fafc' }}
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }}
                  formatter={(value: number) => [`₹${value}`, 'Balance']}
                />
                <Bar dataKey="value" radius={[0, 4, 4, 0]}>
                  {chartData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.value >= 0 ? '#10b981' : '#f43f5e'} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* Stats Summary */}
      <div className="bg-gradient-to-br from-indigo-600 to-indigo-700 p-8 rounded-2xl shadow-xl shadow-indigo-100 text-white flex flex-col md:flex-row items-center justify-between gap-6">
        <div>
          <h3 className="text-indigo-100 font-semibold mb-1">Total Group Spend</h3>
          <p className="text-5xl font-black tracking-tight">₹{totalSpent.toFixed(2)}</p>
        </div>
        <div className="flex gap-4">
          <div className="bg-white/10 px-6 py-3 rounded-2xl backdrop-blur-md border border-white/10">
            <span className="block text-[10px] font-bold text-indigo-100 uppercase tracking-widest mb-1">Per Person Avg</span>
            <span className="text-2xl font-black">₹{(totalSpent / (participants.length || 1)).toFixed(2)}</span>
          </div>
          <div className="bg-white/10 px-6 py-3 rounded-2xl backdrop-blur-md border border-white/10">
            <span className="block text-[10px] font-bold text-indigo-100 uppercase tracking-widest mb-1">Dues Outstanding</span>
            <span className="text-2xl font-black">{settlements.length}</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default SettlementView;

export interface Participant {
  id: string;
  name: string;
  avatar: string;
  upiId?: string;
}

export interface Expense {
  id: string;
  description: string;
  amount: number;
  payerId: string;
  participantIds: string[];
  date: number;
  category: 'Food' | 'Transport' | 'Lodging' | 'Entertainment' | 'Payment' | 'Other';
}

export interface Settlement {
  from: string;
  to: string;
  amount: number;
}

export interface Balance {
  participantId: string;
  amount: number;
}

import React, { useState, useMemo, useEffect } from 'react';
import { Participant, Expense, Settlement, Balance } from './types.ts';
import ParticipantManager from './components/ParticipantManager.tsx';
import ExpenseForm from './components/ExpenseForm.tsx';
import SettlementView from './components/SettlementView.tsx';
import { calculateBalances, calculateSettlements } from './utils/calculation.ts';

const App: React.FC = () => {
  const [participants, setParticipants] = useState<Participant[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [activeTab, setActiveTab] = useState<'expenses' | 'settlement'>('expenses');
  const [selectedExpense, setSelectedExpense] = useState<Expense | null>(null);

  // Persistence and Sharing
  useEffect(() => {
    const hash = window.location.hash.substring(1);
    if (hash) {
      try {
        const decoded = JSON.parse(atob(hash));
        if (decoded.participants && decoded.expenses) {
          setParticipants(decoded.participants);
          setExpenses(decoded.expenses);
          window.location.hash = ""; // Clear hash after import
          return;
        }
      } catch (e) {
        console.error("Failed to parse shared link", e);
      }
    }

    const savedParticipants = localStorage.getItem('splitit_participants');
    const savedExpenses = localStorage.getItem('splitit_expenses');
    if (savedParticipants) setParticipants(JSON.parse(savedParticipants));
    if (savedExpenses) setExpenses(JSON.parse(savedExpenses));
  }, []);

  useEffect(() => {
    localStorage.setItem('splitit_participants', JSON.stringify(participants));
    localStorage.setItem('splitit_expenses', JSON.stringify(expenses));
  }, [participants, expenses]);

  const handleShare = () => {
    const data = btoa(JSON.stringify({ participants, expenses }));
    const shareUrl = `${window.location.origin}${window.location.pathname}#${data}`;
    navigator.clipboard.writeText(shareUrl);
    alert("Shareable link copied to clipboard!");
  };

  const addParticipant = (name: string) => {
    const newP: Participant = {
      id: crypto.randomUUID(),
      name,
      avatar: `https://api.dicebear.com/7.x/initials/svg?seed=${name}&backgroundColor=000000&textColor=ffffff`
    };
    setParticipants([...participants, newP]);
  };

  const removeParticipant = (id: string) => {
    setParticipants(participants.filter(p => p.id !== id));
    setExpenses(expenses.filter(e => e.payerId !== id && !e.participantIds.includes(id)));
  };

  const addExpense = (newExp: Omit<Expense, 'id'>) => {
    const exp: Expense = { ...newExp, id: crypto.randomUUID() };
    setExpenses([exp, ...expenses]);
  };

  const removeExpense = (id: string) => {
    setExpenses(expenses.filter(e => e.id !== id));
    if (selectedExpense?.id === id) setSelectedExpense(null);
  };

  const handleSettleIndividual = (expense: Expense) => {
    const payer = participants.find(p => p.id === expense.payerId);
    if (!payer) return;

    const perPerson = expense.amount / expense.participantIds.length;

    expense.participantIds.forEach(pId => {
      if (pId === expense.payerId) return;
      const borrower = participants.find(p => p.id === pId);
      if (!borrower) return;

      addExpense({
        description: `Paid: ${borrower.name} for ${expense.description}`,
        amount: perPerson,
        payerId: pId,
        participantIds: [expense.payerId],
        category: 'Payment',
        date: Date.now()
      });
    });
    setSelectedExpense(null);
  };

  const handleSettle = (fromId: string, toId: string, amount: number) => {
    const fromName = participants.find(p => p.id === fromId)?.name || 'Someone';
    const toName = participants.find(p => p.id === toId)?.name || 'Someone';
    addExpense({
      description: `Settle: ${fromName} to ${toName}`,
      amount,
      payerId: fromId,
      participantIds: [toId],
      category: 'Payment',
      date: Date.now()
    });
  };

  const updateParticipantUpi = (id: string, upiId: string) => {
    setParticipants(prev => prev.map(p => p.id === id ? { ...p, upiId } : p));
  };

  const { balances, settlements, totalSpent } = useMemo(() => {
    const bals = calculateBalances(participants, expenses);
    return {
      balances: bals,
      settlements: calculateSettlements([...bals]),
      totalSpent: expenses.reduce((acc, curr) => curr.category !== 'Payment' ? acc + curr.amount : acc, 0)
    };
  }, [participants, expenses]);

  return (
    <div className="min-h-screen bg-white text-zinc-950 flex flex-col font-sans">
      {/* Header */}
      <header className="bg-zinc-950 text-white sticky top-0 z-30 shadow-2xl">
        <div className="max-w-6xl mx-auto px-6 h-24 flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 bg-white rounded-full flex items-center justify-center shadow-lg transform rotate-[-10deg]">
              <span className="text-zinc-950 font-black text-xl italic tracking-tighter">S&P</span>
            </div>
            <h1 className="text-2xl font-light tracking-tight">
              split<span className="font-black text-white ml-0.5">It</span>
            </h1>
          </div>

          <div className="flex items-center gap-3">
            <button 
              onClick={handleShare}
              className="p-2.5 rounded-full bg-zinc-800 hover:bg-zinc-700 transition-colors text-white/80"
              title="Share Group Link"
            >
              <i className="fa-solid fa-share-nodes"></i>
            </button>
            <nav className="flex gap-1 bg-zinc-800 p-1 rounded-full border border-zinc-700">
              <button
                onClick={() => setActiveTab('expenses')}
                className={`px-6 py-2 rounded-full text-xs font-black uppercase tracking-widest transition-all ${
                  activeTab === 'expenses' ? 'bg-white text-zinc-950' : 'text-zinc-400 hover:text-white'
                }`}
              >
                Feed
              </button>
              <button
                onClick={() => setActiveTab('settlement')}
                className={`px-6 py-2 rounded-full text-xs font-black uppercase tracking-widest transition-all ${
                  activeTab === 'settlement' ? 'bg-white text-zinc-950' : 'text-zinc-400 hover:text-white'
                }`}
              >
                Settle
              </button>
            </nav>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 max-w-6xl mx-auto w-full px-6 py-12">
        {activeTab === 'expenses' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
            <div className="lg:col-span-3 space-y-8">
              <ParticipantManager participants={participants} onAdd={addParticipant} onRemove={removeParticipant} />
            </div>

            <div className="lg:col-span-5 space-y-8">
              <div className="flex justify-between items-end border-b-4 border-zinc-950 pb-4">
                <h2 className="text-3xl font-black italic tracking-tighter uppercase">Activity</h2>
                <span className="text-xs font-black bg-zinc-100 px-3 py-1 rounded-full border border-zinc-200">
                  {expenses.length} Records
                </span>
              </div>

              <div className="space-y-4">
                {expenses.length === 0 ? (
                  <div className="py-20 text-center border-2 border-dashed border-zinc-200 rounded-3xl">
                    <p className="text-zinc-300 font-black text-xs uppercase tracking-widest italic">The ledger is empty</p>
                  </div>
                ) : (
                  expenses.sort((a, b) => b.date - a.date).map(e => (
                    <div 
                      key={e.id} 
                      onClick={() => setSelectedExpense(e)}
                      className={`group cursor-pointer p-6 rounded-3xl border-2 transition-all duration-300 ${
                        e.category === 'Payment' 
                        ? 'bg-zinc-100 border-transparent italic' 
                        : 'bg-white border-zinc-100 hover:border-zinc-950 hover:shadow-2xl hover:-translate-y-1'
                      }`}
                    >
                      <div className="flex items-start justify-between">
                        <div>
                          <h4 className="font-black text-xl tracking-tighter mb-1">{e.description}</h4>
                          <div className="flex items-center gap-2 text-[10px] font-bold text-zinc-400 uppercase tracking-widest">
                            <span>{new Date(e.date).toLocaleDateString()}</span>
                            <span className="w-1 h-1 bg-zinc-200 rounded-full"></span>
                            <span>{participants.find(p => p.id === e.payerId)?.name} paid</span>
                          </div>
                        </div>
                        <div className="text-right">
                          <div className={`text-2xl font-black ${e.category === 'Payment' ? 'text-zinc-500' : 'text-zinc-950'}`}>
                            ₹{e.amount.toFixed(2)}
                          </div>
                        </div>
                      </div>
                    </div>
                  ))
                )}
              </div>
            </div>

            <div className="lg:col-span-4">
              <ExpenseForm participants={participants} onAdd={addExpense} />
            </div>
          </div>
        ) : (
          <SettlementView
            participants={participants}
            balances={balances}
            settlements={settlements}
            totalSpent={totalSpent}
            onSettle={handleSettle}
            onUpdateUpi={updateParticipantUpi}
          />
        )}
      </main>

      {/* Transaction Detail Modal */}
      {selectedExpense && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-zinc-950/80 backdrop-blur-sm">
          <div className="bg-white rounded-[2rem] max-w-lg w-full overflow-hidden shadow-2xl animate-in zoom-in-95 duration-200">
            <div className="bg-zinc-950 p-8 text-white flex justify-between items-start">
              <div>
                <span className="text-[10px] font-black uppercase tracking-[0.2em] text-zinc-400 mb-2 block">Transaction Detail</span>
