import React from 'react';
import { Participant, Settlement, Balance } from '../types.ts';
import { ResponsiveContainer, BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Cell } from 'recharts';

interface Props {
  participants: Participant[];
  balances: Balance[];
  settlements: Settlement[];
  totalSpent: number;
  onSettle: (fromId: string, toId: string, amount: number) => void;
  onUpdateUpi: (id: string, upiId: string) => void;
}

const SettlementView: React.FC<Props> = ({ participants, balances, settlements, totalSpent, onSettle, onUpdateUpi }) => {
  const getParticipant = (id: string) => participants.find(p => p.id === id);
  const getParticipantName = (id: string) => getParticipant(id)?.name || 'Unknown';

  const handleWhatsAppRequest = (s: Settlement) => {
    const payer = getParticipant(s.from);
    const payee = getParticipant(s.to);

    if (!payer || !payee) return;

    let targetUpi = payee.upiId;

    // If no UPI ID, prompt for it
    if (!targetUpi) {
      const input = prompt(`Enter UPI ID for ${payee.name} to include in the message:`, "");
      if (input === null) return; // cancelled
      if (input.trim()) {
        targetUpi = input.trim();
        onUpdateUpi(payee.id, targetUpi);
      }
    }

    let message = `Hi ${payer.name}, reminder from splitIt! 👋\n\nYou owe me *₹${s.amount.toFixed(2)}*.\n`;
    if (targetUpi) {
      const upiLink = `upi://pay?pa=${targetUpi}&pn=${encodeURIComponent(payee.name)}&am=${s.amount.toFixed(2)}&cu=INR`;
      message += `\nPay here: ${upiLink}\nUPI ID: *${targetUpi}*`;
    }

    const whatsappUrl = `https://api.whatsapp.com/send?text=${encodeURIComponent(message)}`;
    window.open(whatsappUrl, '_blank');
  };

  const chartData = balances.map(b => ({
    name: getParticipantName(b.participantId),
    value: b.amount
  }));

  return (
    <div className="space-y-12 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
        <div className="space-y-8">
          <h2 className="text-3xl font-black italic tracking-tighter uppercase border-b-4 border-zinc-950 pb-2">Settlement</h2>
          <div className="space-y-4">
            {settlements.length === 0 ? (
              <div className="text-center py-20 bg-zinc-50 rounded-[2.5rem]">
                <p className="text-zinc-400 font-black text-xs uppercase tracking-[0.2em] italic">All debts cleared</p>
              </div>
            ) : (
              settlements.map((s, idx) => (
                <div key={idx} className="bg-zinc-100 p-8 rounded-[2.5rem] border-2 border-transparent hover:border-zinc-950 transition-all space-y-6">
                  <div className="flex items-center justify-between">
                    <div className="text-left">
                      <span className="text-[10px] font-black uppercase tracking-widest text-zinc-400 block mb-2">Debtor</span>
                      <p className="text-xl font-black tracking-tighter">{getParticipantName(s.from)}</p>
                    </div>
                    <div className="text-center px-4">
                      <i className="fa-solid fa-arrow-right text-zinc-300 text-xl"></i>
                      <p className="text-xl font-black text-zinc-950 mt-1">₹{s.amount.toFixed(2)}</p>
                    </div>
                    <div className="text-right">
                      <span className="text-[10px] font-black uppercase tracking-widest text-zinc-400 block mb-2">Creditor</span>
                      <p className="text-xl font-black tracking-tighter">{getParticipantName(s.to)}</p>
                    </div>
                  </div>

                  <div className="grid grid-cols-2 gap-3">
                    <button
                      onClick={() => handleWhatsAppRequest(s)}
                      className="bg-zinc-950 text-white text-[10px] font-black uppercase tracking-widest py-4 px-6 rounded-2xl transition-all flex items-center justify-center gap-2"
                    >
                      <i className="fa-brands fa-whatsapp text-sm"></i>
                      Request
                    </button>
                    <button
                      onClick={() => onSettle(s.from, s.to, s.amount)}
                      className="bg-white text-zinc-950 text-[10px] font-black uppercase tracking-widest py-4 px-6 rounded-2xl border-2 border-zinc-200 hover:border-zinc-950 transition-all"
                    >
                      Mark Paid
                    </button>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>

        <div className="space-y-8">
          <h2 className="text-3xl font-black italic tracking-tighter uppercase border-b-4 border-zinc-950 pb-2">Net Dues</h2>
          <div className="bg-white p-8 rounded-[2.5rem] border-2 border-zinc-100 h-[350px]">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData} layout="vertical" margin={{ left: 20 }}>
                <CartesianGrid strokeDasharray="3 3" horizontal={false} stroke="#f1f5f9" />
                <XAxis type="number" hide />
                <YAxis 
                  dataKey="name" 
                  type="category" 
                  width={80} 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{ fontSize: 10, fontWeight: 900, fill: '#000', textTransform: 'uppercase' }} 
                />
                <Tooltip 
                  cursor={{ fill: 'transparent' }}
                  contentStyle={{ borderRadius: '1rem', border: 'none', background: '#000', color: '#fff' }}
                  itemStyle={{ color: '#fff', fontSize: '12px', fontWeight: 'bold' }}
                />
