              <div>
                <span className="text-[10px] font-bold uppercase tracking-[0.2em] text-zinc-400 mb-2 block">Transaction Detail</span>
                <h3 className="text-3xl font-black tracking-tighter">{selectedExpense.description}</h3>
              </div>
              <button onClick={() => setSelectedExpense(null)} className="p-2 hover:bg-white/10 rounded-full transition-colors">
                <i className="fa-solid fa-xmark text-xl"></i>
              </button>
            </div>
            <div className="p-8 space-y-8">
              <div className="flex justify-between items-end">
                <div>
                  <p className="text-[10px] font-bold uppercase text-zinc-400 mb-1">Total Amount</p>
                  <p className="text-4xl font-black">₹{selectedExpense.amount.toFixed(2)}</p>
                </div>
                <div className="text-right">
                  <p className="text-[10px] font-bold uppercase text-zinc-400 mb-1">Payer</p>
                  <p className="text-lg font-bold">{participants.find(p => p.id === selectedExpense.payerId)?.name}</p>
                </div>
              </div>

              <div>
                <p className="text-[10px] font-bold uppercase text-zinc-400 mb-3 tracking-widest">Involved Members</p>
                <div className="flex flex-wrap gap-2">
                  {selectedExpense.participantIds.map(pId => (
                    <div key={pId} className="px-4 py-2 rounded-full bg-zinc-100 border border-zinc-200 text-xs font-bold uppercase">
                      {participants.find(p => p.id === pId)?.name}
                    </div>
                  ))}
                </div>
              </div>

              <div className="flex flex-col gap-3">
                {selectedExpense.category !== 'Payment' && (
                  <button 
                    onClick={() => handleSettleIndividual(selectedExpense)}
                    className="w-full bg-zinc-950 text-white py-4 rounded-2xl font-bold uppercase tracking-widest hover:bg-zinc-800 transition-all shadow-xl"
                  >
                    Settle this transaction
                  </button>
