              </div>
            </div>
          </div>
        </div>
      )}

      {/* Footer */}
      <footer className="bg-white border-t border-zinc-100 py-12">
        <div className="max-w-6xl mx-auto px-6 text-center">
          <div className="w-10 h-10 bg-zinc-950 rounded-lg flex items-center justify-center mx-auto mb-6">
            <i className="fa-solid fa-layer-group text-white text-xs"></i>
          </div>
          <p className="text-[10px] font-bold text-zinc-400 uppercase tracking-[0.5em]">splitIt &copy; 2024</p>
        </div>
      </footer>
    </div>
  );
};

