import React from 'react';
import { Participant, Settlement, Balance } from '../types.ts';
import { ResponsiveContainer, BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Cell } from 'recharts';

interface Props {
  participants: Participant[];
  balances: Balance[];
  settlements: Settlement[];
  totalSpent: number;
  onSettle: (fromId: string, toId: string, amount: number) => void;
  onUpdateUpi: (id: string, upiId: string) => void;
}

const SettlementView: React.FC<Props> = ({ participants, balances, settlements, totalSpent, onSettle, onUpdateUpi }) => {
  const getParticipant = (id: string) => participants.find(p => p.id === id);
  const getParticipantName = (id: string) => getParticipant(id)?.name || 'Unknown';

  const handleWhatsAppRequest = (s: Settlement) => {
    const payer = getParticipant(s.from);
    const payee = getParticipant(s.to);

    if (!payer || !payee) return;

    let targetUpi = payee.upiId;

    // If no UPI ID, prompt for it
    if (!targetUpi) {
      const input = prompt(`Enter UPI ID for ${payee.name} to include in the message:`, "");
      if (input === null) return; // cancelled
      if (input.trim()) {
        targetUpi = input.trim();
        onUpdateUpi(payee.id, targetUpi);
      }
    }

    let message = `Hi ${payer.name}, reminder from splitIt! 👋\n\nYou owe me *₹${s.amount.toFixed(2)}*.\n`;
    if (targetUpi) {
      const upiLink = `upi://pay?pa=${targetUpi}&pn=${encodeURIComponent(payee.name)}&am=${s.amount.toFixed(2)}&cu=INR`;
      message += `\nPay here: ${upiLink}\nUPI ID: *${targetUpi}*`;
    }

    const whatsappUrl = `https://api.whatsapp.com/send?text=${encodeURIComponent(message)}`;
    window.open(whatsappUrl, '_blank');
  };

  const chartData = balances.map(b => ({
    name: getParticipantName(b.participantId),
    value: b.amount
  }));

  return (
    <div className="space-y-12 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
        <div className="space-y-8">
          <h2 className="text-3xl font-black tracking-tighter uppercase border-b-4 border-zinc-950 pb-2">Settlement</h2>
          <div className="space-y-4">
            {settlements.length === 0 ? (
              <div className="text-center py-20 bg-zinc-50 rounded-[2.5rem]">
                <p className="text-zinc-400 font-bold text-xs uppercase tracking-[0.2em]">All settled up</p>
              </div>
            ) : (
              settlements.map((s, idx) => (
                <div key={idx} className="bg-zinc-50 p-8 rounded-[2.5rem] border-2 border-transparent hover:border-zinc-950 transition-all space-y-6">
                  <div className="flex items-center justify-between">
                    <div className="text-left">
                      <span className="text-[10px] font-bold uppercase tracking-widest text-zinc-400 block mb-2">From</span>
                      <p className="text-xl font-bold tracking-tighter">{getParticipantName(s.from)}</p>
                    </div>
                    <div className="text-center px-4">
                      <i className="fa-solid fa-arrow-right text-zinc-300 text-xl"></i>
                      <p className="text-xl font-black text-zinc-950 mt-1">₹{s.amount.toFixed(2)}</p>
                    </div>
                    <div className="text-right">
                      <span className="text-[10px] font-bold uppercase tracking-widest text-zinc-400 block mb-2">To</span>
                      <p className="text-xl font-bold tracking-tighter">{getParticipantName(s.to)}</p>
                    </div>
                  </div>

                  <div className="grid grid-cols-2 gap-3">
                    <button
                      onClick={() => handleWhatsAppRequest(s)}
                      className="bg-zinc-950 text-white text-[10px] font-bold uppercase tracking-widest py-4 px-6 rounded-2xl transition-all flex items-center justify-center gap-2"
                    >
                      <i className="fa-brands fa-whatsapp text-sm"></i>
                      WhatsApp Request
                    </button>
                    <button
                      onClick={() => onSettle(s.from, s.to, s.amount)}
                      className="bg-white text-zinc-950 text-[10px] font-bold uppercase tracking-widest py-4 px-6 rounded-2xl border-2 border-zinc-200 hover:border-zinc-950 transition-all"
                    >
                      Settle Balance
                    </button>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>

        <div className="space-y-8">
          <h2 className="text-3xl font-black tracking-tighter uppercase border-b-4 border-zinc-950 pb-2">Group Balances</h2>
          <div className="bg-white p-8 rounded-[2.5rem] border-2 border-zinc-100 h-[350px]">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData} layout="vertical" margin={{ left: 20 }}>
                <CartesianGrid strokeDasharray="3 3" horizontal={false} stroke="#f1f5f9" />
                <XAxis type="number" hide />
                <YAxis 
                  dataKey="name" 
                  type="category" 
                  width={80} 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{ fontSize: 10, fontWeight: 700, fill: '#000', textTransform: 'uppercase' }} 
                />
                <Tooltip 
                  cursor={{ fill: 'transparent' }}
                  contentStyle={{ borderRadius: '1rem', border: 'none', background: '#000', color: '#fff' }}
                  itemStyle={{ color: '#fff', fontSize: '12px', fontWeight: 'bold' }}
                />
                <Bar dataKey="value" radius={[0, 10, 10, 0]} barSize={30}>
                  {chartData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.value >= 0 ? '#000' : '#e4e4e7'} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      <div className="bg-zinc-950 p-12 rounded-[3rem] text-white flex flex-col md:flex-row items-center justify-between gap-12 shadow-2xl">
        <div className="text-center md:text-left">
          <h3 className="text-zinc-500 font-bold uppercase text-xs tracking-[0.3em] mb-4">Total Expenses</h3>
          <p className="text-7xl font-black tracking-tighter">₹{totalSpent.toFixed(2)}</p>
        </div>
        <div className="grid grid-cols-2 gap-4 w-full md:w-auto">
          <div className="bg-zinc-900 p-6 rounded-3xl border border-zinc-800 text-center">
            <span className="block text-[10px] font-bold text-zinc-500 uppercase tracking-widest mb-2">Avg / Head</span>
            <span className="text-2xl font-black">₹{(totalSpent / (participants.length || 1)).toFixed(2)}</span>
          </div>
          <div className="bg-zinc-900 p-6 rounded-3xl border border-zinc-800 text-center">
            <span className="block text-[10px] font-bold text-zinc-500 uppercase tracking-widest mb-2">Pending</span>
            <span className="text-2xl font-black">{settlements.length}</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default SettlementView;

import React, { useState, useRef } from 'react';
import { Participant, Expense } from '../types.ts';
import { parseReceipt } from '../services/geminiService.ts';

interface Props {
  participants: Participant[];
  onAdd: (expense: Omit<Expense, 'id'>) => void;
}

const ExpenseForm: React.FC<Props> = ({ participants, onAdd }) => {
  const [description, setDescription] = useState('');
  const [amount, setAmount] = useState('');
  const [payerId, setPayerId] = useState('');
  const [category, setCategory] = useState<Expense['category']>('Other');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedParticipants, setSelectedParticipants] = useState<string[]>([]);
  const [isScanning, setIsScanning] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const toggleParticipant = (id: string) => {
    setSelectedParticipants(prev => 
      prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id]
    );
  };

  const handleAll = () => {
    if (selectedParticipants.length === participants.length) {
      setSelectedParticipants([]);
    } else {
      setSelectedParticipants(participants.map(p => p.id));
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (description && amount && payerId && selectedParticipants.length > 0) {
      onAdd({
        description,
        amount: parseFloat(amount),
        payerId,
        participantIds: selectedParticipants,
        category,
        date: new Date(date).getTime()
      });
      setDescription('');
      setAmount('');
      setSelectedParticipants([]);
      setDate(new Date().toISOString().split('T')[0]);
    }
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsScanning(true);
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      const data = await parseReceipt(base64);
      if (data) {
        setDescription(data.description);
        setAmount(data.amount.toString());
        setCategory(data.category);
      }
      setIsScanning(false);
    };
    reader.readAsDataURL(file);
  };

  return (
    <div className="space-y-8 sticky top-32">
      <div className="flex justify-between items-end border-b-4 border-zinc-950 pb-4">
        <h2 className="text-3xl font-black tracking-tighter uppercase">Add</h2>
        <button
          onClick={() => fileInputRef.current?.click()}
          disabled={isScanning}
          className={`flex items-center gap-2 px-4 py-2 rounded-full text-[10px] font-bold uppercase tracking-widest transition-all ${
            isScanning 
            ? 'bg-zinc-100 text-zinc-400'
            : 'bg-zinc-100 hover:bg-zinc-950 hover:text-white'
          }`}
        >
          {isScanning ? <i className="fa-solid fa-spinner animate-spin"></i> : <i className="fa-solid fa-camera"></i>}
          {isScanning ? "Scanning..." : "Scan Receipt"}
        </button>
        <input type="file" accept="image/*" ref={fileInputRef} onChange={handleFileChange} className="hidden" />
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="space-y-2">
          <label className="text-[10px] font-bold uppercase tracking-widest text-zinc-400">Description</label>
          <input
            type="text"
            required
            value={description}
            onChange={e => setDescription(e.target.value)}
            className="w-full px-6 py-4 rounded-2xl bg-zinc-100 border-2 border-transparent focus:bg-white focus:border-zinc-950 outline-none transition-all text-sm font-bold uppercase tracking-widest"
            placeholder="e.g. Dinner, Movie"
          />
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div className="space-y-2">
            <label className="text-[10px] font-bold uppercase tracking-widest text-zinc-400">Amount</label>
            <div className="relative">
              <span className="absolute left-6 top-4 font-black text-zinc-400">₹</span>
              <input
                type="number"
                step="0.01"
                required
                value={amount}
                onChange={e => setAmount(e.target.value)}
                className="w-full pl-10 pr-6 py-4 rounded-2xl bg-zinc-100 border-2 border-transparent focus:bg-white focus:border-zinc-950 outline-none transition-all text-sm font-bold uppercase tracking-widest"
                placeholder="0.00"
              />
            </div>
          </div>
          <div className="space-y-2">
            <label className="text-[10px] font-bold uppercase tracking-widest text-zinc-400">Date</label>
            <input
              type="date"
              required
              value={date}
              onChange={e => setDate(e.target.value)}
              className="w-full px-6 py-4 rounded-2xl bg-zinc-100 border-2 border-transparent focus:bg-white focus:border-zinc-950 outline-none transition-all text-sm font-bold uppercase tracking-widest"
            />
          </div>
        </div>

        <div className="space-y-2">
          <label className="text-[10px] font-bold uppercase tracking-widest text-zinc-400">Category</label>
          <select
            value={category}
            onChange={e => setCategory(e.target.value as any)}
            className="w-full px-6 py-4 rounded-2xl bg-zinc-100 border-2 border-transparent focus:bg-white focus:border-zinc-950 outline-none transition-all text-sm font-bold uppercase tracking-widest"
          >
            <option value="Food">Food</option>
            <option value="Transport">Transport</option>
            <option value="Lodging">Lodging</option>
            <option value="Entertainment">Entertainment</option>
            <option value="Other">Other</option>
          </select>
        </div>

        <div className="space-y-2">
          <label className="text-[10px] font-bold uppercase tracking-widest text-zinc-400">Paid By</label>
          <select
            required
            value={payerId}
            onChange={e => setPayerId(e.target.value)}
            className="w-full px-6 py-4 rounded-2xl bg-zinc-100 border-2 border-transparent focus:bg-white focus:border-zinc-950 outline-none transition-all text-sm font-bold uppercase tracking-widest"
          >
            <option value="" disabled>Select payer...</option>
            {participants.map(p => (
              <option key={p.id} value={p.id}>{p.name.toUpperCase()}</option>
            ))}
          </select>
        </div>

        <div className="space-y-2">
          <div className="flex justify-between items-center mb-1">
            <label className="text-[10px] font-bold uppercase tracking-widest text-zinc-400">Split Among</label>
            <button type="button" onClick={handleAll} className="text-[10px] font-bold text-zinc-950 underline">Select All</button>
          </div>
          <div className="flex flex-wrap gap-2 p-4 bg-zinc-50 rounded-2xl border-2 border-zinc-100">
            {participants.map(p => (
              <button
                key={p.id}
                type="button"
                onClick={() => toggleParticipant(p.id)}
                className={`px-4 py-2 rounded-xl text-[10px] font-bold uppercase tracking-widest transition-all ${
                  selectedParticipants.includes(p.id)
                    ? 'bg-zinc-950 text-white'
                    : 'bg-white text-zinc-400 border border-zinc-200'
                }`}
              >
                {p.name}
              </button>
            ))}
          </div>
        </div>

        <button
          type="submit"
