                <Bar dataKey="value" radius={[0, 10, 10, 0]} barSize={30}>
                  {chartData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.value >= 0 ? '#000' : '#e4e4e7'} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      <div className="bg-zinc-950 p-12 rounded-[3rem] text-white flex flex-col md:flex-row items-center justify-between gap-12 shadow-2xl">
        <div className="text-center md:text-left">
          <h3 className="text-zinc-500 font-bold uppercase text-xs tracking-[0.3em] mb-4">Total Expenses</h3>
          <p className="text-7xl font-black tracking-tighter">₹{totalSpent.toFixed(2)}</p>
