export default ParticipantManager;

import React, { useState, useRef } from 'react';
import { Participant, Expense } from '../types.ts';
import { parseReceipt } from '../services/geminiService.ts';

interface Props {
  participants: Participant[];
  onAdd: (expense: Omit<Expense, 'id'>) => void;
}

const ExpenseForm: React.FC<Props> = ({ participants, onAdd }) => {
  const [description, setDescription] = useState('');
  const [amount, setAmount] = useState('');
  const [payerId, setPayerId] = useState('');
  const [category, setCategory] = useState<Expense['category']>('Other');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedParticipants, setSelectedParticipants] = useState<string[]>([]);
  const [isScanning, setIsScanning] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const toggleParticipant = (id: string) => {
    setSelectedParticipants(prev => 
      prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id]
    );
  };

  const handleAll = () => {
    if (selectedParticipants.length === participants.length) {
      setSelectedParticipants([]);
    } else {
      setSelectedParticipants(participants.map(p => p.id));
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (description && amount && payerId && selectedParticipants.length > 0) {
      onAdd({
        description,
        amount: parseFloat(amount),
        payerId,
        participantIds: selectedParticipants,
        category,
        date: new Date(date).getTime()
      });
      setDescription('');
      setAmount('');
      setSelectedParticipants([]);
      setDate(new Date().toISOString().split('T')[0]);
    }
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsScanning(true);
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      const data = await parseReceipt(base64);
      if (data) {
        setDescription(data.description);
        setAmount(data.amount.toString());
        setCategory(data.category);
      }
      setIsScanning(false);
    };
    reader.readAsDataURL(file);
  };

  return (
    <div className="space-y-6 sm:space-y-8 lg:sticky lg:top-32 mb-8 lg:mb-0">
      <div className="flex justify-between items-end border-b-4 border-zinc-950 pb-4">
        <h2 className="text-2xl sm:text-3xl font-black tracking-tighter uppercase">Add Expenses</h2>
        <button
          onClick={() => fileInputRef.current?.click()}
          disabled={isScanning}
          className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-[10px] font-bold uppercase tracking-widest transition-all ${
            isScanning 
            ? 'bg-zinc-100 text-zinc-400'
            : 'bg-zinc-100 hover:bg-zinc-950 hover:text-white'
          }`}
        >
          {isScanning ? <i className="fa-solid fa-spinner animate-spin"></i> : <i className="fa-solid fa-camera"></i>}
          <span>Scan</span>
        </button>
        <input type="file" accept="image/*" ref={fileInputRef} onChange={handleFileChange} className="hidden" />
      </div>

      <form onSubmit={handleSubmit} className="space-y-5 sm:space-y-6">
        <div className="space-y-2">
          <label className="text-[10px] font-bold uppercase tracking-widest text-zinc-400">Description</label>
          <input
            type="text"
            required
            value={description}
            onChange={e => setDescription(e.target.value)}
            className="w-full px-5 py-4 rounded-2xl bg-zinc-100 border-2 border-transparent focus:bg-white focus:border-zinc-950 outline-none transition-all text-sm font-bold uppercase tracking-widest"
            placeholder="What was it for?"
          />
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div className="space-y-2">
            <label className="text-[10px] font-bold uppercase tracking-widest text-zinc-400">Amount</label>
            <div className="relative">
              <span className="absolute left-5 top-4 font-black text-zinc-400">₹</span>
              <input
                type="number"
                step="0.01"
                required
                value={amount}
                onChange={e => setAmount(e.target.value)}
                className="w-full pl-10 pr-5 py-4 rounded-2xl bg-zinc-100 border-2 border-transparent focus:bg-white focus:border-zinc-950 outline-none transition-all text-sm font-bold uppercase tracking-widest"
                placeholder="0.00"
              />
            </div>
          </div>
          <div className="space-y-2">
            <label className="text-[10px] font-bold uppercase tracking-widest text-zinc-400">Date</label>
            <input
              type="date"
              required
              value={date}
              onChange={e => setDate(e.target.value)}
              className="w-full px-4 py-4 rounded-2xl bg-zinc-100 border-2 border-transparent focus:bg-white focus:border-zinc-950 outline-none transition-all text-xs font-bold uppercase tracking-widest"
            />
          </div>
        </div>

        <div className="space-y-2">
          <label className="text-[10px] font-bold uppercase tracking-widest text-zinc-400">Category</label>
          <select
            value={category}
            onChange={e => setCategory(e.target.value as any)}
            className="w-full px-5 py-4 rounded-2xl bg-zinc-100 border-2 border-transparent focus:bg-white focus:border-zinc-950 outline-none transition-all text-xs font-bold uppercase tracking-widest appearance-none"
          >
            <option value="Food">Food</option>
            <option value="Transport">Transport</option>
            <option value="Lodging">Lodging</option>
            <option value="Entertainment">Entertainment</option>
            <option value="Other">Other</option>
          </select>
        </div>

        <div className="space-y-2">
          <label className="text-[10px] font-bold uppercase tracking-widest text-zinc-400">Paid By</label>
          <select
            required
            value={payerId}
            onChange={e => setPayerId(e.target.value)}
            className="w-full px-5 py-4 rounded-2xl bg-zinc-100 border-2 border-transparent focus:bg-white focus:border-zinc-950 outline-none transition-all text-xs font-bold uppercase tracking-widest appearance-none"
          >
            <option value="" disabled>Who paid?</option>
            {participants.map(p => (
              <option key={p.id} value={p.id}>{p.name.toUpperCase()}</option>
            ))}
          </select>
        </div>

        <div className="space-y-2">
          <div className="flex justify-between items-center px-1">
            <label className="text-[10px] font-bold uppercase tracking-widest text-zinc-400">Split Among</label>
            <button type="button" onClick={handleAll} className="text-[10px] font-bold text-zinc-950 underline underline-offset-2">Select All</button>
          </div>
          <div className="flex flex-wrap gap-2 p-4 bg-zinc-50 rounded-2xl border-2 border-zinc-100">
            {participants.length === 0 ? (
              <p className="text-[9px] font-bold text-zinc-300 uppercase tracking-widest w-full text-center">Add squad members first</p>
            ) : (
              participants.map(p => (
                <button
                  key={p.id}
                  type="button"
                  onClick={() => toggleParticipant(p.id)}
                  className={`px-3 py-2 rounded-xl text-[10px] font-bold uppercase tracking-widest transition-all ${
                    selectedParticipants.includes(p.id)
                      ? 'bg-zinc-950 text-white'
                      : 'bg-white text-zinc-400 border border-zinc-200'
                  }`}
                >
                  {p.name}
                </button>
              ))
            )}
          </div>
        </div>

        <button
          type="submit"
          className="w-full bg-zinc-950 text-white py-5 rounded-2xl font-bold uppercase tracking-widest text-xs shadow-lg hover:bg-zinc-800 transition-all active:scale-95"
        >
          Record Transaction
        </button>
      </form>
    </div>
  );
};

