import React from 'react';
import { Participant, Settlement, Balance } from '../types.ts';
import { ResponsiveContainer, BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Cell } from 'recharts';

interface Props {
  participants: Participant[];
  balances: Balance[];
  settlements: Settlement[];
  totalSpent: number;
  onSettle: (fromId: string, toId: string, amount: number) => void;
  onUpdateUpi: (id: string, upiId: string) => void;
}

const SettlementView: React.FC<Props> = ({ participants, balances, settlements, totalSpent, onSettle, onUpdateUpi }) => {
  const getParticipant = (id: string) => participants.find(p => p.id === id);
  const getParticipantName = (id: string) => getParticipant(id)?.name || 'Guest';

  const handleWhatsAppRequest = (s: Settlement) => {
    const payer = getParticipant(s.from);
    const payee = getParticipant(s.to);
    if (!payer || !payee) return;
    let targetUpi = payee.upiId;
    if (!targetUpi) {
      const input = prompt(`Enter UPI ID for ${payee.name} to include in message:`, "");
      if (input === null) return; 
      if (input.trim()) {
        targetUpi = input.trim();
        onUpdateUpi(payee.id, targetUpi);
      }
    }
    let message = `Hi ${payer.name}, splitIt reminder! ⚡\n\nYou owe me *₹${s.amount.toFixed(2)}*.\n`;
    if (targetUpi) {
      const upiLink = `upi://pay?pa=${targetUpi}&pn=${encodeURIComponent(payee.name)}&am=${s.amount.toFixed(2)}&cu=INR`;
      message += `\nPay: ${upiLink}\nUPI ID: *${targetUpi}*`;
    }
    const whatsappUrl = `https://api.whatsapp.com/send?text=${encodeURIComponent(message)}`;
    window.open(whatsappUrl, '_blank');
  };

  const chartData = balances.map(b => ({
    name: getParticipantName(b.participantId),
    value: b.amount
  }));

  return (
    <div className="space-y-8 sm:space-y-12 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 sm:gap-12">
        {/* Settlements */}
        <div className="space-y-6 sm:space-y-8">
          <h2 className="text-2xl sm:text-3xl font-black tracking-tighter uppercase border-b-4 border-zinc-950 pb-2">Settlement</h2>
          <div className="space-y-4">
            {settlements.length === 0 ? (
              <div className="text-center py-12 sm:py-20 bg-zinc-50 rounded-2xl border-2 border-dashed border-zinc-100">
                <p className="text-zinc-400 font-bold text-xs uppercase tracking-[0.2em]">All settled up</p>
              </div>
            ) : (
              settlements.map((s, idx) => (
                <div key={idx} className="bg-zinc-50 p-6 sm:p-8 rounded-2xl border-2 border-transparent hover:border-zinc-950 transition-all space-y-6">
                  <div className="flex items-center justify-between gap-2">
                    <div className="flex-1 min-w-0">
                      <span className="text-[9px] font-bold uppercase tracking-widest text-zinc-400 block mb-1">From</span>
                      <p className="text-base sm:text-lg font-bold truncate uppercase">{getParticipantName(s.from)}</p>
                    </div>
                    <div className="flex flex-col items-center px-2">
                      <i className="fa-solid fa-arrow-right text-zinc-300"></i>
                      <p className="text-sm sm:text-lg font-black text-zinc-950 mt-1">₹{s.amount.toFixed(2)}</p>
                    </div>
                    <div className="flex-1 min-w-0 text-right">
                      <span className="text-[9px] font-bold uppercase tracking-widest text-zinc-400 block mb-1">To</span>
                      <p className="text-base sm:text-lg font-bold truncate uppercase">{getParticipantName(s.to)}</p>
                    </div>
                  </div>

                  <div className="grid grid-cols-2 gap-3">
                    <button
                      onClick={() => handleWhatsAppRequest(s)}
                      className="bg-zinc-950 text-white text-[9px] font-bold uppercase tracking-widest py-3.5 px-4 rounded-xl transition-all flex items-center justify-center gap-2"
                    >
                      <i className="fa-brands fa-whatsapp text-sm"></i>
                      WhatsApp
                    </button>
                    <button
                      onClick={() => onSettle(s.from, s.to, s.amount)}
                      className="bg-white text-zinc-950 text-[9px] font-bold uppercase tracking-widest py-3.5 px-4 rounded-xl border-2 border-zinc-200 hover:border-zinc-950 transition-all"
                    >
                      Mark Paid
                    </button>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>

        {/* Chart */}
        <div className="space-y-6 sm:space-y-8">
          <h2 className="text-2xl sm:text-3xl font-black tracking-tighter uppercase border-b-4 border-zinc-950 pb-2">Group Balances</h2>
          <div className="bg-white p-6 rounded-2xl border-2 border-zinc-100 h-[300px] sm:h-[350px]">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData} layout="vertical" margin={{ left: 10, right: 10 }}>
                <CartesianGrid strokeDasharray="3 3" horizontal={false} stroke="#f1f5f9" />
                <XAxis type="number" hide />
                <YAxis 
                  dataKey="name" 
                  type="category" 
                  width={60} 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{ fontSize: 9, fontWeight: 700, fill: '#000', textTransform: 'uppercase' }} 
                />
                <Tooltip 
                  cursor={{ fill: 'transparent' }}
                  contentStyle={{ borderRadius: '1rem', border: 'none', background: '#000', color: '#fff', fontSize: '10px' }}
                />
                <Bar dataKey="value" radius={[0, 4, 4, 0]} barSize={24}>
                  {chartData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.value >= 0 ? '#000' : '#e4e4e7'} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* Aggregate */}
      <div className="bg-zinc-950 p-8 sm:p-12 rounded-3xl text-white flex flex-col sm:flex-row items-center justify-between gap-8 sm:gap-12 shadow-2xl">
        <div className="text-center sm:text-left">
          <h3 className="text-zinc-500 font-bold uppercase text-[10px] tracking-[0.3em] mb-2 sm:mb-4">Total Expenses</h3>
          <p className="text-4xl sm:text-6xl font-black tracking-tighter">₹{totalSpent.toFixed(2)}</p>
        </div>
        <div className="grid grid-cols-2 gap-3 sm:gap-4 w-full sm:w-auto">
          <div className="bg-zinc-900 p-4 sm:p-6 rounded-2xl border border-zinc-800 text-center">
            <span className="block text-[8px] sm:text-[10px] font-bold text-zinc-500 uppercase tracking-widest mb-1 sm:mb-2">Avg / Head</span>
            <span className="text-xl sm:text-2xl font-black">₹{(totalSpent / (participants.length || 1)).toFixed(2)}</span>
          </div>
          <div className="bg-zinc-900 p-4 sm:p-6 rounded-2xl border border-zinc-800 text-center">
            <span className="block text-[8px] sm:text-[10px] font-bold text-zinc-500 uppercase tracking-widest mb-1 sm:mb-2">Pending</span>
            <span className="text-xl sm:text-2xl font-black">{settlements.length}</span>
          </div>
        </div>
      </div>
    </div>
  );
};

