import React, { useState, useRef } from 'react';
import { Participant, Expense } from '../types.ts';
import { parseReceipt } from '../services/geminiService.ts';

interface Props {
  participants: Participant[];
  onAdd: (expense: Omit<Expense, 'id'>) => void;
}

const ExpenseForm: React.FC<Props> = ({ participants, onAdd }) => {
  const [description, setDescription] = useState('');
  const [amount, setAmount] = useState('');
  const [payerId, setPayerId] = useState('');
  const [category, setCategory] = useState<Expense['category']>('Other');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedParticipants, setSelectedParticipants] = useState<string[]>([]);
  const [isScanning, setIsScanning] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const toggleParticipant = (id: string) => {
    setSelectedParticipants(prev => 
      prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id]
    );
  };

  const handleAll = () => {
    if (selectedParticipants.length === participants.length) {
      setSelectedParticipants([]);
    } else {
      setSelectedParticipants(participants.map(p => p.id));
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (description && amount && payerId && selectedParticipants.length > 0) {
      onAdd({
        description,
        amount: parseFloat(amount),
        payerId,
        participantIds: selectedParticipants,
        category,
        date: new Date(date).getTime()
      });
      setDescription('');
      setAmount('');
      setSelectedParticipants([]);
      setDate(new Date().toISOString().split('T')[0]);
    }
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsScanning(true);
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      const data = await parseReceipt(base64);
      if (data) {
        setDescription(data.description);
        setAmount(data.amount.toString());
        setCategory(data.category);
      }
      setIsScanning(false);
    };
    reader.readAsDataURL(file);
  };

  return (
    <div className="bg-white rounded-3xl p-8 shadow-sm border border-slate-100">
      <div className="flex justify-between items-center mb-8">
        <div className="flex items-center gap-2 text-[#1e293b]">
          <i className="fa-solid fa-receipt text-[#4f46e5]"></i>
          <h2 className="text-xl font-bold">Add Record</h2>
        </div>
        <button
          onClick={() => fileInputRef.current?.click()}
          disabled={isScanning}
          className="flex items-center gap-2 px-4 py-2 rounded-xl text-[10px] font-bold text-[#4f46e5] bg-[#eef2ff] hover:bg-[#e0e7ff] transition-all uppercase tracking-wider"
        >
          {isScanning ? <i className="fa-solid fa-spinner animate-spin"></i> : <i className="fa-solid fa-camera"></i>}
          <span>SCAN RECEIPT</span>
        </button>
        <input type="file" accept="image/*" ref={fileInputRef} onChange={handleFileChange} className="hidden" />
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="space-y-2">
          <label className="text-[10px] font-bold uppercase tracking-wider text-slate-400">DESCRIPTION</label>
          <input
            type="text"
            required
            value={description}
            onChange={e => setDescription(e.target.value)}
            className="w-full px-4 py-4 rounded-xl bg-slate-50 border border-slate-100 focus:outline-none focus:border-[#4f46e5] text-sm placeholder:text-slate-300"
            placeholder="e.g. Starbucks, Movie Night"
          />
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div className="space-y-2">
            <label className="text-[10px] font-bold uppercase tracking-wider text-slate-400">AMOUNT</label>
            <div className="relative">
              <span className="absolute left-4 top-1/2 -translate-y-1/2 font-bold text-slate-400">₹</span>
              <input
                type="number"
                step="0.01"
                required
                value={amount}
                onChange={e => setAmount(e.target.value)}
                className="w-full pl-8 pr-4 py-4 rounded-xl bg-slate-50 border border-slate-100 focus:outline-none focus:border-[#4f46e5] text-sm"
                placeholder="0.00"
              />
            </div>
          </div>
          <div className="space-y-2">
            <label className="text-[10px] font-bold uppercase tracking-wider text-slate-400">DATE</label>
            <input
              type="date"
              required
              value={date}
              onChange={e => setDate(e.target.value)}
              className="w-full px-4 py-4 rounded-xl bg-slate-50 border border-slate-100 focus:outline-none focus:border-[#4f46e5] text-sm"
            />
          </div>
        </div>

        <div className="space-y-2">
          <label className="text-[10px] font-bold uppercase tracking-wider text-slate-400">CATEGORY</label>
          <select
            value={category}
            onChange={e => setCategory(e.target.value as any)}
            className="w-full px-4 py-4 rounded-xl bg-slate-50 border border-slate-100 focus:outline-none focus:border-[#4f46e5] text-sm appearance-none cursor-pointer"
          >
            <option value="Food">Food</option>
            <option value="Transport">Transport</option>
            <option value="Lodging">Lodging</option>
            <option value="Entertainment">Entertainment</option>
            <option value="Other">Other</option>
          </select>
        </div>

        <div className="space-y-2">
          <label className="text-[10px] font-bold uppercase tracking-wider text-slate-400">WHO PAID?</label>
          <select
            required
            value={payerId}
            onChange={e => setPayerId(e.target.value)}
            className="w-full px-4 py-4 rounded-xl bg-slate-50 border border-slate-100 focus:outline-none focus:border-[#4f46e5] text-sm appearance-none cursor-pointer"
          >
            <option value="" disabled>Select payer</option>
            {participants.map(p => (
              <option key={p.id} value={p.id}>{p.name}</option>
            ))}
          </select>
        </div>

        <div className="space-y-2">
          <div className="flex justify-between items-center px-1">
            <label className="text-[10px] font-bold uppercase tracking-wider text-slate-400">SPLIT AMONG</label>
            <button type="button" onClick={handleAll} className="text-[10px] font-bold text-[#4f46e5] uppercase">TOGGLE ALL</button>
          </div>
          <div className="flex flex-wrap gap-2 p-2 min-h-[50px]">
            {participants.length === 0 ? (
              <p className="text-[9px] text-slate-400 italic w-full text-center py-2">No members yet</p>
            ) : (
              participants.map(p => (
                <button
                  key={p.id}
                  type="button"
                  onClick={() => toggleParticipant(p.id)}
                  className={`px-3 py-1.5 rounded-lg text-[10px] font-bold border transition-all ${
                    selectedParticipants.includes(p.id)
                      ? 'bg-[#4f46e5] text-white border-[#4f46e5]'
                      : 'bg-white text-slate-400 border-slate-200'
                  }`}
                >
                  {p.name}
                </button>
              ))
            )}
          </div>
        </div>

        <button
          type="submit"
          className="w-full bg-[#4f46e5] text-white py-5 rounded-2xl font-bold text-sm shadow-md hover:bg-[#4338ca] transition-all active:scale-[0.98]"
        >
          Add Record
        </button>
      </form>
    </div>
  );
};

export default ExpenseForm;

import React from 'react';
import { Participant, Settlement, Balance } from '../types.ts';
import { ResponsiveContainer, BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Cell } from 'recharts';

interface Props {
  participants: Participant[];
  balances: Balance[];
  settlements: Settlement[];
  totalSpent: number;
  onSettle: (fromId: string, toId: string, amount: number) => void;
  onUpdateUpi: (id: string, upiId: string) => void;
}

const SettlementView: React.FC<Props> = ({ participants, balances, settlements, totalSpent, onSettle, onUpdateUpi }) => {
  const getParticipant = (id: string) => participants.find(p => p.id === id);
  const getParticipantName = (id: string) => getParticipant(id)?.name || 'Guest';

  const handleWhatsAppRequest = (s: Settlement) => {
    const payer = getParticipant(s.from);
    const payee = getParticipant(s.to);
    if (!payer || !payee) return;
    let targetUpi = payee.upiId;
    if (!targetUpi) {
      const input = prompt(`Enter UPI ID for ${payee.name}:`, "");
      if (input === null) return; 
      if (input.trim()) {
        targetUpi = input.trim();
        onUpdateUpi(payee.id, targetUpi);
      }
    }
    let message = `Hi ${payer.name}, reminder from SplitItAI! 👋\n\nYou owe me *₹${s.amount.toFixed(2)}*.\n`;
    if (targetUpi) {
      const upiLink = `upi://pay?pa=${targetUpi}&pn=${encodeURIComponent(payee.name)}&am=${s.amount.toFixed(2)}&cu=INR`;
      message += `\nPay: ${upiLink}\nUPI ID: *${targetUpi}*`;
    }
    const whatsappUrl = `https://api.whatsapp.com/send?text=${encodeURIComponent(message)}`;
    window.open(whatsappUrl, '_blank');
  };

  const chartData = balances.map(b => ({
    name: getParticipantName(b.participantId),
    value: b.amount
  }));

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        {/* Settlements */}
        <div className="bg-white rounded-3xl p-8 shadow-sm border border-slate-100">
          <div className="flex items-center gap-2 mb-8 text-[#1e293b]">
            <i className="fa-solid fa-handshake text-[#4f46e5]"></i>
            <h2 className="text-xl font-bold">Suggested Payments</h2>
          </div>
          <div className="space-y-4">
            {settlements.length === 0 ? (
              <div className="text-center py-12 bg-slate-50 rounded-2xl">
                <p className="text-slate-400 font-bold text-xs uppercase tracking-widest">Everything is settled!</p>
              </div>
            ) : (
              settlements.map((s, idx) => (
                <div key={idx} className="bg-slate-50 p-6 rounded-2xl border border-slate-100 hover:border-[#4f46e5] transition-all">
                  <div className="flex items-center justify-between mb-4">
                    <div className="text-left">
                      <span className="text-[10px] font-bold uppercase text-slate-400 block mb-1">Debtor</span>
                      <p className="font-bold text-[#1e293b]">{getParticipantName(s.from)}</p>
                    </div>
                    <div className="text-center flex flex-col items-center">
                      <i className="fa-solid fa-arrow-right text-[#4f46e5] mb-1"></i>
                      <p className="text-lg font-bold text-[#1e293b]">₹{s.amount.toFixed(2)}</p>
                    </div>
                    <div className="text-right">
                      <span className="text-[10px] font-bold uppercase text-slate-400 block mb-1">Creditor</span>
                      <p className="font-bold text-[#1e293b]">{getParticipantName(s.to)}</p>
                    </div>
                  </div>

                  <div className="grid grid-cols-2 gap-3">
                    <button
                      onClick={() => handleWhatsAppRequest(s)}
                      className="bg-green-500 text-white text-[10px] font-bold uppercase py-3 rounded-xl hover:bg-green-600 transition-colors flex items-center justify-center gap-2"
                    >
                      <i className="fa-brands fa-whatsapp text-sm"></i>
                      Request
                    </button>
                    <button
                      onClick={() => onSettle(s.from, s.to, s.amount)}
                      className="bg-[#4f46e5] text-white text-[10px] font-bold uppercase py-3 rounded-xl hover:bg-[#4338ca] transition-colors"
                    >
                      Mark Paid
                    </button>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>

        {/* Balance Distribution */}
        <div className="bg-white rounded-3xl p-8 shadow-sm border border-slate-100">
          <div className="flex items-center gap-2 mb-8 text-[#1e293b]">
            <i className="fa-solid fa-chart-bar text-[#4f46e5]"></i>
            <h2 className="text-xl font-bold">Balance Overview</h2>
          </div>
          <div className="h-[350px]">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData} layout="vertical" margin={{ left: 10, right: 10 }}>
                <CartesianGrid strokeDasharray="3 3" horizontal={false} stroke="#f1f5f9" />
                <XAxis type="number" hide />
                <YAxis 
                  dataKey="name" 
                  type="category" 
                  width={60} 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{ fontSize: 10, fontWeight: 700, fill: '#64748b' }} 
                />
                <Tooltip 
                  cursor={{ fill: 'transparent' }}
                  contentStyle={{ borderRadius: '1rem', border: 'none', background: '#1e293b', color: '#fff' }}
                />
                <Bar dataKey="value" radius={[0, 4, 4, 0]} barSize={24}>
                  {chartData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.value >= 0 ? '#10b981' : '#f43f5e'} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* Summary Aggregate */}
      <div className="bg-[#1e293b] p-8 sm:p-12 rounded-[2.5rem] text-white flex flex-col sm:flex-row items-center justify-between gap-8 shadow-xl">
        <div className="text-center sm:text-left">
          <h3 className="text-slate-500 font-bold uppercase text-[10px] tracking-[0.2em] mb-2">Aggregate Spent</h3>
          <p className="text-5xl font-bold tracking-tight">₹{totalSpent.toFixed(2)}</p>
        </div>
        <div className="grid grid-cols-2 gap-4 w-full sm:w-auto">
          <div className="bg-slate-800 p-6 rounded-2xl border border-slate-700 text-center">
            <span className="block text-[10px] font-bold text-slate-500 uppercase mb-2">Per Person</span>
            <span className="text-xl font-bold">₹{(totalSpent / (participants.length || 1)).toFixed(2)}</span>
          </div>
          <div className="bg-slate-800 p-6 rounded-2xl border border-slate-700 text-center">
            <span className="block text-[10px] font-bold text-slate-500 uppercase mb-2">Active Dues</span>
            <span className="text-xl font-bold">{settlements.length}</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default SettlementView;

export interface Participant {
  id: string;
  name: string;
  avatar: string;
}

export interface Expense {
  id: string;
  description: string;
  amount: number;
  payerId: string;
  participantIds: string[];
  date: number;
  category: 'Food' | 'Transport' | 'Lodging' | 'Entertainment' | 'Payment' | 'Other';
}

export interface Settlement {
  from: string;
  to: string;
  amount: number;
}

export interface Balance {
  participantId: string;
  amount: number;
}

import React, { useState, useMemo, useEffect } from 'react';
import { Participant, Expense, Settlement, Balance } from './types.ts';
import ParticipantManager from './components/ParticipantManager.tsx';
import ExpenseForm from './components/ExpenseForm.tsx';
import SettlementView from './components/SettlementView.tsx';
import { calculateBalances, calculateSettlements } from './utils/calculation.ts';

const App: React.FC = () => {
  const [participants, setParticipants] = useState<Participant[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [activeTab, setActiveTab] = useState<'expenses' | 'settlement'>('expenses');
  const [selectedExpense, setSelectedExpense] = useState<Expense | null>(null);

  useEffect(() => {
    const hash = window.location.hash.substring(1);
    if (hash) {
      try {
        const decoded = JSON.parse(atob(hash));
        if (decoded.participants && decoded.expenses) {
          setParticipants(decoded.participants);
          setExpenses(decoded.expenses);
          window.location.hash = ""; 
          return;
        }
      } catch (e) {
        console.error("Failed to parse shared link", e);
      }
    }

    const savedParticipants = localStorage.getItem('splitit_participants');
    const savedExpenses = localStorage.getItem('splitit_expenses');
    if (savedParticipants) setParticipants(JSON.parse(savedParticipants));
    if (savedExpenses) setExpenses(JSON.parse(savedExpenses));
  }, []);

  useEffect(() => {
    localStorage.setItem('splitit_participants', JSON.stringify(participants));
    localStorage.setItem('splitit_expenses', JSON.stringify(expenses));
  }, [participants, expenses]);

  const addParticipant = (name: string) => {
    const newP: Participant = {
      id: crypto.randomUUID(),
      name,
      avatar: `https://api.dicebear.com/7.x/initials/svg?seed=${name}&backgroundColor=4f46e5&textColor=ffffff`
    };
    setParticipants([...participants, newP]);
  };

  const removeParticipant = (id: string) => {
    setParticipants(participants.filter(p => p.id !== id));
    setExpenses(expenses.filter(e => e.payerId !== id && !e.participantIds.includes(id)));
  };

  const addExpense = (newExp: Omit<Expense, 'id'>) => {
    const exp: Expense = { ...newExp, id: crypto.randomUUID() };
    setExpenses([exp, ...expenses]);
  };

  const removeExpense = (id: string) => {
    setExpenses(expenses.filter(e => e.id !== id));
    if (selectedExpense?.id === id) setSelectedExpense(null);
  };

  const handleSettleIndividual = (expense: Expense) => {
    const payer = participants.find(p => p.id === expense.payerId);
    if (!payer) return;
    const perPerson = expense.amount / expense.participantIds.length;
    expense.participantIds.forEach(pId => {
      if (pId === expense.payerId) return;
      const borrower = participants.find(p => p.id === pId);
      if (!borrower) return;
      addExpense({
        description: `Settled: ${borrower.name} for ${expense.description}`,
        amount: perPerson,
        payerId: pId,
        participantIds: [expense.payerId],
        category: 'Payment',
        date: Date.now()
      });
    });
    setSelectedExpense(null);
  };

  const handleSettle = (fromId: string, toId: string, amount: number) => {
    const fromName = participants.find(p => p.id === fromId)?.name || 'Someone';
    const toName = participants.find(p => p.id === toId)?.name || 'Someone';
    addExpense({
      description: `Settlement: ${fromName} to ${toName}`,
      amount,
      payerId: fromId,
      participantIds: [toId],
      category: 'Payment',
      date: Date.now()
    });
  };

  const { balances, settlements, totalSpent } = useMemo(() => {
    const bals = calculateBalances(participants, expenses);
    return {
      balances: bals,
      settlements: calculateSettlements([...bals]),
      totalSpent: expenses.reduce((acc, curr) => curr.category !== 'Payment' ? acc + curr.amount : acc, 0)
    };
  }, [participants, expenses]);

  return (
    <div className="min-h-screen bg-[#f8fafc] text-slate-900 flex flex-col font-sans">
      {/* Header */}
      <header className="bg-white border-b border-slate-100 sticky top-0 z-30">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 h-20 flex items-center justify-between">
          <div className="flex flex-col">
            <div className="flex items-center gap-2">
              <div className="w-8 h-8 bg-[#4f46e5] rounded-md flex items-center justify-center text-white text-lg">
                <i className="fa-solid fa-wallet"></i>
              </div>
              <h1 className="text-2xl font-bold text-[#1e293b] tracking-tight">
                SplitIt
              </h1>
            </div>
            <p className="text-[10px] font-bold text-slate-400 tracking-[0.1em] mt-0.5">
              good times in, awkward math out.
            </p>
          </div>

          <nav className="flex bg-[#f1f5f9] p-1 rounded-xl">
            <button
              onClick={() => setActiveTab('expenses')}
              className={`px-6 py-2 rounded-lg text-sm font-semibold transition-all ${
                activeTab === 'expenses' ? 'bg-white text-[#4f46e5] shadow-sm' : 'text-slate-500 hover:text-slate-700'
              }`}
            >
              Overview
            </button>
            <button
              onClick={() => setActiveTab('settlement')}
              className={`px-6 py-2 rounded-lg text-sm font-semibold transition-all ${
                activeTab === 'settlement' ? 'bg-white text-[#4f46e5] shadow-sm' : 'text-slate-500 hover:text-slate-700'
              }`}
            >
              Settlement
            </button>
          </nav>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 max-w-7xl mx-auto w-full px-4 sm:px-6 py-8">
        {activeTab === 'expenses' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
            {/* The Squad */}
            <div className="lg:col-span-3">
              <ParticipantManager participants={participants} onAdd={addParticipant} onRemove={removeParticipant} />
            </div>

            {/* Recent Activity */}
            <div className="lg:col-span-5 space-y-6">
              <div className="flex justify-between items-center">
                <div className="flex items-center gap-2 text-[#1e293b]">
                  <i className="fa-solid fa-list-ul text-[#4f46e5]"></i>
                  <h2 className="text-xl font-bold">Recent Activity</h2>
                </div>
                <span className="text-[10px] font-bold text-slate-400 bg-slate-100 px-3 py-1 rounded-full uppercase tracking-wider">
                  {expenses.length} Records
                </span>
              </div>

              <div className="min-h-[400px] bg-white border-2 border-dashed border-slate-200 rounded-3xl p-8 flex flex-col items-center justify-center text-center">
                {expenses.length === 0 ? (
                  <>
                    <div className="w-16 h-16 bg-slate-50 rounded-full flex items-center justify-center text-slate-300 mb-4">
                      <i className="fa-solid fa-receipt text-2xl"></i>
                    </div>
                    <h3 className="text-lg font-bold text-[#1e293b]">Clean slate!</h3>
                    <p className="text-sm text-slate-400 max-w-[200px] mt-2">
                      Add an expense or scan a receipt to start splitting.
                    </p>
                  </>
                ) : (
                  <div className="w-full space-y-4 text-left self-start">
                    {expenses.sort((a, b) => b.date - a.date).map(e => (
                      <div 
                        key={e.id} 
                        onClick={() => setSelectedExpense(e)}
                        className="p-4 rounded-xl border border-slate-100 hover:bg-slate-50 cursor-pointer transition-colors"
                      >
                        <div className="flex justify-between items-center">
                          <div>
                            <p className="font-bold text-[#1e293b]">{e.description}</p>
                            <p className="text-[10px] text-slate-400 uppercase font-bold mt-1">
                              {participants.find(p => p.id === e.payerId)?.name} • {new Date(e.date).toLocaleDateString()}
                            </p>
                          </div>
                          <p className="font-bold text-[#1e293b]">₹{e.amount.toFixed(2)}</p>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            </div>

            {/* Add Record */}
            <div className="lg:col-span-4">
              <ExpenseForm participants={participants} onAdd={addExpense} />
            </div>
          </div>
        ) : (
          <SettlementView
            participants={participants}
            balances={balances}
            settlements={settlements}
            totalSpent={totalSpent}
            onSettle={handleSettle}
          />
        )}
      </main>

      {/* Detail Modal */}
      {selectedExpense && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
          <div className="bg-white rounded-3xl max-w-lg w-full overflow-hidden shadow-2xl">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center">
              <h3 className="text-lg font-bold text-[#1e293b]">Expense Detail</h3>
              <button onClick={() => setSelectedExpense(null)} className="text-slate-400 hover:text-slate-600">
                <i className="fa-solid fa-xmark"></i>
              </button>
            </div>
            <div className="p-6 space-y-4">
              <div className="flex justify-between items-center">
                <span className="text-slate-400 text-sm">Description</span>
                <span className="font-bold">{selectedExpense.description}</span>
              </div>
              <div className="flex justify-between items-center">
                <span className="text-slate-400 text-sm">Amount</span>
                <span className="font-bold text-xl text-[#4f46e5]">₹{selectedExpense.amount.toFixed(2)}</span>
              </div>
              <div className="flex justify-between items-center">
                <span className="text-slate-400 text-sm">Who Paid</span>
                <span className="font-bold">{participants.find(p => p.id === selectedExpense.payerId)?.name}</span>
              </div>
              <div className="pt-4 flex flex-col gap-2">
                <button 
                  onClick={() => removeExpense(selectedExpense.id)}
                  className="w-full py-3 text-sm font-bold text-red-500 bg-red-50 rounded-xl hover:bg-red-100"
                >
                  Delete Expense
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Participant } from '../types.ts';

interface Props {
  participants: Participant[];
  onAdd: (name: string) => void;
  onRemove: (id: string) => void;
}

const ParticipantManager: React.FC<Props> = ({ participants, onAdd, onRemove }) => {
  const [name, setName] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (name.trim()) {
      onAdd(name.trim());
      setName('');
    }
  };

  return (
    <div className="bg-white rounded-3xl p-6 shadow-sm border border-slate-100 h-full">
      <div className="flex items-center gap-2 text-[#1e293b] mb-6">
        <i className="fa-solid fa-users text-[#4f46e5]"></i>
        <h2 className="text-xl font-bold">The Squad</h2>
      </div>

      <form onSubmit={handleSubmit} className="space-y-4">
        <input
          type="text"
          value={name}
          onChange={(e) => setName(e.target.value)}
          placeholder="Member Name"
          className="w-full px-4 py-3 rounded-xl bg-white border border-slate-200 text-sm focus:outline-none focus:border-[#4f46e5] transition-colors placeholder:text-slate-400"
        />
        <button
          type="submit"
          className="w-full bg-[#4f46e5] text-white px-5 py-4 rounded-xl font-bold text-sm hover:bg-[#4338ca] transition-all shadow-md active:scale-[0.98]"
        >
          Add to Squad
        </button>
      </form>

      <div className="mt-10 space-y-4">
        {participants.length === 0 ? (
          <p className="text-[11px] font-bold text-slate-300 uppercase tracking-widest text-center py-4">
            NO MEMBERS YET
          </p>
        ) : (
          participants.map(p => (
            <div key={p.id} className="flex items-center justify-between group p-3 rounded-xl hover:bg-slate-50 transition-colors">
              <div className="flex items-center gap-3">
                <img src={p.avatar} alt={p.name} className="w-8 h-8 rounded-lg bg-slate-100" />
