              </div>
              <button
                onClick={() => onRemove(p.id)}
                className="text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all p-1"
              >
                <i className="fa-solid fa-trash-can text-xs"></i>
              </button>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default ParticipantManager;

import React from 'react';
import { Participant, Settlement, Balance } from '../types.ts';
import { ResponsiveContainer, BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Cell } from 'recharts';

interface Props {
  participants: Participant[];
  balances: Balance[];
  settlements: Settlement[];
  totalSpent: number;
  onSettle: (fromId: string, toId: string, amount: number) => void;
}

const SettlementView: React.FC<Props> = ({ participants, balances, settlements, totalSpent, onSettle }) => {
  const getParticipant = (id: string) => participants.find(p => p.id === id);
  const getParticipantName = (id: string) => getParticipant(id)?.name || 'Guest';

  const handleWhatsAppRequest = (s: Settlement) => {
    const payer = getParticipant(s.from);
    const payee = getParticipant(s.to);
    if (!payer || !payee) return;

    let message = `Hi ${payer.name}, reminder from SplitIt! 👋\n\nYou owe me *₹${s.amount.toFixed(2)}*.`;
    const whatsappUrl = `https://api.whatsapp.com/send?text=${encodeURIComponent(message)}`;
    window.open(whatsappUrl, '_blank');
  };

  const chartData = balances.map(b => ({
    name: getParticipantName(b.participantId),
    value: b.amount
  }));

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        {/* Settlements */}
        <div className="bg-white rounded-3xl p-8 shadow-sm border border-slate-100">
          <div className="flex items-center gap-2 mb-8 text-[#1e293b]">
            <i className="fa-solid fa-handshake text-[#4f46e5]"></i>
            <h2 className="text-xl font-bold">Suggested Payments</h2>
          </div>
          <div className="space-y-4">
            {settlements.length === 0 ? (
              <div className="text-center py-12 bg-slate-50 rounded-2xl">
                <p className="text-slate-400 font-bold text-xs uppercase tracking-widest">Everything is settled!</p>
              </div>
            ) : (
              settlements.map((s, idx) => (
                <div key={idx} className="bg-slate-50 p-6 rounded-2xl border border-slate-100 hover:border-[#4f46e5] transition-all">
                  <div className="flex items-center justify-between mb-4">
                    <div className="text-left">
                      <span className="text-[10px] font-bold uppercase text-slate-400 block mb-1">Debtor</span>
                      <p className="font-bold text-[#1e293b]">{getParticipantName(s.from)}</p>
                    </div>
                    <div className="text-center flex flex-col items-center">
                      <i className="fa-solid fa-arrow-right text-[#4f46e5] mb-1"></i>
                      <p className="text-lg font-bold text-[#1e293b]">₹{s.amount.toFixed(2)}</p>
                    </div>
                    <div className="text-right">
                      <span className="text-[10px] font-bold uppercase text-slate-400 block mb-1">Creditor</span>
                      <p className="font-bold text-[#1e293b]">{getParticipantName(s.to)}</p>
                    </div>
                  </div>

                  <div className="grid grid-cols-2 gap-3">
                    <button
                      onClick={() => handleWhatsAppRequest(s)}
                      className="bg-green-500 text-white text-[10px] font-bold uppercase py-3 rounded-xl hover:bg-green-600 transition-colors flex items-center justify-center gap-2"
                    >
                      <i className="fa-brands fa-whatsapp text-sm"></i>
                      Request
                    </button>
                    <button
                      onClick={() => onSettle(s.from, s.to, s.amount)}
                      className="bg-[#4f46e5] text-white text-[10px] font-bold uppercase py-3 rounded-xl hover:bg-[#4338ca] transition-colors"
                    >
                      Mark Paid
                    </button>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>

        {/* Balance Distribution */}
        <div className="bg-white rounded-3xl p-8 shadow-sm border border-slate-100">
          <div className="flex items-center gap-2 mb-8 text-[#1e293b]">
            <i className="fa-solid fa-chart-bar text-[#4f46e5]"></i>
            <h2 className="text-xl font-bold">Balance Overview</h2>
          </div>
          <div className="h-[350px]">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData} layout="vertical" margin={{ left: 10, right: 10 }}>
                <CartesianGrid strokeDasharray="3 3" horizontal={false} stroke="#f1f5f9" />
                <XAxis type="number" hide />
                <YAxis 
                  dataKey="name" 
                  type="category" 
                  width={60} 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{ fontSize: 10, fontWeight: 700, fill: '#64748b' }} 
                />
                <Tooltip 
                  cursor={{ fill: 'transparent' }}
                  contentStyle={{ borderRadius: '1rem', border: 'none', background: '#1e293b', color: '#fff' }}
                />
                <Bar dataKey="value" radius={[0, 4, 4, 0]} barSize={24}>
                  {chartData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.value >= 0 ? '#10b981' : '#f43f5e'} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* Summary Aggregate */}
      <div className="bg-[#1e293b] p-8 sm:p-12 rounded-[2.5rem] text-white flex flex-col sm:flex-row items-center justify-between gap-8 shadow-xl">
        <div className="text-center sm:text-left">
          <h3 className="text-slate-500 font-bold uppercase text-[10px] tracking-[0.2em] mb-2">Aggregate Spent</h3>
          <p className="text-5xl font-bold tracking-tight">₹{totalSpent.toFixed(2)}</p>
        </div>
        <div className="grid grid-cols-2 gap-4 w-full sm:w-auto">
          <div className="bg-slate-800 p-6 rounded-2xl border border-slate-700 text-center">
            <span className="block text-[10px] font-bold text-slate-500 uppercase mb-2">Per Person</span>
            <span className="text-xl font-bold">₹{(totalSpent / (participants.length || 1)).toFixed(2)}</span>
          </div>
          <div className="bg-slate-800 p-6 rounded-2xl border border-slate-700 text-center">
            <span className="block text-[10px] font-bold text-slate-500 uppercase mb-2">Active Dues</span>
            <span className="text-xl font-bold">{settlements.length}</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default SettlementView;

import React, { useState, useMemo, useEffect } from 'react';
import { Participant, Expense, Settlement, Balance } from './types.ts';
import ParticipantManager from './components/ParticipantManager.tsx';
import ExpenseForm from './components/ExpenseForm.tsx';
import SettlementView from './components/SettlementView.tsx';
import { calculateBalances, calculateSettlements } from './utils/calculation.ts';
import { 
  ResponsiveContainer, 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  Cell, 
  PieChart, 
  Pie, 
  Legend 
} from 'recharts';

const App: React.FC = () => {
  const [participants, setParticipants] = useState<Participant[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [activeTab, setActiveTab] = useState<'expenses' | 'settlement'>('expenses');
  const [selectedExpense, setSelectedExpense] = useState<Expense | null>(null);
  const [shareStatus, setShareStatus] = useState<'idle' | 'copied'>('idle');

  // URL Sharing & Persistence
  useEffect(() => {
    const loadData = () => {
      const hash = window.location.hash.substring(1);
      if (hash) {
        try {
          // Use URI component safe decoding
          const decodedData = decodeURIComponent(atob(hash));
          const parsed = JSON.parse(decodedData);
          if (Array.isArray(parsed.participants) && Array.isArray(parsed.expenses)) {
            setParticipants(parsed.participants);
            setExpenses(parsed.expenses);
            // Clear hash to prevent accidental re-loads over local changes
            window.history.replaceState(null, "", window.location.pathname);
            return;
          }
        } catch (e) {
          console.error("Failed to parse shared link data", e);
        }
      }

      const savedParticipants = localStorage.getItem('splitit_participants');
      const savedExpenses = localStorage.getItem('splitit_expenses');
      if (savedParticipants) setParticipants(JSON.parse(savedParticipants));
      if (savedExpenses) setExpenses(JSON.parse(savedExpenses));
    };

    loadData();
  }, []);

  useEffect(() => {
    if (participants.length > 0 || expenses.length > 0) {
      localStorage.setItem('splitit_participants', JSON.stringify(participants));
      localStorage.setItem('splitit_expenses', JSON.stringify(expenses));
    }
  }, [participants, expenses]);

  const handleShare = () => {
    try {
      const dataString = JSON.stringify({ participants, expenses });
      // Use URI component safe encoding
      const encodedData = btoa(encodeURIComponent(dataString));
      const shareUrl = `${window.location.origin}${window.location.pathname}#${encodedData}`;

      navigator.clipboard.writeText(shareUrl).then(() => {
        setShareStatus('copied');
        setTimeout(() => setShareStatus('idle'), 3000);
      });
    } catch (e) {
      console.error("Failed to generate share link", e);
      alert("Could not generate share link. Try with less data.");
    }
  };

  const addParticipant = (name: string) => {
    const newP: Participant = {
      id: crypto.randomUUID(),
      name,
      avatar: `https://api.dicebear.com/7.x/initials/svg?seed=${name}&backgroundColor=4f46e5&textColor=ffffff`
    };
    setParticipants([...participants, newP]);
  };

  const removeParticipant = (id: string) => {
    setParticipants(participants.filter(p => p.id !== id));
    setExpenses(expenses.filter(e => e.payerId !== id && !e.participantIds.includes(id)));
  };

  const addExpense = (newExp: Omit<Expense, 'id'>) => {
    const exp: Expense = { ...newExp, id: crypto.randomUUID() };
    setExpenses([exp, ...expenses]);
  };

  const removeExpense = (id: string) => {
    setExpenses(expenses.filter(e => e.id !== id));
    if (selectedExpense?.id === id) setSelectedExpense(null);
  };

  const { balances, settlements, totalSpent } = useMemo(() => {
    const bals = calculateBalances(participants, expenses);
    return {
      balances: bals,
      settlements: calculateSettlements([...bals]),
      totalSpent: expenses.reduce((acc, curr) => curr.category !== 'Payment' ? acc + curr.amount : acc, 0)
    };
  }, [participants, expenses]);

  // Analytics Data
  const categoryData = useMemo(() => {
    const counts: Record<string, number> = {};
    expenses.filter(e => e.category !== 'Payment').forEach(e => {
      counts[e.category] = (counts[e.category] || 0) + e.amount;
    });
    return Object.entries(counts).map(([name, value]) => ({ name, value }));
  }, [expenses]);

  const memberSpendingData = useMemo(() => {
    const spending: Record<string, number> = {};
    participants.forEach(p => spending[p.name] = 0);
    expenses.filter(e => e.category !== 'Payment').forEach(e => {
      const p = participants.find(part => part.id === e.payerId);
      if (p) spending[p.name] += e.amount;
    });
    return Object.entries(spending).map(([name, value]) => ({ name, value }));
  }, [expenses, participants]);

  const COLORS = ['#4f46e5', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899'];

  return (
    <div className="min-h-screen bg-[#f8fafc] text-slate-900 flex flex-col font-sans">
      {/* Header */}
      <header className="bg-white border-b border-slate-100 sticky top-0 z-30 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 h-20 flex items-center justify-between">
          <div className="flex flex-col">
            <div className="flex items-center gap-2">
              <div className="w-8 h-8 bg-[#4f46e5] rounded-md flex items-center justify-center text-white text-lg">
                <i className="fa-solid fa-receipt"></i>
              </div>
              <h1 className="text-2xl font-bold text-[#1e293b] tracking-tight">
                SplitIt
              </h1>
            </div>
            <p className="text-[10px] font-bold text-slate-400 tracking-[0.1em] mt-0.5 uppercase">
              good times in, awkward math out.
            </p>
          </div>

          <div className="flex items-center gap-4">
            <button
              onClick={handleShare}
              className={`flex items-center gap-2 px-4 py-2 rounded-xl text-xs font-bold transition-all border ${
                shareStatus === 'copied' 
                ? 'bg-green-50 border-green-200 text-green-600' 
                : 'bg-white border-slate-200 text-slate-600 hover:border-[#4f46e5] hover:text-[#4f46e5]'
              }`}
            >
              <i className={`fa-solid ${shareStatus === 'copied' ? 'fa-check' : 'fa-share-nodes'}`}></i>
              {shareStatus === 'copied' ? 'Link Copied!' : 'Share with Friends'}
            </button>

            <nav className="flex bg-[#f1f5f9] p-1 rounded-xl">
              <button
                onClick={() => setActiveTab('expenses')}
                className={`px-4 sm:px-6 py-2 rounded-lg text-sm font-semibold transition-all ${
                  activeTab === 'expenses' ? 'bg-white text-[#4f46e5] shadow-sm' : 'text-slate-500 hover:text-slate-700'
                }`}
              >
                Overview
              </button>
              <button
                onClick={() => setActiveTab('settlement')}
                className={`px-4 sm:px-6 py-2 rounded-lg text-sm font-semibold transition-all ${
                  activeTab === 'settlement' ? 'bg-white text-[#4f46e5] shadow-sm' : 'text-slate-500 hover:text-slate-700'
                }`}
              >
                Settlement
              </button>
            </nav>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 max-w-7xl mx-auto w-full px-4 sm:px-6 py-8">
        {activeTab === 'expenses' ? (
          <div className="space-y-8">
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
              {/* The Squad */}
              <div className="lg:col-span-3">
                <ParticipantManager participants={participants} onAdd={addParticipant} onRemove={removeParticipant} />
              </div>

              {/* Recent Activity */}
              <div className="lg:col-span-5 space-y-6">
                <div className="flex justify-between items-center">
                  <div className="flex items-center gap-2 text-[#1e293b]">
                    <i className="fa-solid fa-list-ul text-[#4f46e5]"></i>
                    <h2 className="text-xl font-bold">Recent Activity</h2>
                  </div>
                  <span className="text-[10px] font-bold text-slate-400 bg-slate-100 px-3 py-1 rounded-full uppercase tracking-wider">
                    {expenses.length} Records
                  </span>
                </div>

                <div className="min-h-[400px] bg-white border-2 border-dashed border-slate-200 rounded-3xl p-6 sm:p-8 flex flex-col items-center justify-center text-center overflow-y-auto max-h-[600px]">
                  {expenses.length === 0 ? (
                    <>
                      <div className="w-16 h-16 bg-slate-50 rounded-full flex items-center justify-center text-slate-300 mb-4">
                        <i className="fa-solid fa-receipt text-2xl"></i>
                      </div>
                      <h3 className="text-lg font-bold text-[#1e293b]">Clean slate!</h3>
                      <p className="text-sm text-slate-400 max-w-[200px] mt-2">
                        Add an expense or scan a receipt to start splitting.
                      </p>
                    </>
                  ) : (
                    <div className="w-full space-y-4 text-left self-start">
                      {expenses.sort((a, b) => b.date - a.date).map(e => (
                        <div 
                          key={e.id} 
                          onClick={() => setSelectedExpense(e)}
                          className={`p-4 rounded-xl border transition-all cursor-pointer ${
                            e.category === 'Payment' 
                            ? 'bg-slate-50 border-slate-100 italic opacity-80' 
                            : 'bg-white border-slate-100 hover:border-[#4f46e5] hover:shadow-sm'
                          }`}
                        >
                          <div className="flex justify-between items-center">
                            <div>
                              <p className="font-bold text-[#1e293b] line-clamp-1">{e.description}</p>
                              <p className="text-[10px] text-slate-400 uppercase font-bold mt-1">
                                {participants.find(p => p.id === e.payerId)?.name} • {new Date(e.date).toLocaleDateString()}
                              </p>
                            </div>
                            <div className="text-right">
                              <p className={`font-bold ${e.category === 'Payment' ? 'text-slate-400' : 'text-[#1e293b]'}`}>₹{e.amount.toFixed(2)}</p>
                              <p className="text-[9px] font-bold text-slate-300 uppercase">{e.category}</p>
                            </div>
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              </div>

              {/* Transaction Form */}
              <div className="lg:col-span-4">
                <ExpenseForm participants={participants} onAdd={addExpense} />
              </div>
            </div>

            {/* Analytics Section */}
            {expenses.length > 0 && (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8 pt-8 border-t border-slate-200">
                {/* Category Chart */}
                <div className="bg-white rounded-3xl p-6 shadow-sm border border-slate-100">
                  <div className="flex items-center gap-2 mb-6 text-[#1e293b]">
                    <i className="fa-solid fa-chart-pie text-[#4f46e5]"></i>
                    <h2 className="text-lg font-bold">Spending by Category</h2>
                  </div>
                  <div className="h-[300px] w-full">
                    <ResponsiveContainer width="100%" height="100%">
                      <PieChart>
                        <Pie
                          data={categoryData}
                          cx="50%"
                          cy="50%"
                          innerRadius={60}
                          outerRadius={80}
                          paddingAngle={5}
                          dataKey="value"
                        >
                          {categoryData.map((entry, index) => (
                            <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                          ))}
                        </Pie>
                        <Tooltip 
                           contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 4px 12px rgba(0,0,0,0.1)' }}
                           formatter={(value: number) => `₹${value.toFixed(2)}`}
                        />
                        <Legend iconType="circle" />
                      </PieChart>
                    </ResponsiveContainer>
                  </div>
                </div>

                {/* Member Chart */}
                <div className="bg-white rounded-3xl p-6 shadow-sm border border-slate-100">
                  <div className="flex items-center gap-2 mb-6 text-[#1e293b]">
                    <i className="fa-solid fa-chart-column text-[#4f46e5]"></i>
                    <h2 className="text-lg font-bold">Spending by Member</h2>
                  </div>
                  <div className="h-[300px] w-full">
                    <ResponsiveContainer width="100%" height="100%">
                      <BarChart data={memberSpendingData} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                        <XAxis 
                          dataKey="name" 
                          axisLine={false} 
                          tickLine={false} 
                          tick={{ fontSize: 10, fontWeight: 700, fill: '#64748b' }} 
                        />
                        <YAxis axisLine={false} tickLine={false} tick={{ fontSize: 10, fill: '#64748b' }} />
                        <Tooltip 
                           cursor={{ fill: '#f8fafc' }}
                           contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 4px 12px rgba(0,0,0,0.1)' }}
                           formatter={(value: number) => `₹${value.toFixed(2)}`}
                        />
                        <Bar dataKey="value" fill="#4f46e5" radius={[4, 4, 0, 0]} barSize={40} />
                      </BarChart>
                    </ResponsiveContainer>
                  </div>
                </div>
              </div>
            )}
          </div>
        ) : (
          <SettlementView
            participants={participants}
            balances={balances}
            settlements={settlements}
            totalSpent={totalSpent}
            onSettle={handleSettle}
          />
        )}
      </main>

      {/* Detail Modal */}
      {selectedExpense && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
          <div className="bg-white rounded-3xl max-w-lg w-full overflow-hidden shadow-2xl animate-in zoom-in-95 duration-200">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center">
              <h3 className="text-lg font-bold text-[#1e293b]">Expense Detail</h3>
              <button onClick={() => setSelectedExpense(null)} className="text-slate-400 hover:text-slate-600 p-2">
                <i className="fa-solid fa-xmark"></i>
              </button>
