  const [newEventName, setNewEventName] = useState('');

  // App states scoped to the active event
  const [activeTab, setActiveTab] = useState<'expenses' | 'settlement'>('expenses');
  const [selectedExpense, setSelectedExpense] = useState<Expense | null>(null);
  const [shareStatus, setShareStatus] = useState<'idle' | 'loading' | 'copied'>('idle');
  const [showShareModal, setShowShareModal] = useState(false);
  const [shareEventId, setShareEventId] = useState<string | null>(null);
  const [isInitialized, setIsInitialized] = useState(false);

  const CATEGORY_MAP: Record<string, Expense['category']> = {
    'F': 'Food', 'T': 'Transport', 'L': 'Lodging', 'E': 'Entertainment', 'P': 'Payment', 'O': 'Other'
  };

  const getAvatar = (name: string) => `https://api.dicebear.com/7.x/initials/svg?seed=${name}&backgroundColor=4f46e5&textColor=ffffff`;

  // Persistence & Shared Link Loading
  useEffect(() => {
    const loadInitialData = () => {
      const savedEvents = localStorage.getItem('splitit_multi_events');
      let currentEvents: Record<string, SplitEvent> = savedEvents ? JSON.parse(savedEvents) : {};

      // Handle shared hash
      const hash = window.location.hash.substring(1);
      if (hash) {
        try {
          const decompressed = LZString.decompressFromEncodedURIComponent(hash);
          if (decompressed) {
            const parsed = JSON.parse(decompressed);
            if (Array.isArray(parsed.p) && Array.isArray(parsed.e)) {
              const sharedId = `shared-${Date.now()}`;
              const reconstructed: SplitEvent = {
                id: sharedId,
                name: parsed.n || 'Shared Event',
                participants: parsed.p.map((p: any, idx: number) => {
                  // Handle legacy string array or new object array
                  const name = typeof p === 'string' ? p : p.n;
                  const upi = typeof p === 'string' ? undefined : p.u;
                  return {
                    id: `p-${idx}`,
                    name,
                    upiId: upi,
                    avatar: getAvatar(name)
                  };
                }),
                expenses: parsed.e.map((e: any, idx: number) => ({
                  id: `e-${idx}`,
                  description: e.d,
                  amount: e.a,
                  payerId: `p-${e.p}`,
                  participantIds: e.s.map((sIdx: number) => `p-${sIdx}`),
                  date: e.t * 1000,
                  category: CATEGORY_MAP[e.c] || 'Other'
                })),
                createdAt: Date.now()
              };
              currentEvents[sharedId] = reconstructed;
              setCurrentEventId(sharedId);
              // Clean URL
              window.history.replaceState(null, "", window.location.pathname);
            }
          }
        } catch (e) {
          console.error("Failed to parse shared link data", e);
        }
      }

      setEvents(currentEvents);
      setIsInitialized(true);
    };

    loadInitialData();
  }, []);

  useEffect(() => {
    if (isInitialized) {
      localStorage.setItem('splitit_multi_events', JSON.stringify(events));
    }
  }, [events, isInitialized]);

  // Active event helper
  const activeEvent = currentEventId ? events[currentEventId] : null;

  // Derived data for active event
  const { balances, settlements, totalSpent, categoryData, memberSpendingData } = useMemo(() => {
    if (!activeEvent) return { balances: [], settlements: [], totalSpent: 0, categoryData: [], memberSpendingData: [] };

    const bals = calculateBalances(activeEvent.participants, activeEvent.expenses);
    const setts = calculateSettlements([...bals]);
    const total = activeEvent.expenses.reduce((acc, curr) => curr.category !== 'Payment' ? acc + curr.amount : acc, 0);

    const counts: Record<string, number> = {};
    activeEvent.expenses.filter(e => e.category !== 'Payment').forEach(e => {
      counts[e.category] = (counts[e.category] || 0) + e.amount;
    });
    const catData = Object.entries(counts).map(([name, value]) => ({ name, value }));

    const spending: Record<string, number> = {};
    activeEvent.participants.forEach(p => spending[p.name] = 0);
    activeEvent.expenses.filter(e => e.category !== 'Payment').forEach(e => {
      const p = activeEvent.participants.find(part => part.id === e.payerId);
      if (p) spending[p.name] += e.amount;
    });
    const memData = Object.entries(spending).map(([name, value]) => ({ name, value }));

    return { 
      balances: bals, 
      settlements: setts, 
      totalSpent: total, 
      categoryData: catData, 
      memberSpendingData: memData 
    };
  }, [activeEvent]);

  // Actions
  const createEvent = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newEventName.trim()) return;
    const id = crypto.randomUUID();
    const newEv: SplitEvent = {
      id,
      name: newEventName.trim(),
      participants: [],
      expenses: [],
      createdAt: Date.now()
    };
    setEvents(prev => ({ ...prev, [id]: newEv }));
    setNewEventName('');
    setCurrentEventId(id);
  };

  const deleteEvent = (id: string) => {
    if (window.confirm("Delete this event forever?")) {
      const newEvents = { ...events };
      delete newEvents[id];
      setEvents(newEvents);
      if (currentEventId === id) setCurrentEventId(null);
    }
  };

  const updateActiveEvent = (updates: Partial<SplitEvent>) => {
    if (!currentEventId) return;
    setEvents(prev => ({
      ...prev,
      [currentEventId]: { ...prev[currentEventId], ...updates }
    }));
  };

  const addParticipant = (name: string, upiId?: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      participants: [...activeEvent.participants, { id: crypto.randomUUID(), name, avatar: getAvatar(name), upiId }]
    });
  };

  const removeParticipant = (id: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      participants: activeEvent.participants.filter(p => p.id !== id),
      expenses: activeEvent.expenses.filter(e => e.payerId !== id && !e.participantIds.includes(id))
    });
  };

  const addExpense = (newExp: Omit<Expense, 'id'>) => {
    if (!activeEvent) return;
    updateActiveEvent({
      expenses: [{ ...newExp, id: crypto.randomUUID() }, ...activeEvent.expenses]
    });
  };

  const removeExpense = (id: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      expenses: activeEvent.expenses.filter(e => e.id !== id)
    });
    if (selectedExpense?.id === id) setSelectedExpense(null);
  };

  const handleSettle = (fromId: string, toId: string, amount: number) => {
    if (!activeEvent) return;
    const fromP = activeEvent.participants.find(p => p.id === fromId)?.name;
    const toP = activeEvent.participants.find(p => p.id === toId)?.name;
    addExpense({
      description: `Settlement: ${fromP} paid ${toP}`,
      amount: amount, payerId: fromId, participantIds: [toId], category: 'Payment', date: Date.now()
    });
  };

  // Sharing Helpers
  const getFullShareUrl = (eventId: string) => {
    const targetEvent = events[eventId];
    const pMap = new Map();
    targetEvent.participants.forEach((p, idx) => pMap.set(p.id, idx));

    const payload = {
      n: targetEvent.name,
      p: targetEvent.participants.map(p => ({ n: p.name, u: p.upiId })),
      e: targetEvent.expenses.map(e => ({
        d: e.description,
        a: e.amount,
        p: pMap.get(e.payerId),
        s: e.participantIds.map(id => pMap.get(id)),
        t: Math.floor(e.date / 1000),
        c: e.category[0]
      }))
    };

    const compressed = LZString.compressToEncodedURIComponent(JSON.stringify(payload));
    return `${window.location.origin}${window.location.pathname}#${compressed}`;
  };

  const getShortUrl = async (eventId: string) => {
    const longUrl = getFullShareUrl(eventId);
    try {
      setShareStatus('loading');
      const res = await fetch(`https://tinyurl.com/api-create.php?url=${encodeURIComponent(longUrl)}`);
      if (res.ok) {
        const short = await res.text();
        setShareStatus('idle');
        return short;
      }
    } catch (e) {
      console.warn("Shortening failed", e);
    }
    setShareStatus('idle');
    return longUrl;
  };

  const openShareModal = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setShareEventId(id);
    setShowShareModal(true);
  };

  const handleShareWhatsApp = async () => {
    if (!shareEventId) return;
    const url = await getShortUrl(shareEventId);
    const ev = events[shareEventId];
    const bals = calculateBalances(ev.participants, ev.expenses);
    const setts = calculateSettlements([...bals]);
    const settlementText = setts.length === 0 ? "All settled! ✅" : setts.map(s => `💸 *${ev.participants.find(p=>p.id===s.from)?.name}* owes *${ev.participants.find(p=>p.id===s.to)?.name}*: ₹${s.amount.toFixed(2)}`).join('\n');
    const text = `💰 *SplitIt: ${ev.name}*\n\n*Settlements:*\n${settlementText}\n\n🔗 View & Settle:\n${url}`;
    window.open(`https://api.whatsapp.com/send?text=${encodeURIComponent(text)}`, '_blank');
  };

  const handleCopyLink = async () => {
    if (!shareEventId) return;
    const url = await getShortUrl(shareEventId);
    navigator.clipboard.writeText(url).then(() => {
      setShareStatus('copied');
      setTimeout(() => setShareStatus('idle'), 2000);
    });
  };

  const COLORS = ['#4f46e5', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899'];

  // Dashboard Render
  if (!currentEventId) {
    return (
      <div className="min-h-screen bg-[#f8fafc] flex flex-col font-sans">
        <header className="bg-white border-b border-slate-100 p-6 sm:p-8 flex items-center justify-between">
          <div className="flex items-center gap-3">
             <div className="w-10 h-10 bg-[#4f46e5] rounded-xl flex items-center justify-center text-white text-2xl"><i className="fa-solid fa-receipt"></i></div>
             <h1 className="text-2xl font-black text-slate-800 tracking-tight">SplitIt</h1>
          </div>
          <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest bg-slate-100 px-4 py-1.5 rounded-full">Dashboard</span>
        </header>

        <main className="flex-1 max-w-5xl mx-auto w-full px-4 py-8 sm:py-16 space-y-12">
          {/* Create Event Section */}
          <section className="bg-white rounded-[2.5rem] p-8 sm:p-12 shadow-xl shadow-indigo-50/50 border border-slate-100 text-center space-y-8">
            <div className="space-y-2">
              <h2 className="text-3xl font-bold text-slate-800">New Group Session</h2>
              <p className="text-slate-400 font-medium">Split bills instantly for trips, parties, or dinners.</p>
            </div>

            <form onSubmit={createEvent} className="max-w-md mx-auto relative group">
              <input 
                type="text" 
                value={newEventName}
                onChange={e => setNewEventName(e.target.value)}
                placeholder="Enter event name... e.g. Goa 2024"
                className="w-full px-8 py-5 rounded-3xl bg-slate-50 border-2 border-transparent focus:border-[#4f46e5] focus:bg-white text-lg font-bold transition-all outline-none pr-36 shadow-inner"
              />
              <button 
                type="submit"
                className="absolute right-2 top-2 bottom-2 bg-[#4f46e5] text-white px-8 rounded-2xl font-black text-sm hover:bg-[#4338ca] transition-all shadow-lg active:scale-95"
              >
                START
              </button>
            </form>
          </section>

          {/* Existing Events Grid */}
          {Object.values(events).length > 0 && (
            <section className="space-y-6">
              <div className="flex items-center justify-between px-2">
                <h3 className="text-sm font-black text-slate-400 uppercase tracking-[0.2em]">Your Active Events</h3>
                <span className="text-xs font-bold text-[#4f46e5]">{Object.values(events).length} Saved</span>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
                {(Object.values(events) as SplitEvent[]).sort((a: SplitEvent, b: SplitEvent) => b.createdAt - a.createdAt).map((ev: SplitEvent) => {
                  const evTotal = ev.expenses.reduce((acc, curr) => curr.category !== 'Payment' ? acc + curr.amount : acc, 0);
                  return (
                    <div 
                      key={ev.id}
                      onClick={() => setCurrentEventId(ev.id)}
                      className="group bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm hover:shadow-xl hover:border-[#4f46e5]/20 hover:-translate-y-1 transition-all cursor-pointer flex flex-col justify-between min-h-[220px]"
                    >
                      <div className="space-y-4">
                        <div className="flex justify-between items-start">
                          <div className="w-10 h-10 bg-[#eef2ff] text-[#4f46e5] rounded-xl flex items-center justify-center text-lg font-black group-hover:bg-[#4f46e5] group-hover:text-white transition-colors">
                            {ev.name.charAt(0)}
                          </div>
                          <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                            <button onClick={(e) => openShareModal(e, ev.id)} className="w-8 h-8 rounded-full bg-slate-50 text-slate-400 hover:text-[#4f46e5] flex items-center justify-center transition-colors"><i className="fa-solid fa-share-nodes text-xs"></i></button>
                            <button onClick={(e) => { e.stopPropagation(); deleteEvent(ev.id); }} className="w-8 h-8 rounded-full bg-slate-50 text-slate-400 hover:text-red-500 flex items-center justify-center transition-colors"><i className="fa-solid fa-trash text-xs"></i></button>
                          </div>
                        </div>
                        <div>
                          <h4 className="text-xl font-bold text-slate-800 line-clamp-1">{ev.name}</h4>
                          <p className="text-[10px] font-bold text-slate-400 uppercase mt-1">{new Date(ev.createdAt).toLocaleDateString()} • {ev.participants.length} People</p>
                        </div>
                      </div>

                      <div className="pt-4 border-t border-slate-50 flex items-end justify-between">
                         <div>
                            <span className="block text-[8px] font-black text-slate-300 uppercase tracking-widest">Spent</span>
                            <span className="text-xl font-black text-slate-800">₹{evTotal.toFixed(0)}</span>
                         </div>
                         <i className="fa-solid fa-chevron-right text-slate-200 group-hover:translate-x-1 group-hover:text-[#4f46e5] transition-all"></i>
                      </div>
                    </div>
                  );
                })}
              </div>
            </section>
          )}
        </main>
      </div>
    );
  }

  // Active Event View
  return (
    <div className="min-h-screen bg-[#f8fafc] text-slate-900 flex flex-col font-sans overflow-x-hidden">
      <header className="bg-white border-b border-slate-100 sticky top-0 z-30 shadow-sm px-4">
        <div className="max-w-7xl mx-auto h-20 flex items-center justify-between gap-2">
          <div className="flex items-center gap-4">
            <button 
              onClick={() => setCurrentEventId(null)}
              className="w-10 h-10 rounded-full hover:bg-slate-50 flex items-center justify-center text-slate-400 hover:text-slate-800 transition-all"
            >
              <i className="fa-solid fa-arrow-left"></i>
            </button>
            <div className="flex flex-col min-w-0">
              <h1 className="text-lg sm:text-xl font-bold text-[#1e293b] truncate">{activeEvent.name}</h1>
              <p className="text-[9px] font-bold text-slate-400 tracking-[0.1em] uppercase">SplitIt Management</p>
            </div>
          </div>
          <nav className="flex bg-[#f1f5f9] p-1 rounded-xl shrink-0">
            <button onClick={() => setActiveTab('expenses')} className={`px-4 sm:px-6 py-2 rounded-lg text-xs font-semibold transition-all ${activeTab === 'expenses' ? 'bg-white text-[#4f46e5] shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Overview</button>
            <button onClick={() => setActiveTab('settlement')} className={`px-4 sm:px-6 py-2 rounded-lg text-xs font-semibold transition-all ${activeTab === 'settlement' ? 'bg-white text-[#4f46e5] shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Settlement</button>
          </nav>
        </div>
      </header>

      <main className="flex-1 max-w-7xl mx-auto w-full px-4 sm:px-6 py-6 sm:py-8 space-y-6">
        {/* Quick Summary Row */}
        <div className="flex items-center justify-between bg-white px-6 py-4 rounded-3xl border border-slate-100 shadow-sm">
          <div className="flex gap-8">
            <div><span className="text-[8px] font-bold text-slate-400 uppercase block mb-1">Total Spent</span><p className="text-lg font-black">₹{totalSpent.toFixed(0)}</p></div>
            <div><span className="text-[8px] font-bold text-slate-400 uppercase block mb-1">Squad</span><p className="text-lg font-black">{activeEvent.participants.length}</p></div>
          </div>
          <button 
            onClick={(e) => openShareModal(e, activeEvent.id)}
            className="flex items-center gap-2 px-6 py-3 rounded-2xl text-xs font-bold transition-all bg-[#4f46e5] text-white hover:bg-[#4338ca] shadow-md shadow-indigo-100"
          >
            <i className="fa-solid fa-share-nodes"></i>
            Share Dues
          </button>
        </div>

        {activeTab === 'expenses' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
            <div className="lg:col-span-3"><ParticipantManager participants={activeEvent.participants} onAdd={addParticipant} onRemove={removeParticipant} /></div>
            <div className="lg:col-span-5 space-y-4">
              <div className="flex justify-between items-center"><h2 className="text-lg font-bold flex items-center gap-2"><i className="fa-solid fa-list-ul text-[#4f46e5]"></i>Recent Activity</h2><span className="text-[10px] font-bold text-slate-400 bg-slate-100 px-3 py-1 rounded-full">{activeEvent.expenses.length} Records</span></div>
              <div className="min-h-[400px] bg-white border border-slate-100 rounded-3xl p-4 overflow-y-auto max-h-[600px] scrollbar-hide">
                {activeEvent.expenses.length === 0 ? <div className="h-full flex flex-col items-center justify-center text-center text-slate-300"><i className="fa-solid fa-receipt text-3xl mb-2"></i><p className="text-sm font-bold">No expenses yet</p></div> : 
                  activeEvent.expenses.sort((a,b) => b.date - a.date).map(e => (
                    <div key={e.id} onClick={() => setSelectedExpense(e)} className={`p-4 mb-3 rounded-xl border transition-all cursor-pointer ${e.category === 'Payment' ? 'bg-slate-50 border-slate-100 italic' : 'bg-white border-slate-50 hover:border-[#4f46e5]'}`}>
                      <div className="flex justify-between items-center"><div className="min-w-0"><p className="font-bold text-slate-800 truncate">{e.description}</p><p className="text-[9px] text-slate-400 font-bold uppercase">{activeEvent.participants.find(p=>p.id===e.payerId)?.name} • {new Date(e.date).toLocaleDateString()}</p></div><div className="text-right shrink-0"><p className="font-bold text-slate-800">₹{e.amount.toFixed(2)}</p><p className="text-[8px] text-slate-300 font-bold uppercase">{e.category}</p></div></div>
                    </div>
                  ))}
              </div>
            </div>
            <div className="lg:col-span-4"><ExpenseForm participants={activeEvent.participants} onAdd={addExpense} /></div>
          </div>
        ) : (
          <SettlementView participants={activeEvent.participants} balances={balances} settlements={settlements} totalSpent={totalSpent} onSettle={handleSettle} />
        )}
      </main>

      {/* Shared Modals */}
      {showShareModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
          <div className="bg-white rounded-[2.5rem] max-w-sm w-full shadow-2xl animate-in zoom-in-95 duration-200">
            <div className="p-8 border-b border-slate-100 flex justify-between items-center"><h3 className="text-xl font-bold text-slate-800">Share "{events[shareEventId!]?.name}"</h3><button onClick={() => setShowShareModal(false)} className="text-slate-400 hover:text-slate-600"><i className="fa-solid fa-xmark text-lg"></i></button></div>
            <div className="p-8 grid grid-cols-2 gap-4 relative">
              {shareStatus === 'loading' && <div className="absolute inset-0 bg-white/80 z-10 flex flex-col items-center justify-center gap-2"><i className="fa-solid fa-spinner animate-spin text-[#4f46e5] text-2xl"></i><span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Processing...</span></div>}
              <button onClick={handleShareWhatsApp} className="flex flex-col items-center gap-2 p-6 rounded-3xl bg-green-50 hover:bg-green-100 transition-colors"><div className="w-12 h-12 bg-green-500 rounded-full flex items-center justify-center text-white"><i className="fa-brands fa-whatsapp text-2xl"></i></div><span className="text-xs font-bold text-green-700">WhatsApp</span></button>
              <button onClick={handleCopyLink} className={`flex flex-col items-center gap-2 p-6 rounded-3xl transition-colors ${shareStatus === 'copied' ? 'bg-indigo-100' : 'bg-slate-50'}`}><div className={`w-12 h-12 rounded-full flex items-center justify-center text-white ${shareStatus === 'copied' ? 'bg-indigo-600' : 'bg-slate-700'}`}><i className={`fa-solid ${shareStatus === 'copied' ? 'fa-check' : 'fa-link'} text-xl`}></i></div><span className="text-xs font-bold text-slate-700">{shareStatus === 'copied' ? 'Copied!' : 'Copy Link'}</span></button>
            </div>
            <div className="p-6 bg-slate-50 rounded-b-[2.5rem] text-center"><p className="text-[10px] text-slate-400 font-bold uppercase tracking-[0.2em]">Data remains synced offline</p></div>
          </div>
        </div>
      )}

      {selectedExpense && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
          <div className="bg-white rounded-3xl max-w-lg w-full overflow-hidden shadow-2xl p-8 space-y-6 animate-in zoom-in-95">
            <div className="flex justify-between items-center"><h3 className="text-xl font-bold">Expense Detail</h3><button onClick={() => setSelectedExpense(null)} className="text-slate-400 hover:text-slate-800"><i className="fa-solid fa-xmark"></i></button></div>
            <div className="space-y-4">
              <div className="flex justify-between items-center pb-4 border-b border-slate-50"><span>Description</span><span className="font-bold text-lg">{selectedExpense.description}</span></div>
              <div className="flex justify-between items-center pb-4 border-b border-slate-50"><span>Amount</span><span className="font-black text-2xl text-[#4f46e5]">₹{selectedExpense.amount}</span></div>
              <div className="flex justify-between items-center pb-4 border-b border-slate-50"><span>Who Paid</span><span className="font-bold">{activeEvent.participants.find(p=>p.id===selectedExpense.payerId)?.name}</span></div>
            </div>
            <button onClick={() => removeExpense(selectedExpense.id)} className="w-full py-4 bg-red-50 text-red-500 font-bold rounded-2xl hover:bg-red-100 transition-colors flex items-center justify-center gap-2"><i className="fa-solid fa-trash-can"></i>Delete Transaction</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import LZString from 'lz-string';
import { Participant, Expense, Settlement, Balance, SplitEvent } from './types.ts';
import ParticipantManager from './components/ParticipantManager.tsx';
import ExpenseForm from './components/ExpenseForm.tsx';
import SettlementView from './components/SettlementView.tsx';
import { calculateBalances, calculateSettlements } from './utils/calculation.ts';

const App: React.FC = () => {
  const [events, setEvents] = useState<Record<string, SplitEvent>>({});
  const [currentEventId, setCurrentEventId] = useState<string | null>(null);
  const [newEventName, setNewEventName] = useState('');

  // App states scoped to the active event
  const [activeTab, setActiveTab] = useState<'expenses' | 'settlement'>('expenses');
  const [selectedExpense, setSelectedExpense] = useState<Expense | null>(null);
  const [shareStatus, setShareStatus] = useState<'idle' | 'copied'>('idle');
  const [showShareModal, setShowShareModal] = useState(false);
  const [shareEventId, setShareEventId] = useState<string | null>(null);
  const [isInitialized, setIsInitialized] = useState(false);

  const CATEGORY_MAP: Record<string, Expense['category']> = {
    'F': 'Food', 'T': 'Transport', 'L': 'Lodging', 'E': 'Entertainment', 'P': 'Payment', 'O': 'Other'
  };

  const getAvatar = (name: string) => `https://api.dicebear.com/7.x/initials/svg?seed=${name}&backgroundColor=4f46e5&textColor=ffffff`;

  // Persistence & Shared Link Loading
  useEffect(() => {
    const loadInitialData = () => {
      const savedEvents = localStorage.getItem('splitit_multi_events');
      let currentEvents: Record<string, SplitEvent> = savedEvents ? JSON.parse(savedEvents) : {};

      // Handle shared hash (the unique ID part of the URL)
      const hash = window.location.hash.substring(1);
      if (hash) {
        try {
          const decompressed = LZString.decompressFromEncodedURIComponent(hash);
          if (decompressed) {
            const parsed = JSON.parse(decompressed);
            if (Array.isArray(parsed.p) && Array.isArray(parsed.e)) {
              const sharedId = `shared-${Date.now()}`;
              const reconstructed: SplitEvent = {
                id: sharedId,
                name: parsed.n || 'Shared Event',
                participants: parsed.p.map((p: any, idx: number) => {
                  const name = typeof p === 'string' ? p : p.n;
                  const upi = typeof p === 'string' ? undefined : p.u;
                  return {
                    id: `p-${idx}`,
                    name,
                    upiId: upi,
                    avatar: getAvatar(name)
                  };
                }),
                expenses: parsed.e.map((e: any, idx: number) => ({
                  id: `e-${idx}`,
                  description: e.d,
                  amount: e.a,
                  payerId: `p-${e.p}`,
                  participantIds: e.s.map((sIdx: number) => `p-${sIdx}`),
                  date: e.t * 1000,
                  category: CATEGORY_MAP[e.c] || 'Other'
                })),
                createdAt: Date.now()
              };
              currentEvents[sharedId] = reconstructed;
              setCurrentEventId(sharedId);
              // Clean URL to prevent re-adding on refresh
              window.history.replaceState(null, "", window.location.pathname);
            }
          }
        } catch (e) {
          console.error("Failed to parse shared link data", e);
        }
      }

      setEvents(currentEvents);
      setIsInitialized(true);
    };

    loadInitialData();
  }, []);

  useEffect(() => {
    if (isInitialized) {
      localStorage.setItem('splitit_multi_events', JSON.stringify(events));
    }
  }, [events, isInitialized]);

  // Active event helper
  const activeEvent = currentEventId ? events[currentEventId] : null;

  // Derived data for active event
  const { balances, settlements, totalSpent } = useMemo(() => {
    if (!activeEvent) return { balances: [], settlements: [], totalSpent: 0 };

    const bals = calculateBalances(activeEvent.participants, activeEvent.expenses);
    const setts = calculateSettlements([...bals]);
    const total = activeEvent.expenses.reduce((acc, curr) => curr.category !== 'Payment' ? acc + curr.amount : acc, 0);

    return { 
      balances: bals, 
      settlements: setts, 
      totalSpent: total
    };
  }, [activeEvent]);

  // Actions
  const createEvent = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newEventName.trim()) return;
    const id = crypto.randomUUID();
    const newEv: SplitEvent = {
      id,
      name: newEventName.trim(),
      participants: [],
      expenses: [],
      createdAt: Date.now()
    };
    setEvents(prev => ({ ...prev, [id]: newEv }));
    setNewEventName('');
    setCurrentEventId(id);
  };

  const deleteEvent = (id: string) => {
    if (window.confirm("Delete this event forever?")) {
      const newEvents = { ...events };
      delete newEvents[id];
      setEvents(newEvents);
      if (currentEventId === id) setCurrentEventId(null);
    }
  };

  const updateActiveEvent = (updates: Partial<SplitEvent>) => {
    if (!currentEventId) return;
    setEvents(prev => ({
      ...prev,
      [currentEventId]: { ...prev[currentEventId], ...updates }
    }));
  };

  const addParticipant = (name: string, upiId?: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      participants: [...activeEvent.participants, { id: crypto.randomUUID(), name, avatar: getAvatar(name), upiId }]
    });
  };

  const removeParticipant = (id: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      participants: activeEvent.participants.filter(p => p.id !== id),
      expenses: activeEvent.expenses.filter(e => e.payerId !== id && !e.participantIds.includes(id))
    });
  };

  const addExpense = (newExp: Omit<Expense, 'id'>) => {
    if (!activeEvent) return;
    updateActiveEvent({
      expenses: [{ ...newExp, id: crypto.randomUUID() }, ...activeEvent.expenses]
    });
  };

  const removeExpense = (id: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      expenses: activeEvent.expenses.filter(e => e.id !== id)
    });
    if (selectedExpense?.id === id) setSelectedExpense(null);
  };

  const handleSettle = (fromId: string, toId: string, amount: number) => {
    if (!activeEvent) return;
    const fromP = activeEvent.participants.find(p => p.id === fromId)?.name;
    const toP = activeEvent.participants.find(p => p.id === toId)?.name;
    addExpense({
      description: `Settlement: ${fromP} paid ${toP}`,
      amount: amount, payerId: fromId, participantIds: [toId], category: 'Payment', date: Date.now()
    });
  };

  // Updated Sharing logic as per user request: splitits.in/[unique_id]
  const getShareUrl = (eventId: string) => {
    const targetEvent = events[eventId];
    const pMap = new Map();
    targetEvent.participants.forEach((p, idx) => pMap.set(p.id, idx));

    const payload = {
      n: targetEvent.name,
      p: targetEvent.participants.map(p => ({ n: p.name, u: p.upiId })),
      e: targetEvent.expenses.map(e => ({
        d: e.description,
        a: e.amount,
        p: pMap.get(e.payerId),
        s: e.participantIds.map(id => pMap.get(id)),
        t: Math.floor(e.date / 1000),
        c: e.category[0]
      }))
    };

    const compressed = LZString.compressToEncodedURIComponent(JSON.stringify(payload));
    // The "Unique ID" is the compressed payload. Using hash to ensure the client-side app can load it.
    return `https://splitits.in/#${compressed}`;
  };

  const openShareModal = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setShareEventId(id);
    setShowShareModal(true);
  };

  const handleShareWhatsApp = () => {
    if (!shareEventId) return;
    const url = getShareUrl(shareEventId);
    const ev = events[shareEventId];
    const bals = calculateBalances(ev.participants, ev.expenses);
    const setts = calculateSettlements([...bals]);
    const settlementText = setts.length === 0 ? "All settled! ✅" : setts.map(s => `💸 *${ev.participants.find(p=>p.id===s.from)?.name}* owes *${ev.participants.find(p=>p.id===s.to)?.name}*: ₹${s.amount.toFixed(2)}`).join('\n');
    const text = `💰 *SplitIt: ${ev.name}*\n\n*Settlements:*\n${settlementText}\n\n🔗 View & Settle:\n${url}`;
    window.open(`https://api.whatsapp.com/send?text=${encodeURIComponent(text)}`, '_blank');
  };

  const handleCopyLink = () => {
    if (!shareEventId) return;
    const url = getShareUrl(shareEventId);
    navigator.clipboard.writeText(url).then(() => {
      setShareStatus('copied');
      setTimeout(() => setShareStatus('idle'), 2000);
    });
  };

  // Dashboard Render
  if (!currentEventId) {
    return (
      <div className="min-h-screen bg-[#f8fafc] flex flex-col font-sans">
        <header className="bg-white border-b border-slate-100 p-6 sm:p-8 flex items-center justify-between">
          <div className="flex items-center gap-3">
             <div className="w-10 h-10 bg-[#4f46e5] rounded-xl flex items-center justify-center text-white text-2xl"><i className="fa-solid fa-receipt"></i></div>
             <h1 className="text-2xl font-black text-slate-800 tracking-tight">SplitIt</h1>
          </div>
          <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest bg-slate-100 px-4 py-1.5 rounded-full">Dashboard</span>
        </header>

        <main className="flex-1 max-w-5xl mx-auto w-full px-4 py-8 sm:py-16 space-y-12">
          {/* Create Event Section */}
          <section className="bg-white rounded-[2.5rem] p-8 sm:p-12 shadow-xl shadow-indigo-50/50 border border-slate-100 text-center space-y-8">
            <div className="space-y-2">
              <h2 className="text-3xl font-bold text-slate-800">New Group Session</h2>
              <p className="text-slate-400 font-medium">Split bills instantly for trips, parties, or dinners.</p>
            </div>

            <form onSubmit={createEvent} className="max-w-md mx-auto relative group">
              <input 
                type="text" 
                value={newEventName}
                onChange={e => setNewEventName(e.target.value)}
                placeholder="Enter event name... e.g. Goa 2024"
                className="w-full px-8 py-5 rounded-3xl bg-slate-50 border-2 border-transparent focus:border-[#4f46e5] focus:bg-white text-lg font-bold transition-all outline-none pr-36 shadow-inner"
              />
              <button 
                type="submit"
                className="absolute right-2 top-2 bottom-2 bg-[#4f46e5] text-white px-8 rounded-2xl font-black text-sm hover:bg-[#4338ca] transition-all shadow-lg active:scale-95"
              >
                START
              </button>
            </form>
          </section>

          {/* Existing Events Grid */}
          {Object.values(events).length > 0 && (
            <section className="space-y-6">
              <div className="flex items-center justify-between px-2">
                <h3 className="text-sm font-black text-slate-400 uppercase tracking-[0.2em]">Your Active Events</h3>
                <span className="text-xs font-bold text-[#4f46e5]">{Object.values(events).length} Saved</span>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
                {(Object.values(events) as SplitEvent[]).sort((a: SplitEvent, b: SplitEvent) => b.createdAt - a.createdAt).map((ev: SplitEvent) => {
                  const evTotal = ev.expenses.reduce((acc, curr) => curr.category !== 'Payment' ? acc + curr.amount : acc, 0);
                  return (
                    <div 
                      key={ev.id}
                      onClick={() => setCurrentEventId(ev.id)}
                      className="group bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm hover:shadow-xl hover:border-[#4f46e5]/20 hover:-translate-y-1 transition-all cursor-pointer flex flex-col justify-between min-h-[220px]"
                    >
                      <div className="space-y-4">
                        <div className="flex justify-between items-start">
                          <div className="w-10 h-10 bg-[#eef2ff] text-[#4f46e5] rounded-xl flex items-center justify-center text-lg font-black group-hover:bg-[#4f46e5] group-hover:text-white transition-colors">
                            {ev.name.charAt(0)}
                          </div>
                          <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                            <button onClick={(e) => openShareModal(e, ev.id)} className="w-8 h-8 rounded-full bg-slate-50 text-slate-400 hover:text-[#4f46e5] flex items-center justify-center transition-colors"><i className="fa-solid fa-share-nodes text-xs"></i></button>
                            <button onClick={(e) => { e.stopPropagation(); deleteEvent(ev.id); }} className="w-8 h-8 rounded-full bg-slate-50 text-slate-400 hover:text-red-500 flex items-center justify-center transition-colors"><i className="fa-solid fa-trash text-xs"></i></button>
                          </div>
                        </div>
                        <div>
                          <h4 className="text-xl font-bold text-slate-800 line-clamp-1">{ev.name}</h4>
                          <p className="text-[10px] font-bold text-slate-400 uppercase mt-1">{new Date(ev.createdAt).toLocaleDateString()} • {ev.participants.length} People</p>
                        </div>
                      </div>

                      <div className="pt-4 border-t border-slate-50 flex items-end justify-between">
                         <div>
                            <span className="block text-[8px] font-black text-slate-300 uppercase tracking-widest">Spent</span>
                            <span className="text-xl font-black text-slate-800">₹{evTotal.toFixed(0)}</span>
                         </div>
                         <i className="fa-solid fa-chevron-right text-slate-200 group-hover:translate-x-1 group-hover:text-[#4f46e5] transition-all"></i>
                      </div>
                    </div>
                  );
                })}
              </div>
            </section>
          )}
        </main>
      </div>
    );
  }

  // Active Event View
  return (
    <div className="min-h-screen bg-[#f8fafc] text-slate-900 flex flex-col font-sans overflow-x-hidden">
      <header className="bg-white border-b border-slate-100 sticky top-0 z-30 shadow-sm px-4">
        <div className="max-w-7xl mx-auto h-20 flex items-center justify-between gap-2">
          <div className="flex items-center gap-4">
            <button 
              onClick={() => setCurrentEventId(null)}
              className="w-10 h-10 rounded-full hover:bg-slate-50 flex items-center justify-center text-slate-400 hover:text-slate-800 transition-all"
            >
              <i className="fa-solid fa-arrow-left"></i>
            </button>
            <div className="flex flex-col min-w-0">
              <h1 className="text-lg sm:text-xl font-bold text-[#1e293b] truncate">{activeEvent.name}</h1>
              <p className="text-[9px] font-bold text-slate-400 tracking-[0.1em] uppercase">SplitIt Management</p>
            </div>
          </div>
          <nav className="flex bg-[#f1f5f9] p-1 rounded-xl shrink-0">
            <button onClick={() => setActiveTab('expenses')} className={`px-4 sm:px-6 py-2 rounded-lg text-xs font-semibold transition-all ${activeTab === 'expenses' ? 'bg-white text-[#4f46e5] shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Overview</button>
            <button onClick={() => setActiveTab('settlement')} className={`px-4 sm:px-6 py-2 rounded-lg text-xs font-semibold transition-all ${activeTab === 'settlement' ? 'bg-white text-[#4f46e5] shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Settlement</button>
          </nav>
        </div>
      </header>

      <main className="flex-1 max-w-7xl mx-auto w-full px-4 sm:px-6 py-6 sm:py-8 space-y-6">
        <div className="flex items-center justify-between bg-white px-6 py-4 rounded-3xl border border-slate-100 shadow-sm">
          <div className="flex gap-8">
            <div><span className="text-[8px] font-bold text-slate-400 uppercase block mb-1">Total Spent</span><p className="text-lg font-black">₹{totalSpent.toFixed(0)}</p></div>
            <div><span className="text-[8px] font-bold text-slate-400 uppercase block mb-1">Squad</span><p className="text-lg font-black">{activeEvent.participants.length}</p></div>
          </div>
          <button 
            onClick={(e) => openShareModal(e, activeEvent.id)}
            className="flex items-center gap-2 px-6 py-3 rounded-2xl text-xs font-bold transition-all bg-[#4f46e5] text-white hover:bg-[#4338ca] shadow-md shadow-indigo-100"
          >
            <i className="fa-solid fa-share-nodes"></i>
            Share Dues
          </button>
        </div>

        {activeTab === 'expenses' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
            <div className="lg:col-span-3"><ParticipantManager participants={activeEvent.participants} onAdd={addParticipant} onRemove={removeParticipant} /></div>
            <div className="lg:col-span-5 space-y-4">
              <div className="flex justify-between items-center"><h2 className="text-lg font-bold flex items-center gap-2"><i className="fa-solid fa-list-ul text-[#4f46e5]"></i>Recent Activity</h2><span className="text-[10px] font-bold text-slate-400 bg-slate-100 px-3 py-1 rounded-full">{activeEvent.expenses.length} Records</span></div>
              <div className="min-h-[400px] bg-white border border-slate-100 rounded-3xl p-4 overflow-y-auto max-h-[600px] scrollbar-hide">
                {activeEvent.expenses.length === 0 ? <div className="h-full flex flex-col items-center justify-center text-center text-slate-300"><i className="fa-solid fa-receipt text-3xl mb-2"></i><p className="text-sm font-bold">No expenses yet</p></div> : 
                  activeEvent.expenses.sort((a,b) => b.date - a.date).map(e => (
                    <div key={e.id} onClick={() => setSelectedExpense(e)} className={`p-4 mb-3 rounded-xl border transition-all cursor-pointer ${e.category === 'Payment' ? 'bg-slate-50 border-slate-100 italic' : 'bg-white border-slate-50 hover:border-[#4f46e5]'}`}>
                      <div className="flex justify-between items-center"><div className="min-w-0"><p className="font-bold text-slate-800 truncate">{e.description}</p><p className="text-[9px] text-slate-400 font-bold uppercase">{activeEvent.participants.find(p=>p.id===e.payerId)?.name} • {new Date(e.date).toLocaleDateString()}</p></div><div className="text-right shrink-0"><p className="font-bold text-slate-800">₹{e.amount.toFixed(2)}</p><p className="text-[8px] text-slate-300 font-bold uppercase">{e.category}</p></div></div>
                    </div>
                  ))}
              </div>
            </div>
            <div className="lg:col-span-4"><ExpenseForm participants={activeEvent.participants} onAdd={addExpense} /></div>
          </div>
        ) : (
          <SettlementView participants={activeEvent.participants} balances={balances} settlements={settlements} totalSpent={totalSpent} onSettle={handleSettle} />
        )}
      </main>

      {showShareModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
          <div className="bg-white rounded-[2.5rem] max-w-sm w-full shadow-2xl animate-in zoom-in-95 duration-200">
            <div className="p-8 border-b border-slate-100 flex justify-between items-center"><h3 className="text-xl font-bold text-slate-800">Share "{events[shareEventId!]?.name}"</h3><button onClick={() => setShowShareModal(false)} className="text-slate-400 hover:text-slate-600"><i className="fa-solid fa-xmark text-lg"></i></button></div>
            <div className="p-8 grid grid-cols-2 gap-4 relative">
              <button onClick={handleShareWhatsApp} className="flex flex-col items-center gap-2 p-6 rounded-3xl bg-green-50 hover:bg-green-100 transition-colors"><div className="w-12 h-12 bg-green-500 rounded-full flex items-center justify-center text-white"><i className="fa-brands fa-whatsapp text-2xl"></i></div><span className="text-xs font-bold text-green-700">WhatsApp</span></button>
              <button onClick={handleCopyLink} className={`flex flex-col items-center gap-2 p-6 rounded-3xl transition-colors ${shareStatus === 'copied' ? 'bg-indigo-100' : 'bg-slate-50'}`}><div className={`w-12 h-12 rounded-full flex items-center justify-center text-white ${shareStatus === 'copied' ? 'bg-indigo-600' : 'bg-slate-700'}`}><i className={`fa-solid ${shareStatus === 'copied' ? 'fa-check' : 'fa-link'} text-xl`}></i></div><span className="text-xs font-bold text-slate-700">{shareStatus === 'copied' ? 'Copied!' : 'Copy Link'}</span></button>
            </div>
            <div className="p-6 bg-slate-50 rounded-b-[2.5rem] text-center"><p className="text-[10px] text-slate-400 font-bold uppercase tracking-[0.2em]">Shared via splitits.in</p></div>
          </div>
        </div>
      )}

      {selectedExpense && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
          <div className="bg-white rounded-3xl max-w-lg w-full overflow-hidden shadow-2xl p-8 space-y-6 animate-in zoom-in-95">
            <div className="flex justify-between items-center"><h3 className="text-xl font-bold">Expense Detail</h3><button onClick={() => setSelectedExpense(null)} className="text-slate-400 hover:text-slate-800"><i className="fa-solid fa-xmark"></i></button></div>
            <div className="space-y-4">
              <div className="flex justify-between items-center pb-4 border-b border-slate-50"><span>Description</span><span className="font-bold text-lg">{selectedExpense.description}</span></div>
              <div className="flex justify-between items-center pb-4 border-b border-slate-50"><span>Amount</span><span className="font-black text-2xl text-[#4f46e5]">₹{selectedExpense.amount}</span></div>
              <div className="flex justify-between items-center pb-4 border-b border-slate-50"><span>Who Paid</span><span className="font-bold">{activeEvent.participants.find(p=>p.id===selectedExpense.payerId)?.name}</span></div>
            </div>
            <button onClick={() => removeExpense(selectedExpense.id)} className="w-full py-4 bg-red-50 text-red-500 font-bold rounded-2xl hover:bg-red-100 transition-colors flex items-center justify-center gap-2"><i className="fa-solid fa-trash-can"></i>Delete Transaction</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { createClient } from '@supabase/supabase-js';
import { Participant, Expense, Settlement, Balance, SplitEvent } from './types.ts';
import ParticipantManager from './components/ParticipantManager.tsx';
import ExpenseForm from './components/ExpenseForm.tsx';
import SettlementView from './components/SettlementView.tsx';
import { calculateBalances, calculateSettlements } from './utils/calculation.ts';

// Initialize Supabase Client
const supabase = createClient(
  process.env.SUPABASE_URL || '',
  process.env.SUPABASE_ANON_KEY || ''
);

const App: React.FC = () => {
  const [events, setEvents] = useState<Record<string, SplitEvent>>({});
  const [currentEventId, setCurrentEventId] = useState<string | null>(null);
  const [newEventName, setNewEventName] = useState('');

  // App states scoped to the active event
  const [activeTab, setActiveTab] = useState<'expenses' | 'settlement'>('expenses');
  const [selectedExpense, setSelectedExpense] = useState<Expense | null>(null);
  const [shareStatus, setShareStatus] = useState<'idle' | 'saving' | 'copied' | 'error'>('idle');
  const [showShareModal, setShowShareModal] = useState(false);
  const [shareEventId, setShareEventId] = useState<string | null>(null);
  const [lastSharedUrl, setLastSharedUrl] = useState<string | null>(null);
  const [isInitialized, setIsInitialized] = useState(false);

  const getAvatar = (name: string) => `https://api.dicebear.com/7.x/initials/svg?seed=${name}&backgroundColor=4f46e5&textColor=ffffff`;

  // Fetch Logic: On mount, check for /trip/[ID] pattern in hash
  useEffect(() => {
    const loadData = async () => {
      // 1. Load Local Events
      const savedEvents = localStorage.getItem('splitit_multi_events');
      let currentEvents: Record<string, SplitEvent> = savedEvents ? JSON.parse(savedEvents) : {};

      // 2. Check for Shared Trip ID in URL Hash (#/trip/UUID)
      const hash = window.location.hash;
      const tripMatch = hash.match(/#\/trip\/([a-f0-9-]{36})/i);

      if (tripMatch && tripMatch[1]) {
        const tripId = tripMatch[1];
        try {
          const { data, error } = await supabase
            .from('trips')
            .select('trip_data')
            .eq('id', tripId)
            .single();

          if (data && data.trip_data) {
            const remoteEvent = data.trip_data as SplitEvent;
            // Add or update the local store with fetched data
            const internalId = remoteEvent.id || `shared-${tripId}`;
            currentEvents[internalId] = { ...remoteEvent, id: internalId };
            setCurrentEventId(internalId);

            // Cleanup URL hash
            window.history.replaceState(null, "", window.location.pathname);
          }
        } catch (err) {
          console.error("Error fetching trip from Supabase:", err);
        }
      }

      setEvents(currentEvents);
      setIsInitialized(true);
    };

    loadData();
  }, []);

  // Sync state to LocalStorage
  useEffect(() => {
    if (isInitialized) {
      localStorage.setItem('splitit_multi_events', JSON.stringify(events));
    }
  }, [events, isInitialized]);

  const activeEvent = currentEventId ? events[currentEventId] : null;

  const { balances, settlements, totalSpent } = useMemo(() => {
    if (!activeEvent) return { balances: [], settlements: [], totalSpent: 0 };
    const bals = calculateBalances(activeEvent.participants, activeEvent.expenses);
    const setts = calculateSettlements([...bals]);
    const total = activeEvent.expenses.reduce((acc, curr) => curr.category !== 'Payment' ? acc + curr.amount : acc, 0);
    return { balances: bals, settlements: setts, totalSpent: total };
  }, [activeEvent]);

  // Actions
  const createEvent = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newEventName.trim()) return;
    const id = crypto.randomUUID();
    const newEv: SplitEvent = {
      id,
      name: newEventName.trim(),
      participants: [],
      expenses: [],
      createdAt: Date.now()
    };
    setEvents(prev => ({ ...prev, [id]: newEv }));
    setNewEventName('');
    setCurrentEventId(id);
  };

  const deleteEvent = (id: string) => {
    if (window.confirm("Delete this event forever?")) {
      const newEvents = { ...events };
      delete newEvents[id];
      setEvents(newEvents);
      if (currentEventId === id) setCurrentEventId(null);
    }
  };

  const updateActiveEvent = (updates: Partial<SplitEvent>) => {
    if (!currentEventId) return;
    setEvents(prev => ({
      ...prev,
      [currentEventId]: { ...prev[currentEventId], ...updates }
    }));
  };

  const addParticipant = (name: string, upiId?: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      participants: [...activeEvent.participants, { id: crypto.randomUUID(), name, avatar: getAvatar(name), upiId }]
    });
  };

  const removeParticipant = (id: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      participants: activeEvent.participants.filter(p => p.id !== id),
      expenses: activeEvent.expenses.filter(e => e.payerId !== id && !e.participantIds.includes(id))
    });
  };

  const addExpense = (newExp: Omit<Expense, 'id'>) => {
    if (!activeEvent) return;
    updateActiveEvent({
      expenses: [{ ...newExp, id: crypto.randomUUID() }, ...activeEvent.expenses]
    });
  };

  const removeExpense = (id: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      expenses: activeEvent.expenses.filter(e => e.id !== id)
    });
    if (selectedExpense?.id === id) setSelectedExpense(null);
  };

  const handleSettle = (fromId: string, toId: string, amount: number) => {
    if (!activeEvent) return;
    const fromP = activeEvent.participants.find(p => p.id === fromId)?.name;
    const toP = activeEvent.participants.find(p => p.id === toId)?.name;
    addExpense({
      description: `Settlement: ${fromP} paid ${toP}`,
      amount: amount, payerId: fromId, participantIds: [toId], category: 'Payment', date: Date.now()
    });
  };

  // Save Logic: Upload to Supabase and generate shared URL
  const handleShareToSupabase = async () => {
    if (!shareEventId || !events[shareEventId]) return;

    setShareStatus('saving');
    const targetEvent = events[shareEventId];

    try {
      const { data, error } = await supabase
        .from('trips')
        .insert([{ 
          trip_data: targetEvent,
          name: targetEvent.name 
        }])
        .select();

      if (error) throw error;

      if (data && data[0]) {
        const sharedId = data[0].id;
        const url = `https://splitits.in/#/trip/${sharedId}`;
        setLastSharedUrl(url);
        setShareStatus('idle');
      }
    } catch (err) {
      console.error("Supabase Save Error:", err);
      setShareStatus('error');
    }
  };

  const openShareModal = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setShareEventId(id);
    setLastSharedUrl(null);
    setShareStatus('idle');
    setShowShareModal(true);
  };

  const handleCopyLink = () => {
    if (!lastSharedUrl) return;
    navigator.clipboard.writeText(lastSharedUrl).then(() => {
      setShareStatus('copied');
      setTimeout(() => setShareStatus('idle'), 2000);
    });
  };

  const handleShareWhatsApp = () => {
    if (!lastSharedUrl) return;
    const ev = events[shareEventId!];
    const text = `💰 *SplitIt: ${ev.name}*\n\nSettlements are ready! View & pay here:\n\n🔗 ${lastSharedUrl}`;
    window.open(`https://api.whatsapp.com/send?text=${encodeURIComponent(text)}`, '_blank');
  };

  // Dashboard View
  if (!currentEventId) {
    return (
      <div className="min-h-screen bg-[#f8fafc] flex flex-col font-sans">
        <header className="bg-white border-b border-slate-100 p-6 sm:p-8 flex items-center justify-between">
          <div className="flex items-center gap-3">
             <div className="w-10 h-10 bg-[#4f46e5] rounded-xl flex items-center justify-center text-white text-2xl"><i className="fa-solid fa-receipt"></i></div>
             <h1 className="text-2xl font-black text-slate-800 tracking-tight">SplitIt</h1>
          </div>
          <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest bg-slate-100 px-4 py-1.5 rounded-full">Dashboard</span>
        </header>

        <main className="flex-1 max-w-5xl mx-auto w-full px-4 py-8 sm:py-16 space-y-12">
          <section className="bg-white rounded-[2.5rem] p-8 sm:p-12 shadow-xl shadow-indigo-50/50 border border-slate-100 text-center space-y-8">
            <div className="space-y-2">
              <h2 className="text-3xl font-bold text-slate-800">New Group Session</h2>
              <p className="text-slate-400 font-medium">Split bills instantly for trips, parties, or dinners.</p>
            </div>
            <form onSubmit={createEvent} className="max-w-md mx-auto relative group">
              <input 
                type="text" 
                value={newEventName}
                onChange={e => setNewEventName(e.target.value)}
                placeholder="Enter event name... e.g. Goa 2024"
                className="w-full px-8 py-5 rounded-3xl bg-slate-50 border-2 border-transparent focus:border-[#4f46e5] focus:bg-white text-lg font-bold transition-all outline-none pr-36 shadow-inner"
              />
              <button 
                type="submit"
                className="absolute right-2 top-2 bottom-2 bg-[#4f46e5] text-white px-8 rounded-2xl font-black text-sm hover:bg-[#4338ca] transition-all shadow-lg active:scale-95"
              >
                START
              </button>
            </form>
          </section>

          {Object.values(events).length > 0 && (
            <section className="space-y-6">
              <div className="flex items-center justify-between px-2">
                <h3 className="text-sm font-black text-slate-400 uppercase tracking-[0.2em]">Your Active Events</h3>
                <span className="text-xs font-bold text-[#4f46e5]">{Object.values(events).length} Total</span>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
                {(Object.values(events) as SplitEvent[]).sort((a,b) => b.createdAt - a.createdAt).map(ev => {
                  const evTotal = ev.expenses.reduce((acc, curr) => curr.category !== 'Payment' ? acc + curr.amount : acc, 0);
                  return (
                    <div 
                      key={ev.id}
                      onClick={() => setCurrentEventId(ev.id)}
                      className="group bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm hover:shadow-xl hover:border-[#4f46e5]/20 hover:-translate-y-1 transition-all cursor-pointer flex flex-col justify-between min-h-[220px]"
                    >
                      <div className="space-y-4">
                        <div className="flex justify-between items-start">
                          <div className="w-10 h-10 bg-[#eef2ff] text-[#4f46e5] rounded-xl flex items-center justify-center text-lg font-black group-hover:bg-[#4f46e5] group-hover:text-white transition-colors">
                            {ev.name.charAt(0)}
                          </div>
                          <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                            <button onClick={(e) => openShareModal(e, ev.id)} className="w-8 h-8 rounded-full bg-slate-50 text-slate-400 hover:text-[#4f46e5] flex items-center justify-center transition-colors"><i className="fa-solid fa-share-nodes text-xs"></i></button>
                            <button onClick={(e) => { e.stopPropagation(); deleteEvent(ev.id); }} className="w-8 h-8 rounded-full bg-slate-50 text-slate-400 hover:text-red-500 flex items-center justify-center transition-colors"><i className="fa-solid fa-trash text-xs"></i></button>
                          </div>
                        </div>
                        <div>
                          <h4 className="text-xl font-bold text-slate-800 line-clamp-1">{ev.name}</h4>
                          <p className="text-[10px] font-bold text-slate-400 uppercase mt-1">{new Date(ev.createdAt).toLocaleDateString()} • {ev.participants.length} People</p>
                        </div>
                      </div>
                      <div className="pt-4 border-t border-slate-50 flex items-end justify-between">
                         <div>
                            <span className="block text-[8px] font-black text-slate-300 uppercase tracking-widest">Spent</span>
                            <span className="text-xl font-black text-slate-800">₹{evTotal.toFixed(0)}</span>
                         </div>
                         <i className="fa-solid fa-chevron-right text-slate-200 group-hover:translate-x-1 group-hover:text-[#4f46e5] transition-all"></i>
                      </div>
                    </div>
                  );
                })}
              </div>
            </section>
          )}
        </main>
      </div>
    );
  }

  // Management View
  return (
    <div className="min-h-screen bg-[#f8fafc] text-slate-900 flex flex-col font-sans overflow-x-hidden">
      <header className="bg-white border-b border-slate-100 sticky top-0 z-30 shadow-sm px-4">
        <div className="max-w-7xl mx-auto h-20 flex items-center justify-between gap-2">
          <div className="flex items-center gap-4">
            <button onClick={() => setCurrentEventId(null)} className="w-10 h-10 rounded-full hover:bg-slate-50 flex items-center justify-center text-slate-400 hover:text-slate-800 transition-all"><i className="fa-solid fa-arrow-left"></i></button>
            <div className="flex flex-col min-w-0">
              <h1 className="text-lg sm:text-xl font-bold text-[#1e293b] truncate">{activeEvent.name}</h1>
              <p className="text-[9px] font-bold text-slate-400 tracking-[0.1em] uppercase">Supabase Synced</p>
            </div>
          </div>
          <nav className="flex bg-[#f1f5f9] p-1 rounded-xl shrink-0">
            <button onClick={() => setActiveTab('expenses')} className={`px-4 sm:px-6 py-2 rounded-lg text-xs font-semibold transition-all ${activeTab === 'expenses' ? 'bg-white text-[#4f46e5] shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Overview</button>
            <button onClick={() => setActiveTab('settlement')} className={`px-4 sm:px-6 py-2 rounded-lg text-xs font-semibold transition-all ${activeTab === 'settlement' ? 'bg-white text-[#4f46e5] shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Settlement</button>
          </nav>
        </div>
      </header>

      <main className="flex-1 max-w-7xl mx-auto w-full px-4 sm:px-6 py-6 sm:py-8 space-y-6">
        <div className="flex items-center justify-between bg-white px-6 py-4 rounded-3xl border border-slate-100 shadow-sm">
          <div className="flex gap-8">
            <div><span className="text-[8px] font-bold text-slate-400 uppercase block mb-1">Total Spent</span><p className="text-lg font-black">₹{totalSpent.toFixed(0)}</p></div>
            <div><span className="text-[8px] font-bold text-slate-400 uppercase block mb-1">Squad</span><p className="text-lg font-black">{activeEvent.participants.length}</p></div>
          </div>
          <button 
            onClick={(e) => openShareModal(e, activeEvent.id)}
            className="flex items-center gap-2 px-6 py-3 rounded-2xl text-xs font-bold transition-all bg-[#4f46e5] text-white hover:bg-[#4338ca] shadow-md shadow-indigo-100"
          >
            <i className="fa-solid fa-share-nodes"></i>
            Share Dues
          </button>
        </div>

        {activeTab === 'expenses' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
            <div className="lg:col-span-3"><ParticipantManager participants={activeEvent.participants} onAdd={addParticipant} onRemove={removeParticipant} /></div>
            <div className="lg:col-span-5 space-y-4">
              <div className="flex justify-between items-center"><h2 className="text-lg font-bold flex items-center gap-2"><i className="fa-solid fa-list-ul text-[#4f46e5]"></i>Recent Activity</h2><span className="text-[10px] font-bold text-slate-400 bg-slate-100 px-3 py-1 rounded-full">{activeEvent.expenses.length} Records</span></div>
              <div className="min-h-[400px] bg-white border border-slate-100 rounded-3xl p-4 overflow-y-auto max-h-[600px] scrollbar-hide">
                {activeEvent.expenses.length === 0 ? <div className="h-full flex flex-col items-center justify-center text-center text-slate-300"><i className="fa-solid fa-receipt text-3xl mb-2"></i><p className="text-sm font-bold">No expenses yet</p></div> : 
                  activeEvent.expenses.sort((a,b) => b.date - a.date).map(e => (
                    <div key={e.id} onClick={() => setSelectedExpense(e)} className={`p-4 mb-3 rounded-xl border transition-all cursor-pointer ${e.category === 'Payment' ? 'bg-slate-50 border-slate-100 italic' : 'bg-white border-slate-50 hover:border-[#4f46e5]'}`}>
                      <div className="flex justify-between items-center"><div className="min-w-0"><p className="font-bold text-slate-800 truncate">{e.description}</p><p className="text-[9px] text-slate-400 font-bold uppercase">{activeEvent.participants.find(p=>p.id===e.payerId)?.name} • {new Date(e.date).toLocaleDateString()}</p></div><div className="text-right shrink-0"><p className="font-bold text-slate-800">₹{e.amount.toFixed(2)}</p><p className="text-[8px] text-slate-300 font-bold uppercase">{e.category}</p></div></div>
                    </div>
                  ))}
              </div>
            </div>
            <div className="lg:col-span-4"><ExpenseForm participants={activeEvent.participants} onAdd={addExpense} /></div>
          </div>
        ) : (
          <SettlementView participants={activeEvent.participants} balances={balances} settlements={settlements} totalSpent={totalSpent} onSettle={handleSettle} />
        )}
      </main>

      {/* Share Modal with Supabase logic */}
      {showShareModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
          <div className="bg-white rounded-[2.5rem] max-w-sm w-full shadow-2xl animate-in zoom-in-95 duration-200">
            <div className="p-8 border-b border-slate-100 flex justify-between items-center">
              <div>
                <h3 className="text-xl font-bold text-slate-800">Share Group</h3>
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">Cloud Persistence</p>
              </div>
              <button onClick={() => setShowShareModal(false)} className="text-slate-400 hover:text-slate-600"><i className="fa-solid fa-xmark text-lg"></i></button>
            </div>

            <div className="p-8 space-y-4">
              {shareStatus === 'saving' ? (
                <div className="flex flex-col items-center justify-center py-12 gap-3 text-[#4f46e5]">
                  <i className="fa-solid fa-cloud-arrow-up text-3xl animate-bounce"></i>
                  <p className="text-xs font-black uppercase tracking-widest">Saving to Cloud...</p>
                </div>
              ) : lastSharedUrl ? (
                <div className="space-y-4 animate-in fade-in zoom-in-95">
                  <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100 flex flex-col items-center gap-2">
                    <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Shareable Link</span>
                    <p className="text-xs font-medium text-slate-800 break-all text-center">{lastSharedUrl}</p>
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <button onClick={handleShareWhatsApp} className="flex flex-col items-center gap-2 p-6 rounded-3xl bg-green-50 hover:bg-green-100 transition-colors">
                      <div className="w-12 h-12 bg-green-500 rounded-full flex items-center justify-center text-white"><i className="fa-brands fa-whatsapp text-2xl"></i></div>
                      <span className="text-xs font-bold text-green-700">WhatsApp</span>
                    </button>
                    <button onClick={handleCopyLink} className={`flex flex-col items-center gap-2 p-6 rounded-3xl transition-colors ${shareStatus === 'copied' ? 'bg-indigo-100' : 'bg-slate-50'}`}>
                      <div className={`w-12 h-12 rounded-full flex items-center justify-center text-white ${shareStatus === 'copied' ? 'bg-indigo-600' : 'bg-slate-700'}`}>
                        <i className={`fa-solid ${shareStatus === 'copied' ? 'fa-check' : 'fa-link'} text-xl`}></i>
                      </div>
                      <span className="text-xs font-bold text-slate-700">{shareStatus === 'copied' ? 'Copied!' : 'Copy Link'}</span>
                    </button>
                  </div>
                </div>
              ) : (
                <button 
                  onClick={handleShareToSupabase}
                  className="w-full py-6 bg-[#4f46e5] text-white rounded-3xl font-black text-sm hover:bg-[#4338ca] transition-all shadow-xl shadow-indigo-100"
                >
                  <i className="fa-solid fa-cloud-arrow-up mr-2"></i>
                  CREATE SHORT LINK
                </button>
              )}
              {shareStatus === 'error' && <p className="text-[10px] text-red-500 font-bold text-center">Failed to save. Try again.</p>}
            </div>
            <div className="p-6 bg-slate-50 rounded-b-[2.5rem] text-center"><p className="text-[10px] text-slate-400 font-bold uppercase tracking-[0.2em]">Data synced via Supabase trips table</p></div>
          </div>
        </div>
      )}

      {selectedExpense && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
          <div className="bg-white rounded-3xl max-w-lg w-full overflow-hidden shadow-2xl p-8 space-y-6 animate-in zoom-in-95">
            <div className="flex justify-between items-center"><h3 className="text-xl font-bold">Expense Detail</h3><button onClick={() => setSelectedExpense(null)} className="text-slate-400 hover:text-slate-800"><i className="fa-solid fa-xmark"></i></button></div>
            <div className="space-y-4">
              <div className="flex justify-between items-center pb-4 border-b border-slate-50"><span>Description</span><span className="font-bold text-lg">{selectedExpense.description}</span></div>
              <div className="flex justify-between items-center pb-4 border-b border-slate-50"><span>Amount</span><span className="font-black text-2xl text-[#4f46e5]">₹{selectedExpense.amount}</span></div>
              <div className="flex justify-between items-center pb-4 border-b border-slate-50"><span>Who Paid</span><span className="font-bold">{activeEvent.participants.find(p=>p.id===selectedExpense.payerId)?.name}</span></div>
            </div>
            <button onClick={() => removeExpense(selectedExpense.id)} className="w-full py-4 bg-red-50 text-red-500 font-bold rounded-2xl hover:bg-red-100 transition-colors flex items-center justify-center gap-2"><i className="fa-solid fa-trash-can"></i>Delete Transaction</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { createClient } from '@supabase/supabase-js';
import { Participant, Expense, Settlement, Balance, SplitEvent } from './types.ts';
import ParticipantManager from './components/ParticipantManager.tsx';
import ExpenseForm from './components/ExpenseForm.tsx';
import SettlementView from './components/SettlementView.tsx';
import { calculateBalances, calculateSettlements } from './utils/calculation.ts';

// Initialize Supabase client
const supabase = createClient(
  process.env.SUPABASE_URL || '',
  process.env.SUPABASE_ANON_KEY || ''
);

const App: React.FC = () => {
  const [events, setEvents] = useState<Record<string, SplitEvent>>({});
  const [currentEventId, setCurrentEventId] = useState<string | null>(null);
  const [newEventName, setNewEventName] = useState('');

  // App states scoped to the active event
  const [activeTab, setActiveTab] = useState<'expenses' | 'settlement'>('expenses');
  const [selectedExpense, setSelectedExpense] = useState<Expense | null>(null);
  const [shareStatus, setShareStatus] = useState<'idle' | 'saving' | 'copied' | 'error'>('idle');
  const [showShareModal, setShowShareModal] = useState(false);
  const [shareEventId, setShareEventId] = useState<string | null>(null);
  const [generatedShortUrl, setGeneratedShortUrl] = useState<string | null>(null);
  const [isInitialized, setIsInitialized] = useState(false);

  const getAvatar = (name: string) => `https://api.dicebear.com/7.x/initials/svg?seed=${name}&backgroundColor=4f46e5&textColor=ffffff`;

  // Fetch Logic: On mount, check if URL contains a trip ID and load it
  useEffect(() => {
    const loadInitialData = async () => {
      // First load local storage
      const savedEvents = localStorage.getItem('splitit_multi_events');
      let currentEvents: Record<string, SplitEvent> = savedEvents ? JSON.parse(savedEvents) : {};

      // Check for /trip/[ID] in hash
      const hash = window.location.hash;
      const tripMatch = hash.match(/#\/trip\/([a-f0-9-]{36})/i);

      if (tripMatch && tripMatch[1]) {
        const tripUuid = tripMatch[1];
        try {
          const { data, error } = await supabase
            .from('trips')
            .select('trip_data')
            .eq('id', tripUuid)
            .single();

          if (error) throw error;

          if (data && data.trip_data) {
            const fetchedEvent = data.trip_data as SplitEvent;
            // Use the remote event, but ensure it's uniquely identified in local list
            const localId = fetchedEvent.id || tripUuid;
            currentEvents[localId] = fetchedEvent;
            setCurrentEventId(localId);

            // Clean up the URL to prevent double loading
            window.history.replaceState(null, "", window.location.pathname);
          }
        } catch (err) {
          console.error("Failed to fetch trip from Supabase:", err);
          alert("Could not load shared trip. It might have been deleted or the link is invalid.");
        }
      }

      setEvents(currentEvents);
      setIsInitialized(true);
    };

    loadInitialData();
  }, []);

  useEffect(() => {
    if (isInitialized) {
      localStorage.setItem('splitit_multi_events', JSON.stringify(events));
    }
  }, [events, isInitialized]);

  // Active event helper
  const activeEvent = currentEventId ? events[currentEventId] : null;

  // Derived data for active event
  const { balances, settlements, totalSpent } = useMemo(() => {
    if (!activeEvent) return { balances: [], settlements: [], totalSpent: 0 };

    const bals = calculateBalances(activeEvent.participants, activeEvent.expenses);
    const setts = calculateSettlements([...bals]);
    const total = activeEvent.expenses.reduce((acc, curr) => curr.category !== 'Payment' ? acc + curr.amount : acc, 0);

    return { 
      balances: bals, 
      settlements: setts, 
      totalSpent: total
    };
  }, [activeEvent]);

  // Actions
  const createEvent = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newEventName.trim()) return;
    const id = crypto.randomUUID();
    const newEv: SplitEvent = {
      id,
      name: newEventName.trim(),
      participants: [],
      expenses: [],
      createdAt: Date.now()
    };
    setEvents(prev => ({ ...prev, [id]: newEv }));
    setNewEventName('');
    setCurrentEventId(id);
  };

  const deleteEvent = (id: string) => {
    if (window.confirm("Delete this event forever?")) {
      const newEvents = { ...events };
      delete newEvents[id];
      setEvents(newEvents);
      if (currentEventId === id) setCurrentEventId(null);
    }
  };

  const updateActiveEvent = (updates: Partial<SplitEvent>) => {
    if (!currentEventId) return;
    setEvents(prev => ({
      ...prev,
      [currentEventId]: { ...prev[currentEventId], ...updates }
    }));
  };

  const addParticipant = (name: string, upiId?: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      participants: [...activeEvent.participants, { id: crypto.randomUUID(), name, avatar: getAvatar(name), upiId }]
    });
  };

  const removeParticipant = (id: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      participants: activeEvent.participants.filter(p => p.id !== id),
      expenses: activeEvent.expenses.filter(e => e.payerId !== id && !e.participantIds.includes(id))
    });
  };

  const addExpense = (newExp: Omit<Expense, 'id'>) => {
    if (!activeEvent) return;
    updateActiveEvent({
      expenses: [{ ...newExp, id: crypto.randomUUID() }, ...activeEvent.expenses]
    });
  };

  const removeExpense = (id: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      expenses: activeEvent.expenses.filter(e => e.id !== id)
    });
    if (selectedExpense?.id === id) setSelectedExpense(null);
  };

  const handleSettle = (fromId: string, toId: string, amount: number) => {
    if (!activeEvent) return;
    const fromP = activeEvent.participants.find(p => p.id === fromId)?.name;
    const toP = activeEvent.participants.find(p => p.id === toId)?.name;
    addExpense({
      description: `Settlement: ${fromP} paid ${toP}`,
      amount: amount, payerId: fromId, participantIds: [toId], category: 'Payment', date: Date.now()
    });
  };

  // Save Logic: Push to Supabase trips table
  const handleShareToSupabase = async () => {
    if (!shareEventId || !events[shareEventId]) return;

    setShareStatus('saving');
    const targetEvent = events[shareEventId];

    try {
      const { data, error } = await supabase
        .from('trips')
        .insert([{ 
          trip_data: targetEvent,
          name: targetEvent.name 
        }])
        .select('id')
        .single();

      if (error) throw error;

      if (data && data.id) {
        const shortUrl = `https://splitits.in/#/trip/${data.id}`;
        setGeneratedShortUrl(shortUrl);
        setShareStatus('idle');
      }
    } catch (err) {
      console.error("Error saving to Supabase:", err);
      setShareStatus('error');
    }
  };

  const openShareModal = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setShareEventId(id);
    setGeneratedShortUrl(null);
    setShareStatus('idle');
    setShowShareModal(true);
  };

  const handleShareWhatsApp = () => {
    if (!generatedShortUrl) return;
    const ev = events[shareEventId!];
    const settlementText = settlements.length === 0 ? "All settled! ✅" : settlements.map(s => `💸 *${ev.participants.find(p=>p.id===s.from)?.name}* owes *${ev.participants.find(p=>p.id===s.to)?.name}*: ₹${s.amount.toFixed(2)}`).join('\n');
    const text = `💰 *SplitIt: ${ev.name}*\n\n*Settlements:*\n${settlementText}\n\n🔗 View & Settle:\n${generatedShortUrl}`;
    window.open(`https://api.whatsapp.com/send?text=${encodeURIComponent(text)}`, '_blank');
  };

  const handleCopyLink = () => {
    if (!generatedShortUrl) return;
    navigator.clipboard.writeText(generatedShortUrl).then(() => {
      setShareStatus('copied');
      setTimeout(() => setShareStatus('idle'), 2000);
    });
  };

  // Dashboard Render
  if (!currentEventId) {
    return (
      <div className="min-h-screen bg-[#f8fafc] flex flex-col font-sans">
        <header className="bg-white border-b border-slate-100 p-6 sm:p-8 flex items-center justify-between">
          <div className="flex items-center gap-3">
             <div className="w-10 h-10 bg-[#4f46e5] rounded-xl flex items-center justify-center text-white text-2xl"><i className="fa-solid fa-receipt"></i></div>
             <h1 className="text-2xl font-black text-slate-800 tracking-tight">SplitIt</h1>
          </div>
          <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest bg-slate-100 px-4 py-1.5 rounded-full">Dashboard</span>
        </header>

        <main className="flex-1 max-w-5xl mx-auto w-full px-4 py-8 sm:py-16 space-y-12">
          {/* Create Event Section */}
          <section className="bg-white rounded-[2.5rem] p-8 sm:p-12 shadow-xl shadow-indigo-50/50 border border-slate-100 text-center space-y-8">
            <div className="space-y-2">
              <h2 className="text-3xl font-bold text-slate-800">New Group Session</h2>
              <p className="text-slate-400 font-medium">Split bills instantly for trips, parties, or dinners.</p>
            </div>

            <form onSubmit={createEvent} className="max-w-md mx-auto relative group">
              <input 
                type="text" 
                value={newEventName}
                onChange={e => setNewEventName(e.target.value)}
                placeholder="Enter event name... e.g. Goa 2024"
                className="w-full px-8 py-5 rounded-3xl bg-slate-50 border-2 border-transparent focus:border-[#4f46e5] focus:bg-white text-lg font-bold transition-all outline-none pr-36 shadow-inner"
              />
              <button 
                type="submit"
                className="absolute right-2 top-2 bottom-2 bg-[#4f46e5] text-white px-8 rounded-2xl font-black text-sm hover:bg-[#4338ca] transition-all shadow-lg active:scale-95"
              >
                START
              </button>
            </form>
          </section>

          {/* Existing Events Grid */}
          {Object.values(events).length > 0 && (
            <section className="space-y-6">
              <div className="flex items-center justify-between px-2">
                <h3 className="text-sm font-black text-slate-400 uppercase tracking-[0.2em]">Your Active Events</h3>
                <span className="text-xs font-bold text-[#4f46e5]">{Object.values(events).length} Saved</span>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
                {(Object.values(events) as SplitEvent[]).sort((a: SplitEvent, b: SplitEvent) => b.createdAt - a.createdAt).map((ev: SplitEvent) => {
                  const evTotal = ev.expenses.reduce((acc, curr) => curr.category !== 'Payment' ? acc + curr.amount : acc, 0);
                  return (
                    <div 
                      key={ev.id}
                      onClick={() => setCurrentEventId(ev.id)}
                      className="group bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm hover:shadow-xl hover:border-[#4f46e5]/20 hover:-translate-y-1 transition-all cursor-pointer flex flex-col justify-between min-h-[220px]"
                    >
                      <div className="space-y-4">
                        <div className="flex justify-between items-start">
                          <div className="w-10 h-10 bg-[#eef2ff] text-[#4f46e5] rounded-xl flex items-center justify-center text-lg font-black group-hover:bg-[#4f46e5] group-hover:text-white transition-colors">
                            {ev.name.charAt(0)}
                          </div>
                          <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                            <button onClick={(e) => openShareModal(e, ev.id)} className="w-8 h-8 rounded-full bg-slate-50 text-slate-400 hover:text-[#4f46e5] flex items-center justify-center transition-colors"><i className="fa-solid fa-share-nodes text-xs"></i></button>
                            <button onClick={(e) => { e.stopPropagation(); deleteEvent(ev.id); }} className="w-8 h-8 rounded-full bg-slate-50 text-slate-400 hover:text-red-500 flex items-center justify-center transition-colors"><i className="fa-solid fa-trash text-xs"></i></button>
                          </div>
                        </div>
                        <div>
                          <h4 className="text-xl font-bold text-slate-800 line-clamp-1">{ev.name}</h4>
                          <p className="text-[10px] font-bold text-slate-400 uppercase mt-1">{new Date(ev.createdAt).toLocaleDateString()} • {ev.participants.length} People</p>
                        </div>
                      </div>

                      <div className="pt-4 border-t border-slate-50 flex items-end justify-between">
                         <div>
                            <span className="block text-[8px] font-black text-slate-300 uppercase tracking-widest">Spent</span>
                            <span className="text-xl font-black text-slate-800">₹{evTotal.toFixed(0)}</span>
                         </div>
                         <i className="fa-solid fa-chevron-right text-slate-200 group-hover:translate-x-1 group-hover:text-[#4f46e5] transition-all"></i>
                      </div>
                    </div>
                  );
                })}
              </div>
            </section>
          )}
        </main>
      </div>
    );
  }

  // Active Event View
  return (
    <div className="min-h-screen bg-[#f8fafc] text-slate-900 flex flex-col font-sans overflow-x-hidden">
      <header className="bg-white border-b border-slate-100 sticky top-0 z-30 shadow-sm px-4">
        <div className="max-w-7xl mx-auto h-20 flex items-center justify-between gap-2">
          <div className="flex items-center gap-4">
            <button 
              onClick={() => setCurrentEventId(null)}
              className="w-10 h-10 rounded-full hover:bg-slate-50 flex items-center justify-center text-slate-400 hover:text-slate-800 transition-all"
            >
              <i className="fa-solid fa-arrow-left"></i>
            </button>
            <div className="flex flex-col min-w-0">
              <h1 className="text-lg sm:text-xl font-bold text-[#1e293b] truncate">{activeEvent.name}</h1>
              <p className="text-[9px] font-bold text-slate-400 tracking-[0.1em] uppercase">Supabase Synced</p>
            </div>
          </div>
          <nav className="flex bg-[#f1f5f9] p-1 rounded-xl shrink-0">
            <button onClick={() => setActiveTab('expenses')} className={`px-4 sm:px-6 py-2 rounded-lg text-xs font-semibold transition-all ${activeTab === 'expenses' ? 'bg-white text-[#4f46e5] shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Overview</button>
            <button onClick={() => setActiveTab('settlement')} className={`px-4 sm:px-6 py-2 rounded-lg text-xs font-semibold transition-all ${activeTab === 'settlement' ? 'bg-white text-[#4f46e5] shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Settlement</button>
          </nav>
        </div>
      </header>

      <main className="flex-1 max-w-7xl mx-auto w-full px-4 sm:px-6 py-6 sm:py-8 space-y-6">
        <div className="flex items-center justify-between bg-white px-6 py-4 rounded-3xl border border-slate-100 shadow-sm">
          <div className="flex gap-8">
            <div><span className="text-[8px] font-bold text-slate-400 uppercase block mb-1">Total Spent</span><p className="text-lg font-black">₹{totalSpent.toFixed(0)}</p></div>
            <div><span className="text-[8px] font-bold text-slate-400 uppercase block mb-1">Squad</span><p className="text-lg font-black">{activeEvent.participants.length}</p></div>
          </div>
          <button 
            onClick={(e) => openShareModal(e, activeEvent.id)}
            className="flex items-center gap-2 px-6 py-3 rounded-2xl text-xs font-bold transition-all bg-[#4f46e5] text-white hover:bg-[#4338ca] shadow-md shadow-indigo-100"
          >
            <i className="fa-solid fa-share-nodes"></i>
            Share Dues
          </button>
        </div>

        {activeTab === 'expenses' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
            <div className="lg:col-span-3"><ParticipantManager participants={activeEvent.participants} onAdd={addParticipant} onRemove={removeParticipant} /></div>
            <div className="lg:col-span-5 space-y-4">
              <div className="flex justify-between items-center"><h2 className="text-lg font-bold flex items-center gap-2"><i className="fa-solid fa-list-ul text-[#4f46e5]"></i>Recent Activity</h2><span className="text-[10px] font-bold text-slate-400 bg-slate-100 px-3 py-1 rounded-full">{activeEvent.expenses.length} Records</span></div>
              <div className="min-h-[400px] bg-white border border-slate-100 rounded-3xl p-4 overflow-y-auto max-h-[600px] scrollbar-hide">
                {activeEvent.expenses.length === 0 ? <div className="h-full flex flex-col items-center justify-center text-center text-slate-300"><i className="fa-solid fa-receipt text-3xl mb-2"></i><p className="text-sm font-bold">No expenses yet</p></div> : 
                  activeEvent.expenses.sort((a,b) => b.date - a.date).map(e => (
                    <div key={e.id} onClick={() => setSelectedExpense(e)} className={`p-4 mb-3 rounded-xl border transition-all cursor-pointer ${e.category === 'Payment' ? 'bg-slate-50 border-slate-100 italic' : 'bg-white border-slate-50 hover:border-[#4f46e5]'}`}>
                      <div className="flex justify-between items-center"><div className="min-w-0"><p className="font-bold text-slate-800 truncate">{e.description}</p><p className="text-[9px] text-slate-400 font-bold uppercase">{activeEvent.participants.find(p=>p.id===e.payerId)?.name} • {new Date(e.date).toLocaleDateString()}</p></div><div className="text-right shrink-0"><p className="font-bold text-slate-800">₹{e.amount.toFixed(2)}</p><p className="text-[8px] text-slate-300 font-bold uppercase">{e.category}</p></div></div>
                    </div>
                  ))}
              </div>
            </div>
            <div className="lg:col-span-4"><ExpenseForm participants={activeEvent.participants} onAdd={addExpense} /></div>
          </div>
        ) : (
          <SettlementView participants={activeEvent.participants} balances={balances} settlements={settlements} totalSpent={totalSpent} onSettle={handleSettle} />
        )}
      </main>

      {/* Sharing Modal with Supabase Integration */}
      {showShareModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
          <div className="bg-white rounded-[2.5rem] max-w-sm w-full shadow-2xl animate-in zoom-in-95 duration-200">
            <div className="p-8 border-b border-slate-100 flex justify-between items-center">
              <div>
                <h3 className="text-xl font-bold text-slate-800">Share Group</h3>
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">
                  {shareStatus === 'saving' ? 'Saving to Database...' : 'Instant Cloud Link'}
                </p>
              </div>
              <button onClick={() => setShowShareModal(false)} className="text-slate-400 hover:text-slate-600"><i className="fa-solid fa-xmark text-lg"></i></button>
            </div>

            <div className="p-8 space-y-6">
              {shareStatus === 'saving' ? (
                <div className="flex flex-col items-center justify-center py-12 gap-4">
                  <div className="w-12 h-12 border-4 border-slate-100 border-t-[#4f46e5] rounded-full animate-spin"></div>
                  <p className="text-xs font-bold text-slate-500 uppercase tracking-widest">Optimizing Trip Data...</p>
                </div>
              ) : generatedShortUrl ? (
                <div className="space-y-4 animate-in fade-in duration-300">
                  <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100 text-center">
                    <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest block mb-1">Your Trip URL</span>
                    <p className="text-xs font-medium text-slate-600 truncate">{generatedShortUrl}</p>
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <button onClick={handleShareWhatsApp} className="flex flex-col items-center gap-2 p-6 rounded-3xl bg-green-50 hover:bg-green-100 transition-colors">
                      <div className="w-12 h-12 bg-green-500 rounded-full flex items-center justify-center text-white"><i className="fa-brands fa-whatsapp text-2xl"></i></div>
                      <span className="text-xs font-bold text-green-700">WhatsApp</span>
                    </button>
                    <button onClick={handleCopyLink} className={`flex flex-col items-center gap-2 p-6 rounded-3xl transition-colors ${shareStatus === 'copied' ? 'bg-indigo-100' : 'bg-slate-50'}`}>
                      <div className={`w-12 h-12 rounded-full flex items-center justify-center text-white ${shareStatus === 'copied' ? 'bg-indigo-600' : 'bg-slate-700'}`}>
                        <i className={`fa-solid ${shareStatus === 'copied' ? 'fa-check' : 'fa-link'} text-xl`}></i>
                      </div>
                      <span className="text-xs font-bold text-slate-700">{shareStatus === 'copied' ? 'Copied!' : 'Copy Link'}</span>
                    </button>
                  </div>
                </div>
              ) : (
                <div className="space-y-4">
                  <div className="p-4 bg-indigo-50 rounded-2xl text-center">
                    <p className="text-xs font-medium text-indigo-700">Saving creates a unique ID to share with your squad.</p>
                  </div>
                  <button 
                    onClick={handleShareToSupabase}
                    className="w-full bg-[#4f46e5] text-white py-5 rounded-2xl font-bold text-sm shadow-xl shadow-indigo-100 hover:bg-[#4338ca] transition-all"
                  >
                    Generate Short Link
                  </button>
                </div>
              )}

              {shareStatus === 'error' && (
                <p className="text-[10px] text-red-500 font-bold text-center">Cloud sync failed. Check your connection.</p>
              )}
            </div>

            <div className="p-6 bg-slate-50 rounded-b-[2.5rem] text-center"><p className="text-[10px] text-slate-400 font-bold uppercase tracking-[0.2em]">Data hosted on Supabase</p></div>
          </div>
        </div>
      )}

      {selectedExpense && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
          <div className="bg-white rounded-3xl max-w-lg w-full overflow-hidden shadow-2xl p-8 space-y-6 animate-in zoom-in-95">
            <div className="flex justify-between items-center"><h3 className="text-xl font-bold">Expense Detail</h3><button onClick={() => setSelectedExpense(null)} className="text-slate-400 hover:text-slate-800"><i className="fa-solid fa-xmark"></i></button></div>
            <div className="space-y-4">
              <div className="flex justify-between items-center pb-4 border-b border-slate-50"><span>Description</span><span className="font-bold text-lg">{selectedExpense.description}</span></div>
              <div className="flex justify-between items-center pb-4 border-b border-slate-50"><span>Amount</span><span className="font-black text-2xl text-[#4f46e5]">₹{selectedExpense.amount}</span></div>
              <div className="flex justify-between items-center pb-4 border-b border-slate-50"><span>Who Paid</span><span className="font-bold">{activeEvent.participants.find(p=>p.id===selectedExpense.payerId)?.name}</span></div>
            </div>
            <button onClick={() => removeExpense(selectedExpense.id)} className="w-full py-4 bg-red-50 text-red-500 font-bold rounded-2xl hover:bg-red-100 transition-colors flex items-center justify-center gap-2"><i className="fa-solid fa-trash-can"></i>Delete Transaction</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { createClient, SupabaseClient } from '@supabase/supabase-js';
import { Participant, Expense, Settlement, Balance, SplitEvent } from './types.ts';
import ParticipantManager from './components/ParticipantManager.tsx';
import ExpenseForm from './components/ExpenseForm.tsx';
import SettlementView from './components/SettlementView.tsx';
import { calculateBalances, calculateSettlements } from './utils/calculation.ts';

// Helper to generate a 6-character random ID for truly short URLs
const generateShortId = () => {
  const chars = 'abcdefghijklmnopqrstuvwxyz0123456789';
  let result = '';
  for (let i = 0; i < 6; i++) {
    result += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return result;
};

// Defensive Supabase initialization to prevent app crash if keys are missing from environment
let supabase: SupabaseClient | null = null;
try {
  const url = process.env.SUPABASE_URL;
  const key = process.env.SUPABASE_ANON_KEY;
  if (url && key && url.trim().startsWith('http')) {
    supabase = createClient(url, key);
  }
} catch (e) {
  console.warn("Supabase initialization deferred: Keys might be missing or invalid.");
}

const App: React.FC = () => {
  const [events, setEvents] = useState<Record<string, SplitEvent>>({});
  const [currentEventId, setCurrentEventId] = useState<string | null>(null);
  const [newEventName, setNewEventName] = useState('');

  const [activeTab, setActiveTab] = useState<'expenses' | 'settlement'>('expenses');
  const [selectedExpense, setSelectedExpense] = useState<Expense | null>(null);
  const [shareStatus, setShareStatus] = useState<'idle' | 'saving' | 'copied' | 'error'>('idle');
  const [showShareModal, setShowShareModal] = useState(false);
  const [shareEventId, setShareEventId] = useState<string | null>(null);
  const [generatedShortUrl, setGeneratedShortUrl] = useState<string | null>(null);
  const [isInitialized, setIsInitialized] = useState(false);
  const [isLoadingShared, setIsLoadingShared] = useState(false);

  const getAvatar = (name: string) => `https://api.dicebear.com/7.x/initials/svg?seed=${name}&backgroundColor=4f46e5&textColor=ffffff`;

  // Fetch Logic: Load shared trip from Supabase if a short ID is present in the hash
  useEffect(() => {
    const loadInitialData = async () => {
      // 1. Load Local Storage data
      const savedEvents = localStorage.getItem('splitit_multi_events');
      let currentEvents: Record<string, SplitEvent> = savedEvents ? JSON.parse(savedEvents) : {};

      // 2. Check for Short ID (6 chars) directly after #/ in URL
      const hash = window.location.hash;
      const shortIdMatch = hash.match(/#\/([a-z0-9]{6})$/i);

      if (shortIdMatch && shortIdMatch[1] && supabase) {
        const tripSlug = shortIdMatch[1];
        setIsLoadingShared(true);
        try {
          const { data, error } = await supabase
            .from('trips')
            .select('trip_data')
            .eq('id', tripSlug)
            .single();

          if (!error && data && data.trip_data) {
            const fetchedEvent = data.trip_data as SplitEvent;
            const localId = fetchedEvent.id || tripSlug;
            currentEvents[localId] = fetchedEvent;
            setCurrentEventId(localId);

            // Clean hash to prevent re-fetching on next load
            window.history.replaceState(null, "", window.location.pathname);
          }
        } catch (err) {
          console.error("Failed to fetch trip from Supabase:", err);
        } finally {
          setIsLoadingShared(false);
        }
      }

      setEvents(currentEvents);
      setIsInitialized(true);
    };

    loadInitialData();
  }, []);

  useEffect(() => {
    if (isInitialized) {
      localStorage.setItem('splitit_multi_events', JSON.stringify(events));
    }
  }, [events, isInitialized]);

  const activeEvent = currentEventId ? events[currentEventId] : null;

  const { balances, settlements, totalSpent } = useMemo(() => {
    if (!activeEvent) return { balances: [], settlements: [], totalSpent: 0 };
    const bals = calculateBalances(activeEvent.participants, activeEvent.expenses);
    const setts = calculateSettlements([...bals]);
    const total = activeEvent.expenses.reduce((acc, curr) => curr.category !== 'Payment' ? acc + curr.amount : acc, 0);
    return { balances: bals, settlements: setts, totalSpent: total };
  }, [activeEvent]);

  // Actions
  const createEvent = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newEventName.trim()) return;
    const id = crypto.randomUUID();
    const newEv: SplitEvent = {
      id,
      name: newEventName.trim(),
      participants: [],
      expenses: [],
      createdAt: Date.now()
    };
    setEvents(prev => ({ ...prev, [id]: newEv }));
    setNewEventName('');
    setCurrentEventId(id);
  };

  const deleteEvent = (id: string) => {
    if (window.confirm("Delete this group session?")) {
      const newEvents = { ...events };
      delete newEvents[id];
      setEvents(newEvents);
      if (currentEventId === id) setCurrentEventId(null);
    }
  };

  const updateActiveEvent = (updates: Partial<SplitEvent>) => {
    if (!currentEventId) return;
    setEvents(prev => ({
      ...prev,
      [currentEventId]: { ...prev[currentEventId], ...updates }
    }));
  };

  const addParticipant = (name: string, upiId?: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      participants: [...activeEvent.participants, { id: crypto.randomUUID(), name, avatar: getAvatar(name), upiId }]
    });
  };

  const removeParticipant = (id: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      participants: activeEvent.participants.filter(p => p.id !== id),
      expenses: activeEvent.expenses.filter(e => e.payerId !== id && !e.participantIds.includes(id))
    });
  };

  const addExpense = (newExp: Omit<Expense, 'id'>) => {
    if (!activeEvent) return;
    updateActiveEvent({
      expenses: [{ ...newExp, id: crypto.randomUUID() }, ...activeEvent.expenses]
    });
  };

  const removeExpense = (id: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      expenses: activeEvent.expenses.filter(e => e.id !== id)
    });
    if (selectedExpense?.id === id) setSelectedExpense(null);
  };

  const handleSettle = (fromId: string, toId: string, amount: number) => {
    if (!activeEvent) return;
    const fromP = activeEvent.participants.find(p => p.id === fromId)?.name;
    const toP = activeEvent.participants.find(p => p.id === toId)?.name;
    addExpense({
      description: `Settlement: ${fromP} paid ${toP}`,
      amount: amount, payerId: fromId, participantIds: [toId], category: 'Payment', date: Date.now()
    });
  };

  // Save Logic: Save state to Supabase and generate 6-char short URL
  const handleShareToSupabase = async () => {
    if (!shareEventId || !events[shareEventId] || !supabase) {
      if (!supabase) alert("Database not connected. Please check Supabase credentials.");
      return;
    }

    setShareStatus('saving');
    const targetEvent = events[shareEventId];
    const shortId = generateShortId();

    try {
      const { error } = await supabase
        .from('trips')
        .insert([{ 
          id: shortId,
          trip_data: targetEvent,
          name: targetEvent.name 
        }]);

      if (error) throw error;

      const shortUrl = `https://splitits.in/#/${shortId}`;
      setGeneratedShortUrl(shortUrl);
      setShareStatus('idle');
    } catch (err) {
      console.error("Failed to share:", err);
      setShareStatus('error');
    }
  };

  const openShareModal = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setShareEventId(id);
    setGeneratedShortUrl(null);
    setShareStatus('idle');
    setShowShareModal(true);
  };

  const handleShareWhatsApp = () => {
    if (!generatedShortUrl) return;
    const ev = events[shareEventId!];
    const text = `💰 *SplitIt: ${ev.name}*\n\nTrip details are ready. View here:\n🔗 ${generatedShortUrl}`;
    window.open(`https://api.whatsapp.com/send?text=${encodeURIComponent(text)}`, '_blank');
  };

  const handleCopyLink = () => {
    if (!generatedShortUrl) return;
    navigator.clipboard.writeText(generatedShortUrl).then(() => {
      setShareStatus('copied');
      setTimeout(() => setShareStatus('idle'), 2000);
    });
  };

  // Fix: Return loading state to avoid blank screen during init/fetch
  if (!isInitialized || isLoadingShared) {
    return (
      <div className="min-h-screen bg-[#f8fafc] flex flex-col items-center justify-center font-sans">
        <div className="w-12 h-12 border-4 border-slate-100 border-t-[#4f46e5] rounded-full animate-spin mb-4"></div>
        <p className="text-xs font-bold text-slate-400 uppercase tracking-widest animate-pulse">
          {isLoadingShared ? 'Fetching shared session...' : 'Initializing...'}
        </p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#f8fafc] text-[#1e293b] font-sans pb-12">
      <nav className="sticky top-0 z-50 bg-white/80 backdrop-blur-md border-b border-slate-100 px-4 py-4 sm:px-8">
        <div className="max-w-7xl mx-auto flex items-center justify-between">
          <div 
            className="flex items-center gap-2 cursor-pointer group"
            onClick={() => setCurrentEventId(null)}
          >
            <div className="w-10 h-10 bg-[#4f46e5] rounded-xl flex items-center justify-center shadow-lg shadow-indigo-200 group-hover:scale-110 transition-all">
              <i className="fa-solid fa-money-bill-transfer text-white"></i>
            </div>
            <h1 className="text-xl font-black tracking-tight text-slate-800">SplitIt</h1>
          </div>

          {activeEvent && (
            <div className="flex items-center gap-4">
              <button 
                onClick={(e) => openShareModal(e, activeEvent.id)}
                className="hidden sm:flex items-center gap-2 px-4 py-2 rounded-xl text-xs font-bold text-[#4f46e5] bg-[#eef2ff] hover:bg-[#e0e7ff] transition-all"
              >
                <i className="fa-solid fa-share-nodes"></i>
                SHARE TRIP
              </button>
              <div className="h-6 w-[1px] bg-slate-200 hidden sm:block"></div>
              <p className="text-sm font-bold text-slate-600 truncate max-w-[150px]">{activeEvent.name}</p>
            </div>
          )}
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mt-6 sm:mt-10">
        {!currentEventId ? (
          <div className="max-w-2xl mx-auto py-10 sm:py-20 animate-in fade-in slide-in-from-bottom-8 duration-700">
            <div className="text-center mb-12">
              <h2 className="text-4xl sm:text-5xl font-black text-slate-800 mb-4 tracking-tight leading-tight">Split expenses, <br/><span className="text-[#4f46e5]">minus the drama.</span></h2>
              <p className="text-slate-400 font-medium text-lg">Track group bills, manage shares, and settle up instantly.</p>
            </div>

            <form onSubmit={createEvent} className="bg-white p-8 sm:p-10 rounded-[2.5rem] shadow-xl shadow-slate-200/50 border border-slate-100 mb-12">
              <label className="text-[10px] font-bold uppercase tracking-[0.2em] text-slate-400 block mb-4 px-1">Start a New Group Session</label>
              <div className="flex flex-col sm:flex-row gap-3">
                <input
                  type="text"
                  value={newEventName}
                  onChange={(e) => setNewEventName(e.target.value)}
                  placeholder="e.g. Goa Trip 2024, Flat Expenses"
                  className="flex-1 px-6 py-5 rounded-2xl bg-slate-50 border border-slate-100 focus:outline-none focus:border-[#4f46e5] focus:bg-white text-base transition-all placeholder:text-slate-300"
                />
                <button 
                  type="submit"
                  className="bg-[#4f46e5] text-white px-8 py-5 rounded-2xl font-bold text-base hover:bg-[#4338ca] transition-all shadow-lg shadow-indigo-200 active:scale-[0.98]"
                >
                  Create Group
                </button>
              </div>
            </form>

            {Object.values(events).length > 0 && (
              <div className="space-y-4">
                <h3 className="text-[10px] font-bold uppercase tracking-[0.2em] text-slate-400 px-1">Your Recent Groups</h3>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  {Object.values(events).sort((a, b) => b.createdAt - a.createdAt).map(ev => (
                    <div 
                      key={ev.id}
                      onClick={() => setCurrentEventId(ev.id)}
                      className="group bg-white p-6 rounded-3xl border border-slate-100 hover:border-[#4f46e5] hover:shadow-xl hover:shadow-slate-200/50 transition-all cursor-pointer flex items-center justify-between"
                    >
                      <div className="min-w-0">
                        <p className="font-bold text-slate-800 truncate mb-1">{ev.name}</p>
                        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-wider">{ev.participants.length} Members • {ev.expenses.length} Expenses</p>
                      </div>
                      <div className="flex items-center gap-2">
                        <button 
                          onClick={(e) => openShareModal(e, ev.id)}
                          className="w-8 h-8 flex items-center justify-center rounded-lg text-slate-300 hover:bg-indigo-50 hover:text-[#4f46e5] transition-all"
                        >
                          <i className="fa-solid fa-share-nodes text-sm"></i>
                        </button>
                        <button 
                          onClick={(e) => { e.stopPropagation(); deleteEvent(ev.id); }}
                          className="w-8 h-8 flex items-center justify-center rounded-lg text-slate-300 hover:bg-red-50 hover:text-red-500 transition-all"
                        >
                          <i className="fa-solid fa-trash-can text-sm"></i>
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        ) : (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 sm:gap-10 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="lg:col-span-4 xl:col-span-3 space-y-6">
              <ParticipantManager 
                participants={activeEvent.participants}
                onAdd={addParticipant}
                onRemove={removeParticipant}
              />
              <div className="bg-[#4f46e5] p-6 rounded-3xl text-white shadow-lg shadow-indigo-100 overflow-hidden relative">
                <div className="relative z-10">
                  <p className="text-[10px] font-bold uppercase tracking-widest text-indigo-200 mb-1">Total Group Spend</p>
                  <p className="text-3xl font-black">₹{totalSpent.toFixed(0)}</p>
                </div>
                <i className="fa-solid fa-wallet absolute -right-4 -bottom-4 text-8xl text-indigo-400/20 rotate-12"></i>
              </div>
              <button 
                onClick={() => setCurrentEventId(null)}
                className="w-full flex items-center justify-center gap-2 py-4 rounded-2xl border-2 border-slate-100 text-slate-400 font-bold text-xs uppercase tracking-widest hover:bg-slate-50 hover:border-slate-200 transition-all"
              >
                <i className="fa-solid fa-chevron-left"></i>
                Switch Group
              </button>
            </div>

            <div className="lg:col-span-8 xl:col-span-9 space-y-6">
              <div className="flex bg-slate-100 p-1.5 rounded-2xl w-full sm:w-fit">
                <button
                  onClick={() => setActiveTab('expenses')}
                  className={`flex-1 sm:flex-none px-8 py-3 rounded-xl text-xs font-bold uppercase tracking-wider transition-all ${activeTab === 'expenses' ? 'bg-white text-[#4f46e5] shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
                >
                  Expenses
                </button>
                <button
                  onClick={() => setActiveTab('settlement')}
                  className={`flex-1 sm:flex-none px-8 py-3 rounded-xl text-xs font-bold uppercase tracking-wider transition-all ${activeTab === 'settlement' ? 'bg-white text-[#4f46e5] shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
                >
                  Settlements
                </button>
              </div>

              {activeTab === 'expenses' ? (
                <div className="grid grid-cols-1 xl:grid-cols-2 gap-6">
                  <div className="order-2 xl:order-1">
                    <ExpenseForm participants={activeEvent.participants} onAdd={addExpense} />
                  </div>
                  <div className="order-1 xl:order-2 space-y-4">
                    <div className="flex items-center justify-between px-2">
                      <h3 className="text-xs font-black uppercase tracking-[0.2em] text-slate-400">Activity Feed</h3>
                      <span className="text-[10px] font-bold text-slate-300">{activeEvent.expenses.length} Records</span>
                    </div>
                    <div className="space-y-3 max-h-[800px] overflow-y-auto pr-2 scrollbar-hide">
                      {activeEvent.expenses.length === 0 ? (
                        <div className="bg-white rounded-3xl p-12 border border-dashed border-slate-200 flex flex-col items-center text-center">
                          <div className="w-16 h-16 bg-slate-50 rounded-full flex items-center justify-center mb-4">
                            <i className="fa-solid fa-receipt text-slate-200 text-2xl"></i>
                          </div>
                          <p className="text-slate-400 font-bold text-[10px] uppercase tracking-widest">No expenses yet</p>
                        </div>
                      ) : (
                        activeEvent.expenses.map(exp => (
                          <div key={exp.id} className="bg-white p-4 rounded-2xl border border-slate-100 flex items-center justify-between group hover:border-[#4f46e5] hover:shadow-lg transition-all">
                            <div className="flex items-center gap-4 min-w-0">
                              <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 ${exp.category === 'Payment' ? 'bg-green-100 text-green-600' : 'bg-slate-100 text-slate-500'}`}>
                                <i className={`fa-solid ${exp.category === 'Food' ? 'fa-burger' : exp.category === 'Transport' ? 'fa-car' : exp.category === 'Lodging' ? 'fa-bed' : exp.category === 'Entertainment' ? 'fa-ticket' : exp.category === 'Payment' ? 'fa-hand-holding-dollar' : 'fa-tag'} text-sm`}></i>
                              </div>
                              <div className="min-w-0">
                                <p className="font-bold text-sm text-slate-800 truncate">{exp.description}</p>
                                <p className="text-[10px] text-slate-400 font-medium">Paid by <span className="text-slate-600 font-bold">{activeEvent.participants.find(p => p.id === exp.payerId)?.name}</span></p>
                              </div>
                            </div>
                            <div className="flex items-center gap-4">
                              <p className="font-black text-sm text-slate-800">₹{exp.amount.toFixed(0)}</p>
                              <button onClick={() => removeExpense(exp.id)} className="text-slate-200 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all"><i className="fa-solid fa-trash-can text-xs"></i></button>
                            </div>
                          </div>
                        ))
                      )}
                    </div>
                  </div>
                </div>
              ) : (
                <SettlementView 
                  participants={activeEvent.participants}
                  balances={balances}
                  settlements={settlements}
                  totalSpent={totalSpent}
                  onSettle={handleSettle}
                />
              )}
            </div>
          </div>
        )}
      </main>

      {showShareModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white rounded-[2.5rem] max-w-sm w-full shadow-2xl animate-in zoom-in-95 overflow-hidden">
            <div className="p-8 border-b border-slate-100 flex justify-between items-center">
              <div>
                <h3 className="text-xl font-bold text-slate-800">Share Trip</h3>
              </div>
              <button onClick={() => setShowShareModal(false)} className="text-slate-400 hover:text-slate-600"><i className="fa-solid fa-xmark text-lg"></i></button>
            </div>
            <div className="p-8 space-y-6">
              {!generatedShortUrl ? (
                <button
                  onClick={handleShareToSupabase}
                  disabled={shareStatus === 'saving'}
                  className="w-full bg-[#4f46e5] text-white py-5 rounded-2xl font-bold text-sm shadow-lg hover:bg-[#4338ca] transition-all disabled:opacity-50"
                >
                  {shareStatus === 'saving' ? 'GENERATING...' : 'GENERATE LINK'}
                </button>
              ) : (
                <div className="space-y-4">
                  <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100 flex items-center gap-2">
                    <span className="flex-1 text-xs font-bold text-slate-400 truncate">{generatedShortUrl}</span>
                    <button onClick={handleCopyLink} className="bg-white px-4 py-2 rounded-xl text-[10px] font-black text-[#4f46e5] border border-slate-100">{shareStatus === 'copied' ? 'COPIED!' : 'COPY'}</button>
                  </div>
                  <button onClick={handleShareWhatsApp} className="w-full bg-[#25D366] text-white py-5 rounded-2xl font-bold text-sm flex items-center justify-center gap-3">
                    <i className="fa-brands fa-whatsapp text-xl"></i>
                    <span>WHATSAPP</span>
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { createClient, SupabaseClient } from '@supabase/supabase-js';
import { Participant, Expense, Settlement, Balance, SplitEvent } from './types.ts';
import ParticipantManager from './components/ParticipantManager.tsx';
import ExpenseForm from './components/ExpenseForm.tsx';
import SettlementView from './components/SettlementView.tsx';
import { calculateBalances, calculateSettlements } from './utils/calculation.ts';

// Helper to generate a 6-character random ID for short URLs
const generateShortId = () => {
  const chars = 'abcdefghijklmnopqrstuvwxyz0123456789';
  let result = '';
  for (let i = 0; i < 6; i++) {
    result += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return result;
};

// Defensive Supabase initialization
let supabase: SupabaseClient | null = null;
const supabaseUrl = process.env.SUPABASE_URL;
const supabaseKey = process.env.SUPABASE_ANON_KEY;

if (supabaseUrl && supabaseKey) {
  supabase = createClient(supabaseUrl, supabaseKey);
}

const App: React.FC = () => {
  const [events, setEvents] = useState<Record<string, SplitEvent>>({});
  const [currentEventId, setCurrentEventId] = useState<string | null>(null);
  const [newEventName, setNewEventName] = useState('');

  const [activeTab, setActiveTab] = useState<'expenses' | 'settlement'>('expenses');
  const [selectedExpense, setSelectedExpense] = useState<Expense | null>(null);
  const [shareStatus, setShareStatus] = useState<'idle' | 'saving' | 'copied' | 'error'>('idle');
  const [showShareModal, setShowShareModal] = useState(false);
  const [shareEventId, setShareEventId] = useState<string | null>(null);
  const [generatedShortUrl, setGeneratedShortUrl] = useState<string | null>(null);
  const [isInitialized, setIsInitialized] = useState(false);
  const [isLoadingShared, setIsLoadingShared] = useState(false);

  const getAvatar = (name: string) => `https://api.dicebear.com/7.x/initials/svg?seed=${name}&backgroundColor=4f46e5&textColor=ffffff`;

  // Fetch Logic: Check for short ID in hash on load
  useEffect(() => {
    const loadInitialData = async () => {
      // 1. Load Local Storage
      const savedEvents = localStorage.getItem('splitit_multi_events');
      let currentEvents: Record<string, SplitEvent> = savedEvents ? JSON.parse(savedEvents) : {};

      // 2. Check Hash for /trip/[ID] or just /[ID] (6 characters)
      const hash = window.location.hash;
      const shortIdMatch = hash.match(/#\/?([a-z0-9]{6})$/i);

      if (shortIdMatch && shortIdMatch[1] && supabase) {
        const tripSlug = shortIdMatch[1];
        setIsLoadingShared(true);
        try {
          const { data, error } = await supabase
            .from('trips')
            .select('trip_data')
            .eq('id', tripSlug)
            .single();

          if (!error && data && data.trip_data) {
            const fetchedEvent = data.trip_data as SplitEvent;
            const localId = fetchedEvent.id || tripSlug;
            currentEvents[localId] = fetchedEvent;
            setCurrentEventId(localId);

            // Clean up hash
            window.history.replaceState(null, "", window.location.pathname);
          }
        } catch (err) {
          console.error("Failed to fetch shared trip:", err);
        } finally {
          setIsLoadingShared(false);
        }
      }

      setEvents(currentEvents);
      setIsInitialized(true);
    };

    loadInitialData();
  }, []);

  // Persistence Sync
  useEffect(() => {
    if (isInitialized) {
      localStorage.setItem('splitit_multi_events', JSON.stringify(events));
    }
  }, [events, isInitialized]);

  const activeEvent = currentEventId ? events[currentEventId] : null;

  const { balances, settlements, totalSpent } = useMemo(() => {
    if (!activeEvent) return { balances: [], settlements: [], totalSpent: 0 };
    const bals = calculateBalances(activeEvent.participants, activeEvent.expenses);
    const setts = calculateSettlements([...bals]);
    const total = activeEvent.expenses.reduce((acc, curr) => curr.category !== 'Payment' ? acc + curr.amount : acc, 0);
    return { balances: bals, settlements: setts, totalSpent: total };
  }, [activeEvent]);

  // Actions
  const createEvent = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newEventName.trim()) return;
    const id = crypto.randomUUID();
    const newEv: SplitEvent = {
      id,
      name: newEventName.trim(),
      participants: [],
      expenses: [],
      createdAt: Date.now()
    };
    setEvents(prev => ({ ...prev, [id]: newEv }));
    setNewEventName('');
    setCurrentEventId(id);
  };

  const deleteEvent = (id: string) => {
    if (window.confirm("Delete this group permanently?")) {
      const newEvents = { ...events };
      delete newEvents[id];
      setEvents(newEvents);
      if (currentEventId === id) setCurrentEventId(null);
    }
  };

  const updateActiveEvent = (updates: Partial<SplitEvent>) => {
    if (!currentEventId) return;
    setEvents(prev => ({
      ...prev,
      [currentEventId]: { ...prev[currentEventId], ...updates }
    }));
  };

  const addParticipant = (name: string, upiId?: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      participants: [...activeEvent.participants, { id: crypto.randomUUID(), name, avatar: getAvatar(name), upiId }]
    });
  };

  const removeParticipant = (id: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      participants: activeEvent.participants.filter(p => p.id !== id),
      expenses: activeEvent.expenses.filter(e => e.payerId !== id && !e.participantIds.includes(id))
    });
  };

  const addExpense = (newExp: Omit<Expense, 'id'>) => {
    if (!activeEvent) return;
    updateActiveEvent({
      expenses: [{ ...newExp, id: crypto.randomUUID() }, ...activeEvent.expenses]
    });
  };

  const removeExpense = (id: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      expenses: activeEvent.expenses.filter(e => e.id !== id)
    });
    if (selectedExpense?.id === id) setSelectedExpense(null);
  };

  const handleSettle = (fromId: string, toId: string, amount: number) => {
    if (!activeEvent) return;
    const fromP = activeEvent.participants.find(p => p.id === fromId)?.name;
    const toP = activeEvent.participants.find(p => p.id === toId)?.name;
    addExpense({
      description: `Settlement: ${fromP} paid ${toP}`,
      amount: amount, payerId: fromId, participantIds: [toId], category: 'Payment', date: Date.now()
    });
  };

  // Save Logic: Upload trip to Supabase
  const handleShareToSupabase = async () => {
    if (!shareEventId || !events[shareEventId] || !supabase) {
      if (!supabase) alert("Supabase credentials missing. Check index.html polyfills.");
      return;
    }

    setShareStatus('saving');
    const targetEvent = events[shareEventId];
    const shortId = generateShortId();

    try {
      const { error } = await supabase
        .from('trips')
        .insert([{ 
          id: shortId,
          trip_data: targetEvent,
          name: targetEvent.name 
        }]);

      if (error) throw error;

      const shortUrl = `https://splitits.in/#/${shortId}`;
      setGeneratedShortUrl(shortUrl);
      setShareStatus('idle');
    } catch (err) {
      console.error("Save error:", err);
      setShareStatus('error');
    }
  };

  const openShareModal = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setShareEventId(id);
    setGeneratedShortUrl(null);
    setShareStatus('idle');
    setShowShareModal(true);
  };

  const handleShareWhatsApp = () => {
    if (!generatedShortUrl || !shareEventId) return;
    const ev = events[shareEventId];
    const settlementText = settlements.length === 0 ? "All settled! ✅" : settlements.map(s => `💸 *${ev.participants.find(p=>p.id===s.from)?.name}* owes *${ev.participants.find(p=>p.id===s.to)?.name}*: ₹${s.amount.toFixed(2)}`).join('\n');

    const text = `💰 *SplitIt: ${ev.name}*\n\n*Settlements:*\n${settlementText}\n\n🔗 View & Settle:\n${generatedShortUrl}\n\nNo more awkward money talks! SplitIt handles it all for you.\nTry it Now: splitits.in`;

    window.open(`https://api.whatsapp.com/send?text=${encodeURIComponent(text)}`, '_blank');
  };

  const handleCopyLink = () => {
    if (!generatedShortUrl) return;
    navigator.clipboard.writeText(generatedShortUrl).then(() => {
      setShareStatus('copied');
      setTimeout(() => setShareStatus('idle'), 2000);
    });
  };

  if (!isInitialized || isLoadingShared) {
    return (
      <div className="min-h-screen bg-[#f8fafc] flex flex-col items-center justify-center font-sans">
        <div className="w-12 h-12 border-4 border-slate-100 border-t-[#4f46e5] rounded-full animate-spin mb-4"></div>
        <p className="text-xs font-bold text-slate-400 uppercase tracking-widest animate-pulse">
          {isLoadingShared ? 'Loading Shared Trip...' : 'Initializing splitIt...'}
        </p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#f8fafc] text-[#1e293b] font-sans">
      <nav className="sticky top-0 z-50 bg-white/80 backdrop-blur-md border-b border-slate-100 px-4 py-4 sm:px-8">
        <div className="max-w-7xl mx-auto flex items-center justify-between">
          <div 
            className="flex items-center gap-2 cursor-pointer group"
            onClick={() => setCurrentEventId(null)}
          >
            <div className="w-10 h-10 bg-[#4f46e5] rounded-xl flex items-center justify-center shadow-lg shadow-indigo-200 group-hover:rotate-12 transition-all">
              <i className="fa-solid fa-receipt text-white"></i>
            </div>
            <h1 className="text-xl font-black tracking-tight text-slate-800">SplitIt</h1>
          </div>

          {activeEvent && (
            <div className="flex items-center gap-4">
              <button 
                onClick={(e) => openShareModal(e, activeEvent.id)}
                className="flex items-center gap-2 px-4 py-2 rounded-xl text-[10px] font-black text-[#4f46e5] bg-[#eef2ff] hover:bg-[#e0e7ff] transition-all tracking-widest uppercase"
              >
                <i className="fa-solid fa-share-nodes"></i>
                <span className="hidden sm:inline">Share Event</span>
              </button>
              <div className="h-6 w-[1px] bg-slate-200 hidden sm:block"></div>
              <p className="text-sm font-bold text-slate-600 truncate max-w-[120px]">{activeEvent.name}</p>
            </div>
          )}
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mt-6 sm:mt-10 pb-20">
        {!currentEventId ? (
          <div className="max-w-2xl mx-auto py-10 sm:py-20 animate-in fade-in slide-in-from-bottom-8 duration-700">
            <div className="text-center mb-12">
              <h2 className="text-4xl sm:text-5xl font-black text-slate-800 mb-4 tracking-tight leading-tight">Split costs, <br/><span className="text-[#4f46e5]">effortlessly.</span></h2>
              <p className="text-slate-400 font-medium text-lg">Your group trip's best friend. No math, just memories.</p>
            </div>

            <form onSubmit={createEvent} className="bg-white p-8 sm:p-10 rounded-[2.5rem] shadow-xl shadow-slate-200/50 border border-slate-100 mb-12">
              <label className="text-[10px] font-bold uppercase tracking-[0.2em] text-slate-400 block mb-4 px-1">Create a new group</label>
              <div className="flex flex-col sm:flex-row gap-3">
                <input
                  type="text"
                  value={newEventName}
                  onChange={(e) => setNewEventName(e.target.value)}
                  placeholder="e.g. Weekend at Alibaug"
                  className="flex-1 px-6 py-5 rounded-2xl bg-slate-50 border border-slate-100 focus:outline-none focus:border-[#4f46e5] focus:bg-white text-base transition-all"
                />
                <button 
                  type="submit"
                  className="bg-[#4f46e5] text-white px-8 py-5 rounded-2xl font-bold text-base hover:bg-[#4338ca] transition-all shadow-lg active:scale-95"
                >
                  Get Started
                </button>
              </div>
            </form>

            {Object.values(events).length > 0 && (
              <div className="space-y-4">
                <h3 className="text-[10px] font-bold uppercase tracking-[0.2em] text-slate-400 px-1">Existing Groups</h3>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  {Object.values(events).sort((a, b) => b.createdAt - a.createdAt).map(ev => (
                    <div 
                      key={ev.id}
                      onClick={() => setCurrentEventId(ev.id)}
                      className="group bg-white p-6 rounded-3xl border border-slate-100 hover:border-[#4f46e5] transition-all cursor-pointer flex items-center justify-between"
                    >
                      <div className="min-w-0">
                        <p className="font-bold text-slate-800 truncate">{ev.name}</p>
                        <p className="text-[10px] text-slate-400 font-bold uppercase">{ev.participants.length} Squad • {ev.expenses.length} Exp.</p>
                      </div>
                      <div className="flex gap-1">
                         <button onClick={(e) => openShareModal(e, ev.id)} className="w-8 h-8 rounded-lg text-slate-300 hover:text-indigo-500 hover:bg-indigo-50 transition-all"><i className="fa-solid fa-share-nodes text-sm"></i></button>
                         <button onClick={(e) => { e.stopPropagation(); deleteEvent(ev.id); }} className="w-8 h-8 rounded-lg text-slate-300 hover:text-red-500 hover:bg-red-50 transition-all"><i className="fa-solid fa-trash-can text-sm"></i></button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        ) : (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 animate-in fade-in slide-in-from-bottom-4">
            <div className="lg:col-span-3 space-y-6">
              <ParticipantManager 
                participants={activeEvent.participants}
                onAdd={addParticipant}
                onRemove={removeParticipant}
              />
              <div className="bg-[#1e293b] p-6 rounded-3xl text-white">
                <p className="text-[9px] font-black uppercase tracking-[0.2em] text-slate-500 mb-2">Total Budget</p>
                <p className="text-3xl font-black">₹{totalSpent.toFixed(0)}</p>
              </div>
            </div>

            <div className="lg:col-span-9 space-y-8">
              <div className="flex bg-white p-1.5 rounded-2xl border border-slate-100 shadow-sm w-fit">
                <button
                  onClick={() => setActiveTab('expenses')}
                  className={`px-8 py-3 rounded-xl text-xs font-bold transition-all ${activeTab === 'expenses' ? 'bg-[#4f46e5] text-white' : 'text-slate-400 hover:text-slate-600'}`}
                >
                  Transactions
                </button>
                <button
                  onClick={() => setActiveTab('settlement')}
                  className={`px-8 py-3 rounded-xl text-xs font-bold transition-all ${activeTab === 'settlement' ? 'bg-[#4f46e5] text-white' : 'text-slate-400 hover:text-slate-600'}`}
                >
                  Settlement
                </button>
              </div>

              {activeTab === 'expenses' ? (
                <div className="grid grid-cols-1 xl:grid-cols-2 gap-8">
                  <ExpenseForm participants={activeEvent.participants} onAdd={addExpense} />
                  <div className="space-y-4">
                    <h3 className="text-[10px] font-bold uppercase tracking-widest text-slate-400 px-1">Recent Activity</h3>
                    <div className="space-y-3 max-h-[600px] overflow-y-auto pr-2 scrollbar-hide">
                      {activeEvent.expenses.length === 0 ? (
                        <div className="p-12 border-2 border-dashed border-slate-100 rounded-3xl text-center">
                          <p className="text-slate-300 font-bold text-xs">No expenses logged yet</p>
                        </div>
                      ) : (
                        activeEvent.expenses.map(exp => (
                          <div key={exp.id} className="bg-white p-4 rounded-2xl border border-slate-100 flex items-center justify-between group hover:border-[#4f46e5] transition-all">
                            <div className="flex items-center gap-4">
                              <div className="w-10 h-10 bg-slate-50 rounded-xl flex items-center justify-center text-[#4f46e5]"><i className="fa-solid fa-receipt"></i></div>
                              <div className="min-w-0">
                                <p className="font-bold text-sm text-slate-800 truncate">{exp.description}</p>
                                <p className="text-[10px] text-slate-400 font-bold uppercase">{activeEvent.participants.find(p => p.id === exp.payerId)?.name} • {exp.category}</p>
                              </div>
                            </div>
                            <div className="flex items-center gap-4">
                               <p className="font-black text-sm">₹{exp.amount}</p>
                               <button onClick={() => removeExpense(exp.id)} className="text-slate-200 hover:text-red-500 transition-colors"><i className="fa-solid fa-trash-can text-xs"></i></button>
                            </div>
                          </div>
                        ))
                      )}
                    </div>
                  </div>
                </div>
              ) : (
                <SettlementView 
                  participants={activeEvent.participants}
                  balances={balances}
                  settlements={settlements}
                  totalSpent={totalSpent}
                  onSettle={handleSettle}
                />
              )}
            </div>
          </div>
        )}
      </main>

      {/* Share Modal */}
      {showShareModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white rounded-[2.5rem] max-w-sm w-full shadow-2xl animate-in zoom-in-95 overflow-hidden">
            <div className="p-8 border-b border-slate-100 flex justify-between items-center">
              <div>
                <h3 className="text-xl font-bold text-slate-800">Share Group</h3>
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">Short Link Generation</p>
              </div>
              <button onClick={() => setShowShareModal(false)} className="text-slate-400 hover:text-slate-600"><i className="fa-solid fa-xmark text-lg"></i></button>
            </div>

            <div className="p-8 space-y-6">
              {!generatedShortUrl ? (
                <button
                  onClick={handleShareToSupabase}
                  disabled={shareStatus === 'saving'}
                  className="w-full bg-[#4f46e5] text-white py-5 rounded-2xl font-bold text-sm shadow-lg hover:bg-[#4338ca] transition-all disabled:opacity-50"
                >
                  {shareStatus === 'saving' ? (
                    <span className="flex items-center justify-center gap-2">
                      <i className="fa-solid fa-spinner animate-spin"></i>
                      SAVING...
                    </span>
                  ) : 'CREATE SHORT LINK'}
                </button>
              ) : (
                <div className="space-y-4 animate-in fade-in zoom-in-95">
                  <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100 flex items-center justify-between gap-3">
                    <span className="text-[10px] font-bold text-slate-400 truncate flex-1">{generatedShortUrl}</span>
                    <button 
                      onClick={handleCopyLink} 
                      className={`px-4 py-2 rounded-xl text-[10px] font-black border transition-all ${shareStatus === 'copied' ? 'bg-green-100 text-green-600 border-green-200' : 'bg-white text-[#4f46e5] border-slate-100'}`}
                    >
                      {shareStatus === 'copied' ? 'COPIED' : 'COPY'}
                    </button>
                  </div>
                  <button onClick={handleShareWhatsApp} className="w-full bg-[#25D366] text-white py-5 rounded-2xl font-bold text-sm flex items-center justify-center gap-3 hover:bg-[#20bd5a] transition-all">
                    <i className="fa-brands fa-whatsapp text-xl"></i>
                    SEND ON WHATSAPP
                  </button>
                </div>
              )}
              {shareStatus === 'error' && <p className="text-[10px] text-red-500 font-bold text-center uppercase tracking-widest">Failed to sync with cloud. Try again.</p>}
            </div>
            <div className="p-6 bg-slate-50 text-center"><p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest">Powered by Supabase DB</p></div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { createClient, SupabaseClient } from '@supabase/supabase-js';
import { Participant, Expense, Settlement, Balance, SplitEvent } from './types.ts';
import ParticipantManager from './components/ParticipantManager.tsx';
import ExpenseForm from './components/ExpenseForm.tsx';
import SettlementView from './components/SettlementView.tsx';
import { calculateBalances, calculateSettlements } from './utils/calculation.ts';

// Helper to generate a 6-character random ID for short URLs
const generateShortId = () => {
  const chars = 'abcdefghijklmnopqrstuvwxyz0123456789';
  let result = '';
  for (let i = 0; i < 6; i++) {
    result += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return result;
};

// Defensive Supabase initialization
let supabase: SupabaseClient | null = null;
const supabaseUrl = process.env.SUPABASE_URL;
const supabaseKey = process.env.SUPABASE_ANON_KEY;

if (supabaseUrl && supabaseKey) {
  supabase = createClient(supabaseUrl, supabaseKey);
}

const App: React.FC = () => {
  const [events, setEvents] = useState<Record<string, SplitEvent>>({});
  const [currentEventId, setCurrentEventId] = useState<string | null>(null);
  const [newEventName, setNewEventName] = useState('');

  const [activeTab, setActiveTab] = useState<'expenses' | 'settlement'>('expenses');
  const [selectedExpense, setSelectedExpense] = useState<Expense | null>(null);
  const [shareStatus, setShareStatus] = useState<'idle' | 'saving' | 'copied' | 'error'>('idle');
  const [showShareModal, setShowShareModal] = useState(false);
  const [shareEventId, setShareEventId] = useState<string | null>(null);
  const [generatedShortUrl, setGeneratedShortUrl] = useState<string | null>(null);
  const [isInitialized, setIsInitialized] = useState(false);
  const [isLoadingShared, setIsLoadingShared] = useState(false);

  const getAvatar = (name: string) => `https://api.dicebear.com/7.x/initials/svg?seed=${name}&backgroundColor=4f46e5&textColor=ffffff`;

  // Fetch Logic: Check for short ID in hash on load
  useEffect(() => {
    const loadInitialData = async () => {
      // 1. Load Local Storage
      const savedEvents = localStorage.getItem('splitit_multi_events');
      let currentEvents: Record<string, SplitEvent> = savedEvents ? JSON.parse(savedEvents) : {};

      // 2. Check Hash for /trip/[ID] or just /[ID] (6 characters)
      const hash = window.location.hash;
      const shortIdMatch = hash.match(/#\/?([a-z0-9]{6})$/i);

      if (shortIdMatch && shortIdMatch[1] && supabase) {
        const tripSlug = shortIdMatch[1];
        setIsLoadingShared(true);
        try {
          const { data, error } = await supabase
            .from('trips')
            .select('trip_data')
            .eq('id', tripSlug)
            .single();

          if (!error && data && data.trip_data) {
            const fetchedEvent = data.trip_data as SplitEvent;
            const localId = fetchedEvent.id || tripSlug;
            currentEvents[localId] = fetchedEvent;
            setCurrentEventId(localId);

            // Clean up hash
            window.history.replaceState(null, "", window.location.pathname);
          }
        } catch (err) {
          console.error("Failed to fetch shared trip:", err);
        } finally {
          setIsLoadingShared(false);
        }
      }

      setEvents(currentEvents);
      setIsInitialized(true);
    };

    loadInitialData();
  }, []);

  // Persistence Sync
  useEffect(() => {
    if (isInitialized) {
      localStorage.setItem('splitit_multi_events', JSON.stringify(events));
    }
  }, [events, isInitialized]);

  const activeEvent = currentEventId ? events[currentEventId] : null;

  const { balances, settlements, totalSpent } = useMemo(() => {
    if (!activeEvent) return { balances: [], settlements: [], totalSpent: 0 };
    const bals = calculateBalances(activeEvent.participants, activeEvent.expenses);
    const setts = calculateSettlements([...bals]);
    const total = activeEvent.expenses.reduce((acc, curr) => curr.category !== 'Payment' ? acc + curr.amount : acc, 0);
    return { balances: bals, settlements: setts, totalSpent: total };
  }, [activeEvent]);

  // Actions
  const createEvent = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newEventName.trim()) return;
    const id = crypto.randomUUID();
    const newEv: SplitEvent = {
      id,
      name: newEventName.trim(),
      participants: [],
      expenses: [],
      createdAt: Date.now()
    };
    setEvents(prev => ({ ...prev, [id]: newEv }));
    setNewEventName('');
    setCurrentEventId(id);
  };

  const deleteEvent = (id: string) => {
    if (window.confirm("Delete this group permanently?")) {
      const newEvents = { ...events };
      delete newEvents[id];
      setEvents(newEvents);
      if (currentEventId === id) setCurrentEventId(null);
    }
  };

  const updateActiveEvent = (updates: Partial<SplitEvent>) => {
    if (!currentEventId) return;
    setEvents(prev => ({
      ...prev,
      [currentEventId]: { ...prev[currentEventId], ...updates }
    }));
  };

  const addParticipant = (name: string, upiId?: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      participants: [...activeEvent.participants, { id: crypto.randomUUID(), name, avatar: getAvatar(name), upiId }]
    });
  };

  const removeParticipant = (id: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      participants: activeEvent.participants.filter(p => p.id !== id),
      expenses: activeEvent.expenses.filter(e => e.payerId !== id && !e.participantIds.includes(id))
    });
  };

  const addExpense = (newExp: Omit<Expense, 'id'>) => {
    if (!activeEvent) return;
    updateActiveEvent({
      expenses: [{ ...newExp, id: crypto.randomUUID() }, ...activeEvent.expenses]
    });
  };

  const removeExpense = (id: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      expenses: activeEvent.expenses.filter(e => e.id !== id)
    });
    if (selectedExpense?.id === id) setSelectedExpense(null);
  };

  const handleSettle = (fromId: string, toId: string, amount: number) => {
    if (!activeEvent) return;
    const fromP = activeEvent.participants.find(p => p.id === fromId)?.name;
    const toP = activeEvent.participants.find(p => p.id === toId)?.name;
    addExpense({
      description: `Settlement: ${fromP} paid ${toP}`,
      amount: amount, payerId: fromId, participantIds: [toId], category: 'Payment', date: Date.now()
    });
  };

  // Save Logic: Upload trip to Supabase
  const handleShareToSupabase = async () => {
    if (!shareEventId || !events[shareEventId] || !supabase) {
      if (!supabase) alert("Supabase credentials missing. Check index.html polyfills.");
      return;
    }

    setShareStatus('saving');
    const targetEvent = events[shareEventId];
    const shortId = generateShortId();

    try {
      const { error } = await supabase
        .from('trips')
        .insert([{ 
          id: shortId,
          trip_data: targetEvent,
          name: targetEvent.name 
        }]);

      if (error) throw error;

      const shortUrl = `https://splitits.in/#/${shortId}`;
      setGeneratedShortUrl(shortUrl);
      setShareStatus('idle');
    } catch (err) {
      console.error("Save error:", err);
      setShareStatus('error');
    }
  };

  const openShareModal = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setShareEventId(id);
    setGeneratedShortUrl(null);
    setShareStatus('idle');
    setShowShareModal(true);
  };

  const handleShareWhatsApp = () => {
    if (!generatedShortUrl || !shareEventId) return;
    const ev = events[shareEventId];
    const settlementText = settlements.length === 0 ? "All settled! ✅" : settlements.map(s => `💸 *${ev.participants.find(p=>p.id===s.from)?.name}* owes *${ev.participants.find(p=>p.id===s.to)?.name}*: ₹${s.amount.toFixed(2)}`).join('\n');

    const text = `💰 *SplitIt: ${ev.name}*\n\n*Settlements:*\n${settlementText}\n\n🔗 View & Settle:\n${generatedShortUrl}\n\nNo more awkward money talks! SplitIt handles it all for you.\nTry it Now: splitits.in`;

    window.open(`https://api.whatsapp.com/send?text=${encodeURIComponent(text)}`, '_blank');
  };

  const handleCopyLink = () => {
    if (!generatedShortUrl) return;
    navigator.clipboard.writeText(generatedShortUrl).then(() => {
      setShareStatus('copied');
      setTimeout(() => setShareStatus('idle'), 2000);
    });
  };

  if (!isInitialized || isLoadingShared) {
    return (
      <div className="min-h-screen bg-[#f8fafc] flex flex-col items-center justify-center font-sans">
        <div className="w-12 h-12 border-4 border-slate-100 border-t-[#4f46e5] rounded-full animate-spin mb-4"></div>
        <p className="text-xs font-bold text-slate-400 uppercase tracking-widest animate-pulse">
          {isLoadingShared ? 'Loading Shared Trip...' : 'Initializing splitIt...'}
        </p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#f8fafc] text-[#1e293b] font-sans">
      <nav className="sticky top-0 z-50 bg-white/80 backdrop-blur-md border-b border-slate-100 px-4 py-4 sm:px-8">
        <div className="max-w-7xl mx-auto flex items-center justify-between">
          <div 
            className="flex items-center gap-2 cursor-pointer group"
            onClick={() => setCurrentEventId(null)}
          >
            <div className="w-10 h-10 bg-[#4f46e5] rounded-xl flex items-center justify-center shadow-lg shadow-indigo-200 group-hover:rotate-12 transition-all">
              <i className="fa-solid fa-receipt text-white"></i>
            </div>
            <h1 className="text-xl font-black tracking-tight text-slate-800">SplitIt</h1>
          </div>

          {activeEvent && (
            <div className="flex items-center gap-4">
              <button 
                onClick={(e) => openShareModal(e, activeEvent.id)}
                className="flex items-center gap-2 px-4 py-2 rounded-xl text-[10px] font-black text-[#4f46e5] bg-[#eef2ff] hover:bg-[#e0e7ff] transition-all tracking-widest uppercase"
              >
                <i className="fa-solid fa-share-nodes"></i>
                <span className="hidden sm:inline">Share Event</span>
              </button>
              <div className="h-6 w-[1px] bg-slate-200 hidden sm:block"></div>
              <p className="text-sm font-bold text-slate-600 truncate max-w-[120px]">{activeEvent.name}</p>
            </div>
          )}
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mt-6 sm:mt-10 pb-20">
        {!currentEventId ? (
          <div className="max-w-2xl mx-auto py-10 sm:py-20 animate-in fade-in slide-in-from-bottom-8 duration-700">
            <div className="text-center mb-12">
              <h2 className="text-4xl sm:text-5xl font-black text-slate-800 mb-4 tracking-tight leading-tight">Split costs, <br/><span className="text-[#4f46e5]">effortlessly.</span></h2>
              <p className="text-slate-400 font-medium text-lg">Your group trip's best friend. No math, just memories.</p>
            </div>

            <form onSubmit={createEvent} className="bg-white p-8 sm:p-10 rounded-[2.5rem] shadow-xl shadow-slate-200/50 border border-slate-100 mb-12">
              <label className="text-[10px] font-bold uppercase tracking-[0.2em] text-slate-400 block mb-4 px-1">Create a new group</label>
              <div className="flex flex-col sm:flex-row gap-3">
                <input
                  type="text"
                  value={newEventName}
                  onChange={(e) => setNewEventName(e.target.value)}
                  placeholder="e.g. Weekend at Alibaug"
                  className="flex-1 px-6 py-5 rounded-2xl bg-slate-50 border border-slate-100 focus:outline-none focus:border-[#4f46e5] focus:bg-white text-base transition-all"
                />
                <button 
                  type="submit"
                  className="bg-[#4f46e5] text-white px-8 py-5 rounded-2xl font-bold text-base hover:bg-[#4338ca] transition-all shadow-lg active:scale-95"
                >
                  Get Started
                </button>
              </div>
            </form>

            {Object.values(events).length > 0 && (
              <div className="space-y-4">
                <h3 className="text-[10px] font-bold uppercase tracking-[0.2em] text-slate-400 px-1">Existing Groups</h3>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  {/* Fixed TypeScript error by explicitly casting Object.values(events) to SplitEvent[] to ensure correct property access */}
                  {(Object.values(events) as SplitEvent[]).sort((a, b) => b.createdAt - a.createdAt).map(ev => (
                    <div 
                      key={ev.id}
                      onClick={() => setCurrentEventId(ev.id)}
                      className="group bg-white p-6 rounded-3xl border border-slate-100 hover:border-[#4f46e5] transition-all cursor-pointer flex items-center justify-between"
                    >
                      <div className="min-w-0">
                        <p className="font-bold text-slate-800 truncate">{ev.name}</p>
                        <p className="text-[10px] text-slate-400 font-bold uppercase">{ev.participants.length} Squad • {ev.expenses.length} Exp.</p>
                      </div>
                      <div className="flex gap-1">
                         <button onClick={(e) => openShareModal(e, ev.id)} className="w-8 h-8 rounded-lg text-slate-300 hover:text-indigo-500 hover:bg-indigo-50 transition-all"><i className="fa-solid fa-share-nodes text-sm"></i></button>
                         <button onClick={(e) => { e.stopPropagation(); deleteEvent(ev.id); }} className="w-8 h-8 rounded-lg text-slate-300 hover:text-red-500 hover:bg-red-50 transition-all"><i className="fa-solid fa-trash-can text-sm"></i></button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        ) : (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 animate-in fade-in slide-in-from-bottom-4">
            <div className="lg:col-span-3 space-y-6">
              <ParticipantManager 
                participants={activeEvent.participants}
                onAdd={addParticipant}
                onRemove={removeParticipant}
              />
              <div className="bg-[#1e293b] p-6 rounded-3xl text-white">
                <p className="text-[9px] font-black uppercase tracking-[0.2em] text-slate-500 mb-2">Total Budget</p>
                <p className="text-3xl font-black">₹{totalSpent.toFixed(0)}</p>
              </div>
            </div>

            <div className="lg:col-span-9 space-y-8">
              <div className="flex bg-white p-1.5 rounded-2xl border border-slate-100 shadow-sm w-fit">
                <button
                  onClick={() => setActiveTab('expenses')}
                  className={`px-8 py-3 rounded-xl text-xs font-bold transition-all ${activeTab === 'expenses' ? 'bg-[#4f46e5] text-white' : 'text-slate-400 hover:text-slate-600'}`}
                >
                  Transactions
                </button>
                <button
                  onClick={() => setActiveTab('settlement')}
                  className={`px-8 py-3 rounded-xl text-xs font-bold transition-all ${activeTab === 'settlement' ? 'bg-[#4f46e5] text-white' : 'text-slate-400 hover:text-slate-600'}`}
                >
                  Settlement
                </button>
              </div>

              {activeTab === 'expenses' ? (
                <div className="grid grid-cols-1 xl:grid-cols-2 gap-8">
                  <ExpenseForm participants={activeEvent.participants} onAdd={addExpense} />
                  <div className="space-y-4">
                    <h3 className="text-[10px] font-bold uppercase tracking-widest text-slate-400 px-1">Recent Activity</h3>
                    <div className="space-y-3 max-h-[600px] overflow-y-auto pr-2 scrollbar-hide">
                      {activeEvent.expenses.length === 0 ? (
                        <div className="p-12 border-2 border-dashed border-slate-100 rounded-3xl text-center">
                          <p className="text-slate-300 font-bold text-xs">No expenses logged yet</p>
                        </div>
                      ) : (
                        activeEvent.expenses.map(exp => (
                          <div key={exp.id} className="bg-white p-4 rounded-2xl border border-slate-100 flex items-center justify-between group hover:border-[#4f46e5] transition-all">
                            <div className="flex items-center gap-4">
                              <div className="w-10 h-10 bg-slate-50 rounded-xl flex items-center justify-center text-[#4f46e5]"><i className="fa-solid fa-receipt"></i></div>
                              <div className="min-w-0">
                                <p className="font-bold text-sm text-slate-800 truncate">{exp.description}</p>
                                <p className="text-[10px] text-slate-400 font-bold uppercase">{activeEvent.participants.find(p => p.id === exp.payerId)?.name} • {exp.category}</p>
                              </div>
                            </div>
                            <div className="flex items-center gap-4">
                               <p className="font-black text-sm">₹{exp.amount}</p>
                               <button onClick={() => removeExpense(exp.id)} className="text-slate-200 hover:text-red-500 transition-colors"><i className="fa-solid fa-trash-can text-xs"></i></button>
                            </div>
                          </div>
                        ))
                      )}
                    </div>
                  </div>
                </div>
              ) : (
                <SettlementView 
                  participants={activeEvent.participants}
                  balances={balances}
                  settlements={settlements}
                  totalSpent={totalSpent}
                  onSettle={handleSettle}
                />
              )}
            </div>
          </div>
        )}
      </main>

      {/* Share Modal */}
      {showShareModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white rounded-[2.5rem] max-w-sm w-full shadow-2xl animate-in zoom-in-95 overflow-hidden">
            <div className="p-8 border-b border-slate-100 flex justify-between items-center">
              <div>
                <h3 className="text-xl font-bold text-slate-800">Share Group</h3>
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">Short Link Generation</p>
              </div>
              <button onClick={() => setShowShareModal(false)} className="text-slate-400 hover:text-slate-600"><i className="fa-solid fa-xmark text-lg"></i></button>
            </div>

            <div className="p-8 space-y-6">
              {!generatedShortUrl ? (
                <button
                  onClick={handleShareToSupabase}
                  disabled={shareStatus === 'saving'}
                  className="w-full bg-[#4f46e5] text-white py-5 rounded-2xl font-bold text-sm shadow-lg hover:bg-[#4338ca] transition-all disabled:opacity-50"
                >
                  {shareStatus === 'saving' ? (
                    <span className="flex items-center justify-center gap-2">
                      <i className="fa-solid fa-spinner animate-spin"></i>
                      SAVING...
                    </span>
                  ) : 'CREATE SHORT LINK'}
                </button>
              ) : (
                <div className="space-y-4 animate-in fade-in zoom-in-95">
                  <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100 flex items-center justify-between gap-3">
                    <span className="text-[10px] font-bold text-slate-400 truncate flex-1">{generatedShortUrl}</span>
                    <button 
                      onClick={handleCopyLink} 
                      className={`px-4 py-2 rounded-xl text-[10px] font-black border transition-all ${shareStatus === 'copied' ? 'bg-green-100 text-green-600 border-green-200' : 'bg-white text-[#4f46e5] border-slate-100'}`}
                    >
                      {shareStatus === 'copied' ? 'COPIED' : 'COPY'}
                    </button>
                  </div>
                  <button onClick={handleShareWhatsApp} className="w-full bg-[#25D366] text-white py-5 rounded-2xl font-bold text-sm flex items-center justify-center gap-3 hover:bg-[#20bd5a] transition-all">
                    <i className="fa-brands fa-whatsapp text-xl"></i>
                    SEND ON WHATSAPP
                  </button>
                </div>
              )}
              {shareStatus === 'error' && <p className="text-[10px] text-red-500 font-bold text-center uppercase tracking-widest">Failed to sync with cloud. Try again.</p>}
            </div>
            <div className="p-6 bg-slate-50 text-center"><p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest">Powered by Supabase DB</p></div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { createClient, SupabaseClient } from '@supabase/supabase-js';
import { Participant, Expense, Settlement, Balance, SplitEvent } from './types.ts';
import ParticipantManager from './components/ParticipantManager.tsx';
import ExpenseForm from './components/ExpenseForm.tsx';
import SettlementView from './components/SettlementView.tsx';
import { calculateBalances, calculateSettlements } from './utils/calculation.ts';

// Helper to generate a 6-character random ID for short URLs
const generateShortId = () => {
  const chars = 'abcdefghijklmnopqrstuvwxyz0123456789';
  let result = '';
  for (let i = 0; i < 6; i++) {
    result += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return result;
};

// Initialize Supabase client
const supabase = createClient(
  process.env.SUPABASE_URL || '',
  process.env.SUPABASE_ANON_KEY || ''
);

const App: React.FC = () => {
  const [events, setEvents] = useState<Record<string, SplitEvent>>({});
  const [currentEventId, setCurrentEventId] = useState<string | null>(null);
  const [newEventName, setNewEventName] = useState('');

  // App states scoped to the active event
  const [activeTab, setActiveTab] = useState<'expenses' | 'settlement'>('expenses');
  const [selectedExpense, setSelectedExpense] = useState<Expense | null>(null);
  const [shareStatus, setShareStatus] = useState<'idle' | 'saving' | 'copied' | 'error'>('idle');
  const [showShareModal, setShowShareModal] = useState(false);
  const [shareEventId, setShareEventId] = useState<string | null>(null);
  const [generatedShortUrl, setGeneratedShortUrl] = useState<string | null>(null);
  const [isInitialized, setIsInitialized] = useState(false);
  const [isLoadingShared, setIsLoadingShared] = useState(false);

  const getAvatar = (name: string) => `https://api.dicebear.com/7.x/initials/svg?seed=${name}&backgroundColor=4f46e5&textColor=ffffff`;

  // Fetch Logic: On mount, check if URL contains a short trip ID and load it from Supabase
  useEffect(() => {
    const loadInitialData = async () => {
      // 1. Load local storage events
      const savedEvents = localStorage.getItem('splitit_multi_events');
      let currentEvents: Record<string, SplitEvent> = savedEvents ? JSON.parse(savedEvents) : {};

      // 2. Check for short ID in hash (e.g., #/trip/abc123)
      const hash = window.location.hash;
      const shortIdMatch = hash.match(/#\/?trip\/([a-z0-9]{6})$/i);

      if (shortIdMatch && shortIdMatch[1]) {
        const tripSlug = shortIdMatch[1];
        setIsLoadingShared(true);
        try {
          const { data, error } = await supabase
            .from('trips')
            .select('trip_data')
            .eq('id', tripSlug)
            .single();

          if (error) throw error;

          if (data && data.trip_data) {
            const fetchedEvent = data.trip_data as SplitEvent;
            // Use the remote event, ensure it's in our local dict
            const localId = fetchedEvent.id || tripSlug;
            currentEvents[localId] = fetchedEvent;
            setCurrentEventId(localId);

            // Clean up the URL hash to avoid re-triggering on future internal navigations
            window.history.replaceState(null, "", window.location.pathname);
          }
        } catch (err) {
          console.error("Failed to fetch shared trip from Supabase:", err);
        } finally {
          setIsLoadingShared(false);
        }
      }

      setEvents(currentEvents);
      setIsInitialized(true);
    };

    loadInitialData();
  }, []);

  // Save to Local Storage whenever events change
  useEffect(() => {
    if (isInitialized) {
      localStorage.setItem('splitit_multi_events', JSON.stringify(events));
    }
  }, [events, isInitialized]);

  // Active event helper
  const activeEvent = currentEventId ? events[currentEventId] : null;

  // Derived data for active event
  const { balances, settlements, totalSpent } = useMemo(() => {
    if (!activeEvent) return { balances: [], settlements: [], totalSpent: 0 };

    const bals = calculateBalances(activeEvent.participants, activeEvent.expenses);
    const setts = calculateSettlements([...bals]);
    const total = activeEvent.expenses.reduce((acc, curr) => curr.category !== 'Payment' ? acc + curr.amount : acc, 0);

    return { 
      balances: bals, 
      settlements: setts, 
      totalSpent: total
    };
  }, [activeEvent]);

  // Actions
  const createEvent = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newEventName.trim()) return;
    const id = crypto.randomUUID();
    const newEv: SplitEvent = {
      id,
      name: newEventName.trim(),
      participants: [],
      expenses: [],
      createdAt: Date.now()
    };
    setEvents(prev => ({ ...prev, [id]: newEv }));
    setNewEventName('');
    setCurrentEventId(id);
  };

  const deleteEvent = (id: string) => {
    if (window.confirm("Delete this event session?")) {
      const newEvents = { ...events };
      delete newEvents[id];
      setEvents(newEvents);
      if (currentEventId === id) setCurrentEventId(null);
    }
  };

  const updateActiveEvent = (updates: Partial<SplitEvent>) => {
    if (!currentEventId) return;
    setEvents(prev => ({
      ...prev,
      [currentEventId]: { ...prev[currentEventId], ...updates }
    }));
  };

  const addParticipant = (name: string, upiId?: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      participants: [...activeEvent.participants, { id: crypto.randomUUID(), name, avatar: getAvatar(name), upiId }]
    });
  };

  const removeParticipant = (id: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      participants: activeEvent.participants.filter(p => p.id !== id),
      expenses: activeEvent.expenses.filter(e => e.payerId !== id && !e.participantIds.includes(id))
    });
  };

  const addExpense = (newExp: Omit<Expense, 'id'>) => {
    if (!activeEvent) return;
    updateActiveEvent({
      expenses: [{ ...newExp, id: crypto.randomUUID() }, ...activeEvent.expenses]
    });
  };

  const removeExpense = (id: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      expenses: activeEvent.expenses.filter(e => e.id !== id)
    });
    if (selectedExpense?.id === id) setSelectedExpense(null);
  };

  const handleSettle = (fromId: string, toId: string, amount: number) => {
    if (!activeEvent) return;
    const fromP = activeEvent.participants.find(p => p.id === fromId)?.name;
    const toP = activeEvent.participants.find(p => p.id === toId)?.name;
    addExpense({
      description: `Settlement: ${fromP} paid ${toP}`,
      amount: amount, payerId: fromId, participantIds: [toId], category: 'Payment', date: Date.now()
    });
  };

  // Save Logic: Push to Supabase trips table with a 6-char ID
  const handleShareToSupabase = async () => {
    if (!shareEventId || !events[shareEventId]) return;

    setShareStatus('saving');
    const targetEvent = events[shareEventId];
    const shortId = generateShortId();

    try {
      const { error } = await supabase
        .from('trips')
        .insert([{ 
          id: shortId,
          trip_data: targetEvent,
          name: targetEvent.name 
        }]);

      if (error) throw error;

      const shortUrl = `https://splitits.in/#/trip/${shortId}`;
      setGeneratedShortUrl(shortUrl);
      setShareStatus('idle');
    } catch (err) {
      console.error("Error saving to Supabase:", err);
      setShareStatus('error');
    }
  };

  const openShareModal = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setShareEventId(id);
    setGeneratedShortUrl(null);
    setShareStatus('idle');
    setShowShareModal(true);
  };

  const handleShareWhatsApp = () => {
    if (!generatedShortUrl || !shareEventId) return;
    const ev = events[shareEventId];
    const settlementText = settlements.length === 0 ? "All settled! ✅" : settlements.map(s => `💸 *${ev.participants.find(p=>p.id===s.from)?.name}* owes *${ev.participants.find(p=>p.id===s.to)?.name}*: ₹${s.amount.toFixed(2)}`).join('\n');

    // The requested message with custom footer
    const text = `💰 *SplitIt: ${ev.name}*\n\n*Settlements:*\n${settlementText}\n\n🔗 View & Settle:\n${generatedShortUrl}\n\nNo more awkward money talks! SplitIt handles it all for you.\nTry it Now: splitits.in`;

    window.open(`https://api.whatsapp.com/send?text=${encodeURIComponent(text)}`, '_blank');
  };

  const handleCopyLink = () => {
    if (!generatedShortUrl) return;
    navigator.clipboard.writeText(generatedShortUrl).then(() => {
      setShareStatus('copied');
      setTimeout(() => setShareStatus('idle'), 2000);
    });
  };

  if (!isInitialized || isLoadingShared) {
    return (
      <div className="min-h-screen bg-[#f8fafc] flex flex-col items-center justify-center font-sans">
        <div className="w-12 h-12 border-4 border-slate-100 border-t-[#4f46e5] rounded-full animate-spin mb-4"></div>
        <p className="text-xs font-bold text-slate-400 uppercase tracking-widest animate-pulse">
          {isLoadingShared ? 'Fetching shared trip...' : 'Initializing SplitIt...'}
        </p>
      </div>
    );
  }

  // Dashboard Render (No Active Event selected)
  if (!currentEventId) {
    return (
      <div className="min-h-screen bg-[#f8fafc] flex flex-col font-sans">
        <header className="bg-white border-b border-slate-100 p-6 sm:p-8 flex items-center justify-between">
          <div className="flex items-center gap-3">
             <div className="w-10 h-10 bg-[#4f46e5] rounded-xl flex items-center justify-center text-white text-2xl shadow-lg shadow-indigo-100"><i className="fa-solid fa-money-bill-transfer"></i></div>
             <h1 className="text-2xl font-black text-slate-800 tracking-tight">SplitIt</h1>
          </div>
          <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest bg-slate-100 px-4 py-1.5 rounded-full">Dashboard</span>
        </header>

        <main className="flex-1 max-w-5xl mx-auto w-full px-4 py-8 sm:py-16 space-y-12 animate-in fade-in duration-700">
          <section className="bg-white rounded-[2.5rem] p-8 sm:p-12 shadow-xl shadow-indigo-50/50 border border-slate-100 text-center space-y-8">
            <div className="space-y-2">
              <h2 className="text-3xl font-bold text-slate-800">Start a Group Session</h2>
              <p className="text-slate-400 font-medium">Clear debts, share receipts, and stay friends.</p>
            </div>

            <form onSubmit={createEvent} className="max-w-md mx-auto relative group">
              <input 
                type="text" 
                value={newEventName}
                onChange={e => setNewEventName(e.target.value)}
                placeholder="Trip name, Dinner party, etc."
                className="w-full px-8 py-5 rounded-3xl bg-slate-50 border-2 border-transparent focus:border-[#4f46e5] focus:bg-white text-lg font-bold transition-all outline-none pr-36 shadow-inner"
              />
              <button 
                type="submit"
                className="absolute right-2 top-2 bottom-2 bg-[#4f46e5] text-white px-8 rounded-2xl font-black text-sm hover:bg-[#4338ca] transition-all shadow-lg active:scale-95"
              >
                CREATE
              </button>
            </form>
          </section>

          {Object.values(events).length > 0 && (
            <section className="space-y-6">
              <div className="flex items-center justify-between px-2">
                <h3 className="text-xs font-black text-slate-400 uppercase tracking-[0.2em]">Recent Sessions</h3>
                <span className="text-xs font-bold text-[#4f46e5]">{Object.values(events).length} Sessions</span>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
                {(Object.values(events) as SplitEvent[]).sort((a: SplitEvent, b: SplitEvent) => b.createdAt - a.createdAt).map((ev: SplitEvent) => {
                  const evTotal = ev.expenses.reduce((acc, curr) => curr.category !== 'Payment' ? acc + curr.amount : acc, 0);
                  return (
                    <div 
                      key={ev.id}
                      onClick={() => setCurrentEventId(ev.id)}
                      className="group bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm hover:shadow-xl hover:border-[#4f46e5]/20 hover:-translate-y-1 transition-all cursor-pointer flex flex-col justify-between min-h-[220px]"
                    >
                      <div className="space-y-4">
                        <div className="flex justify-between items-start">
                          <div className="w-10 h-10 bg-[#eef2ff] text-[#4f46e5] rounded-xl flex items-center justify-center text-lg font-black group-hover:bg-[#4f46e5] group-hover:text-white transition-colors">
                            {ev.name.charAt(0)}
                          </div>
                          <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                            <button onClick={(e) => openShareModal(e, ev.id)} className="w-8 h-8 rounded-full bg-slate-50 text-slate-400 hover:text-[#4f46e5] flex items-center justify-center transition-colors"><i className="fa-solid fa-share-nodes text-xs"></i></button>
                            <button onClick={(e) => { e.stopPropagation(); deleteEvent(ev.id); }} className="w-8 h-8 rounded-full bg-slate-50 text-slate-400 hover:text-red-500 flex items-center justify-center transition-colors"><i className="fa-solid fa-trash text-xs"></i></button>
                          </div>
                        </div>
                        <div>
                          <h4 className="text-xl font-bold text-slate-800 line-clamp-1">{ev.name}</h4>
                          <p className="text-[10px] font-bold text-slate-400 uppercase mt-1">{ev.participants.length} Squad • {ev.expenses.length} Activity</p>
                        </div>
                      </div>
                      <div className="pt-4 border-t border-slate-50 flex items-end justify-between">
                         <div>
                            <span className="block text-[8px] font-black text-slate-300 uppercase tracking-widest">Total Volume</span>
                            <span className="text-xl font-black text-slate-800">₹{evTotal.toFixed(0)}</span>
                         </div>
                         <i className="fa-solid fa-chevron-right text-slate-200 group-hover:translate-x-1 group-hover:text-[#4f46e5] transition-all"></i>
                      </div>
                    </div>
                  );
                })}
              </div>
            </section>
          )}
        </main>
      </div>
    );
  }

  // Active Event View
  return (
    <div className="min-h-screen bg-[#f8fafc] text-slate-900 flex flex-col font-sans overflow-x-hidden">
      <header className="bg-white border-b border-slate-100 sticky top-0 z-30 shadow-sm px-4">
        <div className="max-w-7xl mx-auto h-20 flex items-center justify-between gap-2">
          <div className="flex items-center gap-4">
            <button 
              onClick={() => setCurrentEventId(null)}
              className="w-10 h-10 rounded-full hover:bg-slate-50 flex items-center justify-center text-slate-400 hover:text-slate-800 transition-all"
            >
              <i className="fa-solid fa-arrow-left"></i>
            </button>
            <div className="flex flex-col min-w-0">
              <h1 className="text-lg sm:text-xl font-bold text-[#1e293b] truncate">{activeEvent.name}</h1>
              <p className="text-[9px] font-bold text-slate-400 tracking-[0.1em] uppercase">Cloud Synchronized</p>
            </div>
          </div>
          <nav className="flex bg-[#f1f5f9] p-1 rounded-xl shrink-0">
            <button onClick={() => setActiveTab('expenses')} className={`px-4 sm:px-6 py-2 rounded-lg text-xs font-semibold transition-all ${activeTab === 'expenses' ? 'bg-white text-[#4f46e5] shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Activity</button>
            <button onClick={() => setActiveTab('settlement')} className={`px-4 sm:px-6 py-2 rounded-lg text-xs font-semibold transition-all ${activeTab === 'settlement' ? 'bg-white text-[#4f46e5] shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Settlement</button>
          </nav>
        </div>
      </header>

      <main className="flex-1 max-w-7xl mx-auto w-full px-4 sm:px-6 py-6 sm:py-8 space-y-6">
        <div className="flex items-center justify-between bg-white px-6 py-4 rounded-3xl border border-slate-100 shadow-sm">
          <div className="flex gap-8">
            <div><span className="text-[8px] font-bold text-slate-400 uppercase block mb-1">Spent</span><p className="text-lg font-black">₹{totalSpent.toFixed(0)}</p></div>
            <div><span className="text-[8px] font-bold text-slate-400 uppercase block mb-1">Squad</span><p className="text-lg font-black">{activeEvent.participants.length}</p></div>
          </div>
          <button 
            onClick={(e) => openShareModal(e, activeEvent.id)}
            className="flex items-center gap-2 px-6 py-3 rounded-2xl text-xs font-bold transition-all bg-[#4f46e5] text-white hover:bg-[#4338ca] shadow-md shadow-indigo-100 active:scale-95"
          >
            <i className="fa-solid fa-share-nodes"></i>
            Sync & Share
          </button>
        </div>

        {activeTab === 'expenses' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
            <div className="lg:col-span-3"><ParticipantManager participants={activeEvent.participants} onAdd={addParticipant} onRemove={removeParticipant} /></div>
            <div className="lg:col-span-5 space-y-4">
              <div className="flex justify-between items-center"><h2 className="text-lg font-bold flex items-center gap-2"><i className="fa-solid fa-list-ul text-[#4f46e5]"></i>Recent Activity</h2><span className="text-[10px] font-bold text-slate-400 bg-slate-100 px-3 py-1 rounded-full">{activeEvent.expenses.length}</span></div>
              <div className="min-h-[400px] bg-white border border-slate-100 rounded-3xl p-4 overflow-y-auto max-h-[600px] scrollbar-hide">
                {activeEvent.expenses.length === 0 ? <div className="h-full flex flex-col items-center justify-center text-center text-slate-300 py-12"><i className="fa-solid fa-receipt text-3xl mb-2"></i><p className="text-sm font-bold">No activity recorded</p></div> : 
                  activeEvent.expenses.sort((a,b) => b.date - a.date).map(e => (
                    <div key={e.id} onClick={() => setSelectedExpense(e)} className={`p-4 mb-3 rounded-xl border transition-all cursor-pointer ${e.category === 'Payment' ? 'bg-slate-50 border-slate-100 italic' : 'bg-white border-slate-50 hover:border-[#4f46e5]'}`}>
                      <div className="flex justify-between items-center"><div className="min-w-0"><p className="font-bold text-slate-800 truncate">{e.description}</p><p className="text-[9px] text-slate-400 font-bold uppercase">{activeEvent.participants.find(p=>p.id===e.payerId)?.name} • {new Date(e.date).toLocaleDateString()}</p></div><div className="text-right shrink-0"><p className="font-bold text-slate-800">₹{e.amount.toFixed(0)}</p><p className="text-[8px] text-slate-300 font-bold uppercase">{e.category}</p></div></div>
                    </div>
                  ))}
              </div>
            </div>
            <div className="lg:col-span-4"><ExpenseForm participants={activeEvent.participants} onAdd={addExpense} /></div>
          </div>
        ) : (
          <SettlementView participants={activeEvent.participants} balances={balances} settlements={settlements} totalSpent={totalSpent} onSettle={handleSettle} />
        )}
      </main>

      {/* Sharing Modal */}
      {showShareModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
          <div className="bg-white rounded-[2.5rem] max-w-sm w-full shadow-2xl animate-in zoom-in-95 duration-200 overflow-hidden">
            <div className="p-8 border-b border-slate-100 flex justify-between items-center">
              <div>
                <h3 className="text-xl font-bold text-slate-800">Share Link</h3>
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">Short Unique URL</p>
              </div>
              <button onClick={() => setShowShareModal(false)} className="text-slate-400 hover:text-slate-600"><i className="fa-solid fa-xmark text-lg"></i></button>
            </div>

            <div className="p-8 space-y-6">
              {shareStatus === 'saving' ? (
                <div className="flex flex-col items-center justify-center py-12 gap-4">
                  <div className="w-12 h-12 border-4 border-slate-100 border-t-[#4f46e5] rounded-full animate-spin"></div>
                  <p className="text-xs font-bold text-slate-500 uppercase tracking-widest animate-pulse">Saving to Cloud...</p>
                </div>
              ) : generatedShortUrl ? (
                <div className="space-y-4 animate-in fade-in duration-300">
                  <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100 text-center">
                    <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest block mb-1">Your Link</span>
                    <p className="text-xs font-medium text-[#4f46e5] truncate">{generatedShortUrl}</p>
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <button onClick={handleShareWhatsApp} className="flex flex-col items-center gap-2 p-6 rounded-3xl bg-green-50 hover:bg-green-100 transition-colors">
                      <div className="w-12 h-12 bg-green-500 rounded-full flex items-center justify-center text-white"><i className="fa-brands fa-whatsapp text-2xl"></i></div>
                      <span className="text-xs font-bold text-green-700">WhatsApp</span>
                    </button>
                    <button onClick={handleCopyLink} className={`flex flex-col items-center gap-2 p-6 rounded-3xl transition-colors ${shareStatus === 'copied' ? 'bg-indigo-100' : 'bg-slate-50'}`}>
                      <div className={`w-12 h-12 rounded-full flex items-center justify-center text-white ${shareStatus === 'copied' ? 'bg-green-600' : 'bg-slate-700'}`}>
                        <i className={`fa-solid ${shareStatus === 'copied' ? 'fa-check' : 'fa-link'} text-xl`}></i>
                      </div>
                      <span className="text-xs font-bold text-slate-700">{shareStatus === 'copied' ? 'Copied!' : 'Copy Link'}</span>
                    </button>
                  </div>
                </div>
              ) : (
                <button 
                  onClick={handleShareToSupabase}
                  className="w-full bg-[#4f46e5] text-white py-5 rounded-2xl font-bold text-sm shadow-xl shadow-indigo-100 hover:bg-[#4338ca] transition-all"
                >
                  Generate Short URL
                </button>
              )}
            </div>
            <div className="p-6 bg-slate-50 text-center border-t border-slate-100">
              <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest">Secured by Supabase Infrastructure</p>
            </div>
          </div>
        </div>
      )}

      {selectedExpense && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm">
          <div className="bg-white rounded-3xl max-w-lg w-full overflow-hidden shadow-2xl p-8 space-y-6 animate-in zoom-in-95">
            <div className="flex justify-between items-center"><h3 className="text-xl font-bold">Transaction Detail</h3><button onClick={() => setSelectedExpense(null)} className="text-slate-400 hover:text-slate-800"><i className="fa-solid fa-xmark"></i></button></div>
            <div className="space-y-4">
              <div className="flex justify-between items-center pb-4 border-b border-slate-50"><span>Description</span><span className="font-bold text-lg">{selectedExpense.description}</span></div>
              <div className="flex justify-between items-center pb-4 border-b border-slate-50"><span>Amount</span><span className="font-black text-2xl text-[#4f46e5]">₹{selectedExpense.amount}</span></div>
              <div className="flex justify-between items-center pb-4 border-b border-slate-50"><span>Who Paid</span><span className="font-bold">{activeEvent.participants.find(p=>p.id===selectedExpense.payerId)?.name}</span></div>
            </div>
            <button onClick={() => removeExpense(selectedExpense.id)} className="w-full py-4 bg-red-50 text-red-500 font-bold rounded-2xl hover:bg-red-100 transition-colors flex items-center justify-center gap-2"><i className="fa-solid fa-trash-can"></i>Delete Record</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { createClient, SupabaseClient } from '@supabase/supabase-js';
import { Participant, Expense, Settlement, Balance, SplitEvent } from './types.ts';
import ParticipantManager from './components/ParticipantManager.tsx';
import ExpenseForm from './components/ExpenseForm.tsx';
import SettlementView from './components/SettlementView.tsx';
import { calculateBalances, calculateSettlements } from './utils/calculation.ts';

// Helper to generate a 6-character random ID for short URLs
const generateShortId = () => {
  const chars = 'abcdefghijklmnopqrstuvwxyz0123456789';
  let result = '';
  for (let i = 0; i < 6; i++) {
    result += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return result;
};

// Initialize Supabase client using environment variables
const supabase = createClient(
  process.env.SUPABASE_URL || 'https://yrlvjtnxusbgqeqgaonu.supabase.co',
  process.env.SUPABASE_ANON_KEY || 'sb_publishable_bFgmsQkkShvZYtyLf7ASEA_I1J6Y3zw'
);

const App: React.FC = () => {
  const [events, setEvents] = useState<Record<string, SplitEvent>>({});
  const [currentEventId, setCurrentEventId] = useState<string | null>(null);
  const [newEventName, setNewEventName] = useState('');

  // App states scoped to sharing and loading
  const [activeTab, setActiveTab] = useState<'expenses' | 'settlement'>('expenses');
  const [selectedExpense, setSelectedExpense] = useState<Expense | null>(null);
  const [shareStatus, setShareStatus] = useState<'idle' | 'saving' | 'copied' | 'error'>('idle');
  const [showShareModal, setShowShareModal] = useState(false);
  const [shareEventId, setShareEventId] = useState<string | null>(null);
  const [generatedShortUrl, setGeneratedShortUrl] = useState<string | null>(null);
  const [isInitialized, setIsInitialized] = useState(false);
  const [isLoadingShared, setIsLoadingShared] = useState(false);

  const getAvatar = (name: string) => `https://api.dicebear.com/7.x/initials/svg?seed=${name}&backgroundColor=4f46e5&textColor=ffffff`;

  // Fetch Logic: On mount, check if URL contains a short trip ID and load it from Supabase
  useEffect(() => {
    const loadInitialData = async () => {
      // 1. Load local storage events
      const savedEvents = localStorage.getItem('splitit_multi_events');
      let currentEvents: Record<string, SplitEvent> = savedEvents ? JSON.parse(savedEvents) : {};

      // 2. Check for short ID in hash (e.g., #/trip/abc123)
      const hash = window.location.hash;
      const shortIdMatch = hash.match(/#\/?trip\/([a-z0-9]{6})$/i);

      if (shortIdMatch && shortIdMatch[1]) {
        const tripSlug = shortIdMatch[1];
        setIsLoadingShared(true);
        try {
          const { data, error } = await supabase
            .from('trips')
            .select('trip_data')
            .eq('id', tripSlug)
            .single();

          if (error) throw error;

          if (data && data.trip_data) {
            const fetchedEvent = data.trip_data as SplitEvent;
            // Use the remote event, ensure it's in our local dictionary
            const localId = fetchedEvent.id || tripSlug;
            currentEvents[localId] = fetchedEvent;
            setCurrentEventId(localId);

            // Clean up the URL hash after loading to provide a clean browsing experience
            window.history.replaceState(null, "", window.location.pathname);
          }
        } catch (err) {
          console.error("Failed to fetch shared trip from Supabase:", err);
        } finally {
          setIsLoadingShared(false);
        }
      }

      setEvents(currentEvents);
      setIsInitialized(true);
    };

    loadInitialData();
  }, []);

  // Sync state to local storage for persistence
  useEffect(() => {
    if (isInitialized) {
      localStorage.setItem('splitit_multi_events', JSON.stringify(events));
    }
  }, [events, isInitialized]);

  // Helper for the currently viewed event
  const activeEvent = currentEventId ? events[currentEventId] : null;

  // Compute balances and settlements whenever active event changes
  const { balances, settlements, totalSpent } = useMemo(() => {
    if (!activeEvent) return { balances: [], settlements: [], totalSpent: 0 };

    const bals = calculateBalances(activeEvent.participants, activeEvent.expenses);
    const setts = calculateSettlements([...bals]);
    const total = activeEvent.expenses.reduce((acc, curr) => curr.category !== 'Payment' ? acc + curr.amount : acc, 0);

    return { 
      balances: bals, 
      settlements: setts, 
      totalSpent: total
    };
  }, [activeEvent]);

  // Event Handlers
  const createEvent = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newEventName.trim()) return;
    const id = crypto.randomUUID();
    const newEv: SplitEvent = {
      id,
      name: newEventName.trim(),
      participants: [],
      expenses: [],
      createdAt: Date.now()
    };
    setEvents(prev => ({ ...prev, [id]: newEv }));
    setNewEventName('');
    setCurrentEventId(id);
  };

  const deleteEvent = (id: string) => {
    if (window.confirm("Delete this group session permanently?")) {
      const newEvents = { ...events };
      delete newEvents[id];
      setEvents(newEvents);
      if (currentEventId === id) setCurrentEventId(null);
    }
  };

  const updateActiveEvent = (updates: Partial<SplitEvent>) => {
    if (!currentEventId) return;
    setEvents(prev => ({
      ...prev,
      [currentEventId]: { ...prev[currentEventId], ...updates }
    }));
  };

  const addParticipant = (name: string, upiId?: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      participants: [...activeEvent.participants, { id: crypto.randomUUID(), name, avatar: getAvatar(name), upiId }]
    });
  };

  const removeParticipant = (id: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      participants: activeEvent.participants.filter(p => p.id !== id),
      expenses: activeEvent.expenses.filter(e => e.payerId !== id && !e.participantIds.includes(id))
    });
  };

  const addExpense = (newExp: Omit<Expense, 'id'>) => {
    if (!activeEvent) return;
    updateActiveEvent({
      expenses: [{ ...newExp, id: crypto.randomUUID() }, ...activeEvent.expenses]
    });
  };

  const removeExpense = (id: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      expenses: activeEvent.expenses.filter(e => e.id !== id)
    });
    if (selectedExpense?.id === id) setSelectedExpense(null);
  };

  const handleSettle = (fromId: string, toId: string, amount: number) => {
    if (!activeEvent) return;
    const fromP = activeEvent.participants.find(p => p.id === fromId)?.name;
    const toP = activeEvent.participants.find(p => p.id === toId)?.name;
    addExpense({
      description: `Settlement: ${fromP} paid ${toP}`,
      amount: amount, payerId: fromId, participantIds: [toId], category: 'Payment', date: Date.now()
    });
  };

  // Save Logic: Save to Supabase and generate short URL
  const handleShareToSupabase = async () => {
    if (!shareEventId || !events[shareEventId]) return;

    setShareStatus('saving');
    const targetEvent = events[shareEventId];
    const shortId = generateShortId();

    try {
      const { error } = await supabase
        .from('trips')
        .insert([{ 
          id: shortId,
          trip_data: targetEvent,
          name: targetEvent.name 
        }]);

      if (error) throw error;

      const shortUrl = `https://splitits.in/#/trip/${shortId}`;
      setGeneratedShortUrl(shortUrl);
      setShareStatus('idle');
    } catch (err) {
      console.error("Supabase Save Error:", err);
      setShareStatus('error');
    }
  };

  const openShareModal = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setShareEventId(id);
    setGeneratedShortUrl(null);
    setShareStatus('idle');
    setShowShareModal(true);
  };

  const handleShareWhatsApp = () => {
    if (!generatedShortUrl || !shareEventId) return;
    const ev = events[shareEventId];

    // Construct settlement summary
    const settlementText = settlements.length === 0 
      ? "All clear! No pending payments. ✅" 
      : settlements.map(s => {
          const fromName = ev.participants.find(p => p.id === s.from)?.name;
          const toName = ev.participants.find(p => p.id === s.to)?.name;
          return `💸 *${fromName}* owes *${toName}*: ₹${s.amount.toFixed(2)}`;
        }).join('\n');

    // Construct the final message with the requested tagline
    const text = `💰 *SplitIt: ${ev.name}*\n\n*Current Settlements:*\n${settlementText}\n\n🔗 Open trip and settle:\n${generatedShortUrl}\n\nNo more awkward money talks! SplitIt handles it all for you.\nTry it Now: splitits.in`;

    window.open(`https://api.whatsapp.com/send?text=${encodeURIComponent(text)}`, '_blank');
  };

  const handleCopyLink = () => {
    if (!generatedShortUrl) return;
    navigator.clipboard.writeText(generatedShortUrl).then(() => {
      setShareStatus('copied');
      setTimeout(() => setShareStatus('idle'), 2000);
    });
  };

  // Loading Screen for Init or DB Fetch
  if (!isInitialized || isLoadingShared) {
    return (
      <div className="min-h-screen bg-[#f8fafc] flex flex-col items-center justify-center font-sans">
        <div className="w-12 h-12 border-4 border-slate-100 border-t-[#4f46e5] rounded-full animate-spin mb-4"></div>
        <p className="text-xs font-bold text-slate-400 uppercase tracking-widest animate-pulse">
          {isLoadingShared ? 'Fetching shared trip...' : 'Initializing SplitIt...'}
        </p>
      </div>
    );
  }

  // Dashboard View: Shown when no specific event is selected
  if (!currentEventId) {
    return (
      <div className="min-h-screen bg-[#f8fafc] flex flex-col font-sans">
        <header className="bg-white border-b border-slate-100 p-6 sm:p-8 flex items-center justify-between">
          <div className="flex items-center gap-3">
             <div className="w-10 h-10 bg-[#4f46e5] rounded-xl flex items-center justify-center text-white text-2xl shadow-lg shadow-indigo-100 transition-transform hover:rotate-6">
               <i className="fa-solid fa-money-bill-transfer"></i>
             </div>
             <h1 className="text-2xl font-black text-slate-800 tracking-tight">SplitIt</h1>
          </div>
          <div className="hidden sm:block">
            <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest bg-slate-50 border border-slate-100 px-4 py-1.5 rounded-full">Dashboard</span>
          </div>
        </header>

        <main className="flex-1 max-w-5xl mx-auto w-full px-4 py-8 sm:py-20 space-y-12 animate-in fade-in duration-700">
          <section className="bg-white rounded-[3rem] p-8 sm:p-16 shadow-2xl shadow-indigo-100/40 border border-slate-50 text-center space-y-10">
            <div className="space-y-4">
              <h2 className="text-4xl sm:text-5xl font-black text-slate-800 tracking-tight leading-tight">Split expenses, <br/><span className="text-[#4f46e5]">keep the friendship.</span></h2>
              <p className="text-slate-400 font-medium text-lg max-w-lg mx-auto">Toss your paper receipts. splitIt tracks everything so you don't have to.</p>
            </div>

            <form onSubmit={createEvent} className="max-w-md mx-auto relative group">
              <input 
                type="text" 
                value={newEventName}
                onChange={e => setNewEventName(e.target.value)}
                placeholder="Name your adventure (e.g. Goa 2024)"
                className="w-full px-8 py-5 rounded-[2rem] bg-slate-50 border-2 border-transparent focus:border-[#4f46e5] focus:bg-white text-lg font-bold transition-all outline-none pr-36 shadow-inner"
              />
              <button 
                type="submit"
                className="absolute right-2 top-2 bottom-2 bg-[#4f46e5] text-white px-8 rounded-[1.5rem] font-black text-sm hover:bg-[#4338ca] transition-all shadow-lg active:scale-95"
              >
                CREATE
              </button>
            </form>
          </section>

          {Object.keys(events).length > 0 && (
            <section className="space-y-6">
              <div className="flex items-center justify-between px-2">
                <h3 className="text-xs font-black text-slate-400 uppercase tracking-[0.2em]">Recent Groups</h3>
                <span className="text-xs font-bold text-[#4f46e5] bg-[#eef2ff] px-3 py-1 rounded-full">{Object.keys(events).length} Sessions</span>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
                {(Object.values(events) as SplitEvent[]).sort((a, b) => b.createdAt - a.createdAt).map((ev) => {
                  const evTotal = ev.expenses.reduce((acc, curr) => curr.category !== 'Payment' ? acc + curr.amount : acc, 0);
                  return (
                    <div 
                      key={ev.id}
                      onClick={() => setCurrentEventId(ev.id)}
                      className="group bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-sm hover:shadow-2xl hover:border-[#4f46e5]/20 hover:-translate-y-2 transition-all cursor-pointer flex flex-col justify-between min-h-[240px]"
                    >
                      <div className="space-y-4">
                        <div className="flex justify-between items-start">
                          <div className="w-12 h-12 bg-[#eef2ff] text-[#4f46e5] rounded-2xl flex items-center justify-center text-xl font-black group-hover:bg-[#4f46e5] group-hover:text-white transition-all duration-300">
                            {ev.name.charAt(0)}
                          </div>
                          <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                            <button onClick={(e) => openShareModal(e, ev.id)} className="w-9 h-9 rounded-xl bg-slate-50 text-slate-400 hover:text-[#4f46e5] hover:bg-white flex items-center justify-center transition-all border border-transparent hover:border-slate-100"><i className="fa-solid fa-share-nodes text-xs"></i></button>
                            <button onClick={(e) => { e.stopPropagation(); deleteEvent(ev.id); }} className="w-9 h-9 rounded-xl bg-slate-50 text-slate-400 hover:text-red-500 hover:bg-white flex items-center justify-center transition-all border border-transparent hover:border-slate-100"><i className="fa-solid fa-trash-can text-xs"></i></button>
                          </div>
                        </div>
                        <div>
                          <h4 className="text-xl font-black text-slate-800 line-clamp-1 group-hover:text-[#4f46e5] transition-colors">{ev.name}</h4>
                          <p className="text-[10px] font-bold text-slate-400 uppercase mt-1 tracking-wider">{ev.participants.length} Members • {ev.expenses.length} Records</p>
                        </div>
                      </div>
                      <div className="pt-5 border-t border-slate-50 flex items-end justify-between">
                         <div>
                            <span className="block text-[8px] font-black text-slate-300 uppercase tracking-widest mb-1">Total Spent</span>
                            <span className="text-2xl font-black text-slate-800">₹{evTotal.toFixed(0)}</span>
                         </div>
                         <div className="w-10 h-10 rounded-full border border-slate-100 flex items-center justify-center text-slate-300 group-hover:text-[#4f46e5] group-hover:border-[#4f46e5] transition-all">
                           <i className="fa-solid fa-chevron-right text-xs"></i>
                         </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            </section>
          )}
        </main>
      </div>
    );
  }

  // Active Trip Management View
  return (
    <div className="min-h-screen bg-[#f8fafc] text-slate-900 flex flex-col font-sans overflow-x-hidden">
      <header className="bg-white border-b border-slate-100 sticky top-0 z-30 shadow-sm px-4">
        <div className="max-w-7xl mx-auto h-20 flex items-center justify-between gap-4">
          <div className="flex items-center gap-4 min-w-0">
            <button 
              onClick={() => setCurrentEventId(null)}
              className="w-10 h-10 rounded-xl hover:bg-slate-50 flex items-center justify-center text-slate-400 hover:text-slate-800 transition-all border border-transparent hover:border-slate-100"
            >
              <i className="fa-solid fa-arrow-left"></i>
            </button>
            <div className="flex flex-col min-w-0">
              <h1 className="text-lg font-black text-[#1e293b] truncate uppercase tracking-tight">{activeEvent.name}</h1>
              <div className="flex items-center gap-1.5">
                <div className="w-1.5 h-1.5 rounded-full bg-green-500"></div>
                <p className="text-[9px] font-black text-slate-400 tracking-[0.1em] uppercase">Cloud Sync Active</p>
              </div>
            </div>
          </div>
          <nav className="flex bg-[#f1f5f9] p-1.5 rounded-2xl shrink-0">
            <button onClick={() => setActiveTab('expenses')} className={`px-5 py-2.5 rounded-xl text-xs font-bold uppercase tracking-wider transition-all ${activeTab === 'expenses' ? 'bg-white text-[#4f46e5] shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Activity</button>
            <button onClick={() => setActiveTab('settlement')} className={`px-5 py-2.5 rounded-xl text-xs font-bold uppercase tracking-wider transition-all ${activeTab === 'settlement' ? 'bg-white text-[#4f46e5] shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Settlement</button>
          </nav>
        </div>
      </header>

      <main className="flex-1 max-w-7xl mx-auto w-full px-4 sm:px-6 py-6 sm:py-10 space-y-8 animate-in fade-in slide-in-from-bottom-2 duration-500">
        <div className="flex flex-col sm:flex-row items-center justify-between bg-white px-8 py-6 rounded-[2.5rem] border border-slate-100 shadow-xl shadow-slate-100/50 gap-6">
          <div className="flex gap-12 text-center sm:text-left">
            <div>
              <span className="text-[9px] font-black text-slate-400 uppercase block mb-1 tracking-widest">Aggregate Spent</span>
              <p className="text-3xl font-black text-slate-800">₹{totalSpent.toFixed(0)}</p>
            </div>
            <div>
              <span className="text-[9px] font-black text-slate-400 uppercase block mb-1 tracking-widest">The Squad</span>
              <p className="text-3xl font-black text-slate-800">{activeEvent.participants.length}</p>
            </div>
          </div>
          <button 
            onClick={(e) => openShareModal(e, activeEvent.id)}
            className="w-full sm:w-auto flex items-center justify-center gap-3 px-10 py-5 rounded-2xl text-xs font-black uppercase tracking-widest transition-all bg-[#4f46e5] text-white hover:bg-[#4338ca] shadow-xl shadow-indigo-200 active:scale-[0.97]"
          >
            <i className="fa-solid fa-cloud-arrow-up"></i>
            Cloud Sync & Share
          </button>
        </div>

        {activeTab === 'expenses' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
            <div className="lg:col-span-3">
              <ParticipantManager participants={activeEvent.participants} onAdd={addParticipant} onRemove={removeParticipant} />
            </div>
            <div className="lg:col-span-5 space-y-6">
              <div className="flex justify-between items-center px-2">
                <h2 className="text-xs font-black uppercase tracking-[0.2em] text-slate-400 flex items-center gap-2">
                  <i className="fa-solid fa-list-check"></i>
                  Recent Transactions
                </h2>
                <span className="text-[10px] font-bold text-[#4f46e5] bg-[#eef2ff] px-3 py-1 rounded-full">{activeEvent.expenses.length} Total</span>
              </div>
              <div className="min-h-[400px] bg-white border border-slate-100 rounded-[2rem] p-4 overflow-y-auto max-h-[650px] scrollbar-hide shadow-sm">
                {activeEvent.expenses.length === 0 ? (
                  <div className="h-full flex flex-col items-center justify-center text-center text-slate-300 py-24 gap-4">
                    <div className="w-16 h-16 rounded-full bg-slate-50 flex items-center justify-center"><i className="fa-solid fa-receipt text-2xl"></i></div>
                    <p className="text-xs font-bold uppercase tracking-widest">No activity recorded yet</p>
                  </div>
                ) : (
                  activeEvent.expenses.sort((a,b) => b.date - a.date).map(e => (
                    <div 
                      key={e.id} 
                      onClick={() => setSelectedExpense(e)} 
                      className={`p-5 mb-4 rounded-2xl border transition-all cursor-pointer group ${e.category === 'Payment' ? 'bg-slate-50/50 border-slate-100 border-dashed' : 'bg-white border-slate-50 hover:border-[#4f46e5] hover:shadow-lg hover:shadow-indigo-50'}`}
                    >
                      <div className="flex justify-between items-center">
                        <div className="min-w-0 flex items-center gap-4">
                          <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-lg ${e.category === 'Payment' ? 'text-green-500 bg-green-50' : 'text-slate-400 bg-slate-50'}`}>
                             <i className={`fa-solid ${e.category === 'Payment' ? 'fa-hand-holding-dollar' : 'fa-receipt'}`}></i>
                          </div>
                          <div className="min-w-0">
                            <p className="font-black text-slate-800 truncate group-hover:text-[#4f46e5] transition-colors">{e.description}</p>
                            <p className="text-[9px] text-slate-400 font-bold uppercase mt-0.5">
                              <span className="text-slate-600">{activeEvent.participants.find(p=>p.id===e.payerId)?.name}</span> paid • {new Date(e.date).toLocaleDateString()}
                            </p>
                          </div>
                        </div>
                        <div className="text-right shrink-0">
                          <p className="font-black text-slate-800 text-lg">₹{e.amount.toFixed(0)}</p>
                          <p className="text-[8px] text-slate-300 font-black uppercase tracking-widest">{e.category}</p>
                        </div>
                      </div>
                    </div>
                  ))
                )}
              </div>
            </div>
            <div className="lg:col-span-4">
              <ExpenseForm participants={activeEvent.participants} onAdd={addExpense} />
            </div>
          </div>
        ) : (
          <SettlementView participants={activeEvent.participants} balances={balances} settlements={settlements} totalSpent={totalSpent} onSettle={handleSettle} />
        )}
      </main>

      {/* Cloud Sync & Share Modal */}
      {showShareModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md animate-in fade-in duration-300">
          <div className="bg-white rounded-[3rem] max-w-sm w-full shadow-2xl animate-in zoom-in-95 duration-200 overflow-hidden">
            <div className="p-10 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
              <div>
                <h3 className="text-2xl font-black text-slate-800 tracking-tight">Cloud Sync</h3>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">Get your unique short link</p>
              </div>
              <button 
                onClick={() => setShowShareModal(false)} 
                className="w-10 h-10 rounded-full hover:bg-white flex items-center justify-center text-slate-300 hover:text-slate-600 transition-all border border-transparent hover:border-slate-100"
              >
                <i className="fa-solid fa-xmark text-lg"></i>
              </button>
            </div>

            <div className="p-10 space-y-8">
              {shareStatus === 'saving' ? (
                <div className="flex flex-col items-center justify-center py-12 gap-6">
                  <div className="w-16 h-16 border-[6px] border-slate-100 border-t-[#4f46e5] rounded-full animate-spin shadow-inner"></div>
                  <p className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] animate-pulse">Pushing to Cloud...</p>
                </div>
              ) : generatedShortUrl ? (
                <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
                  <div className="p-6 bg-slate-50 rounded-[2rem] border border-slate-100 text-center relative overflow-hidden group">
                    <span className="text-[9px] font-black text-slate-300 uppercase tracking-widest block mb-2">Short Link Generated</span>
                    <p className="text-sm font-bold text-[#4f46e5] truncate px-4">{generatedShortUrl}</p>
                    <div className="absolute inset-0 bg-[#4f46e5]/5 opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none"></div>
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <button onClick={handleShareWhatsApp} className="flex flex-col items-center gap-3 p-6 rounded-[2rem] bg-green-50 hover:bg-green-100 transition-all border border-green-100 group">
                      <div className="w-14 h-14 bg-green-500 rounded-2xl flex items-center justify-center text-white shadow-lg shadow-green-100 group-hover:scale-110 transition-transform"><i className="fa-brands fa-whatsapp text-2xl"></i></div>
                      <span className="text-[10px] font-black text-green-700 uppercase tracking-widest">WhatsApp</span>
                    </button>
                    <button onClick={handleCopyLink} className={`flex flex-col items-center gap-3 p-6 rounded-[2rem] transition-all border group ${shareStatus === 'copied' ? 'bg-green-100 border-green-200' : 'bg-slate-50 border-slate-100 hover:bg-slate-100'}`}>
                      <div className={`w-14 h-14 rounded-2xl flex items-center justify-center text-white shadow-lg transition-all group-hover:scale-110 ${shareStatus === 'copied' ? 'bg-green-600 shadow-green-100' : 'bg-slate-800 shadow-slate-100'}`}>
                        <i className={`fa-solid ${shareStatus === 'copied' ? 'fa-check' : 'fa-link-slash'} text-xl`}></i>
                      </div>
                      <span className="text-[10px] font-black text-slate-700 uppercase tracking-widest">{shareStatus === 'copied' ? 'Success' : 'Copy'}</span>
                    </button>
                  </div>
                </div>
              ) : (
                <button 
                  onClick={handleShareToSupabase}
                  className="w-full bg-[#4f46e5] text-white py-6 rounded-2xl font-black text-xs uppercase tracking-widest shadow-2xl shadow-indigo-200 hover:bg-[#4338ca] hover:-translate-y-1 transition-all active:scale-[0.98]"
                >
                  Generate Private Link
                </button>
              )}
              {shareStatus === 'error' && (
                <div className="p-4 bg-red-50 rounded-xl border border-red-100 text-center">
                  <p className="text-[9px] text-red-500 font-black uppercase tracking-widest">Connection lost. Please check credentials.</p>
                </div>
              )}
            </div>
            <div className="p-8 bg-slate-50/80 text-center border-t border-slate-100">
              <p className="text-[8px] text-slate-400 font-black uppercase tracking-[0.3em] flex items-center justify-center gap-2">
                <i className="fa-solid fa-shield-halved text-[#4f46e5]"></i>
                End-to-End Persistence
              </p>
            </div>
          </div>
        </div>
      )}

      {/* Detail & Deletion Modal */}
      {selectedExpense && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-md animate-in fade-in duration-300">
          <div className="bg-white rounded-[2.5rem] max-w-lg w-full overflow-hidden shadow-2xl p-10 space-y-8 animate-in zoom-in-95 duration-200">
            <div className="flex justify-between items-center">
               <h3 className="text-2xl font-black text-slate-800 tracking-tight">Transaction Info</h3>
               <button onClick={() => setSelectedExpense(null)} className="w-8 h-8 rounded-full bg-slate-50 flex items-center justify-center text-slate-400 hover:text-slate-800 transition-all"><i className="fa-solid fa-xmark"></i></button>
            </div>
            <div className="space-y-6">
              <div className="flex justify-between items-center pb-6 border-b border-slate-50">
                <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Label</span>
                <span className="font-black text-xl text-slate-800">{selectedExpense.description}</span>
              </div>
              <div className="flex justify-between items-center pb-6 border-b border-slate-50">
                <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Value</span>
                <span className="font-black text-3xl text-[#4f46e5]">₹{selectedExpense.amount.toFixed(2)}</span>
              </div>
              <div className="flex justify-between items-center pb-6 border-b border-slate-50">
                <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Payer</span>
                <span className="font-black text-slate-800">{activeEvent.participants.find(p=>p.id===selectedExpense.payerId)?.name}</span>
              </div>
            </div>
            <button 
              onClick={() => removeExpense(selectedExpense.id)} 
              className="w-full py-5 bg-red-50 text-red-500 font-black text-xs uppercase tracking-widest rounded-2xl hover:bg-red-100 transition-all flex items-center justify-center gap-3 border border-red-100"
            >
              <i className="fa-solid fa-trash-can"></i>
              Void Record
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { createClient, SupabaseClient } from '@supabase/supabase-js';
import { Participant, Expense, Settlement, Balance, SplitEvent } from './types.ts';
import ParticipantManager from './components/ParticipantManager.tsx';
import ExpenseForm from './components/ExpenseForm.tsx';
import SettlementView from './components/SettlementView.tsx';
import { calculateBalances, calculateSettlements } from './utils/calculation.ts';

// Helper to generate a 6-character random ID for short URLs and unique event strings
const generateShortId = () => {
  const chars = 'abcdefghijklmnopqrstuvwxyz0123456789';
  let result = '';
  for (let i = 0; i < 6; i++) {
    result += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return result;
};

// Initialize Supabase client lazily or safely
const getSupabase = () => {
  const url = process.env.SUPABASE_URL || 'https://yrlvjtnxusbgqeqgaonu.supabase.co';
  const key = process.env.SUPABASE_ANON_KEY || 'sb_publishable_bFgmsQkkShvZYtyLf7ASEA_I1J6Y3zw';
  if (!url || !key) return null;
  return createClient(url, key);
};

const App: React.FC = () => {
  const [events, setEvents] = useState<Record<string, SplitEvent>>({});
  const [currentEventId, setCurrentEventId] = useState<string | null>(null);
  const [newEventName, setNewEventName] = useState('');

  // App states
  const [activeTab, setActiveTab] = useState<'expenses' | 'settlement'>('expenses');
  const [selectedExpense, setSelectedExpense] = useState<Expense | null>(null);
  const [shareStatus, setShareStatus] = useState<'idle' | 'saving' | 'copied' | 'error'>('idle');
  const [showShareModal, setShowShareModal] = useState(false);
  const [shareEventId, setShareEventId] = useState<string | null>(null);
  const [generatedShortUrl, setGeneratedShortUrl] = useState<string | null>(null);
  const [isInitialized, setIsInitialized] = useState(false);
  const [isLoadingShared, setIsLoadingShared] = useState(false);

  const getAvatar = (name: string) => `https://api.dicebear.com/7.x/initials/svg?seed=${name}&backgroundColor=4f46e5&textColor=ffffff`;

  // Fetch Logic: On mount, check if URL contains a short trip ID
  useEffect(() => {
    const loadInitialData = async () => {
      const savedEvents = localStorage.getItem('splitit_multi_events');
      let currentEvents: Record<string, SplitEvent> = savedEvents ? JSON.parse(savedEvents) : {};

      const hash = window.location.hash;
      const shortIdMatch = hash.match(/#\/?trip\/([a-z0-9]{6})$/i);
      const sb = getSupabase();

      if (shortIdMatch && shortIdMatch[1] && sb) {
        const tripSlug = shortIdMatch[1];
        setIsLoadingShared(true);
        try {
          const { data, error } = await sb
            .from('trips')
            .select('trip_data')
            .eq('id', tripSlug)
            .single();

          if (!error && data?.trip_data) {
            const fetchedEvent = data.trip_data as SplitEvent;
            const localId = fetchedEvent.id || tripSlug;
            currentEvents[localId] = fetchedEvent;
            setCurrentEventId(localId);
            window.history.replaceState(null, "", window.location.pathname);
          }
        } catch (err) {
          console.error("Supabase fetch error:", err);
        } finally {
          setIsLoadingShared(false);
        }
      }

      setEvents(currentEvents);
      setIsInitialized(true);
    };

    loadInitialData();
  }, []);

  useEffect(() => {
    if (isInitialized) {
      localStorage.setItem('splitit_multi_events', JSON.stringify(events));
    }
  }, [events, isInitialized]);

  const activeEvent = currentEventId ? events[currentEventId] : null;

  const { balances, settlements, totalSpent } = useMemo(() => {
    if (!activeEvent) return { balances: [], settlements: [], totalSpent: 0 };
    const bals = calculateBalances(activeEvent.participants, activeEvent.expenses);
    const setts = calculateSettlements([...bals]);
    const total = activeEvent.expenses.reduce((acc, curr) => curr.category !== 'Payment' ? acc + curr.amount : acc, 0);
    return { balances: bals, settlements: setts, totalSpent: total };
  }, [activeEvent]);

  const createEvent = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newEventName.trim()) return;
    // Generate a unique 6-character string ID for the event immediately
    const id = generateShortId();
    const newEv: SplitEvent = {
      id,
      name: newEventName.trim(),
      participants: [],
      expenses: [],
      createdAt: Date.now()
    };
    setEvents(prev => ({ ...prev, [id]: newEv }));
    setNewEventName('');
    setCurrentEventId(id);
  };

  const deleteEvent = (id: string) => {
    if (window.confirm("Permanently delete this group?")) {
      const newEvents = { ...events };
      delete newEvents[id];
      setEvents(newEvents);
      if (currentEventId === id) setCurrentEventId(null);
    }
  };

  const updateActiveEvent = (updates: Partial<SplitEvent>) => {
    if (!currentEventId) return;
    setEvents(prev => ({
      ...prev,
      [currentEventId]: { ...prev[currentEventId], ...updates }
    }));
  };

  const addParticipant = (name: string, upiId?: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      participants: [...activeEvent.participants, { id: crypto.randomUUID(), name, avatar: getAvatar(name), upiId }]
    });
  };

  const removeParticipant = (id: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      participants: activeEvent.participants.filter(p => p.id !== id),
      expenses: activeEvent.expenses.filter(e => e.payerId !== id && !e.participantIds.includes(id))
    });
  };

  const addExpense = (newExp: Omit<Expense, 'id'>) => {
    if (!activeEvent) return;
    updateActiveEvent({
      expenses: [{ ...newExp, id: crypto.randomUUID() }, ...activeEvent.expenses]
    });
  };

  const removeExpense = (id: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      expenses: activeEvent.expenses.filter(e => e.id !== id)
    });
    if (selectedExpense?.id === id) setSelectedExpense(null);
  };

  const handleSettle = (fromId: string, toId: string, amount: number) => {
    if (!activeEvent) return;
    const fromP = activeEvent.participants.find(p => p.id === fromId)?.name;
    const toP = activeEvent.participants.find(p => p.id === toId)?.name;
    addExpense({
      description: `Settlement: ${fromP} paid ${toP}`,
      amount: amount, payerId: fromId, participantIds: [toId], category: 'Payment', date: Date.now()
    });
  };

  // Save Logic: Save to Supabase trips table
  const handleShareToSupabase = async () => {
    if (!shareEventId || !events[shareEventId]) return;

    setShareStatus('saving');
    const sb = getSupabase();
    if (!sb) {
      setShareStatus('error');
      console.error("Supabase client not initialized. Check URL/Key.");
      return;
    }

    const targetEvent = events[shareEventId];
    // Use the event's own ID if it's 6 chars, or generate a new one
    const shortId = targetEvent.id.length === 6 ? targetEvent.id : generateShortId();

    try {
      const { error } = await sb
        .from('trips')
        .upsert([{ 
          id: shortId,
          trip_data: targetEvent,
          name: targetEvent.name 
        }]);

      if (error) throw error;

      const shortUrl = `https://splitits.in/#/trip/${shortId}`;
      setGeneratedShortUrl(shortUrl);
      setShareStatus('idle');
    } catch (err) {
      console.error("Supabase Sync Error:", err);
      setShareStatus('error');
    }
  };

  const openShareModal = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setShareEventId(id);
    setGeneratedShortUrl(null);
    setShareStatus('idle');
    setShowShareModal(true);
  };

  const handleShareWhatsApp = () => {
    if (!generatedShortUrl || !shareEventId) return;
    const ev = events[shareEventId];
    const settlementText = settlements.length === 0 
      ? "All clear! No pending payments. ✅" 
      : settlements.map(s => {
          const fromName = ev.participants.find(p => p.id === s.from)?.name;
          const toName = ev.participants.find(p => p.id === s.to)?.name;
          return `💸 *${fromName}* owes *${toName}*: ₹${s.amount.toFixed(2)}`;
        }).join('\n');

    const text = `💰 *SplitIt: ${ev.name}*\n\n*Current Settlements:*\n${settlementText}\n\n🔗 Open trip and settle:\n${generatedShortUrl}\n\nNo more awkward money talks! SplitIt handles it all for you.\nTry it Now: splitits.in`;

    window.open(`https://api.whatsapp.com/send?text=${encodeURIComponent(text)}`, '_blank');
  };

  const handleCopyLink = () => {
    if (!generatedShortUrl) return;
    navigator.clipboard.writeText(generatedShortUrl).then(() => {
      setShareStatus('copied');
      setTimeout(() => setShareStatus('idle'), 2000);
    });
  };

  if (!isInitialized || isLoadingShared) {
    return (
      <div className="min-h-screen bg-[#f8fafc] flex flex-col items-center justify-center font-sans">
        <div className="w-12 h-12 border-4 border-slate-100 border-t-[#4f46e5] rounded-full animate-spin mb-4"></div>
        <p className="text-xs font-bold text-slate-400 uppercase tracking-widest animate-pulse">
          {isLoadingShared ? 'Fetching shared trip...' : 'Initializing SplitIt...'}
        </p>
      </div>
    );
  }

  if (!currentEventId) {
    return (
      <div className="min-h-screen bg-[#f8fafc] flex flex-col font-sans">
        <header className="bg-white border-b border-slate-100 p-6 sm:p-8 flex items-center justify-between">
          <div className="flex items-center gap-3">
             <div className="w-10 h-10 bg-[#4f46e5] rounded-xl flex items-center justify-center text-white text-2xl shadow-lg shadow-indigo-100 transition-transform hover:rotate-6">
               <i className="fa-solid fa-money-bill-transfer"></i>
             </div>
             <h1 className="text-2xl font-black text-slate-800 tracking-tight">SplitIt</h1>
          </div>
        </header>

        <main className="flex-1 max-w-5xl mx-auto w-full px-4 py-8 sm:py-20 space-y-12 animate-in fade-in duration-700">
          <section className="bg-white rounded-[3rem] p-8 sm:p-16 shadow-2xl shadow-indigo-100/40 border border-slate-50 text-center space-y-10">
            <div className="space-y-4">
              <h2 className="text-4xl sm:text-5xl font-black text-slate-800 tracking-tight leading-tight">Split expenses, <br/><span className="text-[#4f46e5]">keep the friendship.</span></h2>
              <p className="text-slate-400 font-medium text-lg max-w-lg mx-auto">Toss your paper receipts. splitIt tracks everything so you don't have to.</p>
            </div>

            <form onSubmit={createEvent} className="max-w-md mx-auto relative group">
              <input 
                type="text" 
                value={newEventName}
                onChange={e => setNewEventName(e.target.value)}
                placeholder="Name your adventure (e.g. Goa 2024)"
                className="w-full px-8 py-5 rounded-[2rem] bg-slate-50 border-2 border-transparent focus:border-[#4f46e5] focus:bg-white text-lg font-bold transition-all outline-none pr-36 shadow-inner"
              />
              <button 
                type="submit"
                className="absolute right-2 top-2 bottom-2 bg-[#4f46e5] text-white px-8 rounded-[1.5rem] font-black text-sm hover:bg-[#4338ca] transition-all shadow-lg active:scale-95"
              >
                CREATE
              </button>
            </form>
          </section>

          {Object.keys(events).length > 0 && (
            <section className="space-y-6">
              <div className="flex items-center justify-between px-2">
                <h3 className="text-xs font-black text-slate-400 uppercase tracking-[0.2em]">Recent Groups</h3>
                <span className="text-xs font-bold text-[#4f46e5] bg-[#eef2ff] px-3 py-1 rounded-full">{Object.keys(events).length} Sessions</span>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
                {(Object.values(events) as SplitEvent[]).sort((a, b) => b.createdAt - a.createdAt).map((ev) => {
                  const evTotal = ev.expenses.reduce((acc, curr) => curr.category !== 'Payment' ? acc + curr.amount : acc, 0);
                  return (
                    <div 
                      key={ev.id}
                      onClick={() => setCurrentEventId(ev.id)}
                      className="group bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-sm hover:shadow-2xl hover:border-[#4f46e5]/20 transition-all cursor-pointer flex flex-col justify-between min-h-[240px]"
                    >
                      <div className="space-y-4">
                        <div className="flex justify-between items-start">
                          <div className="w-12 h-12 bg-[#eef2ff] text-[#4f46e5] rounded-2xl flex items-center justify-center text-xl font-black group-hover:bg-[#4f46e5] group-hover:text-white transition-all duration-300">
                            {ev.name.charAt(0)}
                          </div>
                          <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                            <button onClick={(e) => openShareModal(e, ev.id)} className="w-9 h-9 rounded-xl bg-slate-50 text-slate-400 hover:text-[#4f46e5] flex items-center justify-center transition-all border border-transparent hover:border-slate-100"><i className="fa-solid fa-share-nodes text-xs"></i></button>
                            <button onClick={(e) => { e.stopPropagation(); deleteEvent(ev.id); }} className="w-9 h-9 rounded-xl bg-slate-50 text-slate-400 hover:text-red-500 flex items-center justify-center transition-all border border-transparent hover:border-slate-100"><i className="fa-solid fa-trash-can text-xs"></i></button>
                          </div>
                        </div>
                        <div>
                          <h4 className="text-xl font-black text-slate-800 line-clamp-1 group-hover:text-[#4f46e5] transition-colors">{ev.name}</h4>
                          <p className="text-[10px] font-bold text-slate-400 uppercase mt-1 tracking-wider">{ev.participants.length} Members • {ev.expenses.length} Records</p>
                        </div>
                      </div>
                      <div className="pt-5 border-t border-slate-50 flex items-end justify-between">
                         <div>
                            <span className="block text-[8px] font-black text-slate-300 uppercase tracking-widest mb-1">Total Spent</span>
                            <span className="text-2xl font-black text-slate-800">₹{evTotal.toFixed(0)}</span>
                         </div>
                         <div className="w-10 h-10 rounded-full border border-slate-100 flex items-center justify-center text-slate-300 group-hover:text-[#4f46e5] group-hover:border-[#4f46e5] transition-all">
                           <i className="fa-solid fa-chevron-right text-xs"></i>
                         </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            </section>
          )}
        </main>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#f8fafc] text-slate-900 flex flex-col font-sans overflow-x-hidden">
      <header className="bg-white border-b border-slate-100 sticky top-0 z-30 shadow-sm px-4">
        <div className="max-w-7xl mx-auto h-20 flex items-center justify-between gap-4">
          <div className="flex items-center gap-4 min-w-0">
            <button 
              onClick={() => setCurrentEventId(null)}
              className="w-10 h-10 rounded-xl hover:bg-slate-50 flex items-center justify-center text-slate-400 hover:text-slate-800 transition-all border border-transparent hover:border-slate-100"
            >
              <i className="fa-solid fa-arrow-left"></i>
            </button>
            <div className="flex flex-col min-w-0">
              <h1 className="text-lg font-black text-[#1e293b] truncate uppercase tracking-tight">{activeEvent.name}</h1>
              <div className="flex items-center gap-1.5">
                <div className="w-1.5 h-1.5 rounded-full bg-green-500"></div>
                <p className="text-[9px] font-black text-slate-400 tracking-[0.1em] uppercase">Cloud Sync Active</p>
              </div>
            </div>
          </div>
          <nav className="flex bg-[#f1f5f9] p-1.5 rounded-2xl shrink-0">
            <button onClick={() => setActiveTab('expenses')} className={`px-5 py-2.5 rounded-xl text-xs font-bold uppercase tracking-wider transition-all ${activeTab === 'expenses' ? 'bg-white text-[#4f46e5] shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Activity</button>
            <button onClick={() => setActiveTab('settlement')} className={`px-5 py-2.5 rounded-xl text-xs font-bold uppercase tracking-wider transition-all ${activeTab === 'settlement' ? 'bg-white text-[#4f46e5] shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Settlement</button>
          </nav>
        </div>
      </header>

      <main className="flex-1 max-w-7xl mx-auto w-full px-4 sm:px-6 py-6 sm:py-10 space-y-8 animate-in fade-in slide-in-from-bottom-2 duration-500">
        <div className="flex flex-col sm:flex-row items-center justify-between bg-white px-8 py-6 rounded-[2.5rem] border border-slate-100 shadow-xl shadow-slate-100/50 gap-6">
          <div className="flex gap-12 text-center sm:text-left">
            <div>
              <span className="text-[9px] font-black text-slate-400 uppercase block mb-1 tracking-widest">Aggregate Spent</span>
              <p className="text-3xl font-black text-slate-800">₹{totalSpent.toFixed(0)}</p>
            </div>
            <div>
              <span className="text-[9px] font-black text-slate-400 uppercase block mb-1 tracking-widest">The Squad</span>
              <p className="text-3xl font-black text-slate-800">{activeEvent.participants.length}</p>
            </div>
          </div>
          <button 
            onClick={(e) => openShareModal(e, activeEvent.id)}
            className="w-full sm:w-auto flex items-center justify-center gap-3 px-10 py-5 rounded-2xl text-xs font-black uppercase tracking-widest transition-all bg-[#4f46e5] text-white hover:bg-[#4338ca] shadow-xl shadow-indigo-200 active:scale-[0.97]"
          >
            <i className="fa-solid fa-cloud-arrow-up"></i>
            Cloud Sync & Share
          </button>
        </div>

        {activeTab === 'expenses' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
            <div className="lg:col-span-3">
              <ParticipantManager participants={activeEvent.participants} onAdd={addParticipant} onRemove={removeParticipant} />
            </div>
            <div className="lg:col-span-5 space-y-6">
              <div className="flex justify-between items-center px-2">
                <h2 className="text-xs font-black uppercase tracking-[0.2em] text-slate-400 flex items-center gap-2">
                  <i className="fa-solid fa-list-check"></i>
                  Recent Transactions
                </h2>
              </div>
              <div className="min-h-[400px] bg-white border border-slate-100 rounded-[2rem] p-4 overflow-y-auto max-h-[650px] scrollbar-hide shadow-sm">
                {activeEvent.expenses.length === 0 ? (
                  <div className="h-full flex flex-col items-center justify-center text-center text-slate-300 py-24 gap-4">
                    <div className="w-16 h-16 rounded-full bg-slate-50 flex items-center justify-center"><i className="fa-solid fa-receipt text-2xl"></i></div>
                    <p className="text-xs font-bold uppercase tracking-widest">No activity recorded yet</p>
                  </div>
                ) : (
                  activeEvent.expenses.sort((a,b) => b.date - a.date).map(e => (
                    <div 
                      key={e.id} 
                      onClick={() => setSelectedExpense(e)} 
                      className={`p-5 mb-4 rounded-2xl border transition-all cursor-pointer group ${e.category === 'Payment' ? 'bg-slate-50/50 border-slate-100 border-dashed' : 'bg-white border-slate-50 hover:border-[#4f46e5] hover:shadow-lg hover:shadow-indigo-50'}`}
                    >
                      <div className="flex justify-between items-center">
                        <div className="min-w-0 flex items-center gap-4">
                          <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-lg ${e.category === 'Payment' ? 'text-green-500 bg-green-50' : 'text-slate-400 bg-slate-50'}`}>
                             <i className={`fa-solid ${e.category === 'Payment' ? 'fa-hand-holding-dollar' : 'fa-receipt'}`}></i>
                          </div>
                          <div className="min-w-0">
                            <p className="font-black text-slate-800 truncate group-hover:text-[#4f46e5] transition-colors">{e.description}</p>
                            <p className="text-[9px] text-slate-400 font-bold uppercase mt-0.5">
                              <span className="text-slate-600">{activeEvent.participants.find(p=>p.id===e.payerId)?.name}</span> paid • {new Date(e.date).toLocaleDateString()}
                            </p>
                          </div>
                        </div>
                        <div className="text-right shrink-0">
                          <p className="font-black text-slate-800 text-lg">₹{e.amount.toFixed(0)}</p>
                        </div>
                      </div>
                    </div>
                  ))
                )}
              </div>
            </div>
            <div className="lg:col-span-4">
              <ExpenseForm participants={activeEvent.participants} onAdd={addExpense} />
            </div>
          </div>
        ) : (
          <SettlementView participants={activeEvent.participants} balances={balances} settlements={settlements} totalSpent={totalSpent} onSettle={handleSettle} />
        )}
      </main>

      {showShareModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md animate-in fade-in duration-300">
          <div className="bg-white rounded-[3rem] max-w-sm w-full shadow-2xl animate-in zoom-in-95 duration-200 overflow-hidden">
            <div className="p-10 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
              <div>
                <h3 className="text-2xl font-black text-slate-800 tracking-tight">Cloud Sync</h3>
              </div>
              <button 
                onClick={() => setShowShareModal(false)} 
                className="w-10 h-10 rounded-full hover:bg-white flex items-center justify-center text-slate-300 hover:text-slate-600 transition-all border border-transparent hover:border-slate-100"
              >
                <i className="fa-solid fa-xmark text-lg"></i>
              </button>
            </div>
            <div className="p-10 space-y-8">
              {shareStatus === 'saving' ? (
                <div className="flex flex-col items-center justify-center py-12 gap-6">
                  <div className="w-16 h-16 border-[6px] border-slate-100 border-t-[#4f46e5] rounded-full animate-spin"></div>
                  <p className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] animate-pulse">Pushing to Cloud...</p>
                </div>
              ) : generatedShortUrl ? (
                <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
                  <div className="p-6 bg-slate-50 rounded-[2rem] border border-slate-100 text-center relative overflow-hidden group">
                    <p className="text-sm font-bold text-[#4f46e5] truncate">{generatedShortUrl}</p>
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <button onClick={handleShareWhatsApp} className="flex flex-col items-center gap-3 p-6 rounded-[2rem] bg-green-50 hover:bg-green-100 transition-all border border-green-100 group">
                      <div className="w-14 h-14 bg-green-500 rounded-2xl flex items-center justify-center text-white shadow-lg"><i className="fa-brands fa-whatsapp text-2xl"></i></div>
                      <span className="text-[10px] font-black text-green-700 uppercase tracking-widest">WhatsApp</span>
                    </button>
                    <button onClick={handleCopyLink} className={`flex flex-col items-center gap-3 p-6 rounded-[2rem] transition-all border group ${shareStatus === 'copied' ? 'bg-green-100 border-green-200' : 'bg-slate-50 border-slate-100'}`}>
                      <div className={`w-14 h-14 rounded-2xl flex items-center justify-center text-white shadow-lg ${shareStatus === 'copied' ? 'bg-green-600' : 'bg-slate-800'}`}>
                        <i className={`fa-solid ${shareStatus === 'copied' ? 'fa-check' : 'fa-link'} text-xl`}></i>
                      </div>
                      <span className="text-[10px] font-black text-slate-700 uppercase tracking-widest">{shareStatus === 'copied' ? 'Success' : 'Copy'}</span>
                    </button>
                  </div>
                </div>
              ) : (
                <button 
                  onClick={handleShareToSupabase}
                  className="w-full bg-[#4f46e5] text-white py-6 rounded-2xl font-black text-xs uppercase tracking-widest shadow-2xl hover:bg-[#4338ca] transition-all"
                >
                  Generate Link
                </button>
              )}
              {shareStatus === 'error' && (
                <div className="p-4 bg-red-50 rounded-xl border border-red-100 text-center">
                  <p className="text-[10px] text-red-500 font-black uppercase tracking-widest leading-relaxed">Failed to connect to Supabase. Please ensure the 'trips' table exists and RLS allows inserts.</p>
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {selectedExpense && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-md">
          <div className="bg-white rounded-[2.5rem] max-w-lg w-full overflow-hidden shadow-2xl p-10 space-y-8 animate-in zoom-in-95">
            <div className="flex justify-between items-center">
               <h3 className="text-2xl font-black text-slate-800">Transaction Info</h3>
               <button onClick={() => setSelectedExpense(null)} className="w-8 h-8 rounded-full bg-slate-50 flex items-center justify-center text-slate-400 hover:text-slate-800"><i className="fa-solid fa-xmark"></i></button>
            </div>
            <div className="space-y-6">
              <div className="flex justify-between items-center pb-6 border-b border-slate-50">
                <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Label</span>
                <span className="font-black text-xl text-slate-800">{selectedExpense.description}</span>
              </div>
              <div className="flex justify-between items-center pb-6 border-b border-slate-50">
                <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Value</span>
                <span className="font-black text-3xl text-[#4f46e5]">₹{selectedExpense.amount.toFixed(2)}</span>
              </div>
            </div>
            <button 
              onClick={() => removeExpense(selectedExpense.id)} 
              className="w-full py-5 bg-red-50 text-red-500 font-black text-xs uppercase tracking-widest rounded-2xl hover:bg-red-100 transition-all border border-red-100"
            >
              <i className="fa-solid fa-trash-can mr-2"></i>
              Void Record
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { createClient, SupabaseClient } from '@supabase/supabase-js';
import { Participant, Expense, Settlement, Balance, SplitEvent } from './types.ts';
import ParticipantManager from './components/ParticipantManager.tsx';
import ExpenseForm from './components/ExpenseForm.tsx';
import SettlementView from './components/SettlementView.tsx';
import { calculateBalances, calculateSettlements } from './utils/calculation.ts';

// Helper to generate a 6-character random ID for short URLs and unique event strings
const generateShortId = () => {
  const chars = 'abcdefghijklmnopqrstuvwxyz0123456789';
  let result = '';
  for (let i = 0; i < 6; i++) {
    result += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return result;
};

// Initialize Supabase client safely
const getSupabase = () => {
  const url = window.process.env.SUPABASE_URL || 'https://yrlvjtnxusbgqeqgaonu.supabase.co';
  const key = window.process.env.SUPABASE_ANON_KEY || 'sb_publishable_bFgmsQkkShvZYtyLf7ASEA_I1J6Y3zw';
  if (!url || !key) return null;
  return createClient(url, key);
};

const App: React.FC = () => {
  const [events, setEvents] = useState<Record<string, SplitEvent>>({});
  const [currentEventId, setCurrentEventId] = useState<string | null>(null);
  const [newEventName, setNewEventName] = useState('');

  // App states
  const [activeTab, setActiveTab] = useState<'expenses' | 'settlement'>('expenses');
  const [selectedExpense, setSelectedExpense] = useState<Expense | null>(null);
  const [shareStatus, setShareStatus] = useState<'idle' | 'saving' | 'copied' | 'error'>('idle');
  const [showShareModal, setShowShareModal] = useState(false);
  const [shareEventId, setShareEventId] = useState<string | null>(null);
  const [generatedShortUrl, setGeneratedShortUrl] = useState<string | null>(null);
  const [isInitialized, setIsInitialized] = useState(false);
  const [isLoadingShared, setIsLoadingShared] = useState(false);

  const getAvatar = (name: string) => `https://api.dicebear.com/7.x/initials/svg?seed=${name}&backgroundColor=4f46e5&textColor=ffffff`;

  // Fetch Logic: Check for short trip ID in hash
  useEffect(() => {
    const loadInitialData = async () => {
      const savedEvents = localStorage.getItem('splitit_multi_events');
      let currentEvents: Record<string, SplitEvent> = savedEvents ? JSON.parse(savedEvents) : {};

      const hash = window.location.hash;
      const shortIdMatch = hash.match(/#\/?trip\/([a-z0-9]{6})$/i);
      const sb = getSupabase();

      if (shortIdMatch && shortIdMatch[1] && sb) {
        const tripSlug = shortIdMatch[1];
        setIsLoadingShared(true);
        try {
          const { data, error } = await sb
            .from('trips')
            .select('trip_data')
            .eq('id', tripSlug)
            .single();

          if (!error && data?.trip_data) {
            const fetchedEvent = data.trip_data as SplitEvent;
            const localId = fetchedEvent.id || tripSlug;
            currentEvents[localId] = fetchedEvent;
            setCurrentEventId(localId);
            window.history.replaceState(null, "", window.location.pathname);
          }
        } catch (err) {
          console.error("Supabase fetch error:", err);
        } finally {
          setIsLoadingShared(false);
        }
      }

      setEvents(currentEvents);
      setIsInitialized(true);
    };

    loadInitialData();
  }, []);

  useEffect(() => {
    if (isInitialized) {
      localStorage.setItem('splitit_multi_events', JSON.stringify(events));
    }
  }, [events, isInitialized]);

  const activeEvent = currentEventId ? events[currentEventId] : null;

  const { balances, settlements, totalSpent } = useMemo(() => {
    if (!activeEvent) return { balances: [], settlements: [], totalSpent: 0 };
    const bals = calculateBalances(activeEvent.participants, activeEvent.expenses);
    const setts = calculateSettlements([...bals]);
    const total = activeEvent.expenses.reduce((acc, curr) => curr.category !== 'Payment' ? acc + curr.amount : acc, 0);
    return { balances: bals, settlements: setts, totalSpent: total };
  }, [activeEvent]);

  const createEvent = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newEventName.trim()) return;
    const id = generateShortId();
    const newEv: SplitEvent = {
      id,
      name: newEventName.trim(),
      participants: [],
      expenses: [],
      createdAt: Date.now()
    };
    setEvents(prev => ({ ...prev, [id]: newEv }));
    setNewEventName('');
    setCurrentEventId(id);
  };

  const deleteEvent = (id: string) => {
    if (window.confirm("Permanently delete this group?")) {
      const newEvents = { ...events };
      delete newEvents[id];
      setEvents(newEvents);
      if (currentEventId === id) setCurrentEventId(null);
    }
  };

  const updateActiveEvent = (updates: Partial<SplitEvent>) => {
    if (!currentEventId) return;
    setEvents(prev => ({
      ...prev,
      [currentEventId]: { ...prev[currentEventId], ...updates }
    }));
  };

  const addParticipant = (name: string, upiId?: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      participants: [...activeEvent.participants, { id: crypto.randomUUID(), name, avatar: getAvatar(name), upiId }]
    });
  };

  const removeParticipant = (id: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      participants: activeEvent.participants.filter(p => p.id !== id),
      expenses: activeEvent.expenses.filter(e => e.payerId !== id && !e.participantIds.includes(id))
    });
  };

  const addExpense = (newExp: Omit<Expense, 'id'>) => {
    if (!activeEvent) return;
    updateActiveEvent({
      expenses: [{ ...newExp, id: crypto.randomUUID() }, ...activeEvent.expenses]
    });
  };

  const removeExpense = (id: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      expenses: activeEvent.expenses.filter(e => e.id !== id)
    });
    if (selectedExpense?.id === id) setSelectedExpense(null);
  };

  const handleSettle = (fromId: string, toId: string, amount: number) => {
    if (!activeEvent) return;
    const fromP = activeEvent.participants.find(p => p.id === fromId)?.name;
    const toP = activeEvent.participants.find(p => p.id === toId)?.name;
    addExpense({
      description: `Settlement: ${fromP} paid ${toP}`,
      amount: amount, payerId: fromId, participantIds: [toId], category: 'Payment', date: Date.now()
    });
  };

  const handleShareToSupabase = async () => {
    if (!shareEventId || !events[shareEventId]) return;

    setShareStatus('saving');
    const sb = getSupabase();
    if (!sb) {
      setShareStatus('error');
      return;
    }

    const targetEvent = events[shareEventId];
    const shortId = targetEvent.id;

    try {
      const { error } = await sb
        .from('trips')
        .upsert([{ 
          id: shortId,
          trip_data: targetEvent,
          name: targetEvent.name 
        }]);

      if (error) throw error;

      const shortUrl = `${window.location.origin}/#/trip/${shortId}`;
      setGeneratedShortUrl(shortUrl);
      setShareStatus('idle');
    } catch (err) {
      console.error("Supabase Sync Error:", err);
      setShareStatus('error');
    }
  };

  const openShareModal = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setShareEventId(id);
    setGeneratedShortUrl(null);
    setShareStatus('idle');
    setShowShareModal(true);
  };

  const getWhatsAppText = () => {
    if (!activeEvent) return '';
    const settlementText = settlements.length === 0 
      ? "All clear! No pending payments. ✅" 
      : settlements.map(s => {
          const fromName = activeEvent.participants.find(p => p.id === s.from)?.name;
          const toName = activeEvent.participants.find(p => p.id === s.to)?.name;
          return `💸 *${fromName}* owes *${toName}*: ₹${s.amount.toFixed(2)}`;
        }).join('\n');

    return `💰 *SplitIt: ${activeEvent.name}*\n\n*Current Settlements:*\n${settlementText}\n\n🔗 Open trip and settle:\n${generatedShortUrl}\n\nNo more awkward money talks! SplitIt handles it all for you.\nTry it Now: splitits.in`;
  };

  const handleShareWhatsApp = () => {
    window.open(`https://api.whatsapp.com/send?text=${encodeURIComponent(getWhatsAppText())}`, '_blank');
  };

  const handleShareGmail = () => {
    const subject = `Expense Split for ${activeEvent?.name}`;
    window.open(`mailto:?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(getWhatsAppText())}`, '_blank');
  };

  const handleShareArattai = () => {
    // Arattai typically uses navigator.share or a web link if supported. 
    // Since there's no public URL scheme for desktop/web Arattai API commonly used, 
    // we use navigator.share as a modern mobile-first fallback.
    if (navigator.share) {
      navigator.share({
        title: `SplitIt: ${activeEvent?.name}`,
        text: getWhatsAppText(),
        url: generatedShortUrl || ''
      }).catch(console.error);
    } else {
      alert("Sharing to Arattai is best supported on mobile devices. Please copy the link instead.");
    }
  };

  const handleCopyLink = () => {
    if (!generatedShortUrl) return;
    navigator.clipboard.writeText(generatedShortUrl).then(() => {
      setShareStatus('copied');
      setTimeout(() => setShareStatus('idle'), 2000);
    });
  };

  if (!isInitialized || isLoadingShared) {
    return (
      <div className="min-h-screen bg-[#f8fafc] flex flex-col items-center justify-center font-sans">
        <div className="w-12 h-12 border-4 border-slate-100 border-t-[#4f46e5] rounded-full animate-spin mb-4"></div>
        <p className="text-xs font-bold text-slate-400 uppercase tracking-widest animate-pulse">Fetching Trip...</p>
      </div>
    );
  }

  // Dashboard
  if (!currentEventId) {
    return (
      <div className="min-h-screen bg-[#f8fafc] flex flex-col font-sans">
        <header className="bg-white border-b border-slate-100 p-6 sm:p-8 text-center sm:text-left">
          <div className="flex flex-col sm:flex-row items-center gap-3 sm:gap-4">
             <div className="w-12 h-12 bg-[#4f46e5] rounded-2xl flex items-center justify-center text-white text-3xl shadow-lg shadow-indigo-100"><i className="fa-solid fa-receipt"></i></div>
             <div className="flex flex-col">
               <h1 className="text-3xl font-black text-slate-900 tracking-tighter">SplitIt</h1>
               <p className="text-xs font-medium text-slate-400 -mt-1">No more awkward money talks!</p>
             </div>
          </div>
        </header>

        <main className="flex-1 max-w-5xl mx-auto w-full px-4 py-10 sm:py-20 space-y-12">
          <section className="bg-white rounded-[2.5rem] p-8 sm:p-16 shadow-2xl shadow-indigo-100/40 border border-slate-50 text-center space-y-10">
            <h2 className="text-4xl sm:text-5xl font-black text-slate-900 tracking-tight leading-tight">Start an event</h2>
            <form onSubmit={createEvent} className="max-w-md mx-auto flex flex-col gap-4">
              <input 
                type="text" 
                value={newEventName}
                onChange={e => setNewEventName(e.target.value)}
                placeholder="Event Name (e.g. Goa Trip)"
                className="w-full px-8 py-5 rounded-3xl bg-slate-50 border-2 border-transparent focus:border-[#4f46e5] focus:bg-white text-lg font-bold transition-all outline-none shadow-inner"
              />
              <button type="submit" className="bg-[#4f46e5] text-white py-5 rounded-3xl font-black text-sm hover:bg-[#4338ca] transition-all shadow-xl active:scale-95">CREATE AN EVENT</button>
            </form>
          </section>

          {Object.keys(events).length > 0 && (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
              {(Object.values(events) as SplitEvent[]).sort((a,b)=>b.createdAt-a.createdAt).map(ev => (
                <div key={ev.id} onClick={()=>setCurrentEventId(ev.id)} className="bg-white p-6 rounded-[2rem] border border-slate-100 hover:shadow-xl transition-all cursor-pointer group">
                  <div className="flex justify-between items-start mb-4">
                    <div className="w-12 h-12 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center font-black">{ev.name.charAt(0)}</div>
                    <button onClick={(e)=>{e.stopPropagation(); deleteEvent(ev.id)}} className="text-slate-200 hover:text-red-500 transition-colors p-2"><i className="fa-solid fa-trash-can"></i></button>
                  </div>
                  <h4 className="text-xl font-black text-slate-800 line-clamp-1">{ev.name}</h4>
