// Helper to generate a 6-character random ID for short URLs and unique event strings
const generateShortId = () => {
  const chars = 'abcdefghijklmnopqrstuvwxyz0123456789';
  let result = '';
  for (let i = 0; i < 6; i++) {
    result += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return result;
};

// Initialize Supabase client safely
const getSupabase = () => {
  // Fix: Property 'process' does not exist on type 'Window'. Accessing process.env directly.
  const url = process.env.SUPABASE_URL || 'https://yrlvjtnxusbgqeqgaonu.supabase.co';
  // Fix: Property 'process' does not exist on type 'Window'. Accessing process.env directly.
  const key = process.env.SUPABASE_ANON_KEY || 'sb_publishable_bFgmsQkkShvZYtyLf7ASEA_I1J6Y3zw';
  if (!url || !key) return null;
  return createClient(url, key);
};

const App: React.FC = () => {
  const [events, setEvents] = useState<Record<string, SplitEvent>>({});
  const [currentEventId, setCurrentEventId] = useState<string | null>(null);
  const [newEventName, setNewEventName] = useState('');

  // App states
  const [activeTab, setActiveTab] = useState<'expenses' | 'settlement'>('expenses');
  const [selectedExpense, setSelectedExpense] = useState<Expense | null>(null);
  const [shareStatus, setShareStatus] = useState<'idle' | 'saving' | 'copied' | 'error'>('idle');
  const [showShareModal, setShowShareModal] = useState(false);
  const [shareEventId, setShareEventId] = useState<string | null>(null);
  const [generatedShortUrl, setGeneratedShortUrl] = useState<string | null>(null);
  const [isInitialized, setIsInitialized] = useState(false);
  const [isLoadingShared, setIsLoadingShared] = useState(false);

  const getAvatar = (name: string) => `https://api.dicebear.com/7.x/initials/svg?seed=${name}&backgroundColor=4f46e5&textColor=ffffff`;

  // Fetch Logic: Check for short trip ID in hash
  useEffect(() => {
    const loadInitialData = async () => {
      const savedEvents = localStorage.getItem('splitit_multi_events');
      let currentEvents: Record<string, SplitEvent> = savedEvents ? JSON.parse(savedEvents) : {};

      const hash = window.location.hash;
      const shortIdMatch = hash.match(/#\/?trip\/([a-z0-9]{6})$/i);
      const sb = getSupabase();

      if (shortIdMatch && shortIdMatch[1] && sb) {
        const tripSlug = shortIdMatch[1];
        setIsLoadingShared(true);
        try {
          const { data, error } = await sb
            .from('trips')
            .select('trip_data')
            .eq('id', tripSlug)
            .single();

          if (!error && data?.trip_data) {
            const fetchedEvent = data.trip_data as SplitEvent;
            const localId = fetchedEvent.id || tripSlug;
            currentEvents[localId] = fetchedEvent;
            setCurrentEventId(localId);
            window.history.replaceState(null, "", window.location.pathname);
          }
        } catch (err) {
          console.error("Supabase fetch error:", err);
        } finally {
          setIsLoadingShared(false);
        }
      }

      setEvents(currentEvents);
      setIsInitialized(true);
    };

    loadInitialData();
  }, []);

  useEffect(() => {
    if (isInitialized) {
      localStorage.setItem('splitit_multi_events', JSON.stringify(events));
    }
  }, [events, isInitialized]);

  const activeEvent = currentEventId ? events[currentEventId] : null;

  const { balances, settlements, totalSpent } = useMemo(() => {
    if (!activeEvent) return { balances: [], settlements: [], totalSpent: 0 };
    const bals = calculateBalances(activeEvent.participants, activeEvent.expenses);
    const setts = calculateSettlements([...bals]);
    const total = activeEvent.expenses.reduce((acc, curr) => curr.category !== 'Payment' ? acc + curr.amount : acc, 0);
    return { balances: bals, settlements: setts, totalSpent: total };
  }, [activeEvent]);

  const createEvent = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newEventName.trim()) return;
    const id = generateShortId();
    const newEv: SplitEvent = {
      id,
      name: newEventName.trim(),
      participants: [],
      expenses: [],
      createdAt: Date.now()
    };
    setEvents(prev => ({ ...prev, [id]: newEv }));
    setNewEventName('');
    setCurrentEventId(id);
  };

  const deleteEvent = (id: string) => {
    if (window.confirm("Permanently delete this group?")) {
      const newEvents = { ...events };
      delete newEvents[id];
      setEvents(newEvents);
      if (currentEventId === id) setCurrentEventId(null);
    }
  };

  const updateActiveEvent = (updates: Partial<SplitEvent>) => {
    if (!currentEventId) return;
    setEvents(prev => ({
      ...prev,
      [currentEventId]: { ...prev[currentEventId], ...updates }
    }));
  };

  const addParticipant = (name: string, upiId?: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      participants: [...activeEvent.participants, { id: crypto.randomUUID(), name, avatar: getAvatar(name), upiId }]
    });
  };

  const removeParticipant = (id: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      participants: activeEvent.participants.filter(p => p.id !== id),
      expenses: activeEvent.expenses.filter(e => e.payerId !== id && !e.participantIds.includes(id))
    });
  };

  const addExpense = (newExp: Omit<Expense, 'id'>) => {
    if (!activeEvent) return;
    updateActiveEvent({
      expenses: [{ ...newExp, id: crypto.randomUUID() }, ...activeEvent.expenses]
    });
  };

  const removeExpense = (id: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      expenses: activeEvent.expenses.filter(e => e.id !== id)
    });
    if (selectedExpense?.id === id) setSelectedExpense(null);
  };

  const handleSettle = (fromId: string, toId: string, amount: number) => {
    if (!activeEvent) return;
    const fromP = activeEvent.participants.find(p => p.id === fromId)?.name;
    const toP = activeEvent.participants.find(p => p.id === toId)?.name;
    addExpense({
      description: `Settlement: ${fromP} paid ${toP}`,
      amount: amount, payerId: fromId, participantIds: [toId], category: 'Payment', date: Date.now()
    });
  };

  const handleShareToSupabase = async () => {
    if (!shareEventId || !events[shareEventId]) return;

    setShareStatus('saving');
    const sb = getSupabase();
    if (!sb) {
      setShareStatus('error');
      return;
    }

    const targetEvent = events[shareEventId];
    const shortId = targetEvent.id;

    try {
      const { error } = await sb
        .from('trips')
        .upsert([{ 
          id: shortId,
          trip_data: targetEvent,
          name: targetEvent.name 
        }]);

      if (error) throw error;

      const shortUrl = `${window.location.origin}/#/trip/${shortId}`;
      setGeneratedShortUrl(shortUrl);
      setShareStatus('idle');
    } catch (err) {
      console.error("Supabase Sync Error:", err);
      setShareStatus('error');
    }
  };

  const openShareModal = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setShareEventId(id);
    setGeneratedShortUrl(null);
    setShareStatus('idle');
    setShowShareModal(true);
  };

  const getWhatsAppText = () => {
    if (!activeEvent) return '';
    const settlementText = settlements.length === 0 
      ? "All clear! No pending payments. ✅" 
      : settlements.map(s => {
          const fromName = activeEvent.participants.find(p => p.id === s.from)?.name;
          const toName = activeEvent.participants.find(p => p.id === s.to)?.name;
          return `💸 *${fromName}* owes *${toName}*: ₹${s.amount.toFixed(2)}`;
        }).join('\n');

    return `💰 *SplitIt: ${activeEvent.name}*\n\n*Current Settlements:*\n${settlementText}\n\n🔗 Open trip and settle:\n${generatedShortUrl}\n\nNo more awkward money talks! SplitIt handles it all for you.\nTry it Now: splitits.in`;
  };

  const handleShareWhatsApp = () => {
    window.open(`https://api.whatsapp.com/send?text=${encodeURIComponent(getWhatsAppText())}`, '_blank');
  };

  const handleShareGmail = () => {
    const subject = `Expense Split for ${activeEvent?.name}`;
    window.open(`mailto:?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(getWhatsAppText())}`, '_blank');
  };

  const handleShareArattai = () => {
    // Arattai typically uses navigator.share or a web link if supported. 
    // Since there's no public URL scheme for desktop/web Arattai API commonly used, 
    // we use navigator.share as a modern mobile-first fallback.
    if (navigator.share) {
      navigator.share({
        title: `SplitIt: ${activeEvent?.name}`,
        text: getWhatsAppText(),
        url: generatedShortUrl || ''
      }).catch(console.error);
    } else {
      alert("Sharing to Arattai is best supported on mobile devices. Please copy the link instead.");
    }
  };

  const handleCopyLink = () => {
    if (!generatedShortUrl) return;
    navigator.clipboard.writeText(generatedShortUrl).then(() => {
      setShareStatus('copied');
      setTimeout(() => setShareStatus('idle'), 2000);
    });
  };

  if (!isInitialized || isLoadingShared) {
    return (
      <div className="min-h-screen bg-[#f8fafc] flex flex-col items-center justify-center font-sans">
        <div className="w-12 h-12 border-4 border-slate-100 border-t-[#4f46e5] rounded-full animate-spin mb-4"></div>
        <p className="text-xs font-bold text-slate-400 uppercase tracking-widest animate-pulse">Fetching Trip...</p>
      </div>
    );
  }

  // Dashboard
  if (!currentEventId) {
    return (
      <div className="min-h-screen bg-[#f8fafc] flex flex-col font-sans">
        <header className="bg-white border-b border-slate-100 p-6 sm:p-8 text-center sm:text-left">
          <div className="flex flex-col sm:flex-row items-center gap-3 sm:gap-4">
             <div className="w-12 h-12 bg-[#4f46e5] rounded-2xl flex items-center justify-center text-white text-3xl shadow-lg shadow-indigo-100"><i className="fa-solid fa-receipt"></i></div>
             <div className="flex flex-col">
               <h1 className="text-3xl font-black text-slate-900 tracking-tighter">SplitIt</h1>
               <p className="text-xs font-medium text-slate-400 -mt-1">No more awkward money talks!</p>
             </div>
          </div>
        </header>

        <main className="flex-1 max-w-5xl mx-auto w-full px-4 py-10 sm:py-20 space-y-12">
          <section className="bg-white rounded-[2.5rem] p-8 sm:p-16 shadow-2xl shadow-indigo-100/40 border border-slate-50 text-center space-y-10">
            <h2 className="text-4xl sm:text-5xl font-black text-slate-900 tracking-tight leading-tight">Start an event</h2>
            <form onSubmit={createEvent} className="max-w-md mx-auto flex flex-col gap-4">
              <input 
                type="text" 
                value={newEventName}
                onChange={e => setNewEventName(e.target.value)}
                placeholder="Event Name (e.g. Goa Trip)"
                className="w-full px-8 py-5 rounded-3xl bg-slate-50 border-2 border-transparent focus:border-[#4f46e5] focus:bg-white text-lg font-bold transition-all outline-none shadow-inner"
              />
              <button type="submit" className="bg-[#4f46e5] text-white py-5 rounded-3xl font-black text-sm hover:bg-[#4338ca] transition-all shadow-xl active:scale-95">CREATE AN EVENT</button>
            </form>
          </section>

          {Object.keys(events).length > 0 && (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
              {(Object.values(events) as SplitEvent[]).sort((a,b)=>b.createdAt-a.createdAt).map(ev => (
                <div key={ev.id} onClick={()=>setCurrentEventId(ev.id)} className="bg-white p-6 rounded-[2rem] border border-slate-100 hover:shadow-xl transition-all cursor-pointer group">
                  <div className="flex justify-between items-start mb-4">
                    <div className="w-12 h-12 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center font-black">{ev.name.charAt(0)}</div>
                    <button onClick={(e)=>{e.stopPropagation(); deleteEvent(ev.id)}} className="text-slate-200 hover:text-red-500 transition-colors p-2"><i className="fa-solid fa-trash-can"></i></button>
                  </div>
                  <h4 className="text-xl font-black text-slate-800 line-clamp-1">{ev.name}</h4>
                  <p className="text-[10px] font-bold text-slate-400 uppercase mt-1">{ev.participants.length} Members • ₹{ev.expenses.reduce((acc,curr)=>curr.category!=='Payment'?acc+curr.amount:acc,0).toFixed(0)}</p>
                </div>
              ))}
            </div>
          )}
        </main>
      </div>
    );
  }

  // Active View
  return (
    <div className="min-h-screen bg-[#f8fafc] text-slate-900 flex flex-col font-sans">
      <header className="bg-white border-b border-slate-100 sticky top-0 z-30 shadow-sm px-4">
        <div className="max-w-7xl mx-auto h-20 flex items-center justify-between gap-4">
          <div className="flex items-center gap-4 min-w-0">
            <button onClick={()=>setCurrentEventId(null)} className="w-10 h-10 rounded-xl hover:bg-slate-50 flex items-center justify-center text-slate-400"><i className="fa-solid fa-arrow-left"></i></button>
            <div className="min-w-0">
              <h1 className="text-lg font-black text-slate-900 truncate uppercase tracking-tight">{activeEvent.name}</h1>
              <p className="text-[9px] font-bold text-slate-400 tracking-widest uppercase -mt-0.5">SplitIt Safe</p>
            </div>
          </div>
          <nav className="flex bg-slate-100 p-1 rounded-xl">
            <button onClick={()=>setActiveTab('expenses')} className={`px-4 py-2 rounded-lg text-xs font-black uppercase transition-all ${activeTab==='expenses'?'bg-white text-indigo-600 shadow-sm':'text-slate-400'}`}>Overview</button>
            <button onClick={()=>setActiveTab('settlement')} className={`px-4 py-2 rounded-lg text-xs font-black uppercase transition-all ${activeTab==='settlement'?'bg-white text-indigo-600 shadow-sm':'text-slate-400'}`}>Settlement</button>
          </nav>
        </div>
      </header>

      <main className="flex-1 max-w-7xl mx-auto w-full px-4 py-8 space-y-8 animate-in fade-in duration-500">
        <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between bg-white px-8 py-6 rounded-[2rem] border border-slate-100 shadow-lg shadow-slate-100/50 gap-6">
          <div className="flex justify-around sm:justify-start gap-12 text-center sm:text-left">
            <div><span className="text-[8px] font-black text-slate-300 uppercase block mb-1">Spent</span><p className="text-3xl font-black">₹{totalSpent.toFixed(0)}</p></div>
            <div><span className="text-[8px] font-black text-slate-300 uppercase block mb-1">Squad</span><p className="text-3xl font-black">{activeEvent.participants.length}</p></div>
          </div>
          <button onClick={(e)=>openShareModal(e, activeEvent.id)} className="bg-[#4f46e5] text-white px-8 py-4 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-[#4338ca] shadow-lg active:scale-95">SHARE WITH SQUAD</button>
        </div>

        {activeTab === 'expenses' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
            <div className="lg:col-span-3 order-2 lg:order-1"><ParticipantManager participants={activeEvent.participants} onAdd={addParticipant} onRemove={removeParticipant} /></div>
            <div className="lg:col-span-5 space-y-6 order-3 lg:order-2">
              <div className="bg-white border border-slate-100 rounded-[2rem] p-4 min-h-[400px] shadow-sm overflow-hidden">
                <h2 className="text-xs font-black uppercase tracking-widest text-slate-400 p-4 border-b border-slate-50 mb-4 flex items-center gap-2"><i className="fa-solid fa-clock-rotate-left"></i>HISTORY</h2>
                <div className="space-y-4 max-h-[600px] overflow-y-auto scrollbar-hide">
                  {activeEvent.expenses.length === 0 ? <div className="text-center py-20 text-slate-300 font-bold uppercase text-[10px]">No records found</div> : 
                    activeEvent.expenses.sort((a,b)=>b.date-a.date).map(e => (
                      <div key={e.id} onClick={()=>setSelectedExpense(e)} className={`p-4 mx-2 rounded-2xl border transition-all cursor-pointer ${e.category==='Payment'?'bg-green-50/50 border-green-100 italic':'bg-white border-slate-50 hover:border-indigo-100 hover:bg-slate-50'}`}>
                        <div className="flex justify-between items-center"><div className="min-w-0"><p className="font-bold text-slate-800 truncate">{e.description}</p><p className="text-[9px] text-slate-400 font-bold uppercase">{activeEvent.participants.find(p=>p.id===e.payerId)?.name} paid</p></div><p className="font-black text-slate-900">₹{e.amount.toFixed(0)}</p></div>
                      </div>
                    ))
                  }
                </div>
              </div>
            </div>
            <div className="lg:col-span-4 order-1 lg:order-3"><ExpenseForm participants={activeEvent.participants} onAdd={addExpense} /></div>
          </div>
        ) : (
          <SettlementView participants={activeEvent.participants} balances={balances} settlements={settlements} totalSpent={totalSpent} onSettle={handleSettle} />
        )}
      </main>

      {showShareModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md animate-in fade-in">
          <div className="bg-white rounded-[2.5rem] max-w-sm w-full shadow-2xl overflow-hidden animate-in zoom-in-95">
            <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
              <h3 className="text-xl font-black text-slate-800">Share with Squad</h3>
              <button onClick={()=>setShowShareModal(false)} className="text-slate-400 hover:text-slate-800"><i className="fa-solid fa-xmark"></i></button>
            </div>
            <div className="p-8 space-y-6">
              {shareStatus === 'saving' ? (
                <div className="flex flex-col items-center py-10 gap-4"><div className="w-10 h-10 border-4 border-slate-100 border-t-indigo-600 rounded-full animate-spin"></div><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Preparing Link...</p></div>
              ) : generatedShortUrl ? (
                <div className="space-y-4">
                  <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100 text-center"><p className="text-xs font-bold text-indigo-600 truncate">{generatedShortUrl}</p></div>
                  <div className="grid grid-cols-2 gap-3">
                    <button onClick={handleShareWhatsApp} className="flex flex-col items-center gap-2 p-5 bg-green-50 rounded-3xl hover:bg-green-100 transition-all">
                      <div className="w-12 h-12 bg-green-500 rounded-2xl flex items-center justify-center text-white text-2xl shadow-lg shadow-green-100"><i className="fa-brands fa-whatsapp"></i></div>
                      <span className="text-[10px] font-black uppercase text-green-700">WhatsApp</span>
                    </button>
                    <button onClick={handleShareGmail} className="flex flex-col items-center gap-2 p-5 bg-red-50 rounded-3xl hover:bg-red-100 transition-all">
                      <div className="w-12 h-12 bg-red-500 rounded-2xl flex items-center justify-center text-white text-2xl shadow-lg shadow-red-100"><i className="fa-solid fa-envelope"></i></div>
                      <span className="text-[10px] font-black uppercase text-red-700">Gmail</span>
                    </button>
                    <button onClick={handleShareArattai} className="flex flex-col items-center gap-2 p-5 bg-blue-50 rounded-3xl hover:bg-blue-100 transition-all">
                      <div className="w-12 h-12 bg-blue-500 rounded-2xl flex items-center justify-center text-white text-2xl shadow-lg shadow-blue-100"><i className="fa-solid fa-share-nodes"></i></div>
                      <span className="text-[10px] font-black uppercase text-blue-700">Arattai</span>
                    </button>
                    <button onClick={handleCopyLink} className={`flex flex-col items-center gap-2 p-5 rounded-3xl transition-all ${shareStatus==='copied'?'bg-green-100':'bg-slate-50 hover:bg-slate-100'}`}>
                      <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-white text-2xl shadow-lg ${shareStatus==='copied'?'bg-green-600':'bg-slate-800'}`}><i className={`fa-solid ${shareStatus==='copied'?'fa-check':'fa-link'}`}></i></div>
                      <span className="text-[10px] font-black uppercase text-slate-700">{shareStatus==='copied'?'Copied':'Link'}</span>
                    </button>
                  </div>
                </div>
              ) : (
                <button onClick={handleShareToSupabase} className="w-full bg-[#4f46e5] text-white py-5 rounded-3xl font-black text-xs uppercase tracking-widest shadow-xl hover:bg-[#4338ca] transition-all">SYNC CLOUD & GET LINK</button>
              )}
              {shareStatus === 'error' && <p className="text-[10px] text-red-500 font-black text-center uppercase tracking-widest">Failed to connect to Supabase. Please retry.</p>}
            </div>
          </div>
        </div>
      )}

      {selectedExpense && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white rounded-[2.5rem] max-w-lg w-full p-8 space-y-6 shadow-2xl animate-in zoom-in-95">
            <div className="flex justify-between items-center"><h3 className="text-xl font-black text-slate-800 uppercase tracking-tight">Record Detail</h3><button onClick={()=>setSelectedExpense(null)} className="text-slate-400 hover:text-slate-800"><i className="fa-solid fa-xmark"></i></button></div>
            <div className="space-y-4 pt-4 border-t border-slate-50">
              <div className="flex justify-between">
                <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Label</span>
                <span className="font-bold text-slate-800">{selectedExpense.description}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Amount</span>
                <span className="font-black text-indigo-600 text-2xl">₹{selectedExpense.amount.toFixed(2)}</span>
              </div>
            </div>
            <button onClick={()=>{removeExpense(selectedExpense.id); setSelectedExpense(null);}} className="w-full py-5 bg-red-50 text-red-500 font-black text-xs uppercase tracking-widest rounded-2xl hover:bg-red-100 transition-all border border-red-100"><i className="fa-solid fa-trash-can mr-2"></i>Delete Forever</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { createClient, SupabaseClient } from '@supabase/supabase-js';
import { Participant, Expense, Settlement, Balance, SplitEvent } from './types.ts';
import ParticipantManager from './components/ParticipantManager.tsx';
import ExpenseForm from './components/ExpenseForm.tsx';
import SettlementView from './components/SettlementView.tsx';
import { calculateBalances, calculateSettlements } from './utils/calculation.ts';

// Helper to generate a 6-character random ID for short URLs and unique event strings
const generateShortId = () => {
  const chars = 'abcdefghijklmnopqrstuvwxyz0123456789';
  let result = '';
  for (let i = 0; i < 6; i++) {
    result += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return result;
};

// Initialize Supabase client safely
const getSupabase = () => {
  const url = process.env.SUPABASE_URL || 'https://yrlvjtnxusbgqeqgaonu.supabase.co';
  const key = process.env.SUPABASE_ANON_KEY || 'sb_publishable_bFgmsQkkShvZYtyLf7ASEA_I1J6Y3zw';
  if (!url || !key) return null;
  return createClient(url, key);
};

const App: React.FC = () => {
  const [events, setEvents] = useState<Record<string, SplitEvent>>({});
  const [currentEventId, setCurrentEventId] = useState<string | null>(null);
  const [newEventName, setNewEventName] = useState('');

  // App states
  const [activeTab, setActiveTab] = useState<'overview' | 'settlement'>('overview');
  const [selectedExpense, setSelectedExpense] = useState<Expense | null>(null);
  const [shareStatus, setShareStatus] = useState<'idle' | 'saving' | 'copied' | 'error'>('idle');
  const [showShareModal, setShowShareModal] = useState(false);
  const [shareEventId, setShareEventId] = useState<string | null>(null);
  const [generatedShortUrl, setGeneratedShortUrl] = useState<string | null>(null);
  const [isInitialized, setIsInitialized] = useState(false);
  const [isLoadingShared, setIsLoadingShared] = useState(false);

  const getAvatar = (name: string) => `https://api.dicebear.com/7.x/initials/svg?seed=${name}&backgroundColor=4f46e5&textColor=ffffff`;

  // Fetch Logic: Check for short trip ID in hash
  useEffect(() => {
    const loadInitialData = async () => {
      const savedEvents = localStorage.getItem('splitit_multi_events');
      let currentEvents: Record<string, SplitEvent> = savedEvents ? JSON.parse(savedEvents) : {};

      const hash = window.location.hash;
      const shortIdMatch = hash.match(/#\/?trip\/([a-z0-9]{6})$/i);
      const sb = getSupabase();

      if (shortIdMatch && shortIdMatch[1] && sb) {
        const tripSlug = shortIdMatch[1];
        setIsLoadingShared(true);
        try {
          const { data, error } = await sb
            .from('trips')
            .select('trip_data')
            .eq('id', tripSlug)
            .single();

          if (!error && data?.trip_data) {
            const fetchedEvent = data.trip_data as SplitEvent;
            const localId = fetchedEvent.id || tripSlug;
            currentEvents[localId] = fetchedEvent;
            setCurrentEventId(localId);
            window.history.replaceState(null, "", window.location.pathname);
          }
        } catch (err) {
          console.error("Supabase fetch error:", err);
        } finally {
          setIsLoadingShared(false);
        }
      }

      setEvents(currentEvents);
      setIsInitialized(true);
    };

    loadInitialData();
  }, []);

  useEffect(() => {
    if (isInitialized) {
      localStorage.setItem('splitit_multi_events', JSON.stringify(events));
    }
  }, [events, isInitialized]);

  const activeEvent = currentEventId ? events[currentEventId] : null;

  const { balances, settlements, totalSpent } = useMemo(() => {
    if (!activeEvent) return { balances: [], settlements: [], totalSpent: 0 };
    const bals = calculateBalances(activeEvent.participants, activeEvent.expenses);
    const setts = calculateSettlements([...bals]);
    const total = activeEvent.expenses.reduce((acc, curr) => curr.category !== 'Payment' ? acc + curr.amount : acc, 0);
    return { balances: bals, settlements: setts, totalSpent: total };
  }, [activeEvent]);

  const createEvent = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newEventName.trim()) return;
    const id = generateShortId();
    const newEv: SplitEvent = {
      id,
      name: newEventName.trim(),
      participants: [],
      expenses: [],
      createdAt: Date.now()
    };
    setEvents(prev => ({ ...prev, [id]: newEv }));
    setNewEventName('');
    setCurrentEventId(id);
  };

  const deleteEvent = (id: string) => {
    if (window.confirm("Permanently delete this group?")) {
      const newEvents = { ...events };
      delete newEvents[id];
      setEvents(newEvents);
      if (currentEventId === id) setCurrentEventId(null);
    }
  };

  const updateActiveEvent = (updates: Partial<SplitEvent>) => {
    if (!currentEventId) return;
    setEvents(prev => ({
      ...prev,
      [currentEventId]: { ...prev[currentEventId], ...updates }
    }));
  };

  const addParticipant = (name: string, upiId?: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      participants: [...activeEvent.participants, { id: crypto.randomUUID(), name, avatar: getAvatar(name), upiId }]
    });
  };

  const removeParticipant = (id: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      participants: activeEvent.participants.filter(p => p.id !== id),
      expenses: activeEvent.expenses.filter(e => e.payerId !== id && !e.participantIds.includes(id))
    });
  };

  const addExpense = (newExp: Omit<Expense, 'id'>) => {
    if (!activeEvent) return;
    updateActiveEvent({
      expenses: [{ ...newExp, id: crypto.randomUUID() }, ...activeEvent.expenses]
    });
  };

  const removeExpense = (id: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      expenses: activeEvent.expenses.filter(e => e.id !== id)
    });
    if (selectedExpense?.id === id) setSelectedExpense(null);
  };

  const handleSettle = (fromId: string, toId: string, amount: number) => {
    if (!activeEvent) return;
    const fromP = activeEvent.participants.find(p => p.id === fromId)?.name;
    const toP = activeEvent.participants.find(p => p.id === toId)?.name;
    addExpense({
      description: `Settlement: ${fromP} paid ${toP}`,
      amount: amount, payerId: fromId, participantIds: [toId], category: 'Payment', date: Date.now()
    });
  };

  const handleShareToSupabase = async () => {
    if (!shareEventId || !events[shareEventId]) return;

    setShareStatus('saving');
    const sb = getSupabase();
    if (!sb) {
      setShareStatus('error');
      return;
    }

    const targetEvent = events[shareEventId];
    const shortId = targetEvent.id;

    try {
      const { error } = await sb
        .from('trips')
        .upsert([{ 
          id: shortId,
          trip_data: targetEvent,
          name: targetEvent.name 
        }]);

      if (error) throw error;

      const shortUrl = `${window.location.origin}/#/trip/${shortId}`;
      setGeneratedShortUrl(shortUrl);
      setShareStatus('idle');
    } catch (err) {
      console.error("Supabase Sync Error:", err);
      setShareStatus('error');
    }
  };

  const openShareModal = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setShareEventId(id);
    setGeneratedShortUrl(null);
    setShareStatus('idle');
    setShowShareModal(true);
  };

  const getWhatsAppText = () => {
    if (!activeEvent) return '';
    const settlementText = settlements.length === 0 
      ? "All clear! No pending payments. ✅" 
      : settlements.map(s => {
          const fromName = activeEvent.participants.find(p => p.id === s.from)?.name;
          const toName = activeEvent.participants.find(p => p.id === s.to)?.name;
          return `💸 *${fromName}* owes *${toName}*: ₹${s.amount.toFixed(2)}`;
        }).join('\n');

    return `💰 *SplitIt: ${activeEvent.name}*\n\n*Current Settlements:*\n${settlementText}\n\n🔗 Open trip and settle:\n${generatedShortUrl}\n\nNo more awkward money talks! SplitIt handles it all for you.\nTry it Now: splitits.in`;
  };

  const handleShareWhatsApp = () => {
    window.open(`https://api.whatsapp.com/send?text=${encodeURIComponent(getWhatsAppText())}`, '_blank');
  };

  const handleShareGmail = () => {
    const subject = `Expense Split for ${activeEvent?.name}`;
    window.open(`mailto:?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(getWhatsAppText())}`, '_blank');
  };

  const handleShareArattai = () => {
    if (navigator.share) {
      navigator.share({
        title: `SplitIt: ${activeEvent?.name}`,
        text: getWhatsAppText(),
        url: generatedShortUrl || ''
      }).catch(console.error);
    } else {
      alert("Sharing via Arattai is best supported on mobile. Please copy the link instead.");
    }
  };

  const handleCopyLink = () => {
    if (!generatedShortUrl) return;
    navigator.clipboard.writeText(generatedShortUrl).then(() => {
      setShareStatus('copied');
      setTimeout(() => setShareStatus('idle'), 2000);
    });
  };

  if (!isInitialized || isLoadingShared) {
    return (
      <div className="min-h-screen bg-[#f8fafc] flex flex-col items-center justify-center font-sans">
        <div className="w-12 h-12 border-4 border-slate-100 border-t-[#4f46e5] rounded-full animate-spin mb-4"></div>
        <p className="text-xs font-bold text-slate-400 uppercase tracking-widest animate-pulse">Fetching Trip...</p>
      </div>
    );
  }

  // Dashboard
  if (!currentEventId) {
    return (
      <div className="min-h-screen bg-[#f8fafc] flex flex-col font-sans">
        <header className="bg-white border-b border-slate-100 p-6 sm:p-8 flex items-start">
          <div className="flex items-center gap-3 sm:gap-4">
             <div className="w-12 h-12 bg-[#4f46e5] rounded-2xl flex items-center justify-center text-white text-3xl shadow-lg shadow-indigo-100">
               <i className="fa-solid fa-receipt"></i>
             </div>
             <div className="flex flex-col items-start text-left">
               <h1 className="text-3xl font-black text-slate-900 tracking-tighter">SplitIt</h1>
               <p className="text-xs font-medium text-slate-400 lowercase -mt-1 tracking-tight">good times in, awkward math out.</p>
             </div>
          </div>
        </header>

        <main className="flex-1 max-w-5xl mx-auto w-full px-4 py-10 sm:py-20 space-y-12">
          <section className="bg-white rounded-[2.5rem] p-8 sm:p-16 shadow-2xl shadow-indigo-100/40 border border-slate-50 text-center space-y-10">
            <h2 className="text-4xl sm:text-5xl font-black text-slate-900 tracking-tight leading-tight">Start an Event</h2>
            <form onSubmit={createEvent} className="max-w-md mx-auto flex flex-col gap-4">
              <input 
                type="text" 
                value={newEventName}
                onChange={e => setNewEventName(e.target.value)}
                placeholder="Event Name (e.g. Goa Trip)"
                className="w-full px-8 py-5 rounded-3xl bg-slate-50 border-2 border-transparent focus:border-[#4f46e5] focus:bg-white text-lg font-bold transition-all outline-none shadow-inner"
              />
              <button type="submit" className="bg-[#4f46e5] text-white py-5 rounded-3xl font-black text-sm hover:bg-[#4338ca] transition-all shadow-xl active:scale-95 uppercase tracking-widest">Create an Event</button>
            </form>
          </section>

          {Object.keys(events).length > 0 && (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
              {(Object.values(events) as SplitEvent[]).sort((a,b)=>b.createdAt-a.createdAt).map(ev => (
                <div key={ev.id} onClick={()=>setCurrentEventId(ev.id)} className="bg-white p-6 rounded-[2rem] border border-slate-100 hover:shadow-xl transition-all cursor-pointer group">
                  <div className="flex justify-between items-start mb-4">
                    <div className="w-12 h-12 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center font-black">{ev.name.charAt(0)}</div>
                    <button onClick={(e)=>{e.stopPropagation(); deleteEvent(ev.id)}} className="text-slate-200 hover:text-red-500 transition-colors p-2"><i className="fa-solid fa-trash-can"></i></button>
                  </div>
                  <h4 className="text-xl font-black text-slate-800 line-clamp-1">{ev.name}</h4>
                  <p className="text-[10px] font-bold text-slate-400 uppercase mt-1 tracking-widest">{ev.participants.length} Members • ₹{ev.expenses.reduce((acc,curr)=>curr.category!=='Payment'?acc+curr.amount:acc,0).toFixed(0)}</p>
                </div>
              ))}
            </div>
          )}
        </main>
      </div>
    );
  }

  // Active View
  return (
    <div className="min-h-screen bg-[#f8fafc] text-slate-900 flex flex-col font-sans">
      <header className="bg-white border-b border-slate-100 sticky top-0 z-30 shadow-sm px-4">
        <div className="max-w-7xl mx-auto h-20 flex items-center justify-between gap-4">
          <div className="flex items-center gap-4 min-w-0">
            <button onClick={()=>setCurrentEventId(null)} className="w-10 h-10 rounded-xl hover:bg-slate-50 flex items-center justify-center text-slate-400"><i className="fa-solid fa-arrow-left"></i></button>
            <div className="min-w-0">
              <h1 className="text-lg font-black text-slate-900 truncate uppercase tracking-tight">{activeEvent.name}</h1>
              <p className="text-[9px] font-bold text-slate-400 tracking-widest uppercase -mt-0.5">SplitIt Safe</p>
            </div>
          </div>
          <nav className="flex bg-slate-100 p-1 rounded-xl">
            <button onClick={()=>setActiveTab('overview')} className={`px-4 py-2 rounded-lg text-xs font-black uppercase transition-all ${activeTab==='overview'?'bg-white text-indigo-600 shadow-sm':'text-slate-400'}`}>Overview</button>
            <button onClick={()=>setActiveTab('settlement')} className={`px-4 py-2 rounded-lg text-xs font-black uppercase transition-all ${activeTab==='settlement'?'bg-white text-indigo-600 shadow-sm':'text-slate-400'}`}>Settlement</button>
          </nav>
        </div>
      </header>

      <main className="flex-1 max-w-7xl mx-auto w-full px-4 py-8 space-y-8 animate-in fade-in duration-500">
        <div className="flex flex-col items-stretch justify-between bg-white px-8 py-6 rounded-[2rem] border border-slate-100 shadow-lg shadow-slate-100/50 gap-6 sm:flex-row sm:items-center">
          <div className="flex justify-around sm:justify-start gap-12 text-center sm:text-left">
            <div><span className="text-[8px] font-black text-slate-300 uppercase block mb-1">Spent</span><p className="text-3xl font-black">₹{totalSpent.toFixed(0)}</p></div>
            <div><span className="text-[8px] font-black text-slate-300 uppercase block mb-1">Squad</span><p className="text-3xl font-black">{activeEvent.participants.length}</p></div>
          </div>
          <button onClick={(e)=>openShareModal(e, activeEvent.id)} className="bg-[#4f46e5] text-white px-8 py-4 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-[#4338ca] shadow-lg active:scale-95">Share with Squad</button>
        </div>

        {activeTab === 'overview' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
            <div className="lg:col-span-3 order-2 lg:order-1"><ParticipantManager participants={activeEvent.participants} onAdd={addParticipant} onRemove={removeParticipant} /></div>
            <div className="lg:col-span-5 space-y-6 order-3 lg:order-2">
              <div className="bg-white border border-slate-100 rounded-[2rem] p-4 min-h-[400px] shadow-sm overflow-hidden">
                <h2 className="text-xs font-black uppercase tracking-widest text-slate-400 p-4 border-b border-slate-50 mb-4 flex items-center gap-2"><i className="fa-solid fa-clock-rotate-left"></i>History</h2>
                <div className="space-y-4 max-h-[600px] overflow-y-auto scrollbar-hide">
                  {activeEvent.expenses.length === 0 ? <div className="text-center py-20 text-slate-300 font-bold uppercase text-[10px]">No records found</div> : 
                    activeEvent.expenses.sort((a,b)=>b.date-a.date).map(e => (
                      <div key={e.id} onClick={()=>setSelectedExpense(e)} className={`p-4 mx-2 rounded-2xl border transition-all cursor-pointer ${e.category==='Payment'?'bg-green-50/50 border-green-100 italic':'bg-white border-slate-50 hover:border-indigo-100 hover:bg-slate-50'}`}>
                        <div className="flex justify-between items-center"><div className="min-w-0"><p className="font-bold text-slate-800 truncate">{e.description}</p><p className="text-[9px] text-slate-400 font-bold uppercase">{activeEvent.participants.find(p=>p.id===e.payerId)?.name} paid</p></div><p className="font-black text-slate-900">₹{e.amount.toFixed(0)}</p></div>
                      </div>
                    ))
                  }
                </div>
              </div>
            </div>
            <div className="lg:col-span-4 order-1 lg:order-3"><ExpenseForm participants={activeEvent.participants} onAdd={addExpense} /></div>
          </div>
        ) : (
          <SettlementView participants={activeEvent.participants} balances={balances} settlements={settlements} totalSpent={totalSpent} onSettle={handleSettle} />
        )}
      </main>

      {showShareModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md animate-in fade-in">
          <div className="bg-white rounded-[2.5rem] max-w-sm w-full shadow-2xl overflow-hidden animate-in zoom-in-95">
            <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
              <h3 className="text-xl font-black text-slate-800">Share with Squad</h3>
              <button onClick={()=>setShowShareModal(false)} className="text-slate-400 hover:text-slate-800"><i className="fa-solid fa-xmark"></i></button>
            </div>
            <div className="p-8 space-y-6">
              {shareStatus === 'saving' ? (
                <div className="flex flex-col items-center py-10 gap-4"><div className="w-10 h-10 border-4 border-slate-100 border-t-indigo-600 rounded-full animate-spin"></div><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Preparing Link...</p></div>
              ) : generatedShortUrl ? (
                <div className="space-y-4">
                  <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100 text-center"><p className="text-xs font-bold text-indigo-600 truncate">{generatedShortUrl}</p></div>
                  <div className="grid grid-cols-2 gap-3">
                    <button onClick={handleShareWhatsApp} className="flex flex-col items-center gap-2 p-5 bg-green-50 rounded-3xl hover:bg-green-100 transition-all">
                      <div className="w-12 h-12 bg-green-500 rounded-2xl flex items-center justify-center text-white text-2xl shadow-lg shadow-green-100"><i className="fa-brands fa-whatsapp"></i></div>
                      <span className="text-[10px] font-black uppercase text-green-700">WhatsApp</span>
                    </button>
                    <button onClick={handleShareGmail} className="flex flex-col items-center gap-2 p-5 bg-red-50 rounded-3xl hover:bg-red-100 transition-all">
                      <div className="w-12 h-12 bg-red-500 rounded-2xl flex items-center justify-center text-white text-2xl shadow-lg shadow-red-100"><i className="fa-solid fa-envelope"></i></div>
                      <span className="text-[10px] font-black uppercase text-red-700">Gmail</span>
                    </button>
                    <button onClick={handleShareArattai} className="flex flex-col items-center gap-2 p-5 bg-blue-50 rounded-3xl hover:bg-blue-100 transition-all">
                      <div className="w-12 h-12 bg-blue-500 rounded-2xl flex items-center justify-center text-white text-2xl shadow-lg shadow-blue-100"><i className="fa-solid fa-share-nodes"></i></div>
                      <span className="text-[10px] font-black uppercase text-blue-700">Arattai</span>
                    </button>
                    <button onClick={handleCopyLink} className={`flex flex-col items-center gap-2 p-5 rounded-3xl transition-all ${shareStatus==='copied'?'bg-green-100':'bg-slate-50 hover:bg-slate-100'}`}>
                      <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-white text-2xl shadow-lg ${shareStatus==='copied'?'bg-green-600':'bg-slate-800'}`}><i className={`fa-solid ${shareStatus==='copied'?'fa-check':'fa-link'}`}></i></div>
                      <span className="text-[10px] font-black uppercase text-slate-700">{shareStatus==='copied'?'Copied':'Copy Link'}</span>
                    </button>
                  </div>
                </div>
              ) : (
                <button onClick={handleShareToSupabase} className="w-full bg-[#4f46e5] text-white py-5 rounded-3xl font-black text-xs uppercase tracking-widest shadow-xl hover:bg-[#4338ca] transition-all">Sync & Generate Link</button>
              )}
            </div>
          </div>
        </div>
      )}

      {selectedExpense && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white rounded-[2.5rem] max-w-lg w-full p-8 space-y-6 shadow-2xl animate-in zoom-in-95">
            <div className="flex justify-between items-center"><h3 className="text-xl font-black text-slate-800 uppercase tracking-tight">Record Detail</h3><button onClick={()=>setSelectedExpense(null)} className="text-slate-400 hover:text-slate-800"><i className="fa-solid fa-xmark"></i></button></div>
            <div className="space-y-4 pt-4 border-t border-slate-50">
              <div className="flex justify-between">
                <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Label</span>
                <span className="font-bold text-slate-800">{selectedExpense.description}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Amount</span>
                <span className="font-black text-indigo-600 text-2xl">₹{selectedExpense.amount.toFixed(2)}</span>
              </div>
            </div>
            <button onClick={()=>{removeExpense(selectedExpense.id); setSelectedExpense(null);}} className="w-full py-5 bg-red-50 text-red-500 font-black text-xs uppercase tracking-widest rounded-2xl hover:bg-red-100 transition-all border border-red-100"><i className="fa-solid fa-trash-can mr-2"></i>Delete Record</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Participant, Settlement, Balance } from '../types.ts';
import { ResponsiveContainer, BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Cell } from 'recharts';

interface Props {
  participants: Participant[];
  balances: Balance[];
  settlements: Settlement[];
  totalSpent: number;
  onSettle: (fromId: string, toId: string, amount: number) => void;
}

const SettlementView: React.FC<Props> = ({ participants, balances, settlements, totalSpent, onSettle }) => {
  const [paymentModal, setPaymentModal] = useState<{ settlement: Settlement; show: boolean } | null>(null);

  const getParticipant = (id: string) => participants.find(p => p.id === id);
  const getParticipantName = (id: string) => getParticipant(id)?.name || 'Guest';

  const handleWhatsAppRequest = (s: Settlement) => {
    const payer = getParticipant(s.from);
    const payee = getParticipant(s.to);
    if (!payer || !payee) return;

    let message = `Hi ${payer.name}, reminder from SplitIt! 👋\n\nYou owe me *₹${s.amount.toFixed(2)}*.`;
    if (payee.upiId) {
      message += `\n\nMy UPI ID: ${payee.upiId}`;
    }
    const whatsappUrl = `https://api.whatsapp.com/send?text=${encodeURIComponent(message)}`;
    window.open(whatsappUrl, '_blank');
  };

  const getUPILink = (s: Settlement, method: 'gpay' | 'phonepe' | 'cred' | 'generic') => {
    const payee = getParticipant(s.to);
    if (!payee || !payee.upiId) return '';

    const upiString = `upi://pay?pa=${payee.upiId}&pn=${encodeURIComponent(payee.name)}&am=${s.amount.toFixed(2)}&cu=INR`;

    switch (method) {
      case 'gpay': return `googlegpay://pay?pa=${payee.upiId}&pn=${encodeURIComponent(payee.name)}&am=${s.amount.toFixed(2)}&cu=INR`;
      case 'phonepe': return `phonepe://pay?pa=${payee.upiId}&pn=${encodeURIComponent(payee.name)}&am=${s.amount.toFixed(2)}&cu=INR`;
      default: return upiString;
    }
  };

  const handlePayment = (method: 'gpay' | 'phonepe' | 'cred' | 'generic') => {
    if (!paymentModal) return;
    const url = getUPILink(paymentModal.settlement, method);
    if (url) {
      window.location.href = url;
    }
    setPaymentModal(null);
  };

  const chartData = balances.map(b => ({
    name: getParticipantName(b.participantId),
    value: b.amount
  }));

  return (
    <div className="space-y-6 sm:space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 sm:gap-8">
        {/* Settlements */}
        <div className="bg-white rounded-[2rem] p-6 sm:p-8 shadow-lg shadow-slate-100/50 border border-slate-100">
          <div className="flex items-center gap-3 mb-6 sm:mb-8">
            <div className="w-10 h-10 bg-indigo-50 text-indigo-600 rounded-xl flex items-center justify-center"><i className="fa-solid fa-handshake"></i></div>
            <h2 className="text-lg font-black uppercase tracking-tight">Pending Payments</h2>
          </div>
          <div className="space-y-4">
            {settlements.length === 0 ? (
              <div className="text-center py-16 bg-slate-50/50 rounded-3xl border-2 border-dashed border-slate-100">
                <p className="text-slate-300 font-black text-[10px] uppercase tracking-widest">Everything is settled! ✅</p>
              </div>
            ) : (
              settlements.map((s, idx) => {
                const payee = getParticipant(s.to);
                return (
                  <div key={idx} className="bg-white p-5 rounded-3xl border border-slate-100 hover:border-indigo-100 transition-all shadow-sm">
                    <div className="flex items-center justify-between mb-6 gap-2">
                      <div className="text-left min-w-0 flex-1">
                        <span className="text-[8px] font-black uppercase text-slate-300 block mb-1">Payer</span>
                        <p className="font-black text-slate-900 truncate text-sm">{getParticipantName(s.from)}</p>
                      </div>
                      <div className="text-center flex flex-col items-center shrink-0 px-2">
                        <i className="fa-solid fa-arrow-right text-indigo-200 text-xs mb-1"></i>
                        <p className="text-xl font-black text-indigo-600">₹{s.amount.toFixed(0)}</p>
                      </div>
                      <div className="text-right min-w-0 flex-1">
                        <span className="text-[8px] font-black uppercase text-slate-300 block mb-1">Receiver</span>
                        <p className="font-black text-slate-900 truncate text-sm">{getParticipantName(s.to)}</p>
                      </div>
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-3 gap-2">
                      <button
                        onClick={() => setPaymentModal({ settlement: s, show: true })}
                        className="bg-indigo-600 text-white text-[9px] font-black uppercase py-3.5 rounded-xl hover:bg-indigo-700 transition-all shadow-md shadow-indigo-100 flex items-center justify-center gap-2"
                      >
                        <i className="fa-solid fa-bolt"></i>
                        MAKE PAYMENT
                      </button>
                      <button
                        onClick={() => handleWhatsAppRequest(s)}
                        className="bg-green-500 text-white text-[9px] font-black uppercase py-3.5 rounded-xl hover:bg-green-600 transition-all shadow-md shadow-green-100 flex items-center justify-center gap-2"
                      >
                        <i className="fa-brands fa-whatsapp"></i>
                        REQUEST
                      </button>
                      <button
                        onClick={() => onSettle(s.from, s.to, s.amount)}
                        className="bg-slate-100 text-slate-500 text-[9px] font-black uppercase py-3.5 rounded-xl hover:bg-slate-200 transition-all flex items-center justify-center gap-2"
                      >
                        <i className="fa-solid fa-check"></i>
                        MARK PAID
                      </button>
                    </div>
                  </div>
                );
              })
            )}
          </div>
        </div>

        {/* Balance Overview */}
        <div className="bg-white rounded-[2rem] p-6 sm:p-8 shadow-lg shadow-slate-100/50 border border-slate-100">
          <div className="flex items-center gap-3 mb-6 sm:mb-8">
            <div className="w-10 h-10 bg-indigo-50 text-indigo-600 rounded-xl flex items-center justify-center"><i className="fa-solid fa-chart-pie"></i></div>
            <h2 className="text-lg font-black uppercase tracking-tight">Chart Overview</h2>
          </div>
          <div className="h-[300px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData} layout="vertical" margin={{ left: 10, right: 30, top: 10, bottom: 10 }}>
                <CartesianGrid strokeDasharray="3 3" horizontal={false} stroke="#f1f5f9" />
                <XAxis type="number" hide />
                <YAxis 
                  dataKey="name" 
                  type="category" 
                  width={80} 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{ fontSize: 10, fontWeight: 900, fill: '#94a3b8' }} 
                />
                <Tooltip 
                  cursor={{ fill: 'transparent' }}
                  contentStyle={{ borderRadius: '1.25rem', border: 'none', background: '#1e293b', color: '#fff', fontSize: '10px', fontWeight: 'bold' }}
                  formatter={(value: number) => `₹${value.toFixed(2)}`}
                />
                <Bar dataKey="value" radius={[0, 8, 8, 0]} barSize={24}>
                  {chartData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.value >= 0 ? '#10b981' : '#ef4444'} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* Payment Selection Modal */}
      {paymentModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md animate-in fade-in">
          <div className="bg-white rounded-[2.5rem] max-w-sm w-full shadow-2xl overflow-hidden animate-in zoom-in-95">
            <div className="p-10 border-b border-slate-100 flex flex-col items-center bg-slate-50/50 text-center">
               <span className="text-[10px] font-black text-indigo-600 uppercase tracking-[0.2em] mb-2">Payable Amount</span>
               <h3 className="text-5xl font-black text-slate-900 tracking-tighter">₹{paymentModal.settlement.amount.toFixed(2)}</h3>
               <p className="text-[10px] font-bold text-slate-400 uppercase mt-4">Paying to {getParticipantName(paymentModal.settlement.to)}</p>
            </div>

            <div className="p-8 grid grid-cols-2 gap-4">
              <button onClick={() => handlePayment('gpay')} className="flex flex-col items-center gap-2 p-5 bg-slate-50 rounded-3xl hover:bg-white border border-transparent hover:border-slate-100 transition-all group">
                <div className="w-14 h-14 bg-white rounded-2xl flex items-center justify-center shadow-sm group-hover:scale-110 transition-transform"><i className="fa-brands fa-google-pay text-3xl text-[#4285F4]"></i></div>
                <span className="text-[10px] font-black uppercase text-slate-500 mt-1">GPay</span>
              </button>
              <button onClick={() => handlePayment('phonepe')} className="flex flex-col items-center gap-2 p-5 bg-slate-50 rounded-3xl hover:bg-white border border-transparent hover:border-slate-100 transition-all group">
                <div className="w-14 h-14 bg-white rounded-2xl flex items-center justify-center shadow-sm group-hover:scale-110 transition-transform"><i className="fa-solid fa-mobile-screen text-2xl text-[#5f259f]"></i></div>
                <span className="text-[10px] font-black uppercase text-slate-500 mt-1">PhonePe</span>
              </button>
              <button onClick={() => handlePayment('cred')} className="flex flex-col items-center gap-2 p-5 bg-slate-50 rounded-3xl hover:bg-white border border-transparent hover:border-slate-100 transition-all group">
                <div className="w-14 h-14 bg-white rounded-2xl flex items-center justify-center shadow-sm font-black text-sm italic group-hover:scale-110 transition-transform tracking-tight">CRED</div>
                <span className="text-[10px] font-black uppercase text-slate-500 mt-1">Cred</span>
              </button>
              <button onClick={() => handlePayment('generic')} className="flex flex-col items-center gap-2 p-5 bg-slate-50 rounded-3xl hover:bg-white border border-transparent hover:border-slate-100 transition-all group">
                <div className="w-14 h-14 bg-white rounded-2xl flex items-center justify-center shadow-sm group-hover:scale-110 transition-transform text-slate-700 font-black text-xs uppercase tracking-tighter">UPI</div>
                <span className="text-[10px] font-black uppercase text-slate-500 mt-1 text-center">Other UPI</span>
              </button>
            </div>

            <div className="p-6 bg-slate-50 border-t border-slate-100">
               <button onClick={() => setPaymentModal(null)} className="w-full py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest hover:text-slate-600 transition-colors">Cancel Payment</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default SettlementView;

import React, { useState, useMemo, useEffect } from 'react';
import { createClient, SupabaseClient } from '@supabase/supabase-js';
import { Participant, Expense, Settlement, Balance, SplitEvent } from './types.ts';
import ParticipantManager from './components/ParticipantManager.tsx';
import ExpenseForm from './components/ExpenseForm.tsx';
import SettlementView from './components/SettlementView.tsx';
import { calculateBalances, calculateSettlements } from './utils/calculation.ts';

// Helper to generate a 6-character random ID for short URLs and unique event strings
const generateShortId = () => {
  const chars = 'abcdefghijklmnopqrstuvwxyz0123456789';
  let result = '';
  for (let i = 0; i < 6; i++) {
    result += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return result;
};

// Initialize Supabase client safely
const getSupabase = () => {
  const url = process.env.SUPABASE_URL || 'https://yrlvjtnxusbgqeqgaonu.supabase.co';
  const key = process.env.SUPABASE_ANON_KEY || 'sb_publishable_bFgmsQkkShvZYtyLf7ASEA_I1J6Y3zw';
  if (!url || !key) return null;
  return createClient(url, key);
};

const App: React.FC = () => {
  const [events, setEvents] = useState<Record<string, SplitEvent>>({});
  const [currentEventId, setCurrentEventId] = useState<string | null>(null);
  const [newEventName, setNewEventName] = useState('');

  // App states
  const [activeTab, setActiveTab] = useState<'overview' | 'settlement'>('overview');
  const [selectedExpense, setSelectedExpense] = useState<Expense | null>(null);
  const [shareStatus, setShareStatus] = useState<'idle' | 'saving' | 'copied' | 'error'>('idle');
  const [showShareModal, setShowShareModal] = useState(false);
  const [shareEventId, setShareEventId] = useState<string | null>(null);
  const [generatedShortUrl, setGeneratedShortUrl] = useState<string | null>(null);
  const [isInitialized, setIsInitialized] = useState(false);
  const [isLoadingShared, setIsLoadingShared] = useState(false);

  const getAvatar = (name: string) => `https://api.dicebear.com/7.x/initials/svg?seed=${name}&backgroundColor=4f46e5&textColor=ffffff`;

  // Fetch Logic: Check for short trip ID in hash
  useEffect(() => {
    const loadInitialData = async () => {
      const savedEvents = localStorage.getItem('splitit_multi_events');
      let currentEvents: Record<string, SplitEvent> = savedEvents ? JSON.parse(savedEvents) : {};

      const hash = window.location.hash;
      const shortIdMatch = hash.match(/#\/?trip\/([a-z0-9]{6})$/i);
      const sb = getSupabase();

      if (shortIdMatch && shortIdMatch[1] && sb) {
        const tripSlug = shortIdMatch[1];
        setIsLoadingShared(true);
        try {
          const { data, error } = await sb
            .from('trips')
            .select('trip_data')
            .eq('id', tripSlug)
            .single();

          if (!error && data?.trip_data) {
            const fetchedEvent = data.trip_data as SplitEvent;
            const localId = fetchedEvent.id || tripSlug;
            currentEvents[localId] = fetchedEvent;
            setCurrentEventId(localId);
            window.history.replaceState(null, "", window.location.pathname);
          }
        } catch (err) {
          console.error("Supabase fetch error:", err);
        } finally {
          setIsLoadingShared(false);
        }
      }

      setEvents(currentEvents);
      setIsInitialized(true);
    };

    loadInitialData();
  }, []);

  useEffect(() => {
    if (isInitialized) {
      localStorage.setItem('splitit_multi_events', JSON.stringify(events));
    }
  }, [events, isInitialized]);

  const activeEvent = currentEventId ? events[currentEventId] : null;

  const { balances, settlements, totalSpent } = useMemo(() => {
    if (!activeEvent) return { balances: [], settlements: [], totalSpent: 0 };
    const bals = calculateBalances(activeEvent.participants, activeEvent.expenses);
    const setts = calculateSettlements([...bals]);
    const total = activeEvent.expenses.reduce((acc, curr) => curr.category !== 'Payment' ? acc + curr.amount : acc, 0);
    return { balances: bals, settlements: setts, totalSpent: total };
  }, [activeEvent]);

  const createEvent = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newEventName.trim()) return;
    const id = generateShortId();
    const newEv: SplitEvent = {
      id,
      name: newEventName.trim(),
      participants: [],
      expenses: [],
      createdAt: Date.now()
    };
    setEvents(prev => ({ ...prev, [id]: newEv }));
    setNewEventName('');
    setCurrentEventId(id);
  };

  const deleteEvent = (id: string) => {
    if (window.confirm("Permanently delete this group?")) {
      const newEvents = { ...events };
      delete newEvents[id];
      setEvents(newEvents);
      if (currentEventId === id) setCurrentEventId(null);
    }
  };

  const updateActiveEvent = (updates: Partial<SplitEvent>) => {
    if (!currentEventId) return;
    setEvents(prev => ({
      ...prev,
      [currentEventId]: { ...prev[currentEventId], ...updates }
    }));
  };

  const addParticipant = (name: string, upiId?: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      participants: [...activeEvent.participants, { id: crypto.randomUUID(), name, avatar: getAvatar(name), upiId }]
    });
  };

  const removeParticipant = (id: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      participants: activeEvent.participants.filter(p => p.id !== id),
      expenses: activeEvent.expenses.filter(e => e.payerId !== id && !e.participantIds.includes(id))
    });
  };

  const addExpense = (newExp: Omit<Expense, 'id'>) => {
    if (!activeEvent) return;
    updateActiveEvent({
      expenses: [{ ...newExp, id: crypto.randomUUID() }, ...activeEvent.expenses]
    });
  };

  const removeExpense = (id: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      expenses: activeEvent.expenses.filter(e => e.id !== id)
    });
    if (selectedExpense?.id === id) setSelectedExpense(null);
  };

  const handleSettle = (fromId: string, toId: string, amount: number) => {
    if (!activeEvent) return;
    const fromP = activeEvent.participants.find(p => p.id === fromId)?.name;
    const toP = activeEvent.participants.find(p => p.id === toId)?.name;
    addExpense({
      description: `Settlement: ${fromP} paid ${toP}`,
      amount: amount, payerId: fromId, participantIds: [toId], category: 'Payment', date: Date.now()
    });
  };

  const handleShareToSupabase = async () => {
    if (!shareEventId || !events[shareEventId]) return;

    setShareStatus('saving');
    const sb = getSupabase();
    if (!sb) {
      setShareStatus('error');
      return;
    }

    const targetEvent = events[shareEventId];
    const shortId = targetEvent.id;

    try {
      const { error } = await sb
        .from('trips')
        .upsert([{ 
          id: shortId,
          trip_data: targetEvent,
          name: targetEvent.name 
        }]);

      if (error) throw error;

      const shortUrl = `${window.location.origin}/#/trip/${shortId}`;
      setGeneratedShortUrl(shortUrl);
      setShareStatus('idle');
    } catch (err) {
      console.error("Supabase Sync Error:", err);
      setShareStatus('error');
    }
  };

  const openShareModal = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setShareEventId(id);
    setGeneratedShortUrl(null);
    setShareStatus('idle');
    setShowShareModal(true);
  };

  const getWhatsAppText = () => {
    if (!activeEvent) return '';
    const settlementText = settlements.length === 0 
      ? "All clear! No pending payments. ✅" 
      : settlements.map(s => {
          const fromName = activeEvent.participants.find(p => p.id === s.from)?.name;
          const toName = activeEvent.participants.find(p => p.id === s.to)?.name;
          return `💸 *${fromName}* owes *${toName}*: ₹${s.amount.toFixed(2)}`;
        }).join('\n');

    return `💰 *SplitIt: ${activeEvent.name}*\n\n*Current Settlements:*\n${settlementText}\n\n🔗 Open trip and settle:\n${generatedShortUrl}\n\nNo more awkward money talks! SplitIt handles it all for you.\nTry it Now: splitits.in`;
  };

  const handleShareWhatsApp = () => {
    window.open(`https://api.whatsapp.com/send?text=${encodeURIComponent(getWhatsAppText())}`, '_blank');
  };

  const handleShareGmail = () => {
    const subject = `Expense Split for ${activeEvent?.name}`;
    window.open(`mailto:?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(getWhatsAppText())}`, '_blank');
  };

  const handleShareArattai = () => {
    if (navigator.share) {
      navigator.share({
        title: `SplitIt: ${activeEvent?.name}`,
        text: getWhatsAppText(),
        url: generatedShortUrl || ''
      }).catch(console.error);
    } else {
      alert("Sharing via Arattai is best supported on mobile. Please copy the link instead.");
    }
  };

  const handleCopyLink = () => {
    if (!generatedShortUrl) return;
    navigator.clipboard.writeText(generatedShortUrl).then(() => {
      setShareStatus('copied');
      setTimeout(() => setShareStatus('idle'), 2000);
    });
  };

  if (!isInitialized || isLoadingShared) {
    return (
      <div className="min-h-screen bg-[#f8fafc] flex flex-col items-center justify-center font-sans">
        <div className="w-12 h-12 border-4 border-slate-100 border-t-[#4f46e5] rounded-full animate-spin mb-4"></div>
        <p className="text-xs font-bold text-slate-400 uppercase tracking-widest animate-pulse">Fetching Trip...</p>
      </div>
    );
  }

  // Dashboard
  if (!currentEventId) {
    return (
      <div className="min-h-screen bg-[#f8fafc] flex flex-col font-sans">
        <header className="bg-white border-b border-slate-100 p-6 sm:p-8 flex items-start">
          <div className="flex items-center gap-3 sm:gap-4">
             <div className="w-12 h-12 bg-[#4f46e5] rounded-2xl flex items-center justify-center text-white text-3xl shadow-lg shadow-indigo-100">
               <i className="fa-solid fa-receipt"></i>
             </div>
             <div className="flex flex-col items-start text-left">
               <h1 className="text-3xl font-black text-slate-900 tracking-tighter">SplitIt</h1>
               <p className="text-xs font-medium text-slate-400 lowercase -mt-1 tracking-tight">good times in, awkward math out.</p>
             </div>
          </div>
        </header>

        <main className="flex-1 max-w-5xl mx-auto w-full px-4 py-10 sm:py-20 space-y-12">
          <section className="bg-white rounded-[2.5rem] p-8 sm:p-16 shadow-2xl shadow-indigo-100/40 border border-slate-50 text-center space-y-10">
            <h2 className="text-4xl sm:text-5xl font-black text-slate-900 tracking-tight leading-tight">Start an Event</h2>
            <form onSubmit={createEvent} className="max-w-md mx-auto flex flex-col gap-4">
              <input 
                type="text" 
                value={newEventName}
                onChange={e => setNewEventName(e.target.value)}
                placeholder="Event Name (e.g. Goa Trip)"
                className="w-full px-8 py-5 rounded-3xl bg-slate-50 border-2 border-transparent focus:border-[#4f46e5] focus:bg-white text-lg font-bold transition-all outline-none shadow-inner"
              />
              <button type="submit" className="bg-[#4f46e5] text-white py-5 rounded-3xl font-black text-sm hover:bg-[#4338ca] transition-all shadow-xl active:scale-95 uppercase tracking-widest">Create an Event</button>
            </form>
          </section>

          {Object.keys(events).length > 0 && (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
              {(Object.values(events) as SplitEvent[]).sort((a,b)=>b.createdAt-a.createdAt).map(ev => (
                <div key={ev.id} onClick={()=>setCurrentEventId(ev.id)} className="bg-white p-6 rounded-[2rem] border border-slate-100 hover:shadow-xl transition-all cursor-pointer group">
                  <div className="flex justify-between items-start mb-4">
                    <div className="w-12 h-12 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center font-black">{ev.name.charAt(0)}</div>
                    <button onClick={(e)=>{e.stopPropagation(); deleteEvent(ev.id)}} className="text-slate-200 hover:text-red-500 transition-colors p-2"><i className="fa-solid fa-trash-can"></i></button>
                  </div>
                  <h4 className="text-xl font-black text-slate-800 line-clamp-1">{ev.name}</h4>
                  <p className="text-[10px] font-bold text-slate-400 uppercase mt-1 tracking-widest">{ev.participants.length} Members • ₹{ev.expenses.reduce((acc,curr)=>curr.category!=='Payment'?acc+curr.amount:acc,0).toFixed(0)}</p>
                </div>
              ))}
            </div>
          )}
        </main>
      </div>
    );
  }

  // Active View
  return (
    <div className="min-h-screen bg-[#f8fafc] text-slate-900 flex flex-col font-sans">
      <header className="bg-white border-b border-slate-100 sticky top-0 z-30 shadow-sm px-4">
        <div className="max-w-7xl mx-auto h-20 flex items-center justify-between gap-4">
          <div className="flex items-center gap-4 min-w-0">
            <button onClick={()=>setCurrentEventId(null)} className="w-10 h-10 rounded-xl hover:bg-slate-50 flex items-center justify-center text-slate-400"><i className="fa-solid fa-arrow-left"></i></button>
            <div className="min-w-0">
              <h1 className="text-lg font-black text-slate-900 truncate uppercase tracking-tight">{activeEvent.name}</h1>
              <p className="text-[9px] font-bold text-slate-400 tracking-widest uppercase -mt-0.5">SplitIt Safe</p>
            </div>
          </div>
          <nav className="flex bg-slate-100 p-1 rounded-xl">
            <button onClick={()=>setActiveTab('overview')} className={`px-4 py-2 rounded-lg text-xs font-black uppercase transition-all ${activeTab==='overview'?'bg-white text-indigo-600 shadow-sm':'text-slate-400'}`}>Overview</button>
            <button onClick={()=>setActiveTab('settlement')} className={`px-4 py-2 rounded-lg text-xs font-black uppercase transition-all ${activeTab==='settlement'?'bg-white text-indigo-600 shadow-sm':'text-slate-400'}`}>Settlement</button>
          </nav>
        </div>
      </header>

      <main className="flex-1 max-w-7xl mx-auto w-full px-4 py-8 space-y-8 animate-in fade-in duration-500">
        <div className="flex flex-col items-stretch justify-between bg-white px-8 py-6 rounded-[2rem] border border-slate-100 shadow-lg shadow-slate-100/50 gap-6 sm:flex-row sm:items-center">
          <div className="flex justify-around sm:justify-start gap-12 text-center sm:text-left">
            <div><span className="text-[8px] font-black text-slate-300 uppercase block mb-1">Spent</span><p className="text-3xl font-black">₹{totalSpent.toFixed(0)}</p></div>
            <div><span className="text-[8px] font-black text-slate-300 uppercase block mb-1">Squad</span><p className="text-3xl font-black">{activeEvent.participants.length}</p></div>
          </div>
          <button onClick={(e)=>openShareModal(e, activeEvent.id)} className="bg-[#4f46e5] text-white px-8 py-4 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-[#4338ca] shadow-lg active:scale-95">Share with Squad</button>
        </div>

        {activeTab === 'overview' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
            {/* "The Squad" moved to order-1 for mobile, lg:order-1 for desktop */}
            <div className="lg:col-span-3 order-1 lg:order-1">
              <ParticipantManager participants={activeEvent.participants} onAdd={addParticipant} onRemove={removeParticipant} />
            </div>
            {/* Expense History order-3 for mobile, lg:order-2 for desktop */}
            <div className="lg:col-span-5 space-y-6 order-3 lg:order-2">
              <div className="bg-white border border-slate-100 rounded-[2rem] p-4 min-h-[400px] shadow-sm overflow-hidden">
                <h2 className="text-xs font-black uppercase tracking-widest text-slate-400 p-4 border-b border-slate-50 mb-4 flex items-center gap-2"><i className="fa-solid fa-clock-rotate-left"></i>History</h2>
                <div className="space-y-4 max-h-[600px] overflow-y-auto scrollbar-hide">
                  {activeEvent.expenses.length === 0 ? <div className="text-center py-20 text-slate-300 font-bold uppercase text-[10px]">No records found</div> : 
                    activeEvent.expenses.sort((a,b)=>b.date-a.date).map(e => (
                      <div key={e.id} onClick={()=>setSelectedExpense(e)} className={`p-4 mx-2 rounded-2xl border transition-all cursor-pointer ${e.category==='Payment'?'bg-green-50/50 border-green-100 italic':'bg-white border-slate-50 hover:border-indigo-100 hover:bg-slate-50'}`}>
                        <div className="flex justify-between items-center"><div className="min-w-0"><p className="font-bold text-slate-800 truncate">{e.description}</p><p className="text-[9px] text-slate-400 font-bold uppercase">{activeEvent.participants.find(p=>p.id===e.payerId)?.name} paid</p></div><p className="font-black text-slate-900">₹{e.amount.toFixed(0)}</p></div>
                      </div>
                    ))
                  }
                </div>
              </div>
            </div>
            {/* Expense Form order-2 for mobile, lg:order-3 for desktop */}
            <div className="lg:col-span-4 order-2 lg:order-3">
              <ExpenseForm participants={activeEvent.participants} onAdd={addExpense} />
            </div>
          </div>
        ) : (
          <SettlementView participants={activeEvent.participants} balances={balances} settlements={settlements} totalSpent={totalSpent} onSettle={handleSettle} />
        )}
      </main>

      {showShareModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md animate-in fade-in">
          <div className="bg-white rounded-[2.5rem] max-w-sm w-full shadow-2xl overflow-hidden animate-in zoom-in-95">
            <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
              <h3 className="text-xl font-black text-slate-800">Share with Squad</h3>
              <button onClick={()=>setShowShareModal(false)} className="text-slate-400 hover:text-slate-800"><i className="fa-solid fa-xmark"></i></button>
            </div>
            <div className="p-8 space-y-6">
              {shareStatus === 'saving' ? (
                <div className="flex flex-col items-center py-10 gap-4"><div className="w-10 h-10 border-4 border-slate-100 border-t-indigo-600 rounded-full animate-spin"></div><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Preparing Link...</p></div>
              ) : generatedShortUrl ? (
                <div className="space-y-4">
                  <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100 text-center"><p className="text-xs font-bold text-indigo-600 truncate">{generatedShortUrl}</p></div>
                  <div className="grid grid-cols-2 gap-3">
                    <button onClick={handleShareWhatsApp} className="flex flex-col items-center gap-2 p-5 bg-green-50 rounded-3xl hover:bg-green-100 transition-all">
                      <div className="w-12 h-12 bg-green-500 rounded-2xl flex items-center justify-center text-white text-2xl shadow-lg shadow-green-100"><i className="fa-brands fa-whatsapp"></i></div>
                      <span className="text-[10px] font-black uppercase text-green-700">WhatsApp</span>
                    </button>
                    <button onClick={handleShareGmail} className="flex flex-col items-center gap-2 p-5 bg-red-50 rounded-3xl hover:bg-red-100 transition-all">
                      <div className="w-12 h-12 bg-red-500 rounded-2xl flex items-center justify-center text-white text-2xl shadow-lg shadow-red-100"><i className="fa-solid fa-envelope"></i></div>
                      <span className="text-[10px] font-black uppercase text-red-700">Gmail</span>
                    </button>
                    <button onClick={handleShareArattai} className="flex flex-col items-center gap-2 p-5 bg-blue-50 rounded-3xl hover:bg-blue-100 transition-all">
                      <div className="w-12 h-12 bg-blue-500 rounded-2xl flex items-center justify-center text-white text-2xl shadow-lg shadow-blue-100"><i className="fa-solid fa-share-nodes"></i></div>
                      <span className="text-[10px] font-black uppercase text-blue-700">Arattai</span>
                    </button>
                    <button onClick={handleCopyLink} className={`flex flex-col items-center gap-2 p-5 rounded-3xl transition-all ${shareStatus==='copied'?'bg-green-100':'bg-slate-50 hover:bg-slate-100'}`}>
                      <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-white text-2xl shadow-lg ${shareStatus==='copied'?'bg-green-600':'bg-slate-800'}`}><i className={`fa-solid ${shareStatus==='copied'?'fa-check':'fa-link'}`}></i></div>
                      <span className="text-[10px] font-black uppercase text-slate-700">{shareStatus==='copied'?'Copied':'Copy Link'}</span>
                    </button>
                  </div>
                </div>
              ) : (
                <button onClick={handleShareToSupabase} className="w-full bg-[#4f46e5] text-white py-5 rounded-3xl font-black text-xs uppercase tracking-widest shadow-xl hover:bg-[#4338ca] transition-all">Sync & Generate Link</button>
              )}
            </div>
          </div>
        </div>
      )}

      {selectedExpense && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white rounded-[2.5rem] max-w-lg w-full p-8 space-y-6 shadow-2xl animate-in zoom-in-95">
            <div className="flex justify-between items-center"><h3 className="text-xl font-black text-slate-800 uppercase tracking-tight">Record Detail</h3><button onClick={()=>setSelectedExpense(null)} className="text-slate-400 hover:text-slate-800"><i className="fa-solid fa-xmark"></i></button></div>
            <div className="space-y-4 pt-4 border-t border-slate-50">
              <div className="flex justify-between">
                <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Label</span>
                <span className="font-bold text-slate-800">{selectedExpense.description}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Amount</span>
                <span className="font-black text-indigo-600 text-2xl">₹{selectedExpense.amount.toFixed(2)}</span>
              </div>
            </div>
            <button onClick={()=>{removeExpense(selectedExpense.id); setSelectedExpense(null);}} className="w-full py-5 bg-red-50 text-red-500 font-black text-xs uppercase tracking-widest rounded-2xl hover:bg-red-100 transition-all border border-red-100"><i className="fa-solid fa-trash-can mr-2"></i>Delete Record</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { createClient } from '@supabase/supabase-js';
import { Participant, Expense, Settlement, Balance, SplitEvent } from './types.ts';
import ParticipantManager from './components/ParticipantManager.tsx';
import ExpenseForm from './components/ExpenseForm.tsx';
import SettlementView from './components/SettlementView.tsx';
import { calculateBalances, calculateSettlements } from './utils/calculation.ts';

// Helper to generate a 6-character random ID for short URLs and unique event strings
const generateShortId = () => {
  const chars = 'abcdefghijklmnopqrstuvwxyz0123456789';
  let result = '';
  for (let i = 0; i < 6; i++) {
    result += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return result;
};

// Initialize Supabase client safely from window.process.env polyfill
const getSupabase = () => {
  const url = (window as any).process?.env?.SUPABASE_URL || 'https://yrlvjtnxusbgqeqgaonu.supabase.co';
  const key = (window as any).process?.env?.SUPABASE_ANON_KEY || 'sb_publishable_bFgmsQkkShvZYtyLf7ASEA_I1J6Y3zw';
  if (!url || !key) return null;
  return createClient(url, key);
};

const App: React.FC = () => {
  const [events, setEvents] = useState<Record<string, SplitEvent>>({});
  const [currentEventId, setCurrentEventId] = useState<string | null>(null);
  const [newEventName, setNewEventName] = useState('');

  // App states
  const [activeTab, setActiveTab] = useState<'overview' | 'settlement'>('overview');
  const [selectedExpense, setSelectedExpense] = useState<Expense | null>(null);
  const [shareStatus, setShareStatus] = useState<'idle' | 'saving' | 'copied' | 'error'>('idle');
  const [showShareModal, setShowShareModal] = useState(false);
  const [shareEventId, setShareEventId] = useState<string | null>(null);
  const [generatedShortUrl, setGeneratedShortUrl] = useState<string | null>(null);
  const [isInitialized, setIsInitialized] = useState(false);
  const [isLoadingShared, setIsLoadingShared] = useState(false);

  const getAvatar = (name: string) => `https://api.dicebear.com/7.x/initials/svg?seed=${name}&backgroundColor=4f46e5&textColor=ffffff`;

  // Fetch Logic: Check for short trip ID in hash on initial load
  useEffect(() => {
    const loadInitialData = async () => {
      const savedEvents = localStorage.getItem('splitit_multi_events');
      let currentEvents: Record<string, SplitEvent> = savedEvents ? JSON.parse(savedEvents) : {};

      const hash = window.location.hash;
      const shortIdMatch = hash.match(/#\/?trip\/([a-z0-9]{6})$/i);
      const sb = getSupabase();

      if (shortIdMatch && shortIdMatch[1] && sb) {
        const tripSlug = shortIdMatch[1];
        setIsLoadingShared(true);
        try {
          const { data, error } = await sb
            .from('trips')
            .select('trip_data')
            .eq('id', tripSlug)
            .single();

          if (!error && data?.trip_data) {
            const fetchedEvent = data.trip_data as SplitEvent;
            const localId = fetchedEvent.id || tripSlug;
            currentEvents[localId] = fetchedEvent;
            setCurrentEventId(localId);
            // Clear hash after loading to avoid re-triggering
            window.history.replaceState(null, "", window.location.pathname);
          }
        } catch (err) {
          console.error("Supabase fetch error:", err);
        } finally {
          setIsLoadingShared(false);
        }
      }

      setEvents(currentEvents);
      setIsInitialized(true);
    };

    loadInitialData();
  }, []);

  // Save local changes to localStorage
  useEffect(() => {
    if (isInitialized) {
      localStorage.setItem('splitit_multi_events', JSON.stringify(events));
    }
  }, [events, isInitialized]);

  const activeEvent = currentEventId ? events[currentEventId] : null;

  const { balances, settlements, totalSpent } = useMemo(() => {
    if (!activeEvent) return { balances: [], settlements: [], totalSpent: 0 };
    const bals = calculateBalances(activeEvent.participants, activeEvent.expenses);
    const setts = calculateSettlements([...bals]);
    const total = activeEvent.expenses.reduce((acc, curr) => curr.category !== 'Payment' ? acc + curr.amount : acc, 0);
    return { balances: bals, settlements: setts, totalSpent: total };
  }, [activeEvent]);

  const createEvent = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newEventName.trim()) return;
    const id = generateShortId();
    const newEv: SplitEvent = {
      id,
      name: newEventName.trim(),
      participants: [],
      expenses: [],
      createdAt: Date.now()
    };
    setEvents(prev => ({ ...prev, [id]: newEv }));
    setNewEventName('');
    setCurrentEventId(id);
  };

  const deleteEvent = (id: string) => {
    if (window.confirm("Permanently delete this group?")) {
      const newEvents = { ...events };
      delete newEvents[id];
      setEvents(newEvents);
      if (currentEventId === id) setCurrentEventId(null);
    }
  };

  const updateActiveEvent = (updates: Partial<SplitEvent>) => {
    if (!currentEventId) return;
    setEvents(prev => ({
      ...prev,
      [currentEventId]: { ...prev[currentEventId], ...updates }
    }));
  };

  const addParticipant = (name: string, upiId?: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      participants: [...activeEvent.participants, { id: crypto.randomUUID(), name, avatar: getAvatar(name), upiId }]
    });
  };

  const removeParticipant = (id: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      participants: activeEvent.participants.filter(p => p.id !== id),
      expenses: activeEvent.expenses.filter(e => e.payerId !== id && !e.participantIds.includes(id))
    });
  };

  const addExpense = (newExp: Omit<Expense, 'id'>) => {
    if (!activeEvent) return;
    updateActiveEvent({
      expenses: [{ ...newExp, id: crypto.randomUUID() }, ...activeEvent.expenses]
    });
  };

  const removeExpense = (id: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      expenses: activeEvent.expenses.filter(e => e.id !== id)
    });
    if (selectedExpense?.id === id) setSelectedExpense(null);
  };

  const handleSettle = (fromId: string, toId: string, amount: number) => {
    if (!activeEvent) return;
    const fromP = activeEvent.participants.find(p => p.id === fromId)?.name;
    const toP = activeEvent.participants.find(p => p.id === toId)?.name;
    addExpense({
      description: `Settlement: ${fromP} paid ${toP}`,
      amount: amount, payerId: fromId, participantIds: [toId], category: 'Payment', date: Date.now()
    });
  };

  const handleShareToSupabase = async () => {
    if (!shareEventId || !events[shareEventId]) return;

    setShareStatus('saving');
    const sb = getSupabase();
    if (!sb) {
      setShareStatus('error');
      return;
    }

    const targetEvent = events[shareEventId];
    const shortId = targetEvent.id;

    try {
      const { error } = await sb
        .from('trips')
        .upsert([{ 
          id: shortId,
          trip_data: targetEvent,
          name: targetEvent.name 
        }]);

      if (error) throw error;

      const shortUrl = `${window.location.origin}/#/trip/${shortId}`;
      setGeneratedShortUrl(shortUrl);
      setShareStatus('idle');
    } catch (err) {
      console.error("Supabase Sync Error:", err);
      setShareStatus('error');
    }
  };

  const openShareModal = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setShareEventId(id);
    setGeneratedShortUrl(null);
    setShareStatus('idle');
    setShowShareModal(true);
  };

  const getWhatsAppText = () => {
    if (!activeEvent) return '';
    const settlementText = settlements.length === 0 
      ? "All clear! No pending payments. ✅" 
      : settlements.map(s => {
          const fromName = activeEvent.participants.find(p => p.id === s.from)?.name;
          const toName = activeEvent.participants.find(p => p.id === s.to)?.name;
          return `💸 *${fromName}* owes *${toName}*: ₹${s.amount.toFixed(2)}`;
        }).join('\n');

    return `💰 *SplitIt: ${activeEvent.name}*\n\n*Current Settlements:*\n${settlementText}\n\n🔗 Open trip and settle:\n${generatedShortUrl}\n\nNo more awkward money talks! SplitIt handles it all for you.`;
  };

  const handleShareWhatsApp = () => {
    window.open(`https://api.whatsapp.com/send?text=${encodeURIComponent(getWhatsAppText())}`, '_blank');
  };

  const handleShareGmail = () => {
    const subject = `Expense Split for ${activeEvent?.name}`;
    window.open(`mailto:?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(getWhatsAppText())}`, '_blank');
  };

  const handleShareArattai = () => {
    if (navigator.share) {
      navigator.share({
        title: `SplitIt: ${activeEvent?.name}`,
        text: getWhatsAppText(),
        url: generatedShortUrl || ''
      }).catch(console.error);
    } else {
      alert("Sharing via Arattai is best supported on mobile. Please copy the link instead.");
    }
  };

  const handleCopyLink = () => {
    if (!generatedShortUrl) return;
    navigator.clipboard.writeText(generatedShortUrl).then(() => {
      setShareStatus('copied');
      setTimeout(() => setShareStatus('idle'), 2000);
    });
  };

  if (!isInitialized || isLoadingShared) {
    return (
      <div className="min-h-screen bg-[#f8fafc] flex flex-col items-center justify-center font-sans">
        <div className="w-12 h-12 border-4 border-slate-100 border-t-[#4f46e5] rounded-full animate-spin mb-4"></div>
        <p className="text-xs font-bold text-slate-400 uppercase tracking-widest animate-pulse">Fetching Trip...</p>
      </div>
    );
  }

  // Dashboard View
  if (!currentEventId) {
    return (
      <div className="min-h-screen bg-[#f8fafc] flex flex-col font-sans">
        <header className="bg-white border-b border-slate-100 p-6 sm:p-8 flex items-start justify-start">
          <div className="flex items-center gap-3 sm:gap-4">
             <div className="w-12 h-12 bg-[#4f46e5] rounded-2xl flex items-center justify-center text-white text-3xl shadow-lg shadow-indigo-100">
               <i className="fa-solid fa-receipt"></i>
             </div>
             <div className="flex flex-col items-start text-left">
               <h1 className="text-3xl font-black text-slate-900 tracking-tighter">SplitIt</h1>
               <p className="text-xs font-medium text-slate-400 lowercase -mt-1 tracking-tight">good times in, awkward math out.</p>
             </div>
          </div>
        </header>

        <main className="flex-1 max-w-5xl mx-auto w-full px-4 py-10 sm:py-20 space-y-12">
          <section className="bg-white rounded-[2.5rem] p-8 sm:p-16 shadow-2xl shadow-indigo-100/40 border border-slate-50 text-center space-y-10">
            <h2 className="text-4xl sm:text-5xl font-black text-slate-900 tracking-tight leading-tight">Start an Event</h2>
            <form onSubmit={createEvent} className="max-w-md mx-auto flex flex-col gap-4">
              <input 
                type="text" 
                value={newEventName}
                onChange={e => setNewEventName(e.target.value)}
                placeholder="Event Name (e.g. Goa Trip)"
                className="w-full px-8 py-5 rounded-3xl bg-slate-50 border-2 border-transparent focus:border-[#4f46e5] focus:bg-white text-lg font-bold transition-all outline-none shadow-inner"
              />
              <button type="submit" className="bg-[#4f46e5] text-white py-5 rounded-3xl font-black text-sm hover:bg-[#4338ca] transition-all shadow-xl active:scale-95 uppercase tracking-widest">Create an Event</button>
            </form>
          </section>

          {Object.keys(events).length > 0 && (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
              {(Object.values(events) as SplitEvent[]).sort((a,b)=>b.createdAt-a.createdAt).map(ev => (
                <div key={ev.id} onClick={()=>setCurrentEventId(ev.id)} className="bg-white p-6 rounded-[2rem] border border-slate-100 hover:shadow-xl transition-all cursor-pointer group">
                  <div className="flex justify-between items-start mb-4">
                    <div className="w-12 h-12 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center font-black">{ev.name.charAt(0)}</div>
                    <button onClick={(e)=>{e.stopPropagation(); deleteEvent(ev.id)}} className="text-slate-200 hover:text-red-500 transition-colors p-2"><i className="fa-solid fa-trash-can"></i></button>
                  </div>
                  <h4 className="text-xl font-black text-slate-800 line-clamp-1">{ev.name}</h4>
                  <p className="text-[10px] font-bold text-slate-400 uppercase mt-1 tracking-widest">{ev.participants.length} Members • ₹{ev.expenses.reduce((acc,curr)=>curr.category!=='Payment'?acc+curr.amount:acc,0).toFixed(0)}</p>
                </div>
              ))}
            </div>
          )}
        </main>
      </div>
    );
  }

  // Active Event View
  return (
    <div className="min-h-screen bg-[#f8fafc] text-slate-900 flex flex-col font-sans">
      <header className="bg-white border-b border-slate-100 sticky top-0 z-30 shadow-sm px-4">
        <div className="max-w-7xl mx-auto h-20 flex items-center justify-between gap-4">
          <div className="flex items-center gap-4 min-w-0">
            <button onClick={()=>setCurrentEventId(null)} className="w-10 h-10 rounded-xl hover:bg-slate-50 flex items-center justify-center text-slate-400"><i className="fa-solid fa-arrow-left"></i></button>
            <div className="min-w-0">
              <h1 className="text-lg font-black text-slate-900 truncate uppercase tracking-tight">{activeEvent.name}</h1>
              <p className="text-[9px] font-bold text-slate-400 tracking-widest uppercase -mt-0.5">SplitIt Safe</p>
            </div>
          </div>
          <nav className="flex bg-slate-100 p-1 rounded-xl">
            <button onClick={()=>setActiveTab('overview')} className={`px-4 py-2 rounded-lg text-xs font-black uppercase transition-all ${activeTab==='overview'?'bg-white text-indigo-600 shadow-sm':'text-slate-400'}`}>Overview</button>
            <button onClick={()=>setActiveTab('settlement')} className={`px-4 py-2 rounded-lg text-xs font-black uppercase transition-all ${activeTab==='settlement'?'bg-white text-indigo-600 shadow-sm':'text-slate-400'}`}>Settlement</button>
          </nav>
        </div>
      </header>

      <main className="flex-1 max-w-7xl mx-auto w-full px-4 py-8 space-y-8 animate-in fade-in duration-500">
        {/* Event Stats & Sharing */}
        <div className="flex flex-col items-stretch justify-between bg-white px-8 py-6 rounded-[2rem] border border-slate-100 shadow-lg shadow-slate-100/50 gap-6 sm:flex-row sm:items-center">
          <div className="flex justify-around sm:justify-start gap-12 text-center sm:text-left">
            <div><span className="text-[8px] font-black text-slate-300 uppercase block mb-1">Spent</span><p className="text-3xl font-black">₹{totalSpent.toFixed(0)}</p></div>
            <div><span className="text-[8px] font-black text-slate-300 uppercase block mb-1">Squad</span><p className="text-3xl font-black">{activeEvent.participants.length}</p></div>
          </div>
          <button onClick={(e)=>openShareModal(e, activeEvent.id)} className="bg-[#4f46e5] text-white px-8 py-4 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-[#4338ca] shadow-lg active:scale-95 transition-all">Share with Squad</button>
        </div>

        {activeTab === 'overview' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
            {/* The Squad (ParticipantManager) is placed at order-1 for top visibility on mobile */}
            <div className="lg:col-span-3 order-1 lg:order-1">
              <ParticipantManager participants={activeEvent.participants} onAdd={addParticipant} onRemove={removeParticipant} />
            </div>

            {/* Expense History at the bottom on mobile (order-3) */}
            <div className="lg:col-span-5 space-y-6 order-3 lg:order-2">
              <div className="bg-white border border-slate-100 rounded-[2rem] p-4 min-h-[400px] shadow-sm overflow-hidden">
                <h2 className="text-xs font-black uppercase tracking-widest text-slate-400 p-4 border-b border-slate-50 mb-4 flex items-center gap-2">
                  <i className="fa-solid fa-clock-rotate-left"></i>History
                </h2>
                <div className="space-y-4 max-h-[600px] overflow-y-auto scrollbar-hide">
                  {activeEvent.expenses.length === 0 ? (
                    <div className="text-center py-20 text-slate-300 font-bold uppercase text-[10px]">No records found</div>
                  ) : (
                    activeEvent.expenses.sort((a,b)=>b.date-a.date).map(e => (
                      <div key={e.id} onClick={()=>setSelectedExpense(e)} className={`p-4 mx-2 rounded-2xl border transition-all cursor-pointer ${e.category==='Payment'?'bg-green-50/50 border-green-100 italic':'bg-white border-slate-50 hover:border-indigo-100 hover:bg-slate-50'}`}>
                        <div className="flex justify-between items-center">
                          <div className="min-w-0">
                            <p className="font-bold text-slate-800 truncate">{e.description}</p>
                            <p className="text-[9px] text-slate-400 font-bold uppercase">{activeEvent.participants.find(p=>p.id===e.payerId)?.name} paid</p>
                          </div>
                          <p className="font-black text-slate-900">₹{e.amount.toFixed(0)}</p>
                        </div>
                      </div>
                    ))
                  )}
                </div>
              </div>
            </div>

            {/* Expense Form in the middle on mobile (order-2) */}
            <div className="lg:col-span-4 order-2 lg:order-3">
              <ExpenseForm participants={activeEvent.participants} onAdd={addExpense} />
            </div>
          </div>
        ) : (
          <SettlementView participants={activeEvent.participants} balances={balances} settlements={settlements} totalSpent={totalSpent} onSettle={handleSettle} />
        )}
      </main>

      {/* Sharing Modal */}
      {showShareModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md animate-in fade-in">
          <div className="bg-white rounded-[2.5rem] max-w-sm w-full shadow-2xl overflow-hidden animate-in zoom-in-95">
            <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
              <h3 className="text-xl font-black text-slate-800">Share with Squad</h3>
              <button onClick={()=>setShowShareModal(false)} className="text-slate-400 hover:text-slate-800"><i className="fa-solid fa-xmark"></i></button>
            </div>
            <div className="p-8 space-y-6">
              {shareStatus === 'saving' ? (
                <div className="flex flex-col items-center py-10 gap-4">
                  <div className="w-10 h-10 border-4 border-slate-100 border-t-indigo-600 rounded-full animate-spin"></div>
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Preparing Link...</p>
                </div>
              ) : generatedShortUrl ? (
                <div className="space-y-4">
                  <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100 text-center">
                    <p className="text-xs font-bold text-indigo-600 truncate">{generatedShortUrl}</p>
                  </div>
                  <div className="grid grid-cols-2 gap-3">
                    <button onClick={handleShareWhatsApp} className="flex flex-col items-center gap-2 p-5 bg-green-50 rounded-3xl hover:bg-green-100 transition-all">
                      <div className="w-12 h-12 bg-green-500 rounded-2xl flex items-center justify-center text-white text-2xl shadow-lg shadow-green-100"><i className="fa-brands fa-whatsapp"></i></div>
                      <span className="text-[10px] font-black uppercase text-green-700">WhatsApp</span>
                    </button>
                    <button onClick={handleShareGmail} className="flex flex-col items-center gap-2 p-5 bg-red-50 rounded-3xl hover:bg-red-100 transition-all">
                      <div className="w-12 h-12 bg-red-500 rounded-2xl flex items-center justify-center text-white text-2xl shadow-lg shadow-red-100"><i className="fa-solid fa-envelope"></i></div>
                      <span className="text-[10px] font-black uppercase text-red-700">Gmail</span>
                    </button>
                    <button onClick={handleShareArattai} className="flex flex-col items-center gap-2 p-5 bg-blue-50 rounded-3xl hover:bg-blue-100 transition-all">
                      <div className="w-12 h-12 bg-blue-500 rounded-2xl flex items-center justify-center text-white text-2xl shadow-lg shadow-blue-100"><i className="fa-solid fa-share-nodes"></i></div>
                      <span className="text-[10px] font-black uppercase text-blue-700">Arattai</span>
                    </button>
                    <button onClick={handleCopyLink} className={`flex flex-col items-center gap-2 p-5 rounded-3xl transition-all ${shareStatus==='copied'?'bg-green-100':'bg-slate-50 hover:bg-slate-100'}`}>
                      <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-white text-2xl shadow-lg ${shareStatus==='copied'?'bg-green-600':'bg-slate-800'}`}><i className={`fa-solid ${shareStatus==='copied'?'fa-check':'fa-link'}`}></i></div>
                      <span className="text-[10px] font-black uppercase text-slate-700">{shareStatus==='copied'?'Copied':'Copy Link'}</span>
                    </button>
                  </div>
                </div>
              ) : (
                <button onClick={handleShareToSupabase} className="w-full bg-[#4f46e5] text-white py-5 rounded-3xl font-black text-xs uppercase tracking-widest shadow-xl hover:bg-[#4338ca] transition-all">Sync & Generate Link</button>
              )}
              {shareStatus === 'error' && (
                <p className="text-[10px] text-red-500 font-black text-center uppercase tracking-widest">Connection error. Check credentials.</p>
              )}
            </div>
          </div>
        </div>
      )}

      {selectedExpense && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white rounded-[2.5rem] max-w-lg w-full p-8 space-y-6 shadow-2xl animate-in zoom-in-95">
            <div className="flex justify-between items-center">
              <h3 className="text-xl font-black text-slate-800 uppercase tracking-tight">Record Detail</h3>
              <button onClick={()=>setSelectedExpense(null)} className="text-slate-400 hover:text-slate-800"><i className="fa-solid fa-xmark"></i></button>
            </div>
            <div className="space-y-4 pt-4 border-t border-slate-50">
              <div className="flex justify-between">
                <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Label</span>
                <span className="font-bold text-slate-800">{selectedExpense.description}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Amount</span>
                <span className="font-black text-indigo-600 text-2xl">₹{selectedExpense.amount.toFixed(2)}</span>
              </div>
            </div>
            <button onClick={()=>{removeExpense(selectedExpense.id); setSelectedExpense(null);}} className="w-full py-5 bg-red-50 text-red-500 font-black text-xs uppercase tracking-widest rounded-2xl hover:bg-red-100 transition-all border border-red-100">
              <i className="fa-solid fa-trash-can mr-2"></i>Delete Record
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { createClient } from '@supabase/supabase-js';
import { Participant, Expense, Settlement, Balance, SplitEvent } from './types.ts';
import ParticipantManager from './components/ParticipantManager.tsx';
import ExpenseForm from './components/ExpenseForm.tsx';
import SettlementView from './components/SettlementView.tsx';
import { calculateBalances, calculateSettlements } from './utils/calculation.ts';

// Helper to generate a 6-character random ID for short URLs and unique event strings
const generateShortId = () => {
  const chars = 'abcdefghijklmnopqrstuvwxyz0123456789';
  let result = '';
  for (let i = 0; i < 6; i++) {
    result += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return result;
};

// Initialize Supabase client safely from window.process.env polyfill
const getSupabase = () => {
  const url = (window as any).process?.env?.SUPABASE_URL || 'https://yrlvjtnxusbgqeqgaonu.supabase.co';
  const key = (window as any).process?.env?.SUPABASE_ANON_KEY || 'sb_publishable_bFgmsQkkShvZYtyLf7ASEA_I1J6Y3zw';
  if (!url || !key) return null;
  return createClient(url, key);
};

const App: React.FC = () => {
  const [events, setEvents] = useState<Record<string, SplitEvent>>({});
  const [currentEventId, setCurrentEventId] = useState<string | null>(null);
  const [newEventName, setNewEventName] = useState('');

  // App states
  const [activeTab, setActiveTab] = useState<'overview' | 'settlement'>('overview');
  const [selectedExpense, setSelectedExpense] = useState<Expense | null>(null);
  const [shareStatus, setShareStatus] = useState<'idle' | 'saving' | 'copied' | 'error'>('idle');
  const [showShareModal, setShowShareModal] = useState(false);
  const [shareEventId, setShareEventId] = useState<string | null>(null);
  const [isInitialized, setIsInitialized] = useState(false);
  const [isLoadingShared, setIsLoadingShared] = useState(false);

  const getAvatar = (name: string) => `https://api.dicebear.com/7.x/initials/svg?seed=${name}&backgroundColor=4f46e5&textColor=ffffff`;

  // Fetch Logic: Check for short trip ID in hash on initial load
  useEffect(() => {
    const loadInitialData = async () => {
      const savedEvents = localStorage.getItem('splitit_multi_events');
      let currentEvents: Record<string, SplitEvent> = savedEvents ? JSON.parse(savedEvents) : {};

      const hash = window.location.hash;
      const shortIdMatch = hash.match(/#\/?trip\/([a-z0-9]{6})$/i);
      const sb = getSupabase();

      if (shortIdMatch && shortIdMatch[1] && sb) {
        const tripSlug = shortIdMatch[1];
        setIsLoadingShared(true);
        try {
          const { data, error } = await sb
            .from('trips')
            .select('trip_data')
            .eq('id', tripSlug)
            .single();

          if (!error && data?.trip_data) {
            const fetchedEvent = data.trip_data as SplitEvent;
            const localId = fetchedEvent.id || tripSlug;
            currentEvents[localId] = fetchedEvent;
            setCurrentEventId(localId);
            // Clear hash after loading to avoid re-triggering and keeping a clean URL
            window.history.replaceState(null, "", window.location.pathname);
          }
        } catch (err) {
          console.error("Supabase fetch error:", err);
        } finally {
          setIsLoadingShared(false);
        }
      }

      setEvents(currentEvents);
      setIsInitialized(true);
    };

    loadInitialData();
  }, []);

  // Save local changes to localStorage
  useEffect(() => {
    if (isInitialized) {
      localStorage.setItem('splitit_multi_events', JSON.stringify(events));
    }
  }, [events, isInitialized]);

  const activeEvent = currentEventId ? events[currentEventId] : null;

  const { balances, settlements, totalSpent } = useMemo(() => {
    if (!activeEvent) return { balances: [], settlements: [], totalSpent: 0 };
    const bals = calculateBalances(activeEvent.participants, activeEvent.expenses);
    const setts = calculateSettlements([...bals]);
    const total = activeEvent.expenses.reduce((acc, curr) => curr.category !== 'Payment' ? acc + curr.amount : acc, 0);
    return { balances: bals, settlements: setts, totalSpent: total };
  }, [activeEvent]);

  const createEvent = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newEventName.trim()) return;
    const id = generateShortId();
    const newEv: SplitEvent = {
      id,
      name: newEventName.trim(),
      participants: [],
      expenses: [],
      createdAt: Date.now()
    };
    setEvents(prev => ({ ...prev, [id]: newEv }));
    setNewEventName('');
    setCurrentEventId(id);
  };

  const deleteEvent = (id: string) => {
    if (window.confirm("Permanently delete this group?")) {
      const newEvents = { ...events };
      delete newEvents[id];
      setEvents(newEvents);
      if (currentEventId === id) setCurrentEventId(null);
    }
  };

  const updateActiveEvent = (updates: Partial<SplitEvent>) => {
    if (!currentEventId) return;
    setEvents(prev => ({
      ...prev,
      [currentEventId]: { ...prev[currentEventId], ...updates }
    }));
  };

  const addParticipant = (name: string, upiId?: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      participants: [...activeEvent.participants, { id: crypto.randomUUID(), name, avatar: getAvatar(name), upiId }]
    });
  };

  const removeParticipant = (id: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      participants: activeEvent.participants.filter(p => p.id !== id),
      expenses: activeEvent.expenses.filter(e => e.payerId !== id && !e.participantIds.includes(id))
    });
  };

  const addExpense = (newExp: Omit<Expense, 'id'>) => {
    if (!activeEvent) return;
    updateActiveEvent({
      expenses: [{ ...newExp, id: crypto.randomUUID() }, ...activeEvent.expenses]
    });
  };

  const removeExpense = (id: string) => {
    if (!activeEvent) return;
    updateActiveEvent({
      expenses: activeEvent.expenses.filter(e => e.id !== id)
    });
    if (selectedExpense?.id === id) setSelectedExpense(null);
  };

  const handleSettle = (fromId: string, toId: string, amount: number) => {
    if (!activeEvent) return;
    const fromP = activeEvent.participants.find(p => p.id === fromId)?.name;
    const toP = activeEvent.participants.find(p => p.id === toId)?.name;
    addExpense({
      description: `Settlement: ${fromP} paid ${toP}`,
      amount: amount, payerId: fromId, participantIds: [toId], category: 'Payment', date: Date.now()
    });
  };

  const handleShareToSupabase = async () => {
    if (!shareEventId || !events[shareEventId]) return;

    setShareStatus('saving');
    const sb = getSupabase();
    if (!sb) {
      setShareStatus('error');
      return;
    }

    const targetEvent = events[shareEventId];
    const shortId = targetEvent.id;

    try {
      const { error } = await sb
        .from('trips')
        .upsert([{ 
          id: shortId,
          trip_data: targetEvent,
          name: targetEvent.name 
        }]);

      if (error) throw error;
      setShareStatus('idle');
    } catch (err) {
      console.error("Supabase Sync Error:", err);
      setShareStatus('error');
    }
  };

  const openShareModal = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setShareEventId(id);
    setShareStatus('idle');
    setShowShareModal(true);
  };

  const currentUniqueUrl = useMemo(() => {
    if (!shareEventId) return '';
    return `${window.location.origin}/#/trip/${shareEventId}`;
  }, [shareEventId]);

  const getWhatsAppText = () => {
    if (!activeEvent) return '';
    const settlementText = settlements.length === 0 
      ? "All clear! No pending payments. ✅" 
      : settlements.map(s => {
          const fromName = activeEvent.participants.find(p => p.id === s.from)?.name;
          const toName = activeEvent.participants.find(p => p.id === s.to)?.name;
          return `💸 *${fromName}* owes *${toName}*: ₹${s.amount.toFixed(2)}`;
        }).join('\n');

    return `💰 *SplitIt: ${activeEvent.name}*\n\n*Current Settlements:*\n${settlementText}\n\n🔗 Open trip and settle:\n${currentUniqueUrl}\n\nNo more awkward money talks! SplitIt handles it all for you.`;
  };

  const handleShareWhatsApp = () => {
    window.open(`https://api.whatsapp.com/send?text=${encodeURIComponent(getWhatsAppText())}`, '_blank');
  };

  const handleShareGmail = () => {
    const subject = `Expense Split for ${activeEvent?.name}`;
    window.open(`mailto:?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(getWhatsAppText())}`, '_blank');
  };

  const handleShareArattai = () => {
    if (navigator.share) {
      navigator.share({
        title: `SplitIt: ${activeEvent?.name}`,
        text: getWhatsAppText(),
        url: currentUniqueUrl
      }).catch(console.error);
    } else {
      alert("Sharing via Arattai is best supported on mobile. Please copy the link instead.");
    }
  };

  const handleCopyLink = () => {
    if (!currentUniqueUrl) return;
    navigator.clipboard.writeText(currentUniqueUrl).then(() => {
      setShareStatus('copied');
      setTimeout(() => setShareStatus('idle'), 2000);
    });
  };

  if (!isInitialized || isLoadingShared) {
    return (
      <div className="min-h-screen bg-[#f8fafc] flex flex-col items-center justify-center font-sans">
        <div className="w-12 h-12 border-4 border-slate-100 border-t-[#4f46e5] rounded-full animate-spin mb-4"></div>
        <p className="text-xs font-bold text-slate-400 uppercase tracking-widest animate-pulse">Fetching Trip...</p>
      </div>
    );
  }

  // Dashboard View
  if (!currentEventId) {
    return (
      <div className="min-h-screen bg-[#f8fafc] flex flex-col font-sans">
        <header className="bg-white border-b border-slate-100 p-6 sm:p-8 flex items-start justify-start">
          <div className="flex items-center gap-3 sm:gap-4">
             <div className="w-12 h-12 bg-[#4f46e5] rounded-2xl flex items-center justify-center text-white text-3xl shadow-lg shadow-indigo-100">
               <i className="fa-solid fa-receipt"></i>
             </div>
             <div className="flex flex-col items-start text-left">
               <h1 className="text-3xl font-black text-slate-900 tracking-tighter">SplitIt</h1>
               <p className="text-xs font-medium text-slate-400 lowercase -mt-1 tracking-tight">good times in, awkward math out.</p>
             </div>
          </div>
        </header>

        <main className="flex-1 max-w-5xl mx-auto w-full px-4 py-10 sm:py-20 space-y-12">
          <section className="bg-white rounded-[2.5rem] p-8 sm:p-16 shadow-2xl shadow-indigo-100/40 border border-slate-50 text-center space-y-10">
            <h2 className="text-4xl sm:text-5xl font-black text-slate-900 tracking-tight leading-tight">Start an Event</h2>
            <form onSubmit={createEvent} className="max-w-md mx-auto flex flex-col gap-4">
              <input 
                type="text" 
                value={newEventName}
                onChange={e => setNewEventName(e.target.value)}
                placeholder="Event Name (e.g. Goa Trip)"
                className="w-full px-8 py-5 rounded-3xl bg-slate-50 border-2 border-transparent focus:border-[#4f46e5] focus:bg-white text-lg font-bold transition-all outline-none shadow-inner"
              />
              <button type="submit" className="bg-[#4f46e5] text-white py-5 rounded-3xl font-black text-sm hover:bg-[#4338ca] transition-all shadow-xl active:scale-95 uppercase tracking-widest">Create an Event</button>
            </form>
          </section>

          {Object.keys(events).length > 0 && (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
              {(Object.values(events) as SplitEvent[]).sort((a,b)=>b.createdAt-a.createdAt).map(ev => (
                <div key={ev.id} onClick={()=>setCurrentEventId(ev.id)} className="bg-white p-6 rounded-[2rem] border border-slate-100 hover:shadow-xl transition-all cursor-pointer group">
                  <div className="flex justify-between items-start mb-4">
                    <div className="w-12 h-12 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center font-black">{ev.name.charAt(0)}</div>
                    <button onClick={(e)=>{e.stopPropagation(); deleteEvent(ev.id)}} className="text-slate-200 hover:text-red-500 transition-colors p-2"><i className="fa-solid fa-trash-can"></i></button>
                  </div>
                  <h4 className="text-xl font-black text-slate-800 line-clamp-1">{ev.name}</h4>
                  <p className="text-[10px] font-bold text-slate-400 uppercase mt-1 tracking-widest">{ev.participants.length} Members • ₹{ev.expenses.reduce((acc,curr)=>curr.category!=='Payment'?acc+curr.amount:acc,0).toFixed(0)}</p>
                </div>
              ))}
            </div>
          )}
        </main>
      </div>
    );
  }

  // Active Event View
  return (
    <div className="min-h-screen bg-[#f8fafc] text-slate-900 flex flex-col font-sans">
      <header className="bg-white border-b border-slate-100 sticky top-0 z-30 shadow-sm px-4">
        <div className="max-w-7xl mx-auto h-20 flex items-center justify-between gap-4">
          <div className="flex items-center gap-4 min-w-0">
            <button onClick={()=>setCurrentEventId(null)} className="w-10 h-10 rounded-xl hover:bg-slate-50 flex items-center justify-center text-slate-400"><i className="fa-solid fa-arrow-left"></i></button>
            <div className="min-w-0">
              <h1 className="text-lg font-black text-slate-900 truncate uppercase tracking-tight">{activeEvent.name}</h1>
              <p className="text-[9px] font-bold text-slate-400 tracking-widest uppercase -mt-0.5">SplitIt Safe</p>
            </div>
          </div>
          <nav className="flex bg-slate-100 p-1 rounded-xl">
            <button onClick={()=>setActiveTab('overview')} className={`px-4 py-2 rounded-lg text-xs font-black uppercase transition-all ${activeTab==='overview'?'bg-white text-indigo-600 shadow-sm':'text-slate-400'}`}>Overview</button>
            <button onClick={()=>setActiveTab('settlement')} className={`px-4 py-2 rounded-lg text-xs font-black uppercase transition-all ${activeTab==='settlement'?'bg-white text-indigo-600 shadow-sm':'text-slate-400'}`}>Settlement</button>
          </nav>
        </div>
      </header>

      <main className="flex-1 max-w-7xl mx-auto w-full px-4 py-8 space-y-8 animate-in fade-in duration-500">
        <div className="flex flex-col items-stretch justify-between bg-white px-8 py-6 rounded-[2rem] border border-slate-100 shadow-lg shadow-slate-100/50 gap-6 sm:flex-row sm:items-center">
          <div className="flex justify-around sm:justify-start gap-12 text-center sm:text-left">
            <div><span className="text-[8px] font-black text-slate-300 uppercase block mb-1">Spent</span><p className="text-3xl font-black">₹{totalSpent.toFixed(0)}</p></div>
            <div><span className="text-[8px] font-black text-slate-300 uppercase block mb-1">Squad</span><p className="text-3xl font-black">{activeEvent.participants.length}</p></div>
          </div>
          <button onClick={(e)=>openShareModal(e, activeEvent.id)} className="bg-[#4f46e5] text-white px-8 py-4 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-[#4338ca] shadow-lg active:scale-95 transition-all">Share with Squad</button>
        </div>

        {activeTab === 'overview' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
            {/* MOBILE-FIRST: Squad is order-1 (top) */}
            <div className="lg:col-span-3 order-1 lg:order-1">
              <ParticipantManager participants={activeEvent.participants} onAdd={addParticipant} onRemove={removeParticipant} />
            </div>

            {/* MOBILE-FIRST: History is order-3 (bottom) */}
            <div className="lg:col-span-5 space-y-6 order-3 lg:order-2">
              <div className="bg-white border border-slate-100 rounded-[2rem] p-4 min-h-[400px] shadow-sm overflow-hidden">
                <h2 className="text-xs font-black uppercase tracking-widest text-slate-400 p-4 border-b border-slate-50 mb-4 flex items-center gap-2">
                  <i className="fa-solid fa-clock-rotate-left"></i>History
                </h2>
                <div className="space-y-4 max-h-[600px] overflow-y-auto scrollbar-hide">
                  {activeEvent.expenses.length === 0 ? (
                    <div className="text-center py-20 text-slate-300 font-bold uppercase text-[10px]">No records found</div>
                  ) : (
                    activeEvent.expenses.sort((a,b)=>b.date-a.date).map(e => (
                      <div key={e.id} onClick={()=>setSelectedExpense(e)} className={`p-4 mx-2 rounded-2xl border transition-all cursor-pointer ${e.category==='Payment'?'bg-green-50/50 border-green-100 italic':'bg-white border-slate-50 hover:border-indigo-100 hover:bg-slate-50'}`}>
                        <div className="flex justify-between items-center">
                          <div className="min-w-0">
                            <p className="font-bold text-slate-800 truncate">{e.description}</p>
                            <p className="text-[9px] text-slate-400 font-bold uppercase">{activeEvent.participants.find(p=>p.id===e.payerId)?.name} paid</p>
                          </div>
                          <p className="font-black text-slate-900">₹{e.amount.toFixed(0)}</p>
                        </div>
                      </div>
                    ))
                  )}
                </div>
              </div>
            </div>

            {/* MOBILE-FIRST: Transaction form is order-2 (middle) */}
            <div className="lg:col-span-4 order-2 lg:order-3">
              <ExpenseForm participants={activeEvent.participants} onAdd={addExpense} />
            </div>
          </div>
        ) : (
          <SettlementView participants={activeEvent.participants} balances={balances} settlements={settlements} totalSpent={totalSpent} onSettle={handleSettle} />
        )}
      </main>

      {/* Sharing Modal */}
      {showShareModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md animate-in fade-in">
          <div className="bg-white rounded-[2.5rem] max-w-sm w-full shadow-2xl overflow-hidden animate-in zoom-in-95">
            <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
              <h3 className="text-xl font-black text-slate-800">Share with Squad</h3>
              <button onClick={()=>setShowShareModal(false)} className="text-slate-400 hover:text-slate-800"><i className="fa-solid fa-xmark"></i></button>
            </div>
            <div className="p-8 space-y-6">
              <div className="space-y-4">
                <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100 text-center relative group">
                  <p className="text-xs font-bold text-indigo-600 truncate pr-8">{currentUniqueUrl}</p>
                  <button onClick={handleCopyLink} className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-indigo-600"><i className={`fa-solid ${shareStatus==='copied'?'fa-check text-green-500':'fa-copy'}`}></i></button>
                </div>

                <div className="grid grid-cols-2 gap-3">
                  <button onClick={handleShareWhatsApp} className="flex flex-col items-center gap-2 p-5 bg-green-50 rounded-3xl hover:bg-green-100 transition-all">
                    <div className="w-12 h-12 bg-green-500 rounded-2xl flex items-center justify-center text-white text-2xl shadow-lg shadow-green-100"><i className="fa-brands fa-whatsapp"></i></div>
                    <span className="text-[10px] font-black uppercase text-green-700">WhatsApp</span>
                  </button>
                  <button onClick={handleShareGmail} className="flex flex-col items-center gap-2 p-5 bg-red-50 rounded-3xl hover:bg-red-100 transition-all">
                    <div className="w-12 h-12 bg-red-500 rounded-2xl flex items-center justify-center text-white text-2xl shadow-lg shadow-red-100"><i className="fa-solid fa-envelope"></i></div>
                    <span className="text-[10px] font-black uppercase text-red-700">Gmail</span>
                  </button>
                  <button onClick={handleShareArattai} className="flex flex-col items-center gap-2 p-5 bg-blue-50 rounded-3xl hover:bg-blue-100 transition-all">
                    <div className="w-12 h-12 bg-blue-500 rounded-2xl flex items-center justify-center text-white text-2xl shadow-lg shadow-blue-100"><i className="fa-solid fa-share-nodes"></i></div>
                    <span className="text-[10px] font-black uppercase text-blue-700">Arattai</span>
                  </button>
                  <button onClick={handleCopyLink} className={`flex flex-col items-center gap-2 p-5 rounded-3xl transition-all ${shareStatus==='copied'?'bg-green-100':'bg-slate-50 hover:bg-slate-100'}`}>
                    <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-white text-2xl shadow-lg ${shareStatus==='copied'?'bg-green-600':'bg-slate-800'}`}><i className={`fa-solid ${shareStatus==='copied'?'fa-check':'fa-link'}`}></i></div>
                    <span className="text-[10px] font-black uppercase text-slate-700">{shareStatus==='copied'?'Copied':'Copy Link'}</span>
                  </button>
                </div>

                <div className="pt-4 border-t border-slate-50">
                   <button 
                    onClick={handleShareToSupabase} 
                    disabled={shareStatus === 'saving'}
                    className="w-full flex items-center justify-center gap-2 bg-indigo-50 text-indigo-600 py-4 rounded-2xl font-black text-[10px] uppercase tracking-[0.2em] hover:bg-indigo-100 transition-all disabled:opacity-50"
                  >
                    {shareStatus === 'saving' ? <i className="fa-solid fa-spinner animate-spin"></i> : <i className="fa-solid fa-cloud-arrow-up"></i>}
                    {shareStatus === 'saving' ? 'Syncing...' : 'Sync to Cloud'}
                  </button>
