              </button>
              <button onClick={() => setShowShareModal(false)} className="w-full py-2 text-[10px] font-black text-slate-300 uppercase tracking-widest hover:text-slate-500 transition-colors">Dismiss</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

