                      </div>
                    </div>
                    <i className="fa-solid fa-chevron-right text-slate-200 group-hover:text-indigo-600 transition-colors"></i>
                  </div>
                ))}
              </div>
            </div>
          )}
        </main>
        <BrandingFooter />
      </div>
    );
