export const saveEventToCloud = async (event: SplitEvent) => {
  try {
    await setDoc(doc(db, "events", event.id), event);
  } catch (e) {
    console.warn("Cloud sync failed, check Firebase config.", e);
  }
};

export const subscribeToEvent = (eventId: string, callback: (event: SplitEvent) => void) => {
  return onSnapshot(doc(db, "events", eventId), (doc) => {
    if (doc.exists()) {
      callback(doc.data() as SplitEvent);
    }
  });
};

export const addParticipantCloud = async (eventId: string, participant: Participant) => {
  const eventRef = doc(db, "events", eventId);
  await updateDoc(eventRef, {
    participants: arrayUnion(participant)
  });
};

export const removeParticipantCloud = async (eventId: string, participant: Participant) => {
  const eventRef = doc(db, "events", eventId);
  await updateDoc(eventRef, {
    participants: arrayRemove(participant)
  });
};

export const addExpenseCloud = async (eventId: string, expense: Expense) => {
  const eventRef = doc(db, "events", eventId);
  await updateDoc(eventRef, {
    expenses: arrayUnion(expense)
  });
};

export const deleteExpenseCloud = async (eventId: string, expenses: Expense[]) => {
  const eventRef = doc(db, "events", eventId);
  await updateDoc(eventRef, { expenses });
};

import React, { useState, useMemo, useEffect } from 'react';
import LZString from 'lz-string';
import { Participant, Expense, SplitEvent } from './types.ts';
import ParticipantManager from './components/ParticipantManager.tsx';
import ExpenseForm from './components/ExpenseForm.tsx';
import SettlementView from './components/SettlementView.tsx';
