              </div>
            ) : (
              settlements.map((s, idx) => {
                const payer = getParticipant(s.from);
                const receiver = getParticipant(s.to);
                return (
                  <div key={idx} className="bg-white border border-slate-100 rounded-[2rem] p-4 sm:p-5 hover:border-indigo-100 transition-all space-y-5">
