                    <div className="flex items-center justify-between gap-1">
                       <div className="flex flex-col items-center gap-1.5 shrink-0 w-[80px]">
                          <img src={payer?.avatar} className="w-12 h-12 rounded-2xl shadow-sm border border-slate-100" />
                          <div className="text-center w-full px-1">
                            <p className="text-[10px] font-black text-slate-900 truncate leading-tight uppercase">{payer?.name}</p>
                            <span className="text-[7px] font-black text-red-500 bg-red-50 px-2 py-0.5 rounded-full block mt-0.5">OWES</span>
                          </div>
                       </div>

                       <div className="flex-1 flex flex-col items-center justify-center min-w-0">
                          <p className="text-2xl font-black text-slate-900 tracking-tighter mb-1">₹{s.amount.toFixed(0)}</p>
                          <div className="flex items-center w-full px-2 gap-1 opacity-20">
                             <div className="h-0.5 flex-1 bg-slate-400 rounded-full"></div>
                             <i className="fa-solid fa-chevron-right text-[7px] text-slate-900"></i>
                             <div className="h-0.5 flex-1 bg-slate-400 rounded-full"></div>
                          </div>
                       </div>

                       <div className="flex flex-col items-center gap-1.5 shrink-0 w-[80px]">
                          <img src={receiver?.avatar} className="w-12 h-12 rounded-2xl shadow-sm border border-slate-100" />
                          <div className="text-center w-full px-1">
                            <p className="text-[10px] font-black text-slate-900 truncate leading-tight uppercase">{receiver?.name}</p>
                            <span className="text-[7px] font-black text-green-500 bg-green-50 px-2 py-0.5 rounded-full block mt-0.5">GETS</span>
                          </div>
                       </div>
                    </div>

                    <div className="grid grid-cols-2 gap-2">
