                    <button onClick={openUpiApp} className="flex flex-col items-center justify-center gap-2 p-4 bg-slate-50 rounded-2xl border border-slate-100 active:scale-95 transition-all">
                      <div className="text-xl text-purple-600"><i className="fa-solid fa-mobile-screen-button"></i></div>
                      <span className="text-[8px] font-black uppercase text-slate-500">PhonePe</span>
