                      <div className="text-base text-indigo-600"><i className="fa-solid fa-at"></i></div>
                      <span className="text-[9px] font-black uppercase text-indigo-600">Enter UPI ID Manually</span>
                    </button>
                  </div>
                </>
              ) : (
                <div className="space-y-4">
                  <div className="space-y-2">
                    <label className="text-[9px] font-black uppercase tracking-widest text-slate-300 px-1">Recipient UPI</label>
                    <input type="text" autoFocus value={manualUpi} onChange={e => setManualUpi(e.target.value)} placeholder="username@bank" className="w-full px-5 py-3.5 rounded-xl bg-slate-50 border border-slate-100 text-sm font-bold outline-none" />
                  </div>
                  <div className="flex gap-2">
                    <button onClick={() => setShowUpiInput(false)} className="flex-1 py-3.5 bg-slate-100 rounded-xl font-black text-[9px] uppercase">Back</button>
                    <button onClick={openUpiApp} className="flex-[2] py-3.5 bg-indigo-600 text-white rounded-xl font-black text-[9px] uppercase">Proceed</button>
                  </div>
                </div>
              )}
              <button onClick={() => setPaymentModal(null)} className="w-full pt-3 text-[9px] font-black text-slate-300 uppercase tracking-widest text-center hover:text-slate-500 transition-colors">Dismiss</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default SettlementView;

import { initializeApp } from "firebase/app";
import { 
  getFirestore, 
  doc, 
  setDoc, 
  onSnapshot, 
  updateDoc,
  arrayUnion
} from "firebase/firestore";
import { SplitEvent, Participant, Expense } from "../types.ts";

// Note: Using a slightly more realistic placeholder to satisfy SDK validation
const firebaseConfig = {
  apiKey: "AIzaSySplitIt_RealTime_Sync_Key",
  authDomain: "splitit-sync-app.firebaseapp.com",
  projectId: "splitit-sync-app",
  storageBucket: "splitit-sync-app.appspot.com",
  messagingSenderId: "987654321",
  appId: "1:987654321:web:a1b2c3d4e5f6"
};

let db: any;
try {
  const app = initializeApp(firebaseConfig);
  db = getFirestore(app);
} catch (e) {
  console.warn("Firebase initialization failed. Running in local-only mode.", e);
}

export const saveEventToCloud = async (event: SplitEvent) => {
  if (!db) return;
  try {
    const eventRef = doc(db, "events", event.id);
    await setDoc(eventRef, event, { merge: true });
  } catch (e) {
    console.error("Cloud Save Error:", e);
  }
};

export const subscribeToEvent = (eventId: string, callback: (event: SplitEvent | null) => void) => {
  if (!db) return () => {};
  return onSnapshot(doc(db, "events", eventId), (snapshot) => {
    if (snapshot.exists()) {
      callback(snapshot.data() as SplitEvent);
    } else {
      callback(null);
    }
  }, (error) => {
    console.warn("Firestore subscription inactive:", error.message);
  });
};

export const addParticipantCloud = async (eventId: string, participant: Participant) => {
  if (!db) return;
  const eventRef = doc(db, "events", eventId);
  await updateDoc(eventRef, {
    participants: arrayUnion(participant)
  });
};

export const addExpenseCloud = async (eventId: string, expense: Expense) => {
