import { createClient } from '@supabase/supabase-js';
import { SplitEvent, Participant, Expense } from '../types.ts';

// These would normally be in your environment variables
const SUPABASE_URL = 'https://your-project-url.supabase.co';
const SUPABASE_ANON_KEY = 'your-anon-key';

export const supabase = createClient(SUPABASE_URL, SUPABASE_ANON_KEY);

export const createEvent = async (name: string, shortCode: string): Promise<string> => {
  const { data, error } = await supabase
    .from('events')
    .insert([{ name, short_code: shortCode }])
    .select()
    .single();

  if (error) throw error;
  return data.id;
};

export const fetchEventByCode = async (shortCode: string) => {
  // Fetch event, then participants, then expenses in a single "flow"
  const { data: event, error: eventError } = await supabase
    .from('events')
    .select('id, name, short_code, created_at')
    .eq('short_code', shortCode)
    .single();

  if (eventError || !event) return null;

  const { data: participants } = await supabase
    .from('participants')
