import React, { useState, useMemo, useEffect } from 'react';
import { Participant, Expense, SplitEvent } from './types.ts';
import ParticipantManager from './components/ParticipantManager.tsx';
import ExpenseForm from './components/ExpenseForm.tsx';
import SettlementView from './components/SettlementView.tsx';
import { calculateBalances, calculateSettlements } from './utils/calculation.ts';
import * as db from './services/supabaseService.ts';

const generateShortId = () => {
  const chars = 'abcdefghijklmnopqrstuvwxyz0123456789';
  let result = '';
  for (let i = 0; i < 6; i++) {
    result += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return result;
};

const App: React.FC = () => {
  const [activeEvent, setActiveEvent] = useState<SplitEvent | null>(null);
  const [path, setPath] = useState(window.location.pathname);
  const [isInitialized, setIsInitialized] = useState(false);
  const [loading, setLoading] = useState(false);
  const [newEventName, setNewEventName] = useState('');
  const [shareStatus, setShareStatus] = useState<'idle' | 'copied'>('idle');
  const [showShareModal, setShowShareModal] = useState(false);
  const [selectedExpense, setSelectedExpense] = useState<Expense | null>(null);
  const [recentCodes, setRecentCodes] = useState<string[]>([]);

  const navigate = (to: string) => {
    window.history.pushState(null, "", to);
    setPath(to);
    window.scrollTo(0, 0);
  };

  const routeMatch = useMemo(() => {
    if (path === '/' || path === '') return { type: 'home' };
    if (path === '/create') return { type: 'create' };
    const eventMatch = path.match(/^\/event\/([a-z0-9]{6})(\/settlement)?$/);
    if (eventMatch) {
      return { 
        type: 'event', 
        code: eventMatch[1], 
        tab: eventMatch[2] === '/settlement' ? 'settlement' : 'squad' 
      };
    }
    return { type: 'home' };
  }, [path]);

  useEffect(() => {
    const saved = localStorage.getItem('splitit_recent_codes');
    if (saved) setRecentCodes(JSON.parse(saved));
  }, []);

  const addToRecent = (code: string) => {
    const updated = [code, ...recentCodes.filter(c => c !== code)].slice(0, 5);
    setRecentCodes(updated);
    localStorage.setItem('splitit_recent_codes', JSON.stringify(updated));
  };

  const loadData = async (code: string) => {
    setLoading(true);
    const data = await db.fetchEventByCode(code);
    if (data) {
      setActiveEvent(data);
      addToRecent(code);
    }
    setLoading(false);
  };

  useEffect(() => {
    if (routeMatch.type === 'event') {
      loadData(routeMatch.code);
    } else {
      setActiveEvent(null);
    }
    setIsInitialized(true);
  }, [routeMatch.code, routeMatch.type]);

  useEffect(() => {
    if (activeEvent?.id && routeMatch.type === 'event') {
      return db.subscribeToChanges(activeEvent.id, () => loadData(routeMatch.code));
    }
  }, [activeEvent?.id]);

  const { balances, settlements, totalSpent } = useMemo(() => {
    if (!activeEvent) return { balances: [], settlements: [], totalSpent: 0 };
    const safeBals = calculateBalances(activeEvent.participants, activeEvent.expenses);
    const setts = calculateSettlements(safeBals);
    const total = activeEvent.expenses.reduce((acc, curr) => curr.category !== 'Payment' ? acc + curr.amount : acc, 0);
    return { balances: safeBals, settlements: setts, totalSpent: total };
  }, [activeEvent]);

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newEventName.trim()) return;
    const code = generateShortId();
    await db.createEvent(newEventName.trim(), code);
    navigate(`/event/${code}`);
  };

  const handleAddParticipant = async (name: string, upiId?: string) => {
    if (!activeEvent) return;
    await db.addParticipant(activeEvent.id, { 
      name, 
      upiId, 
      avatar: `https://api.dicebear.com/7.x/initials/svg?seed=${name}&backgroundColor=4f46e5&textColor=ffffff` 
    });
    loadData(routeMatch.code); // Manual refresh
  };

  const handleAddExpense = async (exp: Omit<Expense, 'id'>) => {
    if (!activeEvent) return;
    await db.addExpense(activeEvent.id, exp);
    loadData(routeMatch.code); // Manual refresh
  };

  const handleShare = (type: 'whatsapp' | 'sms' | 'copy') => {
    const url = window.location.origin + `/event/${routeMatch.code}`;
    const text = `Join my event "${activeEvent?.name}" on SplitIt to track expenses together: ${url}`;

    if (type === 'whatsapp') {
      window.open(`https://wa.me/?text=${encodeURIComponent(text)}`, '_blank');
    } else if (type === 'sms') {
      window.open(`sms:?body=${encodeURIComponent(text)}`, '_blank');
    } else {
      navigator.clipboard.writeText(url);
      setShareStatus('copied');
      setTimeout(() => setShareStatus('idle'), 2000);
    }
  };

  if (!isInitialized) return null;

  if (routeMatch.type === 'home') {
    return (
      <div className="min-h-screen bg-white flex flex-col font-sans animate-in overflow-hidden relative">
        <header className="p-8 absolute top-0 left-0 z-10">
          <div className="flex items-center gap-3 cursor-pointer" onClick={() => navigate('/')}>
            <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white text-xl shadow-lg shadow-indigo-100">
              <i className="fa-solid fa-receipt"></i>
            </div>
            <div>
              <h1 className="text-xl font-black text-slate-900 tracking-tighter">splitIt</h1>
              <p className="text-[9px] font-bold text-slate-400 lowercase tracking-tight -mt-1 leading-none">
                trips end. memories stay. debts don’t.
              </p>
            </div>
          </div>
        </header>

        <main className="flex-1 flex flex-col items-center justify-center px-6 max-w-4xl mx-auto w-full text-center space-y-12">
          <div className="space-y-6">
            <h1 className="text-[56px] sm:text-[90px] font-[900] text-slate-900 tracking-tighter leading-[0.95] max-w-2xl mx-auto">
              Stop doing <span className="text-indigo-600 italic">awkward</span> math.
            </h1>
            <p className="text-lg sm:text-2xl font-medium text-slate-400 max-w-lg mx-auto leading-relaxed">
              The cleanest way to split bills, track group expenses, and settle debts instantly with the squad.
            </p>
          </div>

          <div className="flex flex-col items-center gap-10">
            <div className="relative group">
              <div className="absolute -inset-1 bg-gradient-to-r from-indigo-500 to-purple-600 rounded-full blur opacity-25 group-hover:opacity-40 transition duration-1000 group-hover:duration-200"></div>
              <button 
                onClick={() => navigate('/create')}
                className="relative px-12 py-6 bg-indigo-600 text-white rounded-full font-black text-sm uppercase tracking-widest shadow-2xl active:scale-95 transition-all hover:bg-indigo-700"
              >
                Start an Event
              </button>
            </div>

            {recentCodes.length > 0 && (
              <div className="space-y-4 animate-in">
                <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Recently Visited</p>
                <div className="flex flex-wrap justify-center gap-3">
                  {recentCodes.map(code => (
                    <button 
                      key={code} 
                      onClick={() => navigate(`/event/${code}`)}
                      className="px-5 py-2.5 bg-slate-50 border border-slate-100 rounded-xl text-[10px] font-bold text-slate-600 hover:bg-white hover:border-indigo-100 hover:shadow-sm transition-all"
                    >
                      Code: {code.toUpperCase()}
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>
        </main>
      </div>
    );
  }

  if (routeMatch.type === 'create') {
    return (
      <div className="min-h-screen bg-[#f8fafc] flex flex-col items-center justify-center px-6 animate-in">
        <div className="max-w-md w-full bg-white rounded-[3rem] p-10 shadow-2xl shadow-indigo-100/50 border border-slate-50 space-y-8 text-center">
          <div className="w-16 h-16 bg-indigo-600 rounded-2xl flex items-center justify-center text-white text-3xl mx-auto shadow-lg"><i className="fa-solid fa-receipt"></i></div>
          <div className="space-y-2">
            <h2 className="text-3xl font-black text-slate-900 tracking-tight">Name your squad</h2>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.2em]">What are we splitting today?</p>
          </div>
          <form onSubmit={handleCreate} className="space-y-4">
            <input 
              type="text" 
              autoFocus
              value={newEventName}
              onChange={e => setNewEventName(e.target.value)}
              placeholder="e.g. Goa Trip 2025"
              className="w-full px-8 py-5 rounded-3xl bg-slate-50 border-2 border-transparent focus:border-indigo-600 focus:bg-white text-lg font-bold transition-all outline-none"
            />
            <button type="submit" className="w-full bg-indigo-600 text-white py-5 rounded-3xl font-black text-sm uppercase tracking-widest shadow-xl hover:bg-indigo-700 active:scale-95 transition-all">Create Event</button>
            <button type="button" onClick={() => navigate('/')} className="w-full py-2 text-[10px] font-black text-slate-300 uppercase">Cancel</button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#f8fafc] text-slate-900 flex flex-col font-sans">
      <header className="bg-white border-b border-slate-100 sticky top-0 z-40 px-4 h-20 shadow-sm">
        <div className="max-w-7xl mx-auto h-full flex items-center justify-between gap-2">
          <div className="flex items-center gap-2 min-w-0">
            <button onClick={()=>navigate('/')} className="w-9 h-9 rounded-xl hover:bg-slate-50 flex items-center justify-center text-slate-400 shrink-0 transition-colors"><i className="fa-solid fa-arrow-left"></i></button>
            <div className="min-w-0">
              <h1 className="text-sm font-black truncate uppercase tracking-tight">{activeEvent?.name || 'Loading...'}</h1>
              <p className="text-[8px] font-bold text-slate-400 uppercase tracking-widest">{routeMatch.code}</p>
            </div>
          </div>
          <nav className="flex bg-slate-100 p-1 rounded-xl shrink-0">
            <button onClick={()=>navigate(`/event/${routeMatch.code}`)} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${routeMatch.tab==='squad'?'bg-white text-indigo-600 shadow-sm':'text-slate-400'}`}>SQUAD</button>
            <button onClick={()=>navigate(`/event/${routeMatch.code}/settlement`)} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${routeMatch.tab==='settlement'?'bg-white text-indigo-600 shadow-sm':'text-slate-400'}`}>SETTLEMENT</button>
          </nav>
        </div>
      </header>

      {loading && !activeEvent ? (
        <div className="flex-1 flex flex-col items-center justify-center space-y-4">
          <div className="w-10 h-10 border-4 border-indigo-100 border-t-indigo-600 rounded-full animate-spin"></div>
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Hydrating...</p>
        </div>
      ) : activeEvent && (
        <main className="flex-1 max-w-7xl mx-auto w-full px-4 py-6 space-y-6 animate-in pb-10">
          <div className="bg-white px-6 py-5 rounded-[2rem] border border-slate-100 shadow-xl flex flex-col sm:flex-row justify-between items-center gap-6">
            <div className="flex gap-10 text-center sm:text-left">
              <div><span className="text-[8px] font-black text-slate-300 uppercase block mb-1">Spent</span><p className="text-2xl font-black">₹{totalSpent.toFixed(0)}</p></div>
              <div><span className="text-[8px] font-black text-slate-300 uppercase block mb-1">Squad</span><p className="text-2xl font-black">{activeEvent.participants.length}</p></div>
            </div>
            <button onClick={()=>setShowShareModal(true)} className="w-full sm:w-auto bg-indigo-600 text-white px-8 py-4 rounded-2xl font-black text-[11px] uppercase tracking-widest shadow-lg shadow-indigo-100 active:scale-95 transition-all">Share with Squad</button>
          </div>

          {routeMatch.tab === 'squad' ? (
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
              <div className="lg:col-span-4 order-1">
                <ParticipantManager 
                  participants={activeEvent.participants} 
                  onAdd={handleAddParticipant} 
                  onRemove={(id) => db.deleteParticipant(id)} 
                />
              </div>
              <div className="lg:col-span-4 order-2">
                <ExpenseForm 
                  participants={activeEvent.participants} 
                  onAdd={handleAddExpense} 
                />
              </div>
              <div className="lg:col-span-4 order-3 space-y-6">
                <div className="bg-white border border-slate-100 rounded-[2rem] p-6 shadow-sm">
                  <h3 className="text-[10px] font-black uppercase tracking-widest text-slate-400 mb-6 text-center lg:text-left">Activity Feed</h3>
                  <div className="space-y-3 max-h-[400px] overflow-y-auto scrollbar-hide">
                    {activeEvent.expenses.length === 0 ? <div className="text-center py-10 text-slate-200 font-black text-[10px] uppercase">No activity yet</div> : activeEvent.expenses.sort((a,b)=>b.date-a.date).map(e => (
                      <div key={e.id} onClick={() => setSelectedExpense(e)} className={`p-4 rounded-2xl border transition-all cursor-pointer ${e.category==='Payment'?'bg-green-50/50 border-green-100 italic':'bg-white border-slate-50 hover:border-indigo-100'}`}>
                        <div className="flex justify-between items-center gap-2">
                          <div className="min-w-0 flex-1">
                            <p className="font-black text-slate-800 text-sm truncate">{e.description}</p>
                            <p className="text-[9px] text-slate-400 font-bold uppercase tracking-tighter">{activeEvent.participants.find(p=>p.id===e.payerId)?.name || 'Member'} paid</p>
                          </div>
                          <p className="font-black text-slate-900 text-sm">₹{Number(e.amount).toFixed(0)}</p>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </div>
          ) : (
            <SettlementView 
              participants={activeEvent.participants} 
              balances={balances} 
              settlements={settlements} 
              totalSpent={totalSpent} 
              onSettle={(f, t, a) => db.addExpense(activeEvent.id, { description: `Settlement Record`, amount: a, payerId: f, participantIds: [t], category: 'Payment', date: Date.now() })}
            />
          )}
        </main>
      )}

      {showShareModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/70 backdrop-blur-md animate-in">
          <div className="bg-white rounded-[2.5rem] max-w-sm w-full shadow-2xl p-8 text-center space-y-6">
            <div className="w-16 h-16 bg-indigo-600 rounded-2xl flex items-center justify-center text-white text-2xl mx-auto shadow-lg"><i className="fa-solid fa-users-viewfinder"></i></div>
            <h3 className="text-xl font-black">Share with Squad</h3>
            <p className="text-xs text-slate-500 font-medium leading-relaxed">Let everyone add their own expenses in real-time.</p>

            <div className="grid grid-cols-1 gap-3">
              <button onClick={() => handleShare('whatsapp')} className="w-full flex items-center justify-center gap-3 py-4 bg-green-500 text-white rounded-2xl font-black text-xs uppercase tracking-widest active:scale-95 transition-all">
                <i className="fa-brands fa-whatsapp text-lg"></i> WhatsApp
              </button>
              <button onClick={() => handleShare('sms')} className="w-full flex items-center justify-center gap-3 py-4 bg-indigo-500 text-white rounded-2xl font-black text-xs uppercase tracking-widest active:scale-95 transition-all">
                <i className="fa-solid fa-comment-sms text-lg"></i> Text Message
              </button>
              <button onClick={() => handleShare('copy')} className={`w-full flex items-center justify-center gap-3 py-4 rounded-2xl font-black text-xs uppercase tracking-widest transition-all ${shareStatus==='copied' ? 'bg-slate-900 text-white' : 'bg-slate-100 text-slate-900'}`}>
                {shareStatus==='copied' ? <><i className="fa-solid fa-check"></i> Copied</> : <><i className="fa-solid fa-link"></i> Copy Link</>}
              </button>
            </div>

            <button onClick={() => setShowShareModal(false)} className="w-full py-2 text-[10px] font-black text-slate-300 uppercase">Close</button>
          </div>
        </div>
      )}

      {selectedExpense && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/70 backdrop-blur-md">
          <div className="bg-white rounded-[2rem] max-w-sm w-full p-8 space-y-6 shadow-2xl animate-in">
            <div className="flex justify-between items-center"><h3 className="text-lg font-black">Expense Detail</h3><button onClick={()=>setSelectedExpense(null)} className="p-2"><i className="fa-solid fa-xmark"></i></button></div>
            <div className="space-y-4 pt-4 border-t border-slate-50">
              <div className="flex justify-between items-center"><span className="text-[10px] font-black text-slate-300 uppercase">Label</span><span className="font-bold text-sm truncate max-w-[150px] text-right">{selectedExpense.description}</span></div>
              <div className="flex justify-between items-center"><span className="text-[10px] font-black text-slate-300 uppercase">Amount</span><span className="font-black text-indigo-600 text-xl">₹{Number(selectedExpense.amount).toFixed(0)}</span></div>
            </div>
            <button onClick={() => db.deleteExpense(selectedExpense.id).then(() => setSelectedExpense(null))} className="w-full py-4 bg-red-50 text-red-500 font-black text-[11px] uppercase rounded-2xl border border-red-100 transition-all hover:bg-red-100">
              <i className="fa-solid fa-trash-can mr-2"></i>Delete Record
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Participant, Settlement, Balance } from '../types.ts';
import { ResponsiveContainer, BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Cell } from 'recharts';

interface Props {
  participants: Participant[];
  balances: Balance[];
  settlements: Settlement[];
  totalSpent: number;
  onSettle: (fromId: string, toId: string, amount: number) => void;
}

const SettlementView: React.FC<Props> = ({ participants, balances, settlements, totalSpent, onSettle }) => {
  const [paymentModal, setPaymentModal] = useState<{ settlement: Settlement; show: boolean } | null>(null);
  const [showUpiInput, setShowUpiInput] = useState(false);
  const [manualUpi, setManualUpi] = useState('');

  const getParticipant = (id: string) => participants.find(p => p.id === id);
  const getParticipantName = (id: string) => getParticipant(id)?.name || 'Member';

  const handleWhatsAppReminder = (s: Settlement) => {
    const payer = getParticipant(s.from);
    const payee = getParticipant(s.to);
    if (!payer || !payee) return;
    const msg = `Hey ${payer.name}, split our bills on SplitIt! 💸 You owe me *₹${s.amount.toFixed(0)}*.\n${payee.upiId ? `\nMy UPI: ${payee.upiId}` : ''}\n\nThanks! 👋`;
    window.open(`https://wa.me/?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const openUpiApp = () => {
    if (!paymentModal) return;
    const payee = getParticipant(paymentModal.settlement.to);
    const upi = manualUpi || payee?.upiId;
    if (!upi) {
      setShowUpiInput(true);
      return;
    }
    const link = `upi://pay?pa=${upi}&pn=${encodeURIComponent(payee?.name || 'User')}&am=${paymentModal.settlement.amount.toFixed(2)}&cu=INR`;
    window.location.href = link;
  };

  const chartData = balances.map(b => ({
    name: getParticipantName(b.participantId),
    value: b.amount
  }));

  return (
    <div className="space-y-6 animate-in pb-10">
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white rounded-[2rem] p-5 sm:p-8 shadow-xl shadow-slate-100/30 border border-slate-50">
          <div className="flex items-center gap-3 mb-8">
            <div className="w-10 h-10 bg-indigo-50 text-indigo-600 rounded-xl flex items-center justify-center"><i className="fa-solid fa-hand-holding-dollar text-lg"></i></div>
            <div>
              <h2 className="text-lg font-black tracking-tight">Settle Expenses</h2>
              <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">Clear your dues</p>
            </div>
          </div>

          <div className="space-y-4">
            {settlements.length === 0 ? (
              <div className="text-center py-20 bg-slate-50/50 rounded-[2rem] border-2 border-dashed border-slate-100">
                <p className="text-slate-300 font-black text-[10px] uppercase tracking-widest">All settled up! 🥂</p>
              </div>
            ) : (
              settlements.map((s, idx) => {
                const payer = getParticipant(s.from);
                const receiver = getParticipant(s.to);
                return (
                  <div key={idx} className="bg-white border border-slate-100 rounded-2xl p-4 sm:p-6 hover:border-indigo-100 transition-all space-y-4 shadow-sm">
                    <div className="flex items-center justify-between">
                       <div className="flex items-center gap-3 min-w-0">
                          <img src={payer?.avatar} className="w-10 h-10 rounded-xl bg-slate-50 border border-slate-100" />
                          <div className="min-w-0">
                            <p className="text-[11px] font-black text-slate-900 truncate uppercase tracking-tight">{payer?.name}</p>
                            <p className="text-[8px] font-bold text-slate-400 uppercase">Owes</p>
                          </div>
                       </div>

                       <div className="px-3 text-center">
                          <i className="fa-solid fa-arrow-right text-slate-200 text-xs"></i>
                       </div>

                       <div className="flex items-center gap-3 min-w-0 flex-row-reverse text-right">
                          <img src={receiver?.avatar} className="w-10 h-10 rounded-xl bg-slate-50 border border-slate-100" />
                          <div className="min-w-0">
                            <p className="text-[11px] font-black text-slate-900 truncate uppercase tracking-tight">{receiver?.name}</p>
                            <p className="text-[8px] font-bold text-slate-400 uppercase">Receive</p>
                          </div>
                       </div>
                    </div>

                    <div className="py-2 text-center border-y border-slate-50">
                       <p className="text-2xl font-black text-indigo-600">₹{s.amount.toFixed(0)}</p>
                    </div>

                    <div className="grid grid-cols-2 gap-2 pt-1">
                      <button onClick={() => {setPaymentModal({settlement: s, show: true}); setShowUpiInput(false);}} className="bg-indigo-600 text-white py-3.5 rounded-xl font-black text-[10px] uppercase tracking-widest shadow-md active:scale-95 transition-all">Make Payment</button>
                      <button onClick={() => handleWhatsAppReminder(s)} className="bg-green-50 text-green-600 py-3.5 rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-green-100 transition-all border border-green-100 active:scale-95">Request via WhatsApp</button>
                      <button onClick={() => onSettle(s.from, s.to, s.amount)} className="col-span-2 py-3 text-[9px] font-black text-slate-400 uppercase tracking-widest text-center hover:bg-slate-50 rounded-xl border border-dashed border-slate-100">Settle it Manually</button>
                    </div>
                  </div>
                );
              })
            )}
          </div>
        </div>

        <div className="bg-white rounded-[2rem] p-5 sm:p-8 shadow-xl shadow-slate-100/30 border border-slate-50 flex flex-col">
          <div className="flex items-center gap-3 mb-8">
            <div className="w-10 h-10 bg-indigo-50 text-indigo-600 rounded-xl flex items-center justify-center"><i className="fa-solid fa-chart-simple text-lg"></i></div>
            <div>
              <h2 className="text-lg font-black tracking-tight">Balances</h2>
              <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">Squad Standing</p>
            </div>
          </div>
          <div className="flex-1 min-h-[300px]">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData} layout="vertical" margin={{ left: 10, right: 30, top: 0, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" horizontal={false} stroke="#f1f5f9" />
                <XAxis type="number" hide />
                <YAxis dataKey="name" type="category" width={80} axisLine={false} tickLine={false} tick={{ fontSize: 9, fontWeight: 900, fill: '#64748b' }} />
                <Tooltip cursor={{ fill: 'transparent' }} contentStyle={{ borderRadius: '1rem', border: 'none', background: '#1e293b', color: '#fff', fontSize: '9px', fontWeight: 'bold' }} />
                <Bar dataKey="value" radius={[0, 6, 6, 0]} barSize={20}>
                  {chartData.map((e, i) => <Cell key={i} fill={e.value >= 0 ? '#10b981' : '#ef4444'} />)}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {paymentModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/70 backdrop-blur-md animate-in">
          <div className="bg-white rounded-[2.5rem] max-w-sm w-full shadow-2xl overflow-hidden">
            <div className="p-8 border-b border-slate-50 text-center bg-slate-50/50">
               <span className="text-[9px] font-black text-indigo-500 uppercase tracking-[0.3em] mb-3 block text-center">PAYMENT PORTAL</span>
               <h3 className="text-4xl font-black text-slate-900 tracking-tighter text-center">₹{paymentModal.settlement.amount.toFixed(0)}</h3>
               <p className="text-xs font-bold text-slate-500 mt-3 uppercase text-center">To: {getParticipantName(paymentModal.settlement.to)}</p>
            </div>

            <div className="p-6 space-y-3">
              {!showUpiInput ? (
                <>
                  <div className="grid grid-cols-2 gap-2">
                    <button onClick={openUpiApp} className="flex flex-col items-center justify-center gap-2 p-5 bg-slate-50 rounded-2xl border border-slate-100 active:scale-95 transition-all hover:bg-slate-100">
                      <div className="text-xl text-slate-900"><i className="fa-brands fa-google-pay"></i></div>
                      <span className="text-[8px] font-black uppercase text-slate-500">Google Pay</span>
                    </button>
                    <button onClick={openUpiApp} className="flex flex-col items-center justify-center gap-2 p-5 bg-slate-50 rounded-2xl border border-slate-100 active:scale-95 transition-all hover:bg-slate-100">
                      <div className="text-xl text-purple-600"><i className="fa-solid fa-mobile-screen-button"></i></div>
                      <span className="text-[8px] font-black uppercase text-slate-500">PhonePe</span>
                    </button>
                    <button onClick={() => setShowUpiInput(true)} className="col-span-2 flex items-center justify-center gap-2 p-4 bg-indigo-50 rounded-xl border border-indigo-100 active:scale-95 transition-all">
                      <div className="text-base text-indigo-600"><i className="fa-solid fa-at"></i></div>
                      <span className="text-[9px] font-black uppercase text-indigo-600">Enter UPI ID Manually</span>
                    </button>
                  </div>
                </>
              ) : (
                <div className="space-y-4 animate-in">
                  <div className="space-y-2">
                    <label className="text-[9px] font-black uppercase tracking-widest text-slate-300 px-1">Recipient VPA</label>
                    <input type="text" autoFocus value={manualUpi} onChange={e => setManualUpi(e.target.value)} placeholder="username@upi" className="w-full px-5 py-3.5 rounded-xl bg-slate-50 border border-slate-100 text-sm font-bold outline-none" />
                  </div>
                  <div className="flex gap-2">
                    <button onClick={() => setShowUpiInput(false)} className="flex-1 py-4 bg-slate-100 rounded-xl font-black text-[9px] uppercase tracking-widest">Back</button>
                    <button onClick={openUpiApp} className="flex-[2] py-4 bg-indigo-600 text-white rounded-xl font-black text-[9px] uppercase tracking-widest shadow-lg">Proceed</button>
                  </div>
                </div>
              )}
              <button onClick={() => setPaymentModal(null)} className="w-full pt-4 text-[9px] font-black text-slate-300 uppercase tracking-widest text-center hover:text-slate-500 transition-colors">Dismiss</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default SettlementView;

import React, { useState } from 'react';
import { Participant } from '../types.ts';

interface Props {
  participants: Participant[];
  onAdd: (name: string, upiId?: string) => Promise<void>;
  onRemove: (id: string) => void;
}

const ParticipantManager: React.FC<Props> = ({ participants, onAdd, onRemove }) => {
  const [name, setName] = useState('');
  const [upiId, setUpiId] = useState('');
  const [isAdding, setIsAdding] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (name.trim() && !isAdding) {
      setIsAdding(true);
      try {
        await onAdd(name.trim(), upiId.trim() || undefined);
        setName('');
        setUpiId('');
      } finally {
        setIsAdding(false);
      }
    }
  };

  return (
    <div className="bg-white rounded-3xl p-6 shadow-sm border border-slate-100">
      <div className="flex items-center gap-2 text-[#1e293b] mb-6 justify-center lg:justify-start">
        <i className="fa-solid fa-users text-[#4f46e5]"></i>
        <h2 className="text-lg font-bold">The Squad</h2>
      </div>

      <form onSubmit={handleSubmit} className="space-y-4">
        <div className="flex flex-col gap-1">
          <label className="text-[9px] font-black uppercase tracking-widest text-slate-400 px-1">Member Name</label>
          <input
            type="text"
            required
            value={name}
            onChange={(e) => setName(e.target.value)}
            placeholder="e.g. Rahul, Priya"
            className="w-full px-5 py-4 rounded-2xl bg-slate-50 border border-slate-100 text-sm font-medium focus:outline-none focus:border-[#4f46e5] focus:bg-white transition-all placeholder:text-slate-300"
          />
        </div>
        <div className="flex flex-col gap-1">
          <label className="text-[9px] font-black uppercase tracking-widest text-slate-400 px-1">UPI ID (Optional)</label>
          <input
            type="text"
            value={upiId}
            onChange={(e) => setUpiId(e.target.value)}
            placeholder="e.g. rahul@okaxis"
            className="w-full px-5 py-4 rounded-2xl bg-slate-50 border border-slate-100 text-sm font-medium focus:outline-none focus:border-[#4f46e5] focus:bg-white transition-all placeholder:text-slate-300"
          />
        </div>
        <button
          type="submit"
          disabled={isAdding}
          className="w-full bg-[#4f46e5] text-white px-5 py-5 rounded-2xl font-black text-xs uppercase tracking-[0.15em] hover:bg-[#4338ca] transition-all shadow-md active:scale-95 disabled:opacity-50"
        >
          {isAdding ? <i className="fa-solid fa-spinner animate-spin"></i> : "Add to Squad"}
        </button>
      </form>

      <div className="mt-8 space-y-2 overflow-y-auto max-h-[300px] pr-1 scrollbar-hide">
        {participants.length === 0 ? (
          <p className="text-[9px] font-black text-slate-300 uppercase tracking-[0.2em] text-center py-10">
            SQUAD IS EMPTY
          </p>
        ) : (
          participants.map(p => (
            <div key={p.id} className="flex items-center justify-between group p-3 rounded-2xl hover:bg-slate-50 border border-transparent hover:border-slate-100 transition-all">
              <div className="flex items-center gap-3 min-w-0">
                <img src={p.avatar} alt={p.name} className="w-9 h-9 rounded-xl bg-slate-100 shadow-sm shrink-0" />
                <div className="min-w-0">
                  <p className="font-black text-sm text-[#1e293b] truncate leading-tight">{p.name}</p>
                  {p.upiId && <p className="text-[9px] text-slate-400 font-bold truncate tracking-tight">{p.upiId}</p>}
                </div>
              </div>
              <button
                onClick={() => onRemove(p.id)}
                className="text-slate-300 hover:text-red-500 p-2 shrink-0 transition-colors"
              >
                <i className="fa-solid fa-circle-xmark text-lg"></i>
              </button>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default ParticipantManager;

import React, { useState, useMemo, useEffect } from 'react';
import { Participant, Expense, SplitEvent } from './types.ts';
import ParticipantManager from './components/ParticipantManager.tsx';
import ExpenseForm from './components/ExpenseForm.tsx';
import SettlementView from './components/SettlementView.tsx';
import { calculateBalances, calculateSettlements } from './utils/calculation.ts';
import * as db from './services/supabaseService.ts';

interface RecentEvent {
  code: string;
  name: string;
}

const generateShortId = () => {
  const chars = 'abcdefghijklmnopqrstuvwxyz0123456789';
  let result = '';
  for (let i = 0; i < 6; i++) {
    result += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return result;
};

const App: React.FC = () => {
  const [activeEvent, setActiveEvent] = useState<SplitEvent | null>(null);
  const [path, setPath] = useState(window.location.pathname);
  const [isInitialized, setIsInitialized] = useState(false);
  const [loading, setLoading] = useState(false);
  const [newEventName, setNewEventName] = useState('');
  const [shareStatus, setShareStatus] = useState<'idle' | 'copied'>('idle');
  const [showShareModal, setShowShareModal] = useState(false);
  const [selectedExpense, setSelectedExpense] = useState<Expense | null>(null);
  const [recentEvents, setRecentEvents] = useState<RecentEvent[]>([]);

  const navigate = (to: string) => {
    window.history.pushState(null, "", to);
    setPath(to);
    window.scrollTo(0, 0);
  };

  const routeMatch = useMemo(() => {
    if (path === '/' || path === '') return { type: 'home' };
    if (path === '/create') return { type: 'create' };
    const eventMatch = path.match(/^\/event\/([a-z0-9]{6})(\/settlement)?$/);
    if (eventMatch) {
      return { 
        type: 'event', 
        code: eventMatch[1], 
        tab: eventMatch[2] === '/settlement' ? 'settlement' : 'squad' 
      };
    }
    return { type: 'home' };
  }, [path]);

  useEffect(() => {
    const saved = localStorage.getItem('splitit_recent_events_v2');
    if (saved) setRecentEvents(JSON.parse(saved));
  }, []);

  const addToRecent = (code: string, name: string) => {
    setRecentEvents(prev => {
      const filtered = prev.filter(e => e.code !== code);
      const updated = [{ code, name }, ...filtered].slice(0, 5);
      localStorage.setItem('splitit_recent_events_v2', JSON.stringify(updated));
      return updated;
    });
  };

  const loadData = async (code: string) => {
    setLoading(true);
    try {
      const data = await db.fetchEventByCode(code);
      if (data) {
        setActiveEvent(data);
        addToRecent(code, data.name);
      }
    } catch (err) {
      console.error("Failed to load event:", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (routeMatch.type === 'event') {
      loadData(routeMatch.code);
    } else {
      setActiveEvent(null);
    }
    setIsInitialized(true);
  }, [routeMatch.code, routeMatch.type]);

  useEffect(() => {
    if (activeEvent?.id && routeMatch.type === 'event') {
      return db.subscribeToChanges(activeEvent.id, () => loadData(routeMatch.code));
    }
  }, [activeEvent?.id]);

  const { balances, settlements, totalSpent } = useMemo(() => {
    if (!activeEvent) return { balances: [], settlements: [], totalSpent: 0 };
    const safeBals = calculateBalances(activeEvent.participants, activeEvent.expenses);
    const setts = calculateSettlements(safeBals);
    const total = activeEvent.expenses.reduce((acc, curr) => curr.category !== 'Payment' ? acc + curr.amount : acc, 0);
    return { balances: safeBals, settlements: setts, totalSpent: total };
  }, [activeEvent]);

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newEventName.trim()) return;
    const code = generateShortId();
    try {
      await db.createEvent(newEventName.trim(), code);
      addToRecent(code, newEventName.trim());
      navigate(`/event/${code}`);
    } catch (err) {
      alert("Failed to create event. Please try again.");
    }
  };

  const handleAddParticipant = async (name: string, upiId?: string) => {
    if (!activeEvent) return;
    try {
      await db.addParticipant(activeEvent.id, { 
        name, 
        upiId, 
        avatar: `https://api.dicebear.com/7.x/initials/svg?seed=${encodeURIComponent(name)}&backgroundColor=4f46e5&textColor=ffffff` 
      });
      // Immediate reload to show the new member
      await loadData(routeMatch.code);
    } catch (err) {
      console.error("Add participant error:", err);
      alert("Failed to add member. Check your connection.");
    }
  };

  const handleAddExpense = async (exp: Omit<Expense, 'id'>) => {
    if (!activeEvent) return;
    try {
      await db.addExpense(activeEvent.id, exp);
      await loadData(routeMatch.code);
    } catch (err) {
      console.error("Add expense error:", err);
    }
  };

  const handleShare = (type: 'whatsapp' | 'sms' | 'copy') => {
    const url = window.location.origin + `/event/${routeMatch.code}`;
    const text = `Join our event "${activeEvent?.name}" on SplitIt to track expenses: ${url}`;

    if (type === 'whatsapp') {
      window.open(`https://wa.me/?text=${encodeURIComponent(text)}`, '_blank');
    } else if (type === 'sms') {
      window.open(`sms:?body=${encodeURIComponent(text)}`, '_blank');
    } else {
      navigator.clipboard.writeText(url);
      setShareStatus('copied');
      setTimeout(() => setShareStatus('idle'), 2000);
    }
  };

  if (!isInitialized) return null;

  if (routeMatch.type === 'home') {
    return (
      <div className="min-h-screen bg-white flex flex-col font-sans animate-in overflow-hidden relative">
        <header className="p-8 absolute top-0 left-0 z-10">
          <div className="flex items-center gap-3 cursor-pointer" onClick={() => navigate('/')}>
            <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white text-xl shadow-lg shadow-indigo-100">
              <i className="fa-solid fa-receipt"></i>
            </div>
            <div>
              <h1 className="text-xl font-black text-slate-900 tracking-tighter">splitIt</h1>
              <p className="text-[9px] font-bold text-slate-400 lowercase tracking-tight -mt-1 leading-none">
                trips end. memories stay. debts don’t.
              </p>
            </div>
          </div>
        </header>

        <main className="flex-1 flex flex-col items-center justify-center px-6 max-w-4xl mx-auto w-full text-center space-y-12 pt-20">
          <div className="space-y-6">
            <h1 className="text-[48px] sm:text-[90px] font-[900] text-slate-900 tracking-tighter leading-[0.95] max-w-2xl mx-auto">
              Stop doing <span className="text-indigo-600 italic">awkward</span> math.
            </h1>
            <p className="text-md sm:text-2xl font-medium text-slate-400 max-w-lg mx-auto leading-relaxed">
              The cleanest way to split bills and settle debts with the squad.
            </p>
          </div>

          <div className="flex flex-col items-center gap-10 w-full">
            <div className="relative group w-full max-w-xs">
              <div className="absolute -inset-1 bg-gradient-to-r from-indigo-500 to-purple-600 rounded-full blur opacity-25 group-hover:opacity-40 transition duration-1000"></div>
              <button 
                onClick={() => navigate('/create')}
                className="relative w-full px-8 py-5 bg-indigo-600 text-white rounded-full font-black text-xs uppercase tracking-widest shadow-2xl active:scale-95 transition-all hover:bg-indigo-700"
              >
                Start an Event
              </button>
            </div>

            {recentEvents.length > 0 && (
              <div className="space-y-4 animate-in w-full px-4">
                <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Recent Events</p>
                <div className="flex flex-wrap justify-center gap-3">
                  {recentEvents.map(event => (
                    <button 
                      key={event.code} 
                      onClick={() => navigate(`/event/${event.code}`)}
                      className="px-5 py-3 bg-slate-50 border border-slate-100 rounded-2xl text-[11px] font-black text-slate-700 hover:bg-white hover:border-indigo-100 hover:shadow-sm transition-all flex flex-col items-center min-w-[120px]"
                    >
                      <span className="truncate w-full text-center">{event.name}</span>
                      <span className="text-[8px] text-slate-300 uppercase mt-1">{event.code}</span>
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>
        </main>
      </div>
    );
  }

  if (routeMatch.type === 'create') {
    return (
      <div className="min-h-screen bg-[#f8fafc] flex flex-col items-center justify-center px-6 animate-in">
        <div className="max-w-md w-full bg-white rounded-[3rem] p-8 sm:p-10 shadow-2xl shadow-indigo-100/50 border border-slate-50 space-y-8 text-center">
          <div className="w-16 h-16 bg-indigo-600 rounded-2xl flex items-center justify-center text-white text-3xl mx-auto shadow-lg"><i className="fa-solid fa-receipt"></i></div>
          <div className="space-y-2">
            <h2 className="text-2xl sm:text-3xl font-black text-slate-900 tracking-tight">Name your squad</h2>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.2em]">What are we splitting today?</p>
          </div>
          <form onSubmit={handleCreate} className="space-y-4">
            <input 
              type="text" 
              autoFocus
              required
              value={newEventName}
              onChange={e => setNewEventName(e.target.value)}
              placeholder="e.g. Goa Trip 2025"
              className="w-full px-8 py-5 rounded-3xl bg-slate-50 border-2 border-transparent focus:border-indigo-600 focus:bg-white text-lg font-bold transition-all outline-none text-center"
            />
            <button type="submit" className="w-full bg-indigo-600 text-white py-5 rounded-3xl font-black text-xs uppercase tracking-widest shadow-xl hover:bg-indigo-700 active:scale-95 transition-all">Create Event</button>
            <button type="button" onClick={() => navigate('/')} className="w-full py-2 text-[10px] font-black text-slate-300 uppercase">Cancel</button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#f8fafc] text-slate-900 flex flex-col font-sans">
      <header className="bg-white border-b border-slate-100 sticky top-0 z-40 px-4 h-20 shadow-sm">
        <div className="max-w-7xl mx-auto h-full flex items-center justify-between gap-2">
          <div className="flex items-center gap-2 min-w-0">
            <button onClick={()=>navigate('/')} className="w-9 h-9 rounded-xl hover:bg-slate-50 flex items-center justify-center text-slate-400 shrink-0 transition-colors"><i className="fa-solid fa-arrow-left"></i></button>
            <div className="min-w-0">
              <h1 className="text-xs sm:text-sm font-black truncate uppercase tracking-tight">{activeEvent?.name || 'Loading...'}</h1>
              <p className="text-[8px] font-bold text-slate-400 uppercase tracking-widest">{routeMatch.code}</p>
            </div>
          </div>
          <nav className="flex bg-slate-100 p-1 rounded-xl shrink-0">
            <button onClick={()=>navigate(`/event/${routeMatch.code}`)} className={`px-4 py-2 rounded-lg text-[9px] sm:text-[10px] font-black uppercase transition-all ${routeMatch.tab==='squad'?'bg-white text-indigo-600 shadow-sm':'text-slate-400'}`}>SQUAD</button>
            <button onClick={()=>navigate(`/event/${routeMatch.code}/settlement`)} className={`px-4 py-2 rounded-lg text-[9px] sm:text-[10px] font-black uppercase transition-all ${routeMatch.tab==='settlement'?'bg-white text-indigo-600 shadow-sm':'text-slate-400'}`}>SETTLEMENT</button>
          </nav>
        </div>
      </header>

      {loading && !activeEvent ? (
        <div className="flex-1 flex flex-col items-center justify-center space-y-4">
          <div className="w-10 h-10 border-4 border-indigo-100 border-t-indigo-600 rounded-full animate-spin"></div>
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Hydrating...</p>
        </div>
      ) : activeEvent && (
        <main className="flex-1 max-w-7xl mx-auto w-full px-4 py-6 space-y-6 animate-in pb-10">
          <div className="bg-white px-6 py-5 rounded-[2rem] border border-slate-100 shadow-xl flex flex-col sm:flex-row justify-between items-center gap-6">
            <div className="flex gap-10 text-center sm:text-left">
              <div><span className="text-[8px] font-black text-slate-300 uppercase block mb-1">Spent</span><p className="text-xl sm:text-2xl font-black">₹{totalSpent.toFixed(0)}</p></div>
              <div><span className="text-[8px] font-black text-slate-300 uppercase block mb-1">Squad</span><p className="text-xl sm:text-2xl font-black">{activeEvent.participants.length}</p></div>
            </div>
            <button onClick={()=>setShowShareModal(true)} className="w-full sm:w-auto bg-indigo-600 text-white px-8 py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-lg shadow-indigo-100 active:scale-95 transition-all">Share with Squad</button>
          </div>

          {routeMatch.tab === 'squad' ? (
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
              <div className="lg:col-span-4 order-1">
                <ParticipantManager 
                  participants={activeEvent.participants} 
                  onAdd={handleAddParticipant} 
                  onRemove={async (id) => {
                    await db.deleteParticipant(id);
                    loadData(routeMatch.code);
                  }} 
                />
              </div>
              <div className="lg:col-span-4 order-2">
                <ExpenseForm 
                  participants={activeEvent.participants} 
                  onAdd={handleAddExpense} 
                />
              </div>
              <div className="lg:col-span-4 order-3 space-y-6">
                <div className="bg-white border border-slate-100 rounded-[2rem] p-6 shadow-sm">
                  <h3 className="text-[10px] font-black uppercase tracking-widest text-slate-400 mb-6 text-center lg:text-left">Activity Feed</h3>
                  <div className="space-y-3 max-h-[400px] overflow-y-auto scrollbar-hide">
                    {activeEvent.expenses.length === 0 ? (
                      <div className="text-center py-10 text-slate-200 font-black text-[10px] uppercase">No activity yet</div>
                    ) : (
                      activeEvent.expenses.sort((a,b)=>b.date-a.date).map(e => (
                        <div key={e.id} onClick={() => setSelectedExpense(e)} className={`p-4 rounded-2xl border transition-all cursor-pointer ${e.category==='Payment'?'bg-green-50/50 border-green-100 italic':'bg-white border-slate-50 hover:border-indigo-100'}`}>
                          <div className="flex justify-between items-center gap-2">
                            <div className="min-w-0 flex-1">
                              <p className="font-black text-slate-800 text-sm truncate">{e.description}</p>
                              <p className="text-[9px] text-slate-400 font-bold uppercase tracking-tighter">
                                {activeEvent.participants.find(p=>p.id===e.payerId)?.name || 'Member'} paid
                              </p>
                            </div>
                            <p className="font-black text-slate-900 text-sm whitespace-nowrap">₹{Number(e.amount).toFixed(0)}</p>
                          </div>
                        </div>
                      ))
                    )}
                  </div>
                </div>
              </div>
            </div>
          ) : (
            <SettlementView 
              participants={activeEvent.participants} 
              balances={balances} 
              settlements={settlements} 
              totalSpent={totalSpent} 
              onSettle={async (f, t, a) => {
                await db.addExpense(activeEvent.id, { 
                  description: `Settlement Record`, 
                  amount: a, 
                  payerId: f, 
                  participantIds: [t], 
                  category: 'Payment', 
                  date: Date.now() 
                });
                loadData(routeMatch.code);
              }}
            />
          )}
        </main>
      )}

      {showShareModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/70 backdrop-blur-md animate-in">
          <div className="bg-white rounded-[2.5rem] max-w-sm w-full shadow-2xl p-8 text-center space-y-6">
            <div className="w-16 h-16 bg-indigo-600 rounded-2xl flex items-center justify-center text-white text-2xl mx-auto shadow-lg"><i className="fa-solid fa-users-viewfinder"></i></div>
            <h3 className="text-xl font-black">Share with Squad</h3>
            <p className="text-xs text-slate-500 font-medium leading-relaxed">Let everyone add their own expenses in real-time.</p>

            <div className="grid grid-cols-1 gap-3">
              <button onClick={() => handleShare('whatsapp')} className="w-full flex items-center justify-center gap-3 py-4 bg-green-500 text-white rounded-2xl font-black text-xs uppercase tracking-widest active:scale-95 transition-all">
                <i className="fa-brands fa-whatsapp text-lg"></i> WhatsApp
              </button>
              <button onClick={() => handleShare('sms')} className="w-full flex items-center justify-center gap-3 py-4 bg-indigo-500 text-white rounded-2xl font-black text-xs uppercase tracking-widest active:scale-95 transition-all">
                <i className="fa-solid fa-comment-sms text-lg"></i> Text Message
              </button>
              <button onClick={() => handleShare('copy')} className={`w-full flex items-center justify-center gap-3 py-4 rounded-2xl font-black text-xs uppercase tracking-widest transition-all ${shareStatus==='copied' ? 'bg-slate-900 text-white' : 'bg-slate-100 text-slate-900'}`}>
                {shareStatus==='copied' ? <><i className="fa-solid fa-check"></i> Copied</> : <><i className="fa-solid fa-link"></i> Copy Link</>}
              </button>
            </div>

            <button onClick={() => setShowShareModal(false)} className="w-full py-2 text-[10px] font-black text-slate-300 uppercase">Close</button>
          </div>
        </div>
      )}

      {selectedExpense && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/70 backdrop-blur-md">
          <div className="bg-white rounded-[2rem] max-w-sm w-full p-8 space-y-6 shadow-2xl animate-in">
            <div className="flex justify-between items-center"><h3 className="text-lg font-black">Expense Detail</h3><button onClick={()=>setSelectedExpense(null)} className="p-2"><i className="fa-solid fa-xmark"></i></button></div>
            <div className="space-y-4 pt-4 border-t border-slate-50">
              <div className="flex justify-between items-center"><span className="text-[10px] font-black text-slate-300 uppercase">Label</span><span className="font-bold text-sm truncate max-w-[150px] text-right">{selectedExpense.description}</span></div>
              <div className="flex justify-between items-center"><span className="text-[10px] font-black text-slate-300 uppercase">Amount</span><span className="font-black text-indigo-600 text-xl">₹{Number(selectedExpense.amount).toFixed(0)}</span></div>
            </div>
            <button onClick={() => db.deleteExpense(selectedExpense.id).then(() => { setSelectedExpense(null); loadData(routeMatch.code); })} className="w-full py-4 bg-red-50 text-red-500 font-black text-[11px] uppercase rounded-2xl border border-red-100 transition-all hover:bg-red-100">
              <i className="fa-solid fa-trash-can mr-2"></i>Delete Record
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Participant } from '../types.ts';

interface Props {
  participants: Participant[];
  onAdd: (name: string, upiId?: string) => Promise<void>;
  onRemove: (id: string) => void;
}

const ParticipantManager: React.FC<Props> = ({ participants, onAdd, onRemove }) => {
  const [name, setName] = useState('');
  const [upiId, setUpiId] = useState('');
  const [isAdding, setIsAdding] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const trimmedName = name.trim();
    if (trimmedName && !isAdding) {
      setIsAdding(true);
      try {
        await onAdd(trimmedName, upiId.trim() || undefined);
        setName('');
        setUpiId('');
      } catch (err) {
        console.error("Submit error:", err);
      } finally {
        setIsAdding(false);
      }
    }
  };

  return (
