/**
 * Creates a new event entry in the 'events' table
 */
export const createEvent = async (name: string, shortCode: string): Promise<string> => {
  const { data, error } = await supabase
    .from('events')
    .insert([{ name, short_code: shortCode }])
    .select()
    .single();

  if (error) {
    console.error("Supabase Create Event Error:", error);
    throw error;
  }
  return data.id;
};

/**
 * Fetches an event and all its related participants and expenses using the short_code
 */
export const fetchEventByCode = async (shortCode: string) => {
  try {
    const { data: event, error: eventError } = await supabase
      .from('events')
      .select('id, name, short_code, created_at')
      .eq('short_code', shortCode)
      .single();

    if (eventError || !event) return null;

    const { data: participants } = await supabase
      .from('participants')
      .select('*')
      .eq('event_id', event.id);

    const { data: expenses } = await supabase
      .from('expenses')
      .select('*')
      .eq('event_id', event.id);

    return {
      id: event.id,
      name: event.name,
      shortCode: event.short_code,
      participants: (participants || []).map(p => ({
        id: p.id,
        name: p.name,
        avatar: p.avatar,
        upiId: p.upi_id // Mapping database upi_id to app upiId
      })),
      expenses: (expenses || []).map(e => ({
        ...e,
        payerId: e.payer_id,
        participantIds: e.participant_ids,
        date: new Date(e.created_at).getTime()
      })),
      createdAt: new Date(event.created_at).getTime()
    };
  } catch (e) {
    console.error("Fetch Event Error:", e);
    return null;
  }
};

/**
 * Adds a participant to an existing event
 */
export const addParticipant = async (eventId: string, p: Omit<Participant, 'id'>) => {
  const { data, error } = await supabase
    .from('participants')
    .insert([{ 
      name: p.name, 
      avatar: p.avatar, 
      upi_id: p.upiId || null, // Explicit mapping to database column upi_id
      event_id: eventId 
    }])
    .select()
    .single();

  if (error) {
    console.error("Add Participant Error:", error);
    throw error;
  }
  return {
    ...data,
    upiId: data.upi_id // Return mapped for UI
  };
};

/**
 * Deletes a participant by ID
 */
export const deleteParticipant = async (id: string) => {
  const { error } = await supabase.from('participants').delete().eq('id', id);
  if (error) console.error("Delete Participant Error:", error);
};

/**
 * Adds an expense linked to an event and participants
 */
export const addExpense = async (eventId: string, e: Omit<Expense, 'id'>) => {
  const { data, error } = await supabase
    .from('expenses')
    .insert([{
      event_id: eventId,
      description: e.description,
      amount: e.amount,
      payer_id: e.payerId,
      participant_ids: e.participantIds,
      category: e.category
    }])
    .select()
    .single();

  if (error) {
    console.error("Add Expense Error:", error);
    throw error;
  }
  return data;
};

/**
 * Deletes an expense by ID
 */
export const deleteExpense = async (id: string) => {
  const { error } = await supabase.from('expenses').delete().eq('id', id);
  if (error) console.error("Delete Expense Error:", error);
};

/**
 * Listens for real-time changes to participants or expenses for a specific event
 */
export const subscribeToChanges = (eventId: string, onUpdate: () => void) => {
  const channel = supabase.channel(`event-realtime-${eventId}`)
    .on(
      'postgres_changes', 
      { event: '*', schema: 'public', table: 'participants', filter: `event_id=eq.${eventId}` }, 
      onUpdate
    )
    .on(
      'postgres_changes', 
      { event: '*', schema: 'public', table: 'expenses', filter: `event_id=eq.${eventId}` }, 
      onUpdate
    )
    .subscribe();

  return () => {
    supabase.removeChannel(channel);
  };
}

import React, { useState, useMemo, useEffect } from 'react';
import { Participant, Expense, SplitEvent } from './types.ts';
import ParticipantManager from './components/ParticipantManager.tsx';
import ExpenseForm from './components/ExpenseForm.tsx';
import SettlementView from './components/SettlementView.tsx';
import { calculateBalances, calculateSettlements } from './utils/calculation.ts';
import * as db from './services/supabaseService.ts';

interface RecentEvent {
  code: string;
  name: string;
}

const generateShortId = () => {
  const chars = 'abcdefghijklmnopqrstuvwxyz0123456789';
  let result = '';
  for (let i = 0; i < 6; i++) {
    result += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return result;
};

const App: React.FC = () => {
  const [activeEvent, setActiveEvent] = useState<SplitEvent | null>(null);
  const [path, setPath] = useState(window.location.pathname);
  const [isInitialized, setIsInitialized] = useState(false);
  const [loading, setLoading] = useState(false);
  const [newEventName, setNewEventName] = useState('');
  const [shareStatus, setShareStatus] = useState<'idle' | 'copied'>('idle');
  const [showShareModal, setShowShareModal] = useState(false);
  const [selectedExpense, setSelectedExpense] = useState<Expense | null>(null);
  const [recentEvents, setRecentEvents] = useState<RecentEvent[]>([]);

  const navigate = (to: string) => {
    window.history.pushState(null, "", to);
    setPath(to);
    window.scrollTo(0, 0);
  };

  const routeMatch = useMemo(() => {
    if (path === '/' || path === '') return { type: 'home' };
    if (path === '/create') return { type: 'create' };
    const eventMatch = path.match(/^\/event\/([a-z0-9]{6})(\/settlement)?$/);
    if (eventMatch) {
      return { 
        type: 'event', 
        code: eventMatch[1], 
        tab: eventMatch[2] === '/settlement' ? 'settlement' : 'squad' 
      };
    }
    return { type: 'home' };
  }, [path]);

  useEffect(() => {
    const saved = localStorage.getItem('splitit_recent_events_v3');
    if (saved) setRecentEvents(JSON.parse(saved));
  }, []);

  const addToRecent = (code: string, name: string) => {
    setRecentEvents(prev => {
      const filtered = prev.filter(e => e.code !== code);
      const updated = [{ code, name }, ...filtered].slice(0, 5);
      localStorage.setItem('splitit_recent_events_v3', JSON.stringify(updated));
      return updated;
    });
  };

  const loadData = async (code: string) => {
    setLoading(true);
    try {
      const data = await db.fetchEventByCode(code);
      if (data) {
        setActiveEvent(data);
        addToRecent(code, data.name);
      }
    } catch (err) {
      console.error("Failed to load event:", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (routeMatch.type === 'event') {
      loadData(routeMatch.code);
    } else {
      setActiveEvent(null);
    }
    setIsInitialized(true);
  }, [routeMatch.code, routeMatch.type]);

  useEffect(() => {
    if (activeEvent?.id && routeMatch.type === 'event') {
      return db.subscribeToChanges(activeEvent.id, () => loadData(routeMatch.code));
    }
  }, [activeEvent?.id]);

  const { balances, settlements, totalSpent } = useMemo(() => {
    if (!activeEvent) return { balances: [], settlements: [], totalSpent: 0 };
    const safeBals = calculateBalances(activeEvent.participants, activeEvent.expenses);
    const setts = calculateSettlements(safeBals);
    const total = activeEvent.expenses.reduce((acc, curr) => curr.category !== 'Payment' ? acc + curr.amount : acc, 0);
    return { balances: safeBals, settlements: setts, totalSpent: total };
  }, [activeEvent]);

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newEventName.trim()) return;
    const code = generateShortId();
    try {
      await db.createEvent(newEventName.trim(), code);
      addToRecent(code, newEventName.trim());
      navigate(`/event/${code}`);
    } catch (err) {
      console.error(err);
      alert("Failed to create event. Please try again.");
    }
  };

  const handleAddParticipant = async (name: string, upiId?: string) => {
    if (!activeEvent) return;
    try {
      await db.addParticipant(activeEvent.id, { 
        name, 
        upiId, 
        avatar: `https://api.dicebear.com/7.x/initials/svg?seed=${encodeURIComponent(name)}&backgroundColor=4f46e5&textColor=ffffff` 
      });
      await loadData(routeMatch.code);
    } catch (err) {
      console.error("Add participant error:", err);
      alert("Could not add member. Please check your Supabase connection and schema.");
    }
  };

  const handleAddExpense = async (exp: Omit<Expense, 'id'>) => {
    if (!activeEvent) return;
    try {
      await db.addExpense(activeEvent.id, exp);
      await loadData(routeMatch.code);
    } catch (err) {
      console.error("Add expense error:", err);
    }
  };

  const handleShare = (type: 'whatsapp' | 'sms' | 'copy') => {
    const url = window.location.origin + `/event/${routeMatch.code}`;
    const text = `Join my event "${activeEvent?.name}" on SplitIt: ${url}`;

    if (type === 'whatsapp') {
      window.open(`https://wa.me/?text=${encodeURIComponent(text)}`, '_blank');
    } else if (type === 'sms') {
      window.open(`sms:?body=${encodeURIComponent(text)}`, '_blank');
    } else {
      navigator.clipboard.writeText(url);
      setShareStatus('copied');
      setTimeout(() => setShareStatus('idle'), 2000);
    }
  };

  if (!isInitialized) return null;

  if (routeMatch.type === 'home') {
