              totalSpent={totalSpent} 
              onSettle={async (f, t, a) => {
                await db.addExpense(activeEvent.id, { 
                  description: `Settlement Record`, 
                  amount: a, 
                  payerId: f, 
                  participantIds: [t], 
                  category: 'Payment', 
                  date: Date.now() 
