          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Syncing...</p>
        </div>
      ) : activeEvent && (
        <main className="flex-1 max-w-7xl mx-auto w-full px-4 py-6 space-y-6 animate-in pb-10">
