/**
 * Creates a new event entry in the 'events' table
 */
export const createEvent = async (name: string, shortCode: string): Promise<string> => {
  const { data, error } = await supabase
    .from('events')
    .insert([{ name, short_code: shortCode }])
    .select()
    .single();

  if (error) {
    console.error("Supabase Create Event Error:", error);
    throw error;
  }
  return data.id;
};

/**
 * Fetches an event and all its related participants and expenses using the short_code
 */
export const fetchEventByCode = async (shortCode: string) => {
  try {
    const { data: event, error: eventError } = await supabase
      .from('events')
      .select('id, name, short_code, created_at')
      .eq('short_code', shortCode)
      .single();

    if (eventError || !event) return null;

    const { data: participants } = await supabase
      .from('participants')
      .select('*')
      .eq('event_id', event.id);

    const { data: expenses } = await supabase
      .from('expenses')
      .select('*')
      .eq('event_id', event.id);

    return {
      id: event.id,
      name: event.name,
      shortCode: event.short_code,
      participants: (participants || []).map(p => ({
        id: p.id,
        name: p.name,
        avatar: p.avatar,
        upiId: p.upi_id // Mapping database upi_id to app upiId
      })),
      expenses: (expenses || []).map(e => ({
        ...e,
        payerId: e.payer_id,
        participantIds: e.participant_ids,
        date: new Date(e.created_at).getTime()
      })),
      createdAt: new Date(event.created_at).getTime()
    };
  } catch (e) {
    console.error("Fetch Event Error:", e);
    return null;
  }
};

/**
 * Adds a participant to an existing event
 */
export const addParticipant = async (eventId: string, p: Omit<Participant, 'id'>) => {
  const { data, error } = await supabase
    .from('participants')
    .insert([{ 
      name: p.name, 
      avatar: p.avatar, 
      upi_id: p.upiId || null, // Explicit mapping to database column upi_id
      event_id: eventId 
    }])
    .select()
    .single();

  if (error) {
    console.error("Add Participant Error:", error);
    throw error;
  }
  return {
    ...data,
    upiId: data.upi_id // Return mapped for UI
  };
};

/**
 * Updates a participant's details
 */
export const updateParticipant = async (id: string, updates: Partial<Participant>) => {
  const payload: any = {};
  if (updates.name) payload.name = updates.name;
  if (updates.upiId !== undefined) payload.upi_id = updates.upiId;

  const { error } = await supabase
    .from('participants')
    .update(payload)
    .eq('id', id);

  if (error) {
    console.error("Update Participant Error:", error);
    throw error;
  }
};

/**
 * Deletes a participant by ID
 */
export const deleteParticipant = async (id: string) => {
  const { error } = await supabase.from('participants').delete().eq('id', id);
  if (error) console.error("Delete Participant Error:", error);
};

/**
 * Adds an expense linked to an event and participants
 */
export const addExpense = async (eventId: string, e: Omit<Expense, 'id'>) => {
  const { data, error } = await supabase
    .from('expenses')
    .insert([{
      event_id: eventId,
      description: e.description,
      amount: e.amount,
      payer_id: e.payerId,
      participant_ids: e.participant_ids,
      category: e.category
    }])
    .select()
    .single();

  if (error) {
    console.error("Add Expense Error:", error);
    throw error;
  }
  return data;
};

/**
 * Deletes an expense by ID
 */
export const deleteExpense = async (id: string) => {
  const { error } = await supabase.from('expenses').delete().eq('id', id);
  if (error) console.error("Delete Expense Error:", error);
};

/**
 * Listens for real-time changes to participants or expenses for a specific event
 */
export const subscribeToChanges = (eventId: string, onUpdate: () => void) => {
  const channel = supabase.channel(`event-realtime-${eventId}`)
    .on(
      'postgres_changes', 
      { event: '*', schema: 'public', table: 'participants', filter: `event_id=eq.${eventId}` }, 
      onUpdate
    )
    .on(
      'postgres_changes', 
      { event: '*', schema: 'public', table: 'expenses', filter: `event_id=eq.${eventId}` }, 
      onUpdate
    )
    .subscribe();

  return () => {
    supabase.removeChannel(channel);
  };
}

import React, { useState } from 'react';
import { Participant } from '../types.ts';
import * as db from '../services/supabaseService.ts';

interface Props {
  participants: Participant[];
  onAdd: (name: string, upiId?: string) => Promise<void>;
  onRemove: (id: string) => void;
}

const ParticipantManager: React.FC<Props> = ({ participants, onAdd, onRemove }) => {
  const [name, setName] = useState('');
  const [upiId, setUpiId] = useState('');
  const [isAdding, setIsAdding] = useState(false);

  const [editingId, setEditingId] = useState<string | null>(null);
  const [editName, setEditName] = useState('');
  const [editUpi, setEditUpi] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const trimmedName = name.trim();
    if (trimmedName && !isAdding) {
      setIsAdding(true);
      try {
        await onAdd(trimmedName, upiId.trim() || undefined);
        setName('');
        setUpiId('');
      } catch (err) {
        console.error("Submit error:", err);
      } finally {
        setIsAdding(false);
      }
    }
  };

  const startEditing = (p: Participant) => {
    setEditingId(p.id);
    setEditName(p.name);
    setEditUpi(p.upiId || '');
  };

  const saveEdit = async () => {
    if (!editingId || !editName.trim()) return;
    try {
      await db.updateParticipant(editingId, { name: editName.trim(), upiId: editUpi.trim() || undefined });
      setEditingId(null);
    } catch (err) {
      console.error("Update error:", err);
    }
  };

  return (
    <div className="flex flex-col h-full">
      <div className="bg-white rounded-3xl p-6 shadow-sm border border-slate-100 flex-1">
        <div className="flex items-center gap-2 text-[#1e293b] mb-6 justify-center lg:justify-start">
          <i className="fa-solid fa-users text-[#4f46e5]"></i>
          <h2 className="text-lg font-bold tracking-tight">The Squad</h2>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="flex flex-col gap-1">
            <label className="text-[9px] font-black uppercase tracking-widest text-slate-400 px-1">Member Name</label>
            <input
              type="text"
              required
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="e.g. Rahul, Priya"
              className="w-full px-5 py-4 rounded-2xl bg-slate-50 border border-slate-100 text-sm font-bold focus:outline-none focus:border-[#4f46e5] focus:bg-white transition-all placeholder:text-slate-300"
            />
          </div>
          <div className="flex flex-col gap-1">
            <label className="text-[9px] font-black uppercase tracking-widest text-slate-400 px-1">UPI ID (Optional)</label>
            <input
              type="text"
              value={upiId}
              onChange={(e) => setUpiId(e.target.value)}
              placeholder="e.g. rahul@okaxis"
              className="w-full px-5 py-4 rounded-2xl bg-slate-50 border border-slate-100 text-sm font-bold focus:outline-none focus:border-[#4f46e5] focus:bg-white transition-all placeholder:text-slate-300"
            />
          </div>
          <button
            type="submit"
            disabled={isAdding || !name.trim()}
            className="w-full bg-[#4f46e5] text-white px-5 py-5 rounded-2xl font-black text-xs uppercase tracking-[0.15em] hover:bg-[#4338ca] transition-all shadow-md active:scale-95 disabled:opacity-50 flex items-center justify-center gap-2"
          >
            {isAdding ? <><i className="fa-solid fa-spinner animate-spin"></i> ADDING...</> : "Add to Squad"}
          </button>
        </form>

        <div className="mt-8 space-y-2 overflow-y-auto max-h-[300px] pr-1 scrollbar-hide">
          {participants.length === 0 ? (
            <p className="text-[9px] font-black text-slate-300 uppercase tracking-[0.2em] text-center py-10">
              SQUAD IS EMPTY
            </p>
          ) : (
            participants.map(p => (
              <div key={p.id} className="flex items-center justify-between group p-3 rounded-2xl bg-white border border-slate-50 hover:bg-slate-50 hover:border-slate-100 transition-all">
                <div className="flex items-center gap-3 min-w-0 flex-1">
                  <img src={p.avatar} alt={p.name} className="w-9 h-9 rounded-xl bg-slate-100 shadow-sm shrink-0" />

                  {editingId === p.id ? (
                    <div className="flex flex-col gap-1 flex-1 pr-2">
                      <input 
                        className="text-xs font-bold border-b border-indigo-200 outline-none bg-transparent"
                        value={editName}
                        onChange={e => setEditName(e.target.value)}
                        autoFocus
                      />
                      <input 
                        className="text-[8px] border-b border-indigo-100 outline-none bg-transparent text-slate-400"
                        value={editUpi}
                        onChange={e => setEditUpi(e.target.value)}
