import { Expense, Participant, Settlement, Balance } from '../types.ts';

export const calculateBalances = (participants: Participant[], expenses: Expense[]): Balance[] => {
  const balances: Record<string, number> = {};
  participants.forEach(p => balances[p.id] = 0);

  expenses.forEach(expense => {
    if (expense.category === 'Payment') {
      // Settlement: payerId is the sender (debtor), participantIds[0] is the receiver (creditor)
      // Payer balance increases (becomes less negative)
      balances[expense.payerId] += expense.amount;
      // Recipient balance decreases (becomes less positive)
      expense.participantIds.forEach(pId => {
        balances[pId] -= expense.amount;
      });
    } else {
      // Regular expense: split amount among all participants
      const splitAmount = expense.amount / expense.participantIds.length;

      // Payer gets back their total minus their share
      balances[expense.payerId] += expense.amount;

      // Each participant owes their share
      expense.participantIds.forEach(pId => {
        balances[pId] -= splitAmount;
      });
    }
  });

  return Object.entries(balances).map(([id, amount]) => ({
    participantId: id,
    amount: parseFloat(amount.toFixed(2))
  }));
};

export const calculateSettlements = (balances: Balance[]): Settlement[] => {
  const settlements: Settlement[] = [];
  // Work with a copy to avoid mutating the original array
  const pos = balances.filter(b => b.amount > 0.01).map(b => ({ ...b })).sort((a, b) => b.amount - a.amount);
  const neg = balances.filter(b => b.amount < -0.01).map(b => ({ ...b })).sort((a, b) => a.amount - b.amount);

  let i = 0; // pos index
  let j = 0; // neg index

  while (i < pos.length && j < neg.length) {
    const amount = Math.min(pos[i].amount, Math.abs(neg[j].amount));
    settlements.push({
      from: neg[j].participantId,
      to: pos[i].participantId,
      amount: parseFloat(amount.toFixed(2))
    });

    pos[i].amount -= amount;
    neg[j].amount += amount;

    if (pos[i].amount < 0.01) i++;
    if (Math.abs(neg[j].amount) < 0.01) j++;
  }

  return settlements;
};

import React, { useState, useRef, useMemo } from 'react';
import { Participant, Settlement, Balance, Expense } from '../types.ts';

interface Props {
  participants: Participant[];
  balances: Balance[];
  settlements: Settlement[];
  expenses: Expense[];
  totalSpent: number;
  onSettle: (fromId: string, toId: string, amount: number, description: string, proof?: string) => void;
}

const SettlementView: React.FC<Props> = ({ participants, balances, settlements, expenses, totalSpent, onSettle }) => {
  const [paymentModal, setPaymentModal] = useState<{ settlement: Settlement; show: boolean } | null>(null);
  const [manualConfirmModal, setManualConfirmModal] = useState<Settlement | null>(null);
  const [screenshot, setScreenshot] = useState<string | null>(null);
  const [showUpiInput, setShowUpiInput] = useState(false);
  const [manualUpi, setManualUpi] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const getParticipant = (id: string) => participants.find(p => p.id === id);
  const getParticipantName = (id: string) => getParticipant(id)?.name || 'Member';

  const settlementHistory = useMemo(() => {
    return expenses
      .filter(e => e.category === 'Payment')
      .sort((a, b) => b.date - a.date);
  }, [expenses]);

  const handleWhatsAppReminder = (s: Settlement) => {
    const payer = getParticipant(s.from);
    const payee = getParticipant(s.to);
    if (!payer || !payee) return;

    const msg = `Hey *${payer.name}*, split our bills on SplitIt! 💸 You owe *${payee.name}* *₹${s.amount.toFixed(0)}*.\n${payee.upiId ? `\nMy UPI: ${payee.upiId}` : ''}\n\nLess maths. More memories.\nTry Splitit → www.splitits.in`;

    window.open(`https://wa.me/?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const openUpiApp = () => {
    if (!paymentModal) return;
    const payee = getParticipant(paymentModal.settlement.to);
    const upi = manualUpi || payee?.upiId;
    if (!upi) {
      setShowUpiInput(true);
      return;
    }
    const link = `upi://pay?pa=${upi}&pn=${encodeURIComponent(payee?.name || 'User')}&am=${paymentModal.settlement.amount.toFixed(2)}&cu=INR`;

    // Record as online settlement
    onSettle(paymentModal.settlement.from, paymentModal.settlement.to, paymentModal.settlement.amount, "Online Payment");

    setPaymentModal(null);
    window.location.href = link;
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setScreenshot(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const confirmManualSettle = () => {
    if (manualConfirmModal && screenshot) {
      onSettle(manualConfirmModal.from, manualConfirmModal.to, manualConfirmModal.amount, "Manual Settlement", screenshot);
      setManualConfirmModal(null);
