                          </button>
                        )}
                      </div>
                   </div>
                </div>
                <div className="text-right">
                  <p className="text-sm font-black text-slate-900">₹{h.amount.toFixed(0)}</p>
                  <p className="text-[8px] font-bold text-slate-300 uppercase">{new Date(h.date).toLocaleDateString()}</p>
                </div>
              </div>
            ))
          )}
