import React, { useState } from 'react';
import { Participant } from '../types.ts';
import * as db from '../services/supabaseService.ts';

interface Props {
  participants: Participant[];
  onAdd: (name: string, upiId?: string) => Promise<void>;
  onRemove: (id: string) => void;
}

const ParticipantManager: React.FC<Props> = ({ participants, onAdd, onRemove }) => {
  const [name, setName] = useState('');
  const [upiId, setUpiId] = useState('');
  const [isAdding, setIsAdding] = useState(false);

  const [editingId, setEditingId] = useState<string | null>(null);
  const [editName, setEditName] = useState('');
  const [editUpi, setEditUpi] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const trimmedName = name.trim();
    if (trimmedName && !isAdding) {
      setIsAdding(true);
      try {
        await onAdd(trimmedName, upiId.trim() || undefined);
        setName('');
        setUpiId('');
      } catch (err) {
        console.error("Submit error:", err);
      } finally {
        setIsAdding(false);
      }
    }
  };

  const startEditing = (p: Participant) => {
    setEditingId(p.id);
    setEditName(p.name);
    setEditUpi(p.upiId || '');
  };

  const saveEdit = async () => {
    if (!editingId || !editName.trim()) return;
    try {
      await db.updateParticipant(editingId, { name: editName.trim(), upiId: editUpi.trim() || undefined });
      setEditingId(null);
    } catch (err) {
      console.error("Update error:", err);
    }
  };

  return (
    <div className="flex flex-col h-full">
      <div className="bg-white rounded-3xl p-6 shadow-sm border border-slate-100 flex-1">
        <div className="flex items-center gap-2 text-[#1e293b] mb-6 justify-center lg:justify-start">
          <i className="fa-solid fa-users text-[#4f46e5]"></i>
          <h2 className="text-lg font-bold tracking-tight">The Squad</h2>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="flex flex-col gap-1">
            <label className="text-[9px] font-black uppercase tracking-widest text-slate-400 px-1">Member Name</label>
            <input
              type="text"
              required
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="e.g. rahul, priya"
              className="w-full px-5 py-4 rounded-2xl bg-slate-50 border border-slate-100 text-sm font-bold focus:outline-none focus:border-[#4f46e5] focus:bg-white transition-all placeholder:text-slate-300"
            />
          </div>
          <div className="flex flex-col gap-1">
            <label className="text-[9px] font-black uppercase tracking-widest text-slate-400 px-1">UPI ID (Optional)</label>
            <input
              type="text"
              value={upiId}
              onChange={(e) => setUpiId(e.target.value)}
              placeholder="e.g. rahul@okaxis"
              className="w-full px-5 py-4 rounded-2xl bg-slate-50 border border-slate-100 text-sm font-bold focus:outline-none focus:border-[#4f46e5] focus:bg-white transition-all placeholder:text-slate-300"
            />
          </div>
          <button
            type="submit"
            disabled={isAdding || !name.trim()}
            className="w-full bg-[#4f46e5] text-white px-5 py-5 rounded-2xl font-black text-xs uppercase tracking-[0.15em] hover:bg-[#4338ca] transition-all shadow-md active:scale-95 disabled:opacity-50 flex items-center justify-center gap-2"
          >
            {isAdding ? <><i className="fa-solid fa-spinner animate-spin"></i> ADDING...</> : "Add to Squad"}
          </button>
        </form>

        <div className="mt-8 space-y-2 overflow-y-auto max-h-[300px] pr-1 scrollbar-hide">
          {participants.length === 0 ? (
            <p className="text-[9px] font-black text-slate-300 uppercase tracking-[0.2em] text-center py-10">
              SQUAD IS EMPTY
            </p>
          ) : (
            participants.map(p => (
              <div key={p.id} className="flex items-center justify-between group p-3 rounded-2xl bg-white border border-slate-50 hover:bg-slate-50 hover:border-slate-100 transition-all">
                <div className="flex items-center gap-3 min-w-0 flex-1">
                  <img src={p.avatar} alt={p.name} className="w-9 h-9 rounded-xl bg-slate-100 shadow-sm shrink-0" />

                  {editingId === p.id ? (
                    <div className="flex flex-col gap-1 flex-1 pr-2">
                      <input 
                        className="text-xs font-bold border-b border-indigo-200 outline-none bg-transparent lowercase"
                        value={editName}
                        onChange={e => setEditName(e.target.value)}
                        autoFocus
                      />
                      <input 
                        className="text-[8px] border-b border-indigo-100 outline-none bg-transparent text-slate-400"
                        value={editUpi}
                        onChange={e => setEditUpi(e.target.value)}
                        placeholder="UPI ID"
                      />
                    </div>
                  ) : (
                    <div className="min-w-0">
                      <p className="font-black text-sm text-[#1e293b] truncate leading-tight lowercase tracking-tight">{p.name}</p>
                      {p.upiId && <p className="text-[9px] text-slate-400 font-bold truncate tracking-tight">{p.upiId}</p>}
                    </div>
                  )}
                </div>

                <div className="flex items-center gap-1">
                  {editingId === p.id ? (
                    <>
                      <button onClick={saveEdit} className="text-green-500 p-2 hover:bg-green-50 rounded-lg transition-colors">
                        <i className="fa-solid fa-check"></i>
                      </button>
                      <button onClick={() => setEditingId(null)} className="text-slate-400 p-2 hover:bg-slate-100 rounded-lg transition-colors">
                        <i className="fa-solid fa-xmark"></i>
                      </button>
                    </>
                  ) : (
                    <>
                      <button onClick={() => startEditing(p)} className="text-slate-300 hover:text-indigo-500 p-2 transition-colors">
                        <i className="fa-solid fa-pen text-xs"></i>
                      </button>
                      <button onClick={() => onRemove(p.id)} className="text-slate-300 hover:text-red-500 p-2 transition-colors">
                        <i className="fa-solid fa-circle-xmark text-lg"></i>
                      </button>
                    </>
                  )}
                </div>
              </div>
            ))
          )}
        </div>
      </div>

      <div className="mt-8 text-center space-y-1">
        <p className="text-[10px] font-bold text-slate-400 lowercase tracking-tight">
          Less maths. More memories.
        </p>
        <p className="text-[10px] font-black text-[#4f46e5] uppercase tracking-widest">
          Try Splitit → <span className="underline">www.splitits.in</span>
        </p>
      </div>
    </div>
  );
};

export default ParticipantManager;

import React, { useState, useMemo, useEffect } from 'react';
import { Participant, Expense, SplitEvent } from './types.ts';
import ParticipantManager from './components/ParticipantManager.tsx';
import ExpenseForm from './components/ExpenseForm.tsx';
import SettlementView from './components/SettlementView.tsx';
import OverviewCharts from './components/OverviewCharts.tsx';
import { calculateBalances, calculateSettlements } from './utils/calculation.ts';
import * as db from './services/supabaseService.ts';

interface RecentEvent {
  code: string;
  name: string;
}

interface ActivityLog {
  id: string;
  description: string;
  created_at: string;
}

const generateShortId = () => {
  const chars = 'abcdefghijklmnopqrstuvwxyz0123456789';
  let result = '';
  for (let i = 0; i < 6; i++) {
    result += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return result;
};

const App: React.FC = () => {
  const [activeEvent, setActiveEvent] = useState<SplitEvent | null>(null);
  const [path, setPath] = useState(window.location.pathname);
  const [isInitialized, setIsInitialized] = useState(false);
  const [loading, setLoading] = useState(false);
  const [newEventName, setNewEventName] = useState('');
  const [shareStatus, setShareStatus] = useState<'idle' | 'copied'>('idle');
  const [showShareModal, setShowShareModal] = useState(false);
  const [selectedExpense, setSelectedExpense] = useState<Expense | null>(null);
  const [editingExpense, setEditingExpense] = useState<Expense | null>(null);
  const [recentEvents, setRecentEvents] = useState<RecentEvent[]>([]);
  const [activities, setActivities] = useState<ActivityLog[]>([]);

  const navigate = (to: string) => {
    window.history.pushState(null, "", to);
    setPath(to);
    window.scrollTo(0, 0);
  };

  const routeMatch = useMemo(() => {
    if (path === '/' || path === '') return { type: 'home' };
    if (path === '/create') return { type: 'create' };
    const eventMatch = path.match(/^\/event\/([a-z0-9]{6})(\/settlement)?$/);
    if (eventMatch) {
      return { 
        type: 'event', 
        code: eventMatch[1], 
        tab: eventMatch[2] === '/settlement' ? 'settlement' : 'overview' 
      };
    }
    return { type: 'home' };
  }, [path]);

  useEffect(() => {
    const saved = localStorage.getItem('splitit_recent_events_v3');
    if (saved) setRecentEvents(JSON.parse(saved));
  }, []);

  const addToRecent = (code: string, name: string) => {
    setRecentEvents(prev => {
      const filtered = prev.filter(e => e.code !== code);
      const updated = [{ code, name }, ...filtered].slice(0, 5);
      localStorage.setItem('splitit_recent_events_v3', JSON.stringify(updated));
      return updated;
    });
  };

  const loadData = async (code: string) => {
    setLoading(true);
    try {
      const data = await db.fetchEventByCode(code);
      if (data) {
        setActiveEvent(data);
        addToRecent(code, data.name);
        const history = await db.fetchActivityHistory(data.id);
        setActivities(history);
      }
    } catch (err) {
      console.error("Failed to load event:", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (routeMatch.type === 'event') {
      loadData(routeMatch.code);
    } else {
      setActiveEvent(null);
    }
    setIsInitialized(true);
  }, [routeMatch.code, routeMatch.type]);

  useEffect(() => {
    if (activeEvent?.id && routeMatch.type === 'event') {
      return db.subscribeToChanges(activeEvent.id, () => loadData(routeMatch.code));
    }
  }, [activeEvent?.id]);

  const { balances, settlements, totalSpent } = useMemo(() => {
    if (!activeEvent) return { balances: [], settlements: [], totalSpent: 0 };
    const safeBals = calculateBalances(activeEvent.participants, activeEvent.expenses);
    const setts = calculateSettlements(safeBals);
    const total = activeEvent.expenses.reduce((acc, curr) => curr.category !== 'Payment' ? acc + curr.amount : acc, 0);
    return { balances: safeBals, settlements: setts, totalSpent: total };
  }, [activeEvent]);

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newEventName.trim()) return;
    const code = generateShortId();
    try {
      await db.createEvent(newEventName.trim(), code);
      addToRecent(code, newEventName.trim());
      navigate(`/event/${code}`);
    } catch (err) {
      console.error(err);
      alert("Failed to create event. Please try again.");
    }
  };

  const handleAddParticipant = async (name: string, upiId?: string) => {
    if (!activeEvent) return;
    try {
      await db.addParticipant(activeEvent.id, { 
        name, 
        upiId, 
        avatar: `https://api.dicebear.com/7.x/initials/svg?seed=${encodeURIComponent(name)}&backgroundColor=4f46e5&textColor=ffffff` 
      });
      await loadData(routeMatch.code);
    } catch (err) {
      console.error("Add participant error:", err);
      alert("Could not add member. Please check your connection.");
    }
  };

  const handleAddExpense = async (exp: Omit<Expense, 'id'>) => {
    if (!activeEvent) return;
    try {
      await db.addExpense(activeEvent.id, exp);
      await loadData(routeMatch.code);
    } catch (err) {
      console.error("Add expense error:", err);
    }
  };

  const handleUpdateExpense = async (id: string, exp: Partial<Expense>) => {
    if (!activeEvent) return;
    try {
      await db.updateExpense(id, exp, activeEvent.id);
      await loadData(routeMatch.code);
      setEditingExpense(null);
    } catch (err) {
      console.error("Update expense error:", err);
    }
  };

  const handleShare = (type: 'whatsapp' | 'sms' | 'copy') => {
    const url = window.location.origin + `/event/${routeMatch.code}`;
    const text = `Join my event *${activeEvent?.name}* on Splitit: ${url}\n\nLess maths. More memories.\nTry Splitit → www.splitits.in`;

    if (type === 'whatsapp') {
      window.open(`https://wa.me/?text=${encodeURIComponent(text)}`, '_blank');
    } else if (type === 'sms') {
      window.open(`sms:?body=${encodeURIComponent(text)}`, '_blank');
    } else {
      navigator.clipboard.writeText(text);
      setShareStatus('copied');
      setTimeout(() => setShareStatus('idle'), 2000);
    }
  };

  if (!isInitialized) return null;

  if (routeMatch.type === 'home') {
    return (
      <div className="min-h-screen bg-white flex flex-col font-sans animate-in overflow-hidden relative">
        <header className="p-8 absolute top-0 left-0 z-10">
          <div className="flex items-center gap-3 cursor-pointer" onClick={() => navigate('/')}>
            <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white text-xl shadow-lg shadow-indigo-100">
              <i className="fa-solid fa-receipt"></i>
            </div>
            <div className="flex flex-col">
              <h1 className="text-xl font-black text-slate-900 tracking-tighter leading-none">splitIt</h1>
              <p className="text-[9px] font-bold text-slate-400 lowercase tracking-tight mt-1">
                trips end. memories stay. debts don’t.
              </p>
            </div>
          </div>
        </header>

        <main className="flex-1 flex flex-col items-center justify-center px-6 max-w-4xl mx-auto w-full text-center space-y-8 pt-10">
          <div className="space-y-4">
            <h1 className="text-[54px] sm:text-[90px] font-[900] text-slate-900 tracking-tighter leading-[0.9] max-w-2xl mx-auto">
              Stop doing <span className="text-indigo-600 italic">awkward</span> math.
            </h1>
            <p className="text-sm sm:text-xl font-medium text-slate-500 max-w-lg mx-auto leading-relaxed px-4">
              The cleanest way to split bills, track group expenses, and settle debts instantly with the squad.
            </p>
          </div>

          <div className="flex flex-col items-center gap-10 w-full">
            <button 
              onClick={() => navigate('/create')}
              className="w-full max-w-[280px] px-8 py-5 bg-[#4f46e5] text-white rounded-2xl font-black text-[13px] uppercase tracking-widest shadow-2xl active:scale-95 transition-all hover:bg-indigo-700"
            >
              Start an Event
            </button>

            {recentEvents.length > 0 && (
              <div className="space-y-4 animate-in w-full px-4">
                <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Recent Events</p>
                <div className="flex flex-wrap justify-center gap-2">
                  {recentEvents.map(event => (
                    <button 
