                    >
                      Manual
                    </button>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {manualConfirmModal && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-md animate-in">
